window.QUIZ_NATIONAL = (window.QUIZ_NATIONAL||[]).concat([{"q":"·○○○○○은 6세기 초에 축성되어 9세기까지 사용된 고대성곽(백제와 통일신라시대에 걸쳐 사용)으로 성곽유적이 잘 보존되어 있고 발굴시 명문와편 등이 출토되어 문헌(삼국사기)과 일치 하며, 웅진백제시기의 전남 동부국경지역의 산성특징을 잘 보여주고 있다. 5차례의 발굴조사에서 성벽, 백제～통일신라시대의 건물지 17동, 문지 3개소, 석축집수정 5개 소, 우물 2개소, 점토집수정 6개소, 치 3개소, 수구 3개소, 수혈유구 30여기 등의 많은 유구와 기와류, 토기류, 철기류, 청동기류 등의 다양한 유물이 확인되었으며, 이처럼 ○○○○○은 유구와 유물로 인해 우리나라 고대…","a":"광양 마로산성","c":"사적","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627416.jpg"},{"q":"지례리 천곡의 서북쪽에서 뻗어내린 산세에 의지하여 반변천이 바라보이는 곳에 동남향으로 자리잡은 조선 후기의 주택이다. 조선 숙종 때 대사성을 지낸 지촌의 셋째 아들 김원중이 천곡에 분가할 때 지은 것이다. 안채는 1700년대에 지은 것으로 보이며, 사랑채는 1920년에 크게 고쳐지은 것이다. 임하댐 건설로 인하여 1990년 지금의 위치로 옮겨지었다. 안채와 사랑채·대문간채 등이 튼 'ㅁ'자모양을 이루고 있다. 안채 오른쪽에 방앗간채가 있고 사랑마당 왼쪽 한켠에는 외양간을 두었으며, 담밖 뒷쪽 낮은 언덕에 사당을 마련하였다. 흙담을 사각형으로 쌓아 건물들을 둘러싸게 하…","a":"안동 오류헌 고택","c":"국가민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635486.jpg"},{"q":"속리산 기슭에 있는 ○○○는 신라 진흥왕 14년(553)에 처음 지었고, 혜공왕 12년(776)에 다시 지었다. 임진왜란으로 모두 불탄 것을 인조 2년(1624)에 벽암이 다시 지었으며 그 뒤 여러 차례 수리를 거쳐 오늘에 이르고 있다. ○○○○은 앞면 3칸·옆면 3칸 규모의 정사각형 1층 건물로, 지붕은 중앙에서 4면으로 똑같이 경사가 진 사모지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위에만 있는 주심포 양식으로 꾸몄다. 건물 안에는 앉은키 2.8m의 금색 목조 관세음보살상을 모시고 있다. 관세음보살상은 머리에 화관(花冠)을 쓰고 있으며, 얼굴에…","a":"보은 법주사 원통보전","c":"보물","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617138.jpg"},{"q":"백제의 옛 땅이었던 충청·전라도에는 ○○ 정림사지 오층석탑(국보)의 양식을 모방한 백제계 석탑이 몇 개 전하고 있는데 이 탑 역시 그런 계열에 속하는 탑이다. 땅 위에 자연석에 가까운 바닥돌을 깔고 그 위에 같은 돌로 너비를 좁히면서 3단의 기단(基壇)을 만들었다. 탑신(塔身)은 네 귀퉁이에 위로 오를수록 좁아지는 형태의 기둥 모양을 새겼고, 그 사이에 긴 판돌을 세워 면을 이루게 하였다. 동서남북 사면에 감실모양이 있는데, 우주와 면석의 약화된 모습으로 보는 경우도 있다. 감실은 목탑에 많이 나타나던 것으로 불상을 모시는 방을 의미한다. 석탑에서는 대부분 이를 형상…","a":"부여 장하리 삼층석탑","c":"보물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617583.jpg"},{"q":"완구는 일명 ‘댕구’라고도 부르며 유통식(有筒式) 화기의 한 종류로 조선 태종 때 최해산이 만들었다고 한다. 완구는 크게 완(碗), 격목통(激木筒), 약통(藥筒)의 3부분으로 나눌 수 있다. 완은 발사물 즉 큰 돌이나 쇠공을 올려 놓는 곳으로 그릇 모양을 하고 있다. ○○○의 약통은 화약을 넣는 곳으로 점화선을 끼우는 점화구멍을 2개 가지고 있다. 약통과 완 중간에는 격목통이 있는데 이 곳에는 화약이 폭발할 때 생기는 폭발력을 완에 전달하기 위한 나무로 만든 격목이 있다. 전체 길이 64.5㎝인 ○○○로 1985년 경상남도 하동군 동화리에서 등산하던 주민에 의해 우연…","a":"중완구(1986-1)","c":"보물","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622832.jpg"},{"q":"이 건물은 개항 후 일본인과 함께 들어온 일본 조동종(曹洞宗) 사찰인 금강사의 불전으로 건립하였으나, 광복 후 조계종 사찰 ○○○로 변경하여 현재에 이르고 있다. ○○○과 승려들이 거처하는 요사채는 복도로 연결되어 있고, 지붕 물매는 급경사를 이루며, 건물 외벽에 미서기 문이 설치되어 있는 등 일본 사찰 건축 양식을 따랐다. 법당 내부가 일부 변형되었지만 대체로 원형이 잘 보존되어 있다.","a":"군산 동국사 대웅전","c":"국가등록문화유산","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668706.jpg"},{"q":"『○○○○○』은 18세기 전반을 대표하는 명필 백하 ○○이 58세 되는 1737년(영조 13) 3월에 태화산에서 쓴 것이다. 다양한 크기의 해행초로 쓰여 있는데, 소해는 왕희지풍, 중자 해서는 동기창풍, 행서와 초서는 미불 서풍을 바탕으로 동기창 서풍이 가미되어 있다. 또 ○○의 글씨 앞뒤에는 당대와 후대의 명사 네 사람의 제발(題跋)이 딸려 있으며, ○○ 서예의 장처와 한계를 지적하고 있어 조선후기 서예비평의 본격적인 예로 주목된다. 보존상태도 매우 양호하다. ○○의 노년시절 서풍을 가장 대표하는 ○○이다.","a":"윤순 필적 고시서축","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614987.jpg"},{"q":"이 책은 조선 세종에서 중종조에 이르는 동안 대마도, 파저강, 건주위, 이마차, 서북로구, 삼포왜란 등을 정벌한 역사를 기록한 것이다. 체재를 보면 목록과 범례에 이어 상권에는 대마도 정벌(征對馬島)·파저강 정벌(征婆猪江)·건주위 정벌(征建州衛)이, 하권에는 건주위 정벌(征建州衛)·이마차 정벌(征尼麻車)·서북로구 정벌(征西北虜寇)·삼포반왜 정벌(征三浦叛倭)이 수록되어 있다. 서술의 체재는 각 전쟁별로 연대에 따라 강목체(綱目體)로 기술되어 있는데, 범례에서 말하고 있듯이 조선의 군사행동은 정(征) 또는 토(討)로 칭하고 적병은 구(寇) 또는 반(叛), 적을 격파한 경…","a":"국조정토록","c":"보물","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616108.jpg"},{"q":"○○○○의 ○○○은 토석담이 주류를 이루고 있으며, 이 외에 돌담과 탱자나무울타리가 함께 구성되어 한옥, 오래된 큰 나무와 잘 어우러져 아름다운 경관을 형성하고 있다. 토석담은 높이 1.5~2m, 폭 40~60cm 정도인데, 길이 20~40cm 방형의 막돌과 진흙을 전통적인 축조방식에 따라 쌓았다. 돌담은 주로 막돌을 높이 1.5m 안팎으로 쌓았는데, 골목과 접하지 않은 옆집과의 경계에 담이나 축대를 만들 때 많이 사용하였다. 마을 입구에 있는 한옥에 둘러친 탱자나무 울타리가 돌로 쌓은 기단 위에 조성되어 있어 더욱 멋스럽다.","a":"의령 오운마을 옛 담장","c":"국가등록문화유산","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669524.jpg"},{"q":"마한의 왕궁이 있던 자리로 알려진 터에 있는 ○○○○○을 보수하기 위해, 1965년 해체하면서 탑을 받치고 있던 기단부와 1층 지붕돌 윗면에서 발견된 유물들이다. 발견된 유물들은 백제에서 통일신라에 이르는 시기의 것들로 판단된다. 기단부 윗면에 品자형으로 뚫린 3개의 구멍 중 동쪽에서는 광배와 대좌를 갖추고 있는 금동여래입상 1구와 불교 의식 때 흔들어 소리를 내던 청동방울 1개가 나왔고, 북쪽구멍에서는 향류(香類)가, 또 다른 구멍은 이미 도굴된 상태였다. 1층 지붕돌 윗면 중앙에 뚫려있는 2개의 구멍에서는 각각 연꽃 봉오리모양의 마개가 덮여있는 녹색의 유리사리병과…","a":"익산 왕궁리 오층석탑 사리장엄구","c":"국보","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612358.jpg"},{"q":"○○ 적성면 ○○○에 있는 후기구석기시대에서 초기철기시대에 걸친 유적이다. 남한강가 충적대지에 자리하고 있으며, 강을 끼고 있는 주위의 환경이 선사시대 사람들이 살기에 적당한 곳으로, 발견된 석기들은 다양하고 당시 만들었던 기술도 특징을 보이고 있다. 특히 후기구석기시대에서 볼 수 있는 돌날몸돌과 자루를 끼울 수 있도록 슴베가 달린 찌르개는 중국 화북지방, 시베리아 남부지방, 일본 열도 후기구석기시대 유적에서 나온 석기들과 비교할 수 있는 좋은 연구자료가 된다. 구석기시대 유적 주변에서 초기철기시대 집터가 발견되었는데, 집터의 생김새가 독특한 모양을 하고 있어 중원지…","a":"단양 수양개 유적","c":"사적","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626287.jpg"},{"q":"○○○는 신라말 고려초의 명승 진공대사가 다시 지은 유명한 사찰이다. 이곳에는 2구의 불상이 있는데 원래 광배(光背)와 대좌(臺座)를 모두 갖추고 있었으나 광배는 깨진 채 버려졌다. 높이 1.13m의 석조아미타여래좌상은 원만한 얼굴과 당당한 어깨로 현실적 사실주의가 잘 반영되어 있다. 옷은 왼쪽 어깨만을 감싼 형태이며, 손은 가볍게 주먹을 쥔 상태에서 손바닥을 위로 하고 양 손의 엄지 손가락을 맞대고 있다. 높이 1.17m의 ○○○○○은 단정한 얼굴과 안정된 신체의 형태로 석조아미타여래좌상과 같이 현실적 사실주의를 잘 나타내고 있다. 양 어깨를 감싼 옷은 얇게 빚은…","a":"영주 비로사 석조비로자나불좌상","c":"보물","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621927.jpg"},{"q":"광복 이후 어지러운 당시의 치안 상태를 잘 보여주는 시설물로 빨치산 활동과 경찰에 의한 공비토벌등 한국 현대사에서 나타난 혼란과정의 한 단면을 볼 수 있는 유구로 역사적 가치가 있음.","a":"임실 운암망루","c":"국가등록문화유산","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2031383.jpg"},{"q":"이 벽화는 1997년 1월 16일에 발견되었으며 현재는 보존처리 한 후 사찰박물관에 보관되어 있다. 화면은 중방부분이 휘어지면서 부분적으로 균열이 생기고, 자연적 또는 인위적으로 훼손된 부분이 많아 제 모습을 상당히 잃었으나 구도 및 색채 그리고 일부의 문양 등은 판별이 가능하다. 내용은 설법인(說法印)을 짓고 있는 중앙의 본존불을 중심으로 여러 권속들이 에워싸고 있는 도상으로, 남아 있는 화기를 통해 석가모니불이 영축산에서 『묘법연화경(妙法蓮華經)』을 설하실 때의 장면을 도해한 <영산회상도(靈山會上圖)>이다. 전반에 걸친 무거운 적·녹색 위주의 채색을 사용하여 다소…","a":"안동 봉정사 영산회상벽화","c":"보물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622274.jpg"},{"q":"○○ 동쪽에 있는 화왕산의 북쪽 봉우리로부터 서쪽으로 뻗은 야산의 골짜기를 에워싼 포곡식 산성이다. 쌓은 연대는 확실히 알 수 없으나, 신라 진흥왕이 대가야를 완전히 정복하고 이곳에 하주(下州)를 두었는데 그 때 이미 이 성이 존재한 것으로 보고 있다. 부근에는 가야 고분들이 많이 있어 연대추정의 자료가 되고 있다. 임진왜란(1592)과도 관계가 깊은 산성으로 알려져 있다. 둘레 1,9㎞로 산성으로서는 규모가 매우 큰 편이고 비교적 석축의 상태가 잘 남아있는 편이다. 삼국시대에 흔히 볼 수 있는 산성의 형태이며, 성의 앞면이 계곡 입구를 향하여 있는 것으로 보아 수비…","a":"창녕 목마산성","c":"사적","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628129.jpg"},{"q":"1995년 전남 구례군 마산면 황전리에 소재하고 있는 ○○○ 경내 ○○○○○의 해체보수작업을 하던 중 탑 내부에서 발견된 통일신라시대의 일괄 유물이다. 백지묵서다라니경, 청동불상범 외에 청동방울과 장식, 철제칼, 금속편, 수정 등 다양한 유물이 발견되었다. 이들 유물 중 백지묵서다라니경은 다라니경의 내용을 필사한 것으로, 고려시대 이전의 서적이나 기록이 거의 전해지지 않는 상황에서 통일신라기의 종이·글자체·문자 등 서지학적 혹은 불교에 대한 중요한 정보를 제공해 주는 귀중한 자료이다. 탑인은 한국 고대인쇄사에 있어서 초기단계를 알게 해주는 국내 유일의 실물자료이다.…","a":"화엄사 서 오층석탑 사리장엄구","c":"보물","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619843.jpg"},{"q":"○○○은 ○○○의 정전으로 신하들이 임금에게 새해 인사를 드리거나 국가의 큰 행사를 치루던 장소로 사용하였으며, 외국 사신을 맞이하던 장소로도 이용하였다. 조선 성종 15년(1484)에 지었는데, 임진왜란 때 불에 탄 것을 광해군 8년(1616)에 다시 지었다. 앞면 5칸·옆면 3칸 규모의 1층 건물로, 경복궁의 근정전과 창덕궁의 인정전이 2층 규모로 거대하게 지어진 것에 비해 궁궐의 정전으로서는 작은 규모이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이며, 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위뿐만 아니라 기둥 사이에도 있는 다포 양식…","a":"창경궁 명정전","c":"국보","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611755.jpg"},{"q":"구 곡성역은 2동, 1층 규모로 역사 건축면적 216.19㎡, 창고 건축면적 189.50㎡이다. 구 곡성역은 전라선로의 역사로 1933년에 건립되었으며 등록된 간이역중 규모가 큰편에 속하며., 1933년 10월 15일 보통역으로 영업 개시하였다. 1999년 전라선 복선화로 곡성역이 신축이전하면서 폐역되었다. 지붕형태는 박공이 양쪽에 설치되었으며, 전면은 입구에 배면는 사무실쪽에 배치되어 있다. 구조는 목조에 맞배지붕으로 2001년 등록전 보수시 지붕재료와 벽체 일부가 변형되었다. 내부에는 난방시설이 대합실과 사무실 사이에 위치하며 굴뚝이 지붕위에 조적되어 있다. 역사…","a":"구 곡성역사","c":"국가등록문화유산","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668917.jpg"},{"q":"<○○○○○>은 조선 중기 문신인 ○○○을 그린 ○○화이다. 선생은 선조 18년(1585) 문과에 급제한 뒤 평안감사, 공조판서 등을 역임하였다. 이 ○○화는 가로 93㎝, 세로 185㎝의 크기이고 의자에 앉은 모습을 그렸다. 머리에는 낮은 사모를 쓰고 붉은색의 관복을 입었으며, 두 손은 소매 안으로 마주 잡아 보이지 않는다. 옷의 옆트임 안쪽으로 보이는 속옷과 양쪽 어깨의 기울기를 달리해 안정되어 보이는데, 이러한 자세는 조선 중기 ○○화에 나타나는 특징이다. 그러나 얼굴에 있어 윤곽선의 농도를 다르게 하여 표현하는 방법은 조선 후기에 나타나는 수법으로 후대에 다시…","a":"이상길 초상","c":"보물","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618514.jpg"},{"q":"천체의 움직임을 관찰하던 신라시대의 천문관측대로, 받침대 역할을 하는 기단부(基壇部)위에 술병 모양의 원통부(圓筒部)를 올리고 맨 위에 정(井)자형의 정상부(頂上部)를 얹은 모습으로 높이는 약9m이다. 원통부는 부채꼴 모양의 돌로 27단을 쌓아 올렸으며, 매끄럽게 잘 다듬어진 외부에 비해 내부는 돌의 뒷뿌리가 삐죽삐죽 나와 벽면이 고르지 않다. 남동쪽으로 난 창을 중심으로 아래쪽은 막돌로 채워져 있고 위쪽은 정상까지 뚫려서 속이 비어 있다. 동쪽 절반이 판돌로 막혀있는 정상부는 정(井)자 모양으로 맞물린 길다란 석재의 끝이 바깥까지 뚫고 나와있다. 이런 모습은 19∼…","a":"경주 첨성대","c":"국보","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612759.jpg"},{"q":"고려시대 만들어진 종으로 1967년 경기도 ○○군 금사면 상품리에서 우연히 발견된 것으로, 크기는 길이 84㎝, 입지름 55㎝이다. 종을 매다는 고리인 용뉴는 한마리의 용이 고개를 들고 있는 모습이며, 소리의 울림을 돕는 용통은 6단의 마디로 구획하였고, 용통의 각 부분마다 덩굴무늬를 양각하였다. 종의 상단과 하단, 9개의 돌출된 모양의 연뢰를 둘러싼 사각형의 연곽에는 가늘게 연이은 구슬 모양의 띠를 돌리고, 그 내부에 모란 덩굴무늬를 장식하였다. 연곽내의 연뢰는 꽃으로 도드라지게 표현하였다. 종 몸체에는 천흥사종(국보)의 비천상과 달리 불상과 보살상을 번갈아가며 부…","a":"여주 출토 동종","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614649.jpg"},{"q":"○○○○○은 고식 수법을 잘 보여주고 있음. 온돌방 부분까지도 원기둥을 사용하고 부재의 규격을 크게 하였으며, 장식은 배제하여 엄격한 느낌을 주며, 여기에 지붕가구 세부와 공포 형식에서 절제미 등 미학적인 건축 양식과 조형미가 돋보임. ○○○은 서원의 보편적 가치를 지키면서도 지역적 특징과 고유한 특징을 간직하고, 건축적으로 미학적 가치가 뛰어나며 임란직후 창건된 조선 후기의 강당건축의 모범을 보임","a":"구미 금오서원 정학당","c":"보물","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122910545200.jpg"},{"q":"보천사는 수암사(水巖寺)라고도 전해지고 있으며, 통일신라시대 경덕왕 때 창건되었던 사찰이다. ○○은 절터의 북쪽 산기슭 계곡에 세워져 있고, 위아래 모두 8각형의 기본형을 충실히 따르고 있다. 정사각형의 바닥돌 위로 기단의 아래받침돌·가운데받침돌·윗받침돌을 올렸다. 아래받침돌은 2단으로 이루어져 있고 그 사이에 돌띠를 돌려 구분하였으며, 윗단에는 용과 구름무늬를 얕게 돋을새김하였다. 가운데받침돌도 8각으로 모서리마다 기둥 모양을 새긴 후, 면에 타원형의 조각을 두었다. 윗받침돌에는 2겹으로 16장의 연꽃잎을 조각하였다. 탑신은 각 모서리마다 기둥 모양의 조각을 두었고…","a":"의령 보천사지 승탑","c":"보물","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622679.jpg"},{"q":"○○○○○에 있는 ○○○○의 ○○로, 임진왜란때 승군(僧軍)으로 나선 ○○○○를 승군 대장 도총섭(都總攝)으로 임명한 교지와 정조가 ○○○○의 충절을 기리는 내용을 친히 적은 ○○○○화상당명 총 2점이다. ○○○○ 휴정(休靜, 1520∼1604)은 선조 25년(1592) 임진왜란이 일어나자 왕의 특명을 받아 팔도도총섭이 되어 73세의 노령으로 전국에 격문을 돌려 승군 1,500명을 모아 활약하는 등 전쟁에 공을 세웠다. 교지는 임진왜란 초 발급되었다가 화재로 소실된 ○○○○의 도총섭 교지를 만력 30년, 즉 선조 35년(1602)에 재발급한 것이다. ○○○○화상당명은…","a":"해남 대흥사 서산대사 유물","c":"보물","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619846.jpg"},{"q":"통일신라시대 모전탑 계열에 속하는 탑으로써, 모전탑은 전탑(전탑:흙으로 구운 벽돌로 쌓은 탑)을 모방한 것으로, 돌을 벽돌 모양으로 다듬어 쌓아 올린 것을 이른다. 기단(基壇)은 주사위 모양의 커다란 돌덩이 8개를 2단으로 쌓은 독특한 형태로 이루어져 있다. 기단 윗면에 1층 몸돌을 받치기 위한 1장의 평평한 돌이 끼워져 있는데, 남산리 석탑에 3단의 층급이 있는 것에 비하면 간략화된 것이다. 탑신부(塔身部)는 몸돌과 지붕돌이 각각 1장의 돌로 되어 있고, 1층 몸돌에는 큼직한 네모꼴 감실(龕室:불상을 모시는 방)을 얇게 파서 문을 표시하였다. 문의 좌우에는 1구씩의…","a":"경주 서악동 삼층석탑","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620160.jpg"},{"q":"○○○선생은 3·1운동 발발 직후 유림계를 대표하여 파리장서를 갖고 상해로 건너가 파리강화회의에 송부하고 대한민국 임시의정원 구성에 참여, 제2차 유림단사건 등에 관계하였다. 해방 후 친일유림들을 청산하여 유학의 기틀을 바로 세우고 성균관대학을 설립한 종교지도자이자 교육가로 활동한 인물로, 이곳은 선생의 애국정신을 기릴 수 있는 역사적·교육적 가치가 큰 곳이다.","a":"서울 김창숙 묘소","c":"국가등록문화유산","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667539.jpg"},{"q":"경주시 황남동 미추왕릉 지구에 있는 삼국시대 신라 무덤인 ○○○○의 북쪽 무덤에서 발견된 금 ○○○와 띠드리개(요패)이다. ○○○○은 남·북으로 2개의 봉분이 표주박 모양으로 붙어있다. 과대는 직물로 된 띠의 표면에 사각형의 금속판을 붙인 ○○○로서 길이 120㎝, 띠드리개 길이 22.5∼77.5㎝이다. 28장의 판(板)으로 만들어진 이 ○○○는 주위에 있는 작은 구멍들로 미루어 가죽같은 것에 꿰매었던 것으로 짐작된다. ○○○ 아래에 매달려 있는 13개의 띠드리개는 경첩으로 ○○○와 연결하였다. 이 ○○○와 띠드리개는 완벽한 상태로 출토되어 신라 당시의, 착용법과 띠…","a":"황남대총 북분 금제 허리띠","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612867.jpg"},{"q":"기영회란 기로회라고도 하며, 만 70세 이상의 2품 이상 원로 사대부로 구성된 모임을 말한다. 이 기영회의 모임 후에 이를 기념하기 위해 그린 그림이 ○○○○이다. 친목 모임인 기영회는 처음에는 주로 산이나 강가에서 열었으나 16세기 이후에는 건물 안으로 장소를 옮겼다. 이 그림은 조선 중기 국가의 원로들이 참석한 기영회 모임을 기념하여 그린 그림이다. 그림의 맨 윗부분에는 ○○○○라고 제목을 적고, 가운데에는 건물 대청에서 열리는 연회장면을 그렸으며, 맨 아래부분에는 모임에 참석한 사람들의 이름, 자, 호, 본관, 품계와 관직 등을 앉은 순서대로 차례로 적고 시문과…","a":"기영회도","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614769.jpg"},{"q":"북한산 기슭에 있는 ○○○○ 입구의 병풍바위에 얕은 홈을 파고 조각한 높이 3.02m의 여래입상이다. 불상의 어깨 좌우에 큰 4각형의 구멍이 있는 것으로 보아 마애불 앞에 목조가구가 있었던 것으로 보인다 민머리 위에는 상투 모양의 머리묶음이 큼직하게 솟아 있으며, 얼굴에서는 온화하면서도 중후한 인상을 풍기고 있다. 상체는 어깨가 벌어져 건장한 모습인데 U자형으로 넓게 트인 가슴사이로 내의와 군의의 띠매듭이 드러나고 있다. 옷은 양 어깨에 걸쳐 입고 있는데 신체에 비해 다소 두껍게 나타내고 있어서 새로운 특징을 보여주고 있다. 왼팔에는 겨드랑이 사이로 물결모양의 옷주름…","a":"서울 삼천사지 마애여래입상","c":"보물","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613560.jpg"},{"q":"예전 정의(성읍) 고을에서 '대장간'으로 사용하였다고 전하는 집이다. 19세기 후기에 지었다고 하며 고평오 가옥(국가민속문화유산) 맞은편 면사무소 관원들만 사용했다던 ‘남문통’이란 우물이 있던 앞쪽에 자리잡고 있다. 이 길은 객사에서 남문으로 이르는 길가로 정의 고을의 중요한 길목으로 알려져 있다. 이것은 대장간이 어느 마을에서나 그 마을의 중요한 지점에 자리잡고 있다는 점과 일치한다고 할 수 있다. 건물은 대문이 없고 안채(안거리)와 모로 배치한 모커리로 ㄱ자형의 단순한 배치를 이루고 있다. 안채는 문을 들어서면 마당을 앞에 두고 남향으로 서 있다. 가운데 대청마루…","a":"제주 성읍마을 대장간집","c":"국가민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1636021.jpg"},{"q":"이 ○○이 위치하는 산운마을은 북쪽의 금성산과 남쪽의 창이들 들판 사이에 자리잡고 있으며, 조선 명종 때 영천이씨가 들어와서 같은 성씨마을로 번성하였다. 마을에는 운곡당과 ○○○을 비롯하여 10여 채의 전통가옥이 남아 있으며, 운곡당은 ○○○을 지은 이가발의 형인 운곡(雲谷) 이의발(李義發)이 지은 것이다. ○○○은 조선 후기 ○○지방 양반의 집으로 살림채와 별당에 해당하는 안사랑채의 두 영역으로 이루어져 있다. 살림채는 대문채, 안채, 사랑채, 중문채로 되어 있는데, ‘−’자형 대문채를 들어서면 ‘ㄱ’자형 안채와 ‘ㄴ’자형 사랑채, 중문채가 합쳐서 전체적으로 튼 ‘…","a":"의성 소우당 고택","c":"국가민속문화유산","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635596.jpg"},{"q":"○○ 나성과 능산리 무덤들 사이 절터 서쪽의 한 구덩이에서 450여점의 유물과 함께 발견된 ○○의 향로이다. 높이 64㎝, 무게 11.8㎏이나 되는 대형 향로로, 크게 몸체와 뚜껑으로 구분되며 위에 부착한 봉황과 받침대를 포함하면 4부분으로 구성된다. 뚜껑에는 23개의 산들이 4∼5겹으로 첩첩산중을 이루는 풍경을 보여주고 있다. 피리와 소비파, 현금, 북들을 연주하는 5인의 악사와 각종 무인상, 기마수렵상 등 16인의 인물상과 봉황, 용을 비롯한 상상의 날짐승, 호랑이, 사슴 등 39마리의 현실 세계 동물들이 표현되어 있다. 이 밖에 6개의 나무와 12개의 바위, 산…","a":"백제 금동대향로","c":"국보","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612303.jpg"},{"q":"이 마을의 ○○은 대개 토석담으로 담 하부는 방형에 가까운 큰 자연석을 사용하여 대부분 메쌓기 방식으로 쌓았다. 그 위에는 하부의 자연석보다 작은 20cm내외의 돌을 담 안팎에 사용하여 진흙과 교대로 쌓아 올렸고, 대부분 ○○ 상부에는 한식기와를 이었다. 활처럼 휘어진 전통○○길이 전통고가와 어우러져 고즈넉하고 아늑한 느낌을 준다","a":"거창 황산마을 옛 담장","c":"국가등록문화유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669473.jpg"},{"q":"함춘원은 조선시대의 정원으로 지금의 ○○대학교 의과대학 부속병원이 위치한 곳이다. 『동국여지비고』에는 창경궁의 동쪽, 경희궁 개양문의 남쪽 등에 있는 궁궐의 정원 이름이 함춘원이라고 기록되어 있으나 그중 그 입지나 규모로 보아 가장 대표적인 것은 창경궁 동쪽의 것이다. 함춘원은 성종 15년(1484)에 창경궁을 짓고, 풍수지리설에 의해 이곳에 나무를 심고 담장을 둘러 그곳에 관계없는 사람의 출입을 금하였던 것에서 시작되었으며, 성종 24년(1493)년에 정식으로 이름이 붙여져 창경궁에 딸린 정원이 되었다. 연산군 때에는 함춘원 밖의 백성들의 집을 없애고 확장하였으며,…","a":"서울 경모궁지","c":"사적","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624741.jpg"},{"q":"○○○은 조상의 극락왕생을 빌기 위해 그린 불교그림이다. 이 그림은 가로 200㎝ 세로 237.5㎝ 크기이며 3단으로 화면구성을 하고 있다. 그림의 맨 윗부분에는 가운데 아미타삼존을 포함한 7여래와 극락세계로 영혼을 인도하는 인로왕보살 등을 그려 이상세계를 표현하였다. 특히 불·보살의 몸을 금가루로 칠했는데, 이는 다른 불화에서는 거의 그 예를 찾아볼 수 없다. 그림의 중간에는 산수(山水)를 배경으로 영혼이 극락으로 인도되길 기원하는 제사상을 차려 공양하는 모습이 그려져 있고, 아래부분에는 속세의 여러 장면이 생동감 있게 묘사되어 당시 풍속연구에 귀중한 자료가 되고…","a":"청룡사 감로탱","c":"보물","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616067.jpg"},{"q":"경상북도 안동 지방에서 의병활동을 전개한 ○○○○○이 사용하던 칼이다. ○○○은 1962년 건국훈장 독립장이 추서된 인물로 이 칼은 후손이 1985.1.24.독립기념관에 기증하였다. 칼에 “三寅劍”, 칼집에 “倡義劍”이라 각인되어 있으며 나무칼집은 후대에 제작된 것으로 추정된다. ○○○은 1896년 2월 유시연과 함께 영양·안동 지방의 의병을 모아 청량산에서 기병하였고 봉화와 영주를 점령하여 군수가 바치는 군기(軍器)로 무장하고 안동으로 진군하였으며 청송·의성·영덕·영해를 순방하며 의병 봉기를 촉구하였다. 1907년 고종이 직접 의병 봉기를 촉하는 밀지를 내리자 의병…","a":"의병장 김도현 칼","c":"국가등록문화유산","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668641.jpg"},{"q":"조선 후기에 태조 이성계(李成桂)의 관향(貫鄕)인 전주를 그린 지도이다. 전주부의 읍성과 주변의 산세, 내부의 관아 건물들을 산수화풍으로 그린, 회화식 지도의 대표작이다. 전주성 전체를 부감법으로 묘사하여 화면의 중앙에 배치하고 그 주변에 봉우리가 이어지는 모습을 그렸다. 읍성의 내부에는 관찰사의 청사인 선화당(宣化堂)을 비롯한 감영 건물과 부윤(府尹)이 집무하던 본관(本官), 객사(客舍)가 그려져 있다. 또, 태조의 영정(影幀)을 봉안했던 진전(眞殿)인 경기전(慶基殿)도 부각되어 있는데, 아직 조경묘가 세워지지 않은 모습이며 그 자리에 나무가 우거지고 백로 떼가 앉…","a":"전주지도","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614922.jpg"},{"q":"○○은 선사시대 사람들이 조개를 먹고 버린 조가비와 생활 쓰레기들이 쌓여 이루어진 것으로 조개더미 유적이라고도 하는데 당시의 생활 모습을 잘 보여주는 유적이다. 바닷가에서 떨어진 얕으막한 언덕에 조개더미가 분포되어 있으나, 유적이 이루어질 당시엔 바닷가에 있었을 것으로 보인다. 유적의 층위는 위로부터 겉흙층·조가비섞임층·회색찰흙층으로 되어있다. 회색찰흙층에서는 쇠를 녹여내던 쇠부리터가 나왔는데, 이것은 우리나라 최초로 발견된 고대 제철 관계유적이다. 출토된 유물은 토기·뼈와 뿔로 만든 도구·철기·바늘·가락바퀴·독무덤(옹관묘) 등이 있다. 이러한 유물의 특징으로 보아…","a":"부산 동래 패총","c":"사적","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625126.jpg"},{"q":"1927년 건립된 이 건물은 ○○○○○ 여사가 받은 생일 헌금으로, 건축을 전공한 남장로회 서로득(Swinehart) 선교사가 건축하였다. 좌우 대칭의 중복도형으로 정면 출입구에 설치한 아담한 돌출 현관인 포치가 인상적이다. 이 돌출 현관 위 삼각형의 박공지붕과 이를 받치는 투스칸 오더(Tuscan Order)의 원형 기둥은 다른 학교 건물에서는 볼 수 없는 독특한 것이다.","a":"광주 구 수피아여학교 윈스브로우 홀","c":"국가등록문화유산","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667915.jpg"},{"q":"조선 후기 전국의 군현을 회화식으로 그린 지도를 수록한 지도첩이다. 군현 지도뿐만 아니라 조선전도, 도별도와 중국도, 황성도, 북경궁궐, 왜국지도와 함께 주요 관방의 지도도 포함되어 있다. 원래 8첩이었으나 지금은 6책으로 되어 있다. 제1책 경기도, 제2책 해서전도·관서전도, 제3책 관동전도·북관전도, 제4책 서북피아양계전도, 제5책 영남전도, 제6책 호서전도, 제7책 호남전도, 제8책 팔도총도 등으로 구성되어 있다. 제4책의 서북피아양계전도와 제8책의 팔도총도는 대형전도이다. 지도에 수록된 내용은 군현 호구수 등의 통계를 볼 때 1748년(영조 24)~1750년(…","a":"해동지도","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614927.jpg"},{"q":"절에 행사가 있을 때 절 입구에 당(幢)이라는 깃발을 달아두는데, 당간(幢竿)이란 이 깃발을 달아두는 대(臺)를 말한다. ○○읍 ○○○은 ○○읍에서 순창행 도로를 따라 1㎞쯤 가다보면 논 한가운데에 높게 서 있다. 연꽃잎이 새겨진 돌 위에 당간을 세우고 양 옆에 기둥을 세워 지탱하고 있다. 당간은 가늘고 긴 8각 돌기둥 3개를 연결하고 연결부위에 철띠를 둘렀다. 꼭대기에는 쇠로 만든 둥근 보륜(寶輪:바퀴모양의 장식)이 있는데 풍경같은 장식물이 달려있고 위에는 철침이 솟아있다. 바로 옆에 세워져 있는 석비(石碑)의 내용으로 미루어, 현재의 이 ○○○은 조선 헌종 5년(…","a":"담양 객사리 석당간","c":"보물","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619216.jpg"},{"q":"청계 ○○의 ○○화로 크기는 가로 109㎝, 세로 142㎝이다. ○○은 조선의 학자로 중종 20년(1525)에 과거에 합격하여 이조판서까지 오른 인물이다. 모시바탕에 채색하여 그린 이 ○○화는 오른쪽을 바라보며 앉아 있는 모습으로 두 손은 소매 안에서 마주잡고 있다. 머리에는 높고 테가 넓은 전립을 썼으며 녹색의 옷을 입고 있다. 얼굴은 몇 개의 선으로만 처리했고 눈매는 매우 가늘다. 명상에 잠긴 듯한 얼굴과 전체적인 분위기가 학자로서의 면모를 암시하고 있다. 깔고 앉은 호랑이 가죽의 방석은 부피감이 없고 매우 평면적이지만 그림이 어색하지 않다. 묵선만 사용한 것이…","a":"김진 초상","c":"보물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622137.jpg"},{"q":"○○ 1935년, ○○○ 1930년, ○○ 1943년 건립된 ○○○○○는 을미개혁의 일환으로 공포된 소학교령에 따라 설립된 ○○ 최초의 근대식 공립학교이다. ○○은 근대 벽돌 건축의 조형미를 엿볼 수 있는 건물로, 당시 가장 품질 좋은 수입산 목재와 특수 벽돌을 사용하여 지었다고 한다. ○○○은 건물 내부에 기둥을 설치하지 않았으며, ○○은 각 교실마다 굴뚝을 설치하고 상인방과 하인방에 돌림띠를 둘러 장식하여 당시 학교 건물의 특징을 보여주고 있다.","a":"광주 서석초등학교 본관·별관·체육관","c":"국가등록문화유산","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667855.jpg"},{"q":"불감이란 불상을 모시기 위해 만든 집이나 방을 뜻하는 것으로, 일반적인 건축물보다는 그 규모가 작다. 다탑봉(多塔峰) 골짜기에 자리한 ○○○○○은 건물 밖에 만들어진 감실의 대표적 예이다. 그 이름에서도 알 수 있듯이 산의 정상에 이르는 동안 여러 기의 석탑과 불상을 볼 수 있다. 감실은 직사각형 모양으로, 양쪽 벽을 판돌로 막아두고 앞뒤를 통하게 하였다. 그 위는 목조 건축의 모양을 본떠 옆에서 보아 여덟팔(八)자모양인 팔작지붕처럼 다듬은 돌을 얹어놓았다. 감실 안에는 2구의 불상이 모셔져 있는데, 특이하게도 등이 서로 맞붙은 모습으로 흔히 볼 수 없는 예이다. 불…","a":"화순 운주사 석조불감","c":"보물","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619349.jpg"},{"q":"1948년에 명문(銘文)이 있는 신라 범종이 발견되어 주목되었던 선림원터에는 석탑을 비롯하여 석등·홍각선사탑비·석조부도 등이 전해지고 있으며, 이들 석조유물들은 대부분 쓰러져 있었으나 모두 복원되었다. 이 탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 전형적인 신라석탑으로, 법당터 남쪽의 원래 위치에 복원되었다. 여러 장의 돌로 탑의 토대를 만들고, 아래층 기단을 올려 각 면 모서리와 중앙에 기둥을 새겼다. 위층 기단 역시 각 면 모서리와 중앙에 기둥을 새겼는데, 한 면을 둘로 나눈 뒤 8부중상을 도드라지게 새겼다. 탑신은 몸돌과 지붕돌이 각각 한 돌로 되…","a":"양양 선림원지 삼층석탑","c":"보물","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616550.jpg"},{"q":"○○○○○는 고려 현종 12년(1021)에 창건된 절이다. 절이름 앞의 ‘봉선(奉先)’은 고려 현종(顯宗)이 불교의 교리를 전하기 위하여 절을 짓고자 하였으나 실천하지 못하고 돌아가신 아버지 안종(安宗)의 뜻을 받든다는 의미로 붙인 이름이다. 현재 절터에는 절의 창건에 관한 기록을 담은 비석만이 남아 있다. 갈비(碣碑)는 일반적인 석비보다 규모가 작은 것을 말하는데, 대개는 머릿돌이나 지붕돌을 따로 얹지 않고 비몸의 끝부분을 둥글게 처리하는 것이 보통이다. 하지만 이 비는 거북받침돌과 머릿돌을 모두 갖추고 있어 석비의 형식과 다르지 않다. 거북모습의 받침돌은 양식상의…","a":"천안 봉선홍경사 갈기비","c":"국보","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612203.jpg"},{"q":"직지사 대웅전 앞에 동·서로 서 있는 2기의 석탑으로, 원래 경북 ○○의 도천사터에 쓰러져 있던 것을 이 곳으로 옮겨 놓은 것이다. 두 탑 모두 각 부분의 양식이 같아서 1단의 기단(基壇)위로 3층의 탑신(塔身)을 올리고 있다. 여러 장의 넓적한 돌로 짜여진 기단은 4면의 모서리와 가운데에 기둥 모양의 조각을 두었다. 탑신의 각 층 몸돌과 지붕돌은 각각 하나의 돌로 이루어져 있으며, 각 몸돌에는 모서리마다 뚜렷한 기둥 모양의 조각이 새겨져 있다. 얇고 평평한 지붕돌의 밑면 받침으로 1·2층은 5단, 3층은 4단을 두었고, 수평을 이루던 처마는 네 귀퉁이에서 경쾌하게…","a":"문경 도천사지 동·서 삼층석탑","c":"보물","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621254.jpg"},{"q":"과대는 직물로 된 띠의 표면에 사각형의 금속판을 붙여 만든 ○○○를 말하며, 요패는 ○○○에 늘어뜨린 장식품을 말한다. 옛날 사람들은 ○○○에 옥(玉)같은 장식품과 작은칼, 약상자, 숫돌, 부싯돌, 족집게 등 일상도구를 매달았는데, 이를 관복에 적용한 것으로 보인다. 백제나 신라에서는 관직이나 신분에 따라 재료, 색, 수를 달리하여 그 등급을 상징하였다. 경북 경주시 노서동 소재 ○○○에서 출토된 신라시대 ○○ 과대 및 요패는 과대길이 109㎝, 요패길이 54.4㎝이다. 과대는 39개의 순○○ 판으로 이루어져 있고, 양끝에 ○○○을 연결시켜 주는 고리인 교구를 달았으…","a":"금관총 금제 허리띠","c":"국보","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612814.jpg"},{"q":"○○○는 고려 충목왕 1년(1345)에 세워졌다. 절 이름은 중국의 달마대사가 숭산 소림사에서 9년간 앉아 도를 닦았다는 옛 이야기를 기리는 뜻에서 지었다고 한다. ○○○○○은 17세기 이전에 지은 건물로 추정하고 있다. 규모는 앞면 3칸·옆면 2칸이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위와 기둥 사이에도 있는 다포 양식인데, 건물 옆면에는 공포를 배치하지 않았다. 건물 안쪽은 보 끝에 용머리를 조각해 놓았고, 기둥 윗부분에 설치된 건축 부재들은 각각 연꽃, 용의 몸, 용 앞발이 여의주…","a":"익산 숭림사 보광전","c":"보물","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618532.jpg"},{"q":"○○은 조선 14대 선조(宣祖)와 첫 번째 왕비 의인왕후 박씨(懿仁王后 朴氏), 두 번째 왕비 인목왕후 김씨(仁穆王后 金氏)의 능으로 ○○○○○에서 세 번째로 조성된 능이다. 능의 형식은 같은 능역에 하나의 ○○○을 두고 서로 다른 언덕에 봉분을 조성한 동원이강릉(同原異岡陵)이다. 원래 ○○ 능역에는 1600년(선조 33) 의인왕후의 유릉(裕陵)이 먼저 조성되었다. 이후 1608년(광해군 즉위) 선조가 세상을 떠나자 선조의 능인 ○○을 건원릉 서쪽(현 헌종 경릉)에 조성하였는데, 1630년(인조 8)에 능에 물이 차고 터가 좋지 않다는 상소에 따라 현 위치로 능을 옮…","a":"구리 동구릉 목릉 정자각","c":"보물","r":"경기도","s":"구리시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616223.jpg"},{"q":"ㅇ르네상스양식의 민족애국단체 회관으로 건립, ○○○○○ 교정안 해체복원(1985년) ㅇ 건립당시에는 민족애국단체인 “서북학회”의 회관으로 종로구 낙원동에 세워졌던 건물이다. 일제강점기에는 오성학교, 보성전문학교, 협성실업학교 등 민족계 학교의 교사로 사용되다가 1941년 ○○○○○ 설립자 유석창박사가 인수하였다. 광복 후에는 이 건물에서 각종 정치단체와 교육기관들이 창설되기도 하였으며 1946년에 ○○○○○의 모체인 조선정치학관이 창립되었다. 그 후 ○○○○○ 법인 사무실 등으로 사용되었다. 1977년 도시계획으로 철거해체되어, 주요 자재를 현 ○○○○○ 캠퍼스(모진…","a":"서울 건국대학교 구 서북학회회관","c":"국가등록문화유산","r":"서울특별시","s":"광진구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666896.jpg"},{"q":"○○○○○은 왕숙안(王叔安)이 전서(篆書)로 「봉○○○○○책(奉使朝鮮倡和詩冊)」이라 쓴 제전(題篆)과 ○○○ 본체 및 청(淸)나라 당한제(唐翰題)와 나진옥(羅振玉)이 쓴 발문(跋文)의 세 부분으로 구성되어 있다. 명(明)나라 봉사(奉使) 예겸(倪謙)과 집현전 학사(集賢殿 學士)인 성삼문(成三問), 신숙주(申叔舟), 정인지(鄭麟趾) 사이에 서로 나눈 ○○○를 모아 권축으로 만든 것을 광서(光緖) 을사년(乙巳年)에 개장한 것이다. 이 시권은 명(明)나라 한림원시강(翰林院侍講) 예겸이 경제(景帝, 1450∼1457 재위)의 등극을 알리는 조서(詔書)를 가지고 조선에 온 세…","a":"봉사조선창화시권","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614797.jpg"},{"q":"○○○○○에 모셔져 있는 불화로, 석가의 생애를 여덟 장면으로 나누어 묘사한 ○○○이다. ○○○의 여덟 장면은 석가모니가 도솔천에서 코끼리를 타고 사바세계로 내려오는 장면인 도솔래의상, 석가모니가 룸비니공원에서 마야부인의 옆구리를 통해 출생하는 모습을 그린 비람강생상, 태자가 성문 밖의 중생들의 고통을 관찰하고 인생무상을 느끼는 장면의 사문유관상, 부모의 반대를 무릎쓰고 출가하는 장면을 묘사한 유성출가상, 설산(雪山)에서 신선들과 수행하는 모습을 그린 설산수도상, 태자가 수행 중 온갖 유혹과 위협을 물리치는 수하항마상, 부처가 녹야원에서 최초로 설법하는 모습을 나타낸…","a":"쌍계사 팔상전 팔상탱","c":"보물","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622965.jpg"},{"q":"이 불경은 10세기 말에 인도 출신의 학승 시호(施護)가 번역한 초조대장경 가운데 하나이다. ‘○○○○○’라는 이름은 ‘덕망이 높은 지세보살(持世菩薩)의 주문’이라는 뜻이며, 수지(受持) 독송(讀誦)하면 무거운 죄도 소멸시킬 수 있으며, 소원을 성취할 수 있다고 설하고 있다. 각자(刻字)가 정교하고, 글자의 먹색 및 지질 등으로 보아 11세기 인출의 정각본으로서 초조판(初雕板)의 원형을 살필 수 있어 역사적 의미가 깊다. 권말에는 신역(新譯)할 때의 증의자(證義者), 철문(綴文), 필수(筆授), 증범문(證梵文), 증범의(證梵義), 윤문(潤文)자의 기록이 있어 그 당시…","a":"초조본 성지세다라니경","c":"보물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616145.jpg"},{"q":"고려시대에 쌓은 성으로 조선 세조 3년(1457)에 성을 확장했고, 임진왜란(1592) 후에 대대적인 보수 공사가 있었다. 돌을 쌓아 만든 것으로 둘레는 3,126척(약 940m), 높이는 9척(약 2.7m)이며 대포를 쏠 수 있는 성벽에 나온 포루가 3개이고, 우물이 20여 개 있었다고 한다. 성문은 4개로 동·서·남·북에 있었으나 현재는 모두 없어지고 북문터에 기초석만 남아있다. 1993년 남문터에 복원한 남고문이 있는데, 2층으로 된 누(樓)는 앞면 3칸·옆면 2칸이며, 지붕은 화려하다. 옆에서 보면 여덟 팔(八)자 모양인 팔작지붕으로 되어있어 ○○○○의 옛 모…","a":"나주읍성","c":"사적","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627148.jpg"},{"q":"○○○는 진흥왕 14년(553)에 의신조사가 창건하였고, 그 뒤 혜공왕 12년(776년)에 진표가 새롭게 고쳐 지었으며 그 뒤로 진표의 제자들에 의하여 미륵신앙의 중심도량이 되었다. ○○○ 경내에 있는 마애여래의상은 높이가 약 6m나 되는 큼직한 바위에 돋을새김으로 조각되어 있다. 보기 드물게 의자에 앉아 있는 모습으로 옆 바위에 조각된 지장보살과 함께 ○○○의 성격을 알려주는 미륵불이다. 불상의 머리는 바위에 새긴 것들에서는 보기 드물게 작은 소라 모양의 머리칼을 촘촘하게 새겼다. 둥글고 온화한 얼굴에는 크고 긴 코와 둥근 눈썹, 뚜렷한 눈두덩과 함께 두꺼운 입술이…","a":"보은 법주사 마애여래의좌상","c":"보물","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617004.jpg"},{"q":"이 차는 ○○자동차가 일본의 도요타 ○○○○를 국내에 들여와 조립‧생산한 모델이다. 사람들이 자가운전을 시작할 무렵인 1967년부터 1971년까지 2,005대를 생산하였는데, 연료가 적게 들어 주로 도시 중류층이 자가용으로 이용하였다. 공랭식 엔진을 장착하여 주행하다가 자주 쉬면서 엔진을 식혀야 했으며, ‘꼬마차’, ‘빨간차’, ‘왕눈이차’ 등의 애칭으로 불리었다. 현재 국내에 남아 있는 3대 가운데 이 차가 가장 오래되었으며, 최초의 국산 경차로 연료절약형 승용차의 첫 모델이라는 점에서 역사적 가치가 높다.","a":"신진 퍼블리카","c":"국가등록문화유산","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668121.jpg"},{"q":"○○○○○는 나무에 불상을 조각해서 만든 탱화인데, 탱화는 대개 천이나 종이에 그린 그림을 족자나 액자형태로 만들어 거는 불화를 말하지만 나무로 조각한 것이 특이하다. 크기는 가로 183㎝, 세로 181㎝로 거의 정사각형에 가까우며, 현재 전하고 있는 조선 후기의 목조 탱화 가운데 가장 간략한 배치구도를 가지고 있다. 화면은 크게 상하로 나누었는데, 하단에는 아미타불을 중심으로 오른쪽으로는 보현보살과 세지보살을, 왼쪽으로는 문수보살과 관음보살을 배치하였다. 상단에는 석가의 제자인 아난과 가섭을 중심으로 오른쪽으로 월광보살과 지장보살을, 왼쪽으로는 일광보살과 미륵보살을…","a":"남원 실상사 약수암 목각아미타여래설법상","c":"보물","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618375.jpg"},{"q":"○○○○의 병마절도사가 머물던 성으로, 조선 태종 17년(1417)에 쌓은 해발 45m 이하의 낮은 구릉을 이용해 골짜기를 두른 타원형의 성이다. 초기에는 성벽 위에서 담처럼 생겨 몸을 숨긴 채 총이나 활을 쏘는 시설인 여장을 비롯한 기본적인 시설만 갖추었다. 그 후 세종 때에 이르러 국방력 강화를 위해 성을 보호하고 공격력을 강화시키기 위해 옹성·적대·해자 등 여러 방어시설을 설치했다. 『동국여지승람』에 따르면 당시 성의 둘레는 3,723척(약 1.2㎞)이고, 높이는 12척(약 3.7m)이며, 성 안에는 우물·도랑·창고 등이 있었다고 한다. 조선시대 ○○○○ 병마절…","a":"울산 경상좌도병영성","c":"사적","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625379.jpg"},{"q":"19세기 초에 지은 것으로 보이는 초가로, 집의 뒷산이 좌우로 뻗어나와 감싸고 앞으로는 넓은 들판이 펼쳐지는 명당에 동남향으로 자리잡고 있다. 오른쪽 산자락에 울창한 소나무 숲과 연못을 조성하였고, 들판에 나무를 일렬로 심어 진입로를 조성하여 아늑함을 느끼게 한다. 안마당을 중심으로 안채와 사랑채가 나란히 배치되고 광채가 왼쪽·부엌이 오른쪽을 감싸고 있어 전체적으로 튼 'ㅁ'자 모양을 이루고 있다. 앞면 5칸·옆면 1칸반 규모의 안채는, 왼쪽부터 방 3개를 차례로 배치하였고 오른쪽이 부엌이다. 부엌과 'ㄱ'자로 연결되어 부엌광·헛간·외양간이 있다. 사랑채는 2칸의 사…","a":"예산 오추리 고택","c":"국가민속문화유산","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634303.jpg"},{"q":"작은 초가집으로 대문을 들어서면 북쪽으로 안채가 있고 서쪽으로 돼지막이 있다. 안채는 온돌방 2개와 큰 부엌으로 구성되어 있는 남향집이다. 방문은 큰방·작은방의 크기가 다르며, 큰방의 문 옆에는 머릿창이 하나 더 달려있다. 이것은 남해안 지방에서 자주 볼 수 있는 구조이다. 방문 앞에는 크기나 형태가 맞지 않는 미묘한 모습의 뜰마루가 있다. 부엌은 뒷벽을 뒤 퇴칸의 기둥을 따라 쳤기 때문에 한결 넓어졌다. 그리고 벽의 윗부분에 뚫어 놓은 살창으로 빛이 들어와 비교적 밝은 편이다. 부엌의 동쪽 마당에는 장독대가 있고 나머지의 넓은 터는 채소밭이다. 훈련된 목수에 의해…","a":"순천 낙안읍성 들마루집","c":"국가민속문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634580.jpg"},{"q":"○○○에서 후원으로 가는 길은 현재는 내의원으로 불리는 건물군을 왼쪽으로 끼고 담으로 좌우를 막은 통로를 이용하게 된다. 이 통로는 약간 오르막길로 되어 있으며 길은 좌측으로 꺾이면서 내리막길로 변하는데 그 지점에서 부용지 일대의 모습이 내려다보인다. 3면이 경사지이며 경사가 모이는 한가운데에 방형(方形)의 연못인 부용지가 있다. ‘부용(芙蓉)’은 ‘연꽃’을 뜻하는데, ○○○ 후원의 대표적인 방지(方池)이다. 동서 길이가 34.5m,남북 길이가 29.4m에 이르는 방형의 연못이다. 부용지의 네모난 연못과 둥근 섬은 ‘하늘은 둥글고 땅은 네모나다’는 천원지방(天圓地方)…","a":"창덕궁 부용정","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615027.jpg"},{"q":"<개요> ㅇ 조선조부터 일제강점기를 거쳐 1960년대까지 ○○○의 업무를 담당하는 청사가 서울에 소재 하고 있었다. 수도에 인접해 있는 ○○○의 행정관청을 중앙정부의 지근거리에 두고 감독, 관리 하려 하였던 관행이 광복 후에도 당분간 이어져 왔던 것이다. ㅇ 1963년에 ○○○○을 수원으로 이전하기로 결정하고 청사설계, 시공을 거쳐 1967년 6월에 준공 하였다. 전국적으로 비슷한 시기에 관공서 청사건축 붐이 일었는데 이 건물이 전형(典型)이 되기도 하였다. ㅇ 설계자는 김희춘과 나상진의 공동으로 기록되어 있다. 팔달산 기슭에 수원화성의 각 시설물 들을 존중하며 수평…","a":"경기도청사 구관","c":"국가등록문화유산","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017081415331600.jpg"},{"q":"○○○○은 퇴계 이황 선생이 ○○○당을 짓고 유생을 교육하며 학문을 쌓던 곳이다. 퇴계 이황(1501∼1570) 선생은 주자학을 집대성한 유학자로 우리나라 유학의 길을 정립하면서 백운동서원의 운영, ○○○당의 설립으로 후진양성과 학문연구에 전력하였다. 중종, 명종, 선조의 지극한 존경을 받았으며 일본 유학의 부흥에도 큰 영향을 주었다. ○○○○은 조선 선조 7년(1574) 그의 학덕을 추모하는 문인과 유생들이 상덕사란 사당을 짓고 전교당 동·서재를 지어 서원으로 완성했으며, 선조 8년(1575) 국왕에게 이름을 받아 사액서원이 되면서 영남지방 유학의 중심지가 되었다.…","a":"안동 도산서원","c":"사적","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627758.jpg"},{"q":"○○○○○는 조선시대 만들어진 높이 25.0㎝ 아가리 지름 5.3㎝ 밑지름 7.7㎝의 병으로 청화○○운룡문병(보물)과 한 쌍으로 발견되었다. 아가리는 밖으로 약간 벌어지고 몸체 아래쪽이 풍만하며, 목이 조금 길어 날렵하면서도 단아한 모양을 보이는 병으로, 궁중의 연례에 사용된 술병으로 보인다. 몸통 전면에 구름 속에서 3개의 발톱을 세우고 수염을 나부끼면서 여의주를 잡으려는 용을 그렸다. 이런 유형의 그림은 중국 명나라 전기 청화○○의 용무늬에서 따 온 것으로, 조선 중기 이후에 나타나는 표현과는 달리 매우 사실적이다. 다른 문양은 없이 굽다리 부분에만 한 줄의 가로…","a":"백자 청화운룡문 병(1984-1)","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613916.jpg"},{"q":"<○○○○○>은 오사모에 단령을 입고 의자에 앉아 있는 전신좌상이다. 가슴에는 모란과 운안(雲雁) 문양을 한 흉배가 부착되어 있으며, 삽금대를 두르고 있어 1603∼14년에 정이품의 대사헌과 이조판서를 지낸 ○○○의 당시 품계와 정확히 일치한다. 안면은 좌안 7분면이며 몸체는 8분면 정도이다. 공수자세를 취한 단령 사이로 흰 창의의 소매가 보이며, 의자의 손잡이는 인물의 양 편으로 뻗어 있는데, 이러한 표현형식은 이중로영정 등 정사(靖社) 공신상 보다는 앞선 형식이다. 바닥에는 채전이 깔려 있고 족좌대(足座臺) 위에는 팔자형(八字形)으로 벌린 흑피혜(黑皮鞋)가 보인다…","a":"선조어서사 송언신 밀찰첩 및 송언신 초상 - 송언신 초상","c":"보물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615899.jpg"},{"q":"이 책은 조선 중기의 문신(文臣) 김정국(金正國)이 ○○○○을 요약하여 4권으로 편집한 후, 그 당시 나주 관청에 보관해 있던 금성목활자(錦城木活字)를 기본으로 하고 부족한 것은 새로 보충하여 ○○○○○ 400부를 간행한 것이다. 권말에 있는 김정국의 후서에 보면, 그 인출경위(印出經緯)는 절요자(節要者) 김정국(金正國)이 중종(中宗) 33년(1538) 여름 호남관찰사(湖南觀察使)의 명(命)을 받고 부임(赴任)한 이후, 도사(都事) 김회백(金晦伯)과 의논하여 금성(錦城)인 나주목(羅州牧)에 있던 목활자(木活字)에 부족자(不足字)와 결자(缺字)를 새겨 보완하여 그해 가…","a":"성리대전서절요(2004)","c":"보물","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617205.jpg"},{"q":"○○○○○는 경주시 황남동 미추왕릉 지구에 있는 삼국시대 신라 무덤인 ○○○○에서 발견된 ○○○와 띠드리개(요패)이다. ○○○○은 2개의 봉분이 남·북으로 표주박 모양으로 붙어 있다. ○○○ 길이는 99㎝이며, 소형 띠드리개 길이 18∼22㎝, 대형 띠드리개 길이 79.5㎝의 크기이다. 이 ○○○는 문양이 뚫린 사각형의 판과 나뭇잎 장식 34매를 연결하였다. 나뭇잎 장식 아래에는 7줄의 띠드리개가 있는데, 1줄은 길고 6줄은 짧다. 이 ○○○의 좌우 끝에는 서로 연결할 수 있는 띠고리(교구)가 달려 있다.","a":"황남대총 남분 금제 허리띠","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621308.jpg"},{"q":"○○은 조선 4대 세종(재위 1418∼1450)과 부인 소헌왕후 심씨(1395∼1446)의 무덤이다. 세종은 정치·경제·사회·역사·문화 등 각 분야에서 조선시대 문화의 황금기를 이룩한 왕이다. 세종 28년(1446)에 소헌왕후가 죽자 헌릉 서쪽 산줄기에 쌍실 무덤인 ○○을 만들었다. 동쪽 방은 왕후의 무덤으로 삼고, 서쪽 방은 왕이 살아 있을 때 미리 마련한 무덤으로 문종 즉위년(1450)에 왕이 죽자 합장하였다. 조선왕릉 중 최초로 한 봉우리에 서로 다른 방을 갖추고 있는 합장무덤을 하고 있다. 무덤배치는 『국조오례의』에 따라 만든 것으로, 조선 전기 무덤배치의 기…","a":"여주 영릉과 영릉","c":"사적","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625543.jpg"},{"q":"○○○○○는 연산군 때의 학자인 화산 ○○선생의 종손가에 대대로 전해오는 문서들이다. ○○는 성종 때 문과에 합격하였고, 중국어를 잘하여 요동에 질정관으로 다녀오기도 하였다. 후에 도승지, 충청도관찰사를 거쳐 동지중추부사에 이르렀는데, 연산군 10년(1504)에 갑자사화에 연루되어 평해로 귀양한 뒤 극형을 당하였다. 중종반정이 있은 후 우참찬에 추증되면서 억울하게 되집어 쓴 누명을 벗게 되었다. 문서는 2건으로 하나는 「한성부황화방소재가대매매문서」이며, 다른 하나는 「재산양도문서」이다. 이 두 문서는 조선 전기의 경제 및 가족관계사를 연구하는데 중요한 자료로 평가된다…","a":"권주 종가 고문서","c":"보물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621181.jpg"},{"q":"○○ 시가지 중심에 자리잡고 있는 탑이다. 조선 인조 때 이곳의 현감이었던 유정립이 인조반정으로 파직당하고 낙향하여 이 탑 부근에 집을 세우려고 터를 닦다가 ‘충원사(忠圓寺)’라는 글이 새겨진 그릇을 발견하여, 충원사 내에 속하였던 것이 아닐까 추측된다. 한국전쟁 때 심한 손상을 입어 보존 상태가 좋지 않은 데다 기단의 일부가 지하에 파묻혀 있었는데, 지난 2000년에 시행된 전면적인 보수공사로 기단부의 제 모습을 찾게 되었다. 이 석탑은 아랫부분을 발굴 조사한 결과 2층기단 위에 7층의 탑신이 놓여진 것으로 확인되었다. 탑의 받침대 역할을 하는 윗층 기단도 탑몸돌에…","a":"춘천 칠층석탑","c":"보물","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616253.jpg"},{"q":"당나라 승려 현각이 지은 선종(禪宗)의 지침서로 각 구절에 송나라 남명선사 법천이 그 뜻을 구체적으로 밝힌 책이다. ○○○○○는 고려 고종 26년(1239)에 최이(崔怡)가 이미 간행한 금속활자본을 견본으로 삼아 다시 새긴 것 중 하나가 전해진 것이다. 닥종이에 찍은 목판본으로 크기는 세로 27.5㎝, 가로 16.6㎝이다. 책 머리부분에는 1077년에 오용천용(吳庸天用)이 지은 글이, 끝부분에는 1076년에 축황(祝況)이 판을 새길 때 지은 글이 실려 있다. 그 뒤에 최이가 선종에 있어 ‘○○○’가 중요함에도 불구하고 전해지지 않자 금속활자본을 거듭 새겨냄으로써 후대…","a":"남명천화상송증도가(1984)","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613823.jpg"},{"q":"이 아미타불상은 최근(2004년) 발견된 복장물 <아미타불상중수 봉함판>의 수보묵서명(修補墨書銘)에 의해 고려 충렬왕 6년(1280) 불사를 위해 특별히 설립된 승재색(僧齋色)의 주관 하에 내시 시흥위위(內侍試興威衛)의 장사(長史) 송(宋)씨가 보수를 담당한 것임이 밝혀졌다. 따라서 이 불상의 제작연대가 중수연대인 1280년보다 앞선 시기라는 것을 알 수 있다. 불사를 주관한 승재색은 고려 충렬왕 무렵에 설치되어 경전의 간행, 사찰의 중수, 불상의 개금과 보수, 불교제의 등을 담당하던 관부로 생각되며, 위의 아미타불상 중수는 현재까지 발견된 승재색의 불사활동 관련 자…","a":"서산 개심사 목조아미타여래좌상","c":"보물","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2021102909225500.jpg"},{"q":"석가가 영축산에서 설법하는 장면을 그린 ○○○○○으로, 괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞 뜰에 걸어놓고 예배를 드리는 대형 불교그림이다. 이 괘불은 길이 10.50m, 폭 8.97m로 본존불인 석가불은 중앙에 화면 가득 그리고 석가불 좌우로 문수보살과 보현보살을 배치하였으며, 그 뒤로 다보여래와 아미타여래, 관음보살, 세지보살 등의 4보살이 서 있는 7존 형식구도를 이루고 있다. 각 존상들은 둥근 얼굴에 원만한 체구를 지니며 뺨과 눈자위, 턱밑, 손과 발은 옅은 분홍색으로 처리해 밝아 보인다. 주로 붉은색과 녹색을 사용하였고 연한색을 넣어 경쾌함…","a":"내소사 영산회 괘불탱","c":"보물","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618676.jpg"},{"q":"○○○○○는 선조 때의 문신인 ○○○이 1583년에서 1587년 사이에 관원으로서 참여했던 계 모임을 그린 6폭의 그림이다. ‘괴원장방○○○’(槐院長房契會圖,1583년경), ‘봉산○○○’(蓬山契會圖,1583년), ‘태상○○○, ‘예조낭관○○○’(禮曹郎官契會圖,1586년), ‘형조낭관○○○’(刑曹郎官契會圖,1586년), ‘미원○○○’(薇垣契會圖,1587년)로 구성되어 있는데, 봉산○○○, 태상○○○, 형조낭관○○○는 16세기 전반 안견파의 편파구도 산수의 전통을 토대로 경물들의 분리가 확대된 변화를 보여준다. 괴원장방○○○, 예조낭관○○○는 서호계 야외○○○의 특징을…","a":"정사신 참석 계회도 일괄","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614833.jpg"},{"q":"1935년에 건립된 “○○○○○”는 일제강점기 한센병 환자들의 인권유린 현장을 간직하고 있는 교도소 건축으로 건립당시 원형이 잘 간직되어 역사적, 건축사적 가치가 높다.","a":"고흥 순천교도소 구 소록도지소","c":"국가등록문화유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669043.jpg"},{"q":"○○○ 법당에 모셔져 있는 목불좌상으로 1978년 불상 몸에 다시 금칠을 할 때 발견된 기록을 통해 고려 공민왕 11년(1362)을 하한으로 아미타불상이 조성되었음이 밝혀졌다. 얼굴은 단아하고 엄숙한 표정이며 무게있는 몸은 단정하고 앞으로 약간 숙여져 있다. 양 어깨를 감싸 흘러내린 옷은 가슴에서 매는 띠매듭이 사라지고, 3줄의 옷주름이 묘사되어 특징적이다. 전체적으로 고려 후기를 대표할 만한 뛰어난 작품이다.","a":"화성 봉림사 목조아미타여래좌상","c":"보물","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615901.jpg"},{"q":"○○○○○은 ○○군 도곡마을(가마골)에서 뒤편의 야산을 배경으로 전면에 들이 펼쳐진 지점에 남향으로 입지하며, 임진왜란 때 큰 공을 세운 박의장의 아들 박선이 형인 박유를 위하여 1644년에 초창하였음 ○ 17세기 이후부터 나타나는 안마당의 확장과 사랑채의 돌출, 사당 공간의 높은 독립성 등 배치 유형, 지역의 토착적 특징을 잘 보여주는 안채와 사랑채의 공간구성 등에서 17세기 사대부 주거건축 정체와 지역적 특성을 보여주고 있으며, 안채 창문 중간의 설주 흔적이나 사랑 대청의 파련대공 등에서 조선 중기의 건축 기법이 나타남 ○ 집안과 관계된 문헌자료가 잘 보존되어 있…","a":"영덕 무안박씨 무의공파 종택","c":"국가민속문화유산","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2016103113340500.JPG"},{"q":"이 건물은 1928년에 경성재판소로 건립된 법원 건물로, 광복 후 ○○○○○로 사용되었으며, 현재 ○○시립미술관으로 사용되고 있다. 일제 강점기에 우리나라 침탈 기반 시설로서 일본이 지은 법원 건물로, 당시 총독이던 사이토 마코토의 글씨로 확인되는 “定礎 昭和二年十一月 朝鮮總督子爵齋藤實 齋藤實” 기록이 새겨진 정초석이 남아 일본이 자행했던 한국 침탈의 뼈아픈 역사를 증언하고 있다. ○○시립미술관으로 기능을 바꾸면서 전면 현관부를 제외하고는 모두 새롭게 신축됨에 따라, 원형대로 남은 전면 현관부만 국가등록문화유산으로 등록하여 보존되고 있으며, 이는 ‘구 ○○○○○’의…","a":"서울 구 대법원 청사","c":"국가등록문화유산","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667038.jpg"},{"q":"극락보전 안쪽 벽에 그려진 벽화로 삼존불화, 아미타래영도를 포함하여 총 29점이다. 지금은 모두 해체되어 보존각에 보관ㆍ진열되어 있다. 이 벽화는 삼존불화, 아미타래영도, 오불도 2점, 관음보살도를 비롯한 보살도 5점, 주악비천도 6점, 연화당초향로도 7점, 보상모란문도 5점, 당초문도 1점, 입불도 1점 등으로 극락보전 안쪽벽을 장식하고 있었다. 삼존불화는 동쪽벽 중앙에 그려져 있던 그림으로, 가로로 긴 화면 가운데에 설법하고 있는 듯한 모습의 본존불을 그리고 좌우로는 서있는 모습의 보살상과 여섯 비구를 배치하였다. 배경으로는 바위산을 그려 넣었다. 본존불의 얼굴은…","a":"무위사 극락전 내벽사면벽화","c":"보물","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619671.jpg"},{"q":"왕실이 후원한 미술교육기관인 서화미술원에서 교육받은 대표적 신진 화가인 김은호에 의해 1920년경 제작되어 ○○○에 부착된 벽화로, 채색 화조화의 전통을 계승하고 있으며, 형상의 표현과 기술묘사에 충실하여 화려한 구성을 담고 있다. 궁중 벽화로는 다른 5점과 더불어 유일하게 현존하고 있으며, 단순한 장식이 아닌 전각의 기능과 연계되어 추락한 왕실의 안녕 및 권위의 회복, 왕실의 역량을 재확인하는 길상적, 상징적 의미를 갖고 있어 역사적, 예술적 가치가 있다. 다만 제작자인 김은호는 「일제강점하 반민족행위 진상규명에 관한 특별법」에 따른 친일반민족행위진상규명 보고서에…","a":"창덕궁 대조전 백학도","c":"국가등록문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667055.jpg"},{"q":"고려 강종(재위 1211∼1213)의 부인인 원덕태후 유씨의 무덤이다. 원덕태후는 고종의 어머니로 강종 1년(1212)에 왕비가 되고 연덕궁주라 하였다. 뒷날 원덕태후는 추대되고 1253년에 정강의 시호가 더해졌는데, 언제 사망하였는지는 알려지지 않고 있다. 석물은 없어졌고 봉분과 무덤을 둘러싼 담도 무너졌던 것을 1974년에 지금의 모습으로 손질하여 고쳤다. <br/><b>※(○○ → ○○○○)으로 명칭변경 되었습니다. (2011.07.28 고시)</b>","a":"강화 곤릉","c":"사적","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625315.jpg"},{"q":"○○○는 신라 진흥왕 14년(553)에 인도에서 공부를 하고 돌아온 승려 의신이 처음 지은 절이다. ○○○○○은 우리나라에 남아 있는 유일한 5층 목조탑으로 지금의 건물은 임진왜란 이후에 다시 짓고 1968년에 해체·수리한 것이다. 벽 면에 부처의 일생을 8장면으로 구분하여 그린 팔상도가 그려져 있어 ○○○이라 이름 붙였다. 1층과 2층은 앞·옆면 5칸, 3·4층은 앞·옆면 3칸, 5층은 앞·옆면 2칸씩으로 되어 있고, 4면에는 돌계단이 있는데 낮은 기단 위에 서 있어 크기에 비해 안정감을 준다. 지붕은 꼭대기 꼭지점을 중심으로 4개의 지붕면을 가진 사모지붕으로 만들…","a":"보은 법주사 팔상전","c":"국보","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612155.jpg"},{"q":"중국 당나라 현각선사(647∼713)가 선종의 요결(要訣:긴요한 뜻)과 수선(修繕)을 깨달은 내용을 찬술한 것이다. 우리나라에는 고려 때 회암사의 혜근화상이 처음 입수하였고, 그의 제자 훤선이 이방직의 도움을 받아 고려 우왕 7년(1381) 봄 충주 청룡사에서 출판하였다. 조선 성종 3년(1472) 인수대비가 세조, 예종, 의경왕의 명복을 빌고, 정희대왕대비, 주상전하와 왕비전하의 만수무강 등을 기원하기 위해 여러 불경을 간행하였을 때, 이 책 200부를 인출하였다. 목판과 활자판을 같이 적용하여 간행한 인쇄물이 원형 그대로 전래된 것으로, 고려말과 조선초의 불교사…","a":"선종영가집(1999)","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614747.jpg"},{"q":"무장사터는 ○○시에서 상당히 먼 거리에 있는 깊은 산골에 있으며, 문무왕이 삼국을 통일한 후 병기와 투구를 매장한 곳이라는 뜻으로 ‘무장사’라는 이름이 붙여졌다. 즉 병기가 필요없는 평화스러운 시대를 열겠다는 문무왕의 결연한 의지가 이 절을 창건하는데 큰 힘이 되었고, 또한 절 안에 3층석탑을 세우는 계기가 된 것이다. 이 탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 전형적인 신라석탑의 양식이다. 아래층 기단은 각 면마다 모서리기둥과 가운데기둥 2개를 새겼고, 윗층 기단은 동그란 안상(眼象)을 각 면에 2개씩 조각하였다. 탑의 중심부분인 탑신부는 몸돌과…","a":"경주 무장사지 삼층석탑","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620310.jpg"},{"q":"신라 30대 문무왕(재위 661∼681)의 무덤이다. 동해안에서 200m 떨어진 바다에 있는 수중릉으로, 신라인들의 창의적인 생각을 엿볼 수 있는 곳이다. 문무왕은 아버지인 태종 무열왕의 업적을 이어받아 고구려를 멸망시키고, 당의 침략을 막아 삼국통일을 이루었다. 또한 병부, 창부 등 중앙관청을 창설하였고, 지방통치를 위한 5소경제도와 9서당 10정의 군사제도의 기틀을 마련하는 등 국가 체제 완성의 기초를 제공하였다. 대왕암은 자연 바위를 이용하여 만든 것으로 그 안은 동서남북으로 인공수로를 만들었다. 바닷물은 동쪽에서 들어와 서쪽으로 나가게 만들어 항상 잔잔하게 하…","a":"경주 문무대왕릉","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627740.jpg"},{"q":"단정한 비례의 ○○○○으로 윗면은 편평하며 가장자리에서 8각 형태의 단을 이루었다. 그리고 밑면의 각 모서리에는 작은 굽다리를 8개 세웠다. 윗면의 중앙부에 물구멍을 뚫고 옆면의 한 모서리에는 주구(注口)를 붙였다. 윗면에 청화와 철화기법을 사용하여 나비를 그렸으며 옆면에도 청화와 철화기법을 번갈아 가며 사용하여 칠언절구(七言絶句)를 써 넣었다. 유색은 엷은 청색을 띠는 맑은 투명유로서 광택은 은은하고 빙렬이 없다. 청화·철화문양의 필치가 뛰어나고 칠언절구의 시가 연적의 문양, 형태와 함께 잘 어우러져서 18세기 선비문화의 일단을 보여주는 수작이라 할 수 있다.","a":"백자 청화철화‘시’명나비문 팔각연적","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614858.jpg"},{"q":"○○○○○는 경주시 황남동 미추왕릉 지구에 있는 삼국시대 신라 무덤인 ○○○○에서 발견된 ○○○○○이다. ○○○○은 2개의 봉분이 남·북으로 표주박 모양으로 붙어 있다. 이 ○○○○○는 남쪽 무덤 널(관) 밖 머리쪽의 껴묻거리 구덩이(부장갱) 안에서 발견된 것으로, 길이 35㎝이다.","a":"황남대총 남분 은제 팔뚝가리개","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621312.jpg"},{"q":"흰 돌을 사용하여 쌓은 성이 마치 시루를 올려놓고 시루테를 바른 듯 하다고 하여 시루메산성이라고도 부르는 백제 산성이다. 성왕 16년(538) 수도를 사비로 옮기고 나서 수도를 보호하기 위해 쌓은 것으로 추정된다. 둘레는 약 600m이고 높이는 2∼3m 정도이다. 일부 무너진 곳이 있지만 성의 남쪽부분은 비교적 잘 남아 있고, 특히 서쪽·남쪽·북쪽에 각각 문이 있던 흔적이 남아있다. 성벽은 자연 지세를 이용하여 쌓았다. 성 안에는 백제토기와 기와조각이 많이 남아 있으며 동쪽에는 우물터가 있다. 은산면에 있는 이중산성, 서쪽의 옥녀봉산성과 서로 바라 보면서 연결 되어있…","a":"부여 증산성","c":"사적","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626557.jpg"},{"q":"누에고치모양처럼 남북으로 길게 누워 낮은 구릉을 이루는 이 산은 신라 실성왕 12년(413)부터 신성하게 여겨져 성역으로 보존되어 온 곳이다. 기록에는 ‘왕이 ○○에 상서로운 구름이 서린 것을 보고 신하들에게 신령이 하늘에서 내려와 노는 곳이니 당연 복을 주는 지역이다. 이제부터는 ○○의 나무 한 그루도 베지 말라’는 명령을 내렸다고 한다. 7세기부터는 불교의 성스러운 산으로 왕실에 복을 주는 장소로 변하기 시작하였다. 선덕여왕의 유언에 따라 만든 여왕의 능을 비롯하여 신라 향가의 현장인 사천왕사지, 문무왕의 화장터로 여겨지는 능지탑, 바위에 부처를 새긴 마애불, 구…","a":"경주 낭산 일원","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627750.jpg"},{"q":"고종 광무 2년(1898)에 준공한 우리나라 최초의 본격적인 개신교 교회건물이다. 본래는 십자형으로 115평이었으나 1926년 증축 때 양쪽 날개부분을 넓혀서 현재는 175평의 네모난 모양을 이루고 있다. 원래 건물은 그대로 두고 양 날개 부분만 늘려지었기 때문에 건물의 원래모습에는 손상이 없다. 벽돌쌓기를 하였으며, 곳곳에 아치형의 창문을 내어 고딕양식의 단순화된 교회당 모습을 이루고 있다. 돌을 다듬어 반듯하게 쌓은 기단은 조선시대 목조 건축의 솜씨가 배어있어 주목된다. 이 교회당의 종은 장식없는 내부 기둥들의 겉모습과 함께 소박한 분위기를 지니기 있다. 소박한…","a":"서울 정동교회","c":"사적","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624797.jpg"},{"q":"임진왜란(1592)과 병자호란(1636)을 겪은 후 잇따른 외침에 대비하기 위해서 세워진 성이다. 성은 내성·중성·외성을 각각 다른 시기에 쌓았고, 성 안에는 별장을 두어 항상 수호케 하였다. 하양, 신령, 의흥, 의성, 군위의 군영과 군량이 이 성에 속하며 ○○도호부도 이 산성내에 있었다. 내성은 인조 18년(1640)에 관찰사 이명웅의 건의로 쌓았으며, ○○도호부가 이 안에 있었다. 중성은 영조 17년(1741)에 관찰사 정익하가 왕명을 받아 쌓은 것으로 방어를 위한 군사적 목적이 크다. 중요시설은 내성 안에 있으며, 중성에는 4개 고을의 창고가 있어 비축미를 보…","a":"칠곡 가산산성","c":"사적","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627821.jpg"},{"q":"이 건물은 별량지소 금융조합이 설립되면서 금융 업무의 하나인 보관 업무를 하려고 건립한 ○○이다. 목재 트러스 지붕 구조로, 건물 내부 중간에 기둥을 설치하지 않아 공간의 활용성을 높였으며, 외벽은 목재 널판에 골함석으로 마감하였고, 지붕창을 설치해 채광과 환기가 원활하도록 하였다. 곡창지대인 ○○ 지역에서 생산된 쌀을 반출해 가는 데 선봉적 역할을 했던 일제강점기 수탈의 역사를 증언하고 있다.","a":"순천 별량농협 창고","c":"국가등록문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668954.jpg"},{"q":"1951년 건립된 이 건물은 ○○○○○으로 건립되었으며, 지금은 신한은행 대전역 금융센터로 사용되고 있다. 지상 2층 철근콘크리트조로 장식이 없는 화강석 평판 붙임으로 마감하였으며, 종래 은행건축의 고전적인 외형을 탈피하여 최대한 장식을 배제한 단순하면서도 전체적으로 조화로운 구성의 모더니즘 건물이다. 20세기 중반 서양의 기능주의 건축에 영향을 받은 한국 근대 건축의 경향을 잘 보여 주고 있다.","a":"구 조흥은행 대전지점","c":"국가등록문화유산","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667944.jpg"},{"q":"○○○○○은 줄여서 ‘○○○○○’또는 ‘○○○’이라고도 하며, 부처님의 말씀을 머리 속으로 이해하는데 그치지 않고 자신이 직접 경험하여 얻을 것을 주요사상으로 하고 있다. ○○○○○료○○○○○ 권6∼10(大佛頂如來密因修證了義諸菩薩萬行首楞嚴經 卷六∼十)은 당나라의 반자밀제(般刺密帝)가 번역한『○○○』10권 가운데 권 6∼10에 해당하며 5권이 하나의 책으로 묶여있다. 나무판에 새긴 후 닥종이에 찍어낸 것으로 크기는 세로 26.1㎝, 가로 16.6㎝이다. 책 끝부분에는 고려 공민왕 21년(1372)에 경기도 안성의 청룡사에서 간행했으며, 김호와 영암군부인 최씨가 시주를…","a":"대불정여래밀인수증요의제보살만행수능엄경 권6~10(1981-1)","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613668.jpg"},{"q":"1966년 10월 경주 ○○○의 석탑을 보수하기 위해 해체했을 때 탑 내부의 사리공에서 발견된 사리장엄유물들이다. 중심부에 놓여졌던 사리외함과 함께 안에는 원구형으로 생긴 은제의 사리 내·외합과 금동사리합, 무구정광대다라니경, 각종 구슬과 함께 있었다. 사리함의 주위에는 청동제 비천상과 1점의 원형동경과 1/4동경편, 목탑, 경옥제곡옥, 구슬, 향목 등이 놓여있었다. 사리함의 바깥 기단부 바닥에서는 비단에 쌓인 종이 뭉치가 발견되었는데, 종이가 한데 뭉쳐져 글의 내용은 알 수 없다. 사리외함은 4면에 덩굴무늬를 좌우대칭의 모양으로 뚫어 새겼으며, 몸체를 받치고 있는…","a":"불국사 삼층석탑 사리장엄구","c":"국보","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612839.jpg"},{"q":"봉황산 중턱에 있는 ○○○는 신라 문무왕 16년(676)에 의상대사가 왕명을 받들어 화엄의 큰 가르침을 펴던 곳이다. ○○○○ 뒤에는 ‘부석(浮石)’이라고 새겨져 있는 바위가 있는데, 『송고승전』에 있는 설화를 보면, 의상대사가 당나라에서 유학을 마치고 귀국할 때 그를 흠모한 여인 선묘가 용으로 변해 이곳까지 따라와서 줄곧 의상대사를 보호하면서 절을 지을 수 있게 도왔다고 한다. 이곳에 숨어 있던 도적떼를 선묘가 바위로 변해 날려 물리친 후 ○○○○ 뒤에 내려 앉았다고 전한다. ○○○○은 ○○○의 중심건물로 극락정토를 상징하는 아미타여래불상을 모시고 있다. 신라 문무…","a":"영주 부석사 무량수전","c":"국보","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612647.jpg"},{"q":"○○○의 절터 주변은 민가가 여기저기 흩어져 있어, 절의 규모와 흔적을 찾아볼 수 없고, 과거에는 탑이름을 ‘명장리○○○○’이라 하였던 점으로 미루어 ‘○○○사지탑’이라는 이름 역시 확실하지 않다. 석탑의 형태는 2단의 기단(基壇)위에 3층의 탑신(塔身)을 세운 모습이다. 기단은 각 면의 네 모서리와 가운데에 기둥 모양을 본떠 새겼는데, 가운데에는 그 기둥이 2개씩이다. 탑신부는 몸돌과 지붕돌이 각각 한 돌씩이고, 각 몸돌마다 네 모서리에 기둥조각을 두었다. 지붕돌은 밑면의 받침이 5단이며, 경사면의 곡선이 강하여 네 귀퉁이가 느리게 위로 들려 있다. 기단의 구성과…","a":"경주 용명리 삼층석탑","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621780.jpg"},{"q":"총통은 불씨를 손으로 점화·발사하는 화포(火砲)이다. 천(天)자는 천자문의 첫 자로 만든 순서를 표시하는 기호이다. 총 길이 1.31m, 통신 길이 1.16m, 포구 지름 12.8㎝로써 포 입구 띠를 제외한 마디는 모두 8개이다. 총신 포구 쪽에는 탄약을 장전하는 약실을 향하여 가로로 ‘가정을묘시월천사백구십삼근십냥장양내요동(嘉靖乙卯十月天四百九十三斤十兩匠梁內了同)’이라는 글이 음각 되어 있어, 조선 명종 10년(1555)에 만들었음을 알 수 있다. 이 총통은 우리나라 화포 중 가장 큰 화기일 뿐 아니라, 그 명문이 남아 있는 가장 오래된 것으로 국방 과학기술 문화유산으…","a":"천자총통","c":"보물","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613552.jpg"},{"q":"신라 최초의 김씨 왕으로 백제의 여러차례 공격을 막아내고 농업을 장려한 신라 13대 왕인 미추이사금(재위 262∼284)의 무덤이다. 『삼국사기』에는 ○○○○과 관련된 전설이 전해지고 있다. 신라 유례왕 14년(297) 이서고국(伊西古國) 사람이 수도인 금성을 공격하여 위급한 상황에 처하자 대나무잎을 귀에 꽂은 군사가 나타나 적을 물리치고 사라졌다. 누군가 ○○○○에 댓잎을 수북이 쌓인 것을 보고 ○○○이 죽어서도 신라를 도와주었다하여 ○○○○을 죽장릉(竹長陵), 죽현릉(竹現陵)이라 부른다고 한다. ○○ 황남동 무덤들 중 가장 잘 정비된 대릉원 내에 높이 12.4m,…","a":"경주 미추왕릉","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627779.jpg"},{"q":"조선 후기에 만들어진 작품으로 높이 21.1㎝, 아가리 지름 3.6㎝, 밑지름 7.8㎝의 크기이다. 8각의 항아리 몸체 위에 목이 긴 병이 얹혀 있는 일종의 표주박형의 병으로 조선 후기에 새로 나타난 형태이다. 한국적인 익살이 넘치는 이 병은 아래에 모를 깎은 단아한 항아리의 모습과 윗쪽의 유연한 곡선을 지닌 병이 붙어, 곡선과 각이 조화를 이루어 참신한 느낌을 준다. 문양은 밝은 청색 안료를 사용하여, 윗쪽 병의 몸체 양면에는 능숙한 솜씨로 칠보문을 그렸고, 아래 항아리에는 3곳에 활짝 핀 모양의 난초문양이 비교적 단정하게 표현되었다. 유약은 옅은 청색을 머금은 백…","a":"백자 청화칠보난초문 병","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614425.jpg"},{"q":"보(補)는 조선시대 왕과 왕세자의 곤룡포(袞龍袍)나 ○○·세자빈의 적의(翟衣)·원삼(圓衫)·당의(唐衣)의 가슴과 등, 양 어깨에 부착하여 장식한 둥근 천으로 주로 용을 수놓았다. 문양에 따라 ‘용보(龍補)’라고도 하며 형태에 따라 ‘원보(圓補)’라고도 한다. 용은 상상의 동물로 예로부터 천자(天子)나 국왕을 상징하는 동물로 여겨왔기 때문에 조선시대 왕의 직계가족들은 용보를 부착하였으며 용의 발톱수로 신분의 구분을 두었다. 즉 왕과 ○○는 ○○○, 왕세자와 세자빈은 사조룡(四爪龍), 왕세손과 세손빈은 삼조룡(三爪龍)의 보를 사용하였다. 그러나 말기에는 이러한 제도가 확…","a":"오조룡 왕비 보","c":"국가민속문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2022011717170200.jpg"},{"q":"이 성당은 김대건(金大建) 신부가 중국에서 조선 헌종(憲宗) 11년 1845년에 사제서품을 받고 페레올주교, 다블뤼신부와 함께 황산나루터에 상륙한 것을 기념하기 위하여 1906년에 지은 건물이다. 1906년 베르모렐 신부가 감독과 설계를 하고 중국인 기술자들을 동원해 지었다. 당시에는 목조건축으로 앞면 5칸·옆면 13칸이었는데, 1916년 건물을 고치면서 일부분을 벽돌로 바꿨으며, 그 뒤 다시 2차례 수리를 하였다. 2층 건물과 비슷하며 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕에 천장은 판자로 처리했고 바닥에 널판지를 깔았다. 천주교가 들어오면서 지은 건물이며…","a":"익산 나바위성당","c":"사적","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626900.jpg"},{"q":"○○○○은 공릉(장순왕후)과 순릉(공혜왕후), 영릉(효장세자와 효순왕후)으로 구성되어 있다. 공릉은 조선 8대 예종의 원비인 장순왕후(1445∼1461)의 무덤이다. 장순왕후는 한명회의 딸로 1460년에 세자빈에 책봉되었으나 이듬해 죽었다. 처음에 왕후릉이 아닌 세자빈 무덤으로 만들어졌기 때문에 병풍석, 난간석, 망주석은 없다. 다만 양석과 둘레돌을 둘러 무덤을 보호하게 하였다. 순릉은 성종의 원비 공혜왕후(1456∼1474)의 무덤으로 공혜왕후는 왕비로 봉해진 후 5년 뒤에 세상을 떠났다. 무덤 밑둘레에는 12칸의 난간석이 둘러져 있고 양석, 호석, 망주석 등의 석…","a":"파주 삼릉","c":"사적","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625644.jpg"},{"q":"○○○의 정상을 둘러싼 길이 620ｍ의 백제 성이다. 경사가 가파르고 서쪽은 임진강, 남쪽은 한강·동쪽은 농경지·북쪽은 산으로 이어진다. 성벽은 서쪽 부근이 잘 남아있다. 성벽 쌓기 수법을 보면 밖으로는 위로 올라가면서 돌을 안으로 들여 쌓고, 성벽 내부는 돌로 채웠다. 이러한 성곽의 형태는 백제 성곽 연구에 매우 중요한 자료가 된다. 광개토대왕릉비와 『삼국사기』백제본기에 나오는 관미성이 이 바로 ○○○○이라는 주장이 있으며, 김정호의 『대동여지도』에는 이곳을 관미성이라 기록해 더욱 주목 받고 있다.","a":"파주 오두산성","c":"사적","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625824.jpg"},{"q":"○○○종은 고려말부터 수용된 중국종적인 요소 가운데 한국 전통 종에서 보였던 형식과 요소가 가미되어 새로운 조선전기의 종으로 정착되는 과정을 잘 보여주는 범종이다. 이후 만들어지는 조선전기 범종의 하나의 기준이 되는 작품이라는 점에서 ○○○종은 다른 조선전기 범종의 발전과정을 보여주는 기념비적인 작품이라 할 수 있다. 크기나 문양·주조기술의 탁월함 외에도 왕실에서 발원(發願)한 종이어서 각 분야의 관장(官匠)들이 대거 참여해 만들어졌으며 명문(銘文)은 주성시(鑄成時)의 조직체계를 알려 주고 있다는 점 등에서 당시의 사회제반사항을 이해할 수 있는 귀중한 자료이기도 하다…","a":"흥천사명 동종","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614859.jpg"},{"q":"이 책은 덕종비인 인수대왕대비가 승려 학조로 하여금 시식권공(施食勸供), 일용상행(日用常行) 등 불교에서 하는 여러가지 행사들을 한글로 번역하여 연산군 2년(1496) 5월에 인경목활자로 4백부를 간행하게 한 것이다. 크기는 가로 21.2㎝, 세로 34.5㎝이다. 인수대왕대비와 정현대비는 성종이 돌아가시자, 연산군 1년(1495) 임금의 명복을 빌기 위해 원각사에서 대대적으로 이것을 인쇄하고 그 다음해에 걸쳐 인경자와 인경한 글자를 만들어 먼저『천지명양수륙잡문』을 찍어내는 한편 이 책을 한글로 번역하여 찍어내게 하였다. 궁중에서 사적으로 쓸 수 있는 돈을 들여 활자를…","a":"진언권공(언해)","c":"보물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615951.jpg"},{"q":"○○○는 ○○○과 창경궁 경계에 위치하고 있다.맨 좌측에 ○○○가 크게 자리 잡고 그 우측으로 석복헌과 수강재가 연이어져 있으며, 이들 뒤편에는 화초·석물·꽃담 굴뚝 등으로 가꾸어진 아름다운 화계와 그 위의 꽃담 너머로는 상량정·한정당·취운정이 위치해 있다. 원래 왕의 연침공간 조성을 목적으로 ○○○가 지어지고 이듬해에 빈의 처소를 위하여 석복헌을 짓고 수강재를 중수하여 오늘에 이르고 있다. 궁궐 안에 사대부주택형식으로 지은 건물로는 ○○○와 연경당뿐이다. ○○○는 헌종 13년(1847)에 왕이 왕비와 대왕대비를 위해 마련하여 조선 왕실의 권위를 확립하고 자신의 개혁…","a":"창덕궁 낙선재","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615028.jpg"},{"q":"조선 10대 ○○○과 거창군부인 신씨(1476~1537)의 묘이다. ○○○은 9대 성종과 폐비 윤씨의 아들로 태어나 1494년 왕위에 올랐다. 즉위 초에는 성종 대의 평화로움이 그대로 이어졌다. 사치풍조를 잠재우기 위해 구체적인 금지 조항을 만들어 단속하였고, 종묘에 신주를 모시는 제도를 새롭게 정비하였으며, 비융사를 설치하여 철갑옷과 무기를 만들어 생산하는 등 국방정책에도 힘을 썼다. 그러나 무오사화(戊午士禍, 성종실록 편찬 중 김일손 등 사림이 훈구파에게 화를 입은 사건으로 김종직의 「조의제문」이 원인이 되어 사림이 피해를 본 사건)와 갑자사화(甲子士禍, 생모 폐…","a":"서울 연산군묘","c":"사적","r":"서울특별시","s":"도봉구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2021070909361500.jpg"},{"q":"○○는 ○○시 삼천포항과 남해군 창선도 사이에 위치한 조그마한 섬으로 섬 전체에 대규모의 유적이 형성되어 있다. 이 유적은 1979년부터 부산대학교박물관의 지표조사를 통해 그 존재가 알려졌으며, 1985년과 1986년 두 차례에 걸쳐 부산대학교 박물관에 의해 발굴이 실시되었다. 그리고 1988년부터 2001.12까지 3차례에 걸쳐 경남고고학연구소, 부산대학교박물관, 동아대학교 박물관에서 발굴을 실시하여 많은 유적과 유물, 유구가 확인되었다. 발굴조사 결과 패총과 무덤유구, 주거지 등과 함께 각종 토기류(중국계 경질토기, 일본계 야요이토기, 점토대 토기 등), 반량전,…","a":"사천 늑도 유적","c":"사적","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628400.jpg"},{"q":"구급의방을 집대성하여 민간에서 사용할 수 있게끔 만든 한글로 쓴 한의학 서적으로, 조선 성종 20년(1489)에 윤호, 임원준 등이 임금의 명을 받들어 편찬하여 목판본으로 간행한 것이다. 이것은 활자로 다시 간행한 총 8권 가운데 ○○의 1책이다. 질병을 중풍, 두통 등 127종으로 나누어 그 치료방문을 모아 엮었으며 누구나 알기 쉽게 한글로 번역하여 쉽게 편찬하였다. 이 책은 초간본은 전하지 않고, 을해자본으로 그대로 뒤집어 새긴 중간본만 전한다. 그러나 현존하는 중간본도 전질이 아니라 권1, 2, 3, 6, 7의 5권 5책만 전하고 있다. 이들은 같은 판본이 아니…","a":"구급간이방 권6(1996)","c":"보물","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617234.jpg"},{"q":"○○○○의 ○○○은 토석담이 주류를 이루며 전형적인 농촌 가옥들과 어우러져 독특한 풍경을 이루고 있다. ○○ 하부에 큰 돌을 60~90cm 정도 쌓은 다음 그 위에 좀 더 작은 돌과 진흙을 교대로 쌓아 올렸다. ○○ 높이는 2m 정도로 높은 편이며, ○○ 위쪽에는 돌출된 기와를 받치도록 판판한 돌을 ○○ 안팎으로 6~7cm 정도 내밀어 쌓았다.","a":"산청 단계마을 옛 담장","c":"국가등록문화유산","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669475.jpg"},{"q":"○○○○○은 대학교 교사로서 강의를 위한 실용적인 목적이 강조된 건축물로 모더니즘 건축의 조형적 특징이 잘 표현된 건축물이다. 특히, 중앙 출입구 포치와 파사드의 수직·수평적 요소, 과감한 블록처리는 당시 단순화 된 고딕양식에 근대성과 조형성을 가미한 것으로 희소성 측면에서 보존 가치가 있다.","a":"전북대학교 구 문리과대학","c":"국가등록문화유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019120914292400.jpg"},{"q":"조선 6대 단종(재위 1452∼1455)의 무덤이다. 단종은 수양대군에게 왕위를 빼앗긴 뒤, 충신들이 그를 다시 왕으로 복위시키려는 계획이 밝혀져 ○○로 유배되어 그곳에서 세상을 떠났다. 단종이 죽자 후환이 두려워 시신을 거두는 사람이 없었는데 ○○호장 엄흥도가 장사를 지냈다. 중종 이후 조정에서 단종에 대한 제사와 무덤에 대한 의견이 나오게 되어, 선조 때에 이르러 상석·표석·장명등·망주석을 세우게 되었다. 숙종 7년(1681)에 노산군을 노산대군으로 하였고, 숙종 24년(1698)에 복위시켜 이름을 ○○이라 하였다. 무덤에는 병풍석과 난간석을 세우지 않았다. 능의…","a":"영월 장릉","c":"사적","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626081.jpg"},{"q":"○○○은 인조반정의 주역들인 연평부원군(延平府院君) 이귀(李貴, 1557 ~ 1633)의 차자(次子)이자 연양부원군(延陽府院君) 이시백(李時白, (1581 ~ 1660)의 동생이다. ○○○은 아버지와 형을 따라 1623년의 30세 때 인조반정에 참여하여 정사공신(靖社功臣) 2등으로 연성군(延城君)에 봉해지고, 이후 여러 차례 판서를 지낸 뒤 현종 즉위년(1659) 가을에 판의금부사(判義禁府事)를 지냈다. 현재 대전의 후손가에 전하는 ○○○의 ○○은 모두 6점인데, 본래는 ○○○의 후손들이 세거(世居)하던 홍성(洪城)의 사당(祠堂)에서 주로 봉안해오던 것들이라고 한다.…","a":"이시방 초상","c":"보물","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614870.jpg"},{"q":"조선 선조 25년(1592) 부산첨사로 임진왜란 때 공을 세운 김호가 살았던 집이다. 17세기전후에 세운 것으로 추정하며 집터는 신라시대 절터였다는 설이 있는데, 주변에 통일신라시대에 만들어진 여러 석조물이 있고 마당의 우물돌은 지금까지도 사용하고 있다. 대문을 들어선 정면에 안채, 왼쪽에 아래채, 안채 오른쪽 뒤편으로 가묘(家廟)가 배치되어 있다. 원래 사랑채가 동쪽에 있었다고 하나, 현재는 자리만 남아있다. 안채는 앞면 5칸·옆면 1칸 규모에 왼쪽부터 부엌, 방, 대청, 방으로 단순한 구성을 이루고 있다. 집을 처리한 기법들은 옛 법식을 따르고 있고 대청 앞에는…","a":"경주 월암종택","c":"국가민속문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634853.jpg"},{"q":"○○○○○은 ○○ 최초의 근대식 개인 종합병원으로 당시 ○○부립병원, 철도병원과 함께 지역에서 중요한 의료기관 건물로 근대 의료사적으로 가치가 있음 1927년 2월, 12월에 각각 건립된 두동이 하나로 합쳐진 건물로 내부 평면이 사각형, 마름모꼴 형태의 다양한 실들로 구성되어 있으며 최초 건립되었던 1, 2, 3층에는 목조계단과 장식, 디테일 등 목재로 마감된 원형이 잘 남아 있음","a":"부산 구 백제병원","c":"국가등록문화유산","r":"부산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2241680.jpg"},{"q":"불교경전은 크게 경(經), 율(律), 논(論)으로 나누어 지는데, 아비담은 부처님의 지혜를 체계적으로 설명하고 있는 논(論)부분을 총칭하여 이르는 말이다. ○○○○○은 성불(成佛)하는데 필요한 부처님의 지혜를 체계적으로 모아 중생들이 실천할 것을 설명하고 있는 부분이라고 할 수 있다. 이 책은 고려 현종 때(재위 1011∼1031) 부처님의 힘으로 거란의 침입을 극복하고자 만든 초조대장경 가운데 하나로, 북량(北凉)의 부타발마(浮陀跋摩)와 도태(道泰)가 공동으로 번역한 60권 가운데 권 제16이다. 닥종이에 찍은 목판본으로 종이를 길게 이어 붙여 두루마리처럼 말아서…","a":"초조본 아비담비바사론 권16","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614466.jpg"},{"q":"1935년 감리교 부인선교부의 한국 사업간사 토머스(Mrs. Thomas)여사의 업적을 기념하며 세워진 건물로, 미국인 선교사로 일본에서 건축가로 활동한 윌리암보리스(William Merrell Vorries, 1881-1964) 의 설계로 지어졌다. 최초에는 체육관으로 건축되었으나, 현재는 무용과에서 사용하고 있다. 전체적으로 신축 당시의 모습을 온전하게 갖추고 있으며 관리 상태도 매우 양호하다.","a":"서울 이화여자대학교 토마스홀","c":"국가등록문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017042209555800.JPG"},{"q":"○○란 다리 밑이 무지개같이 반원형이 되도록 쌓은 다리를 말하며, 아치교·홍예교·무지개다리라고도 한다. 이 다리는 현재 남아 있는 ○○ 중에서 가장 규모가 크며, 현재도 주민들이 사용하고 있다. 예전에는 이 자리에 뗏목을 이은 다리가 있어 ○○라는 지명이 생겨났으며, 조선 영조 5년(1729)에 선암사의 한 스님이 돌다리로 만들어 놓았다고 한다. 그후 영조 13년(1737) 다리를 고치면서, 3칸의 무지개다리로 만들어졌고, 1981∼1984년까지의 4년에 걸친 보수공사를 통해 지금에 이르고 있다. 무지개 모양을 한 다리밑의 천장 한 가운데 마다 용머리를 조각한 돌이…","a":"보성 벌교 홍교","c":"보물","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619051.jpg"},{"q":"○○○은 신라 흥덕왕 3년(828) 장보고가 설치한 해군기지이자 무역기지로, 전라남도 ○○ 앞바다의 작은섬인 장도에 있다. 당시 이곳은 신라와 당, 일본을 잇는 해상무역의 중요한 길목이었다. 장보고(?∼846)는 평민 출신으로 당나라에 건너가 장군이 되었으나, 해적들이 신라사람들을 노예로 삼는 것에 분개하여 신라에 돌아와 왕의 허락을 받고 828년 ○○○을 설치하였다. ○○○은 국제무역의 중심지로 동아시아 무역을 독점하여 번영을 누리며 큰 세력으로 성장하였다. 이후 장보고는 왕위계승과 관련된 권력다툼에 휘말려 자객 염장에 의해 846년 암살당하였고, 문성왕 13년(8…","a":"완도 청해진 유적","c":"사적","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627124.jpg"},{"q":"○○○는 지리산 천왕봉 서편에 위치한 절로, 통일신라 흥덕왕 3년(828)에 홍척(洪陟)이 창건하였다. 이 곳에서 북쪽으로 얼마쯤 가다보면 ○○○이 나타나는데, ○○○에 딸린 소박한 암자로, 그 아래 경작지에 이 탑이 세워져 있다. 낮은 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습으로, 각 부의 구조와 조각에서 특이한 양식과 수법을 보이고 있다. 즉, 일반적인 탑은 위로 올라갈수록 너비와 높이가 줄어드는데 비해 이 탑은 너비가 거의 일정하며, 2층과 3층은 높이도 비슷하다. 층을 이루지 않고 두툼한 한 단으로 표현된 지붕돌의 받침도 당시의 수법에서 벗어나 있다.…","a":"남원 실상사 백장암 삼층석탑","c":"국보","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612336.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 한다. '법화경'은 부처가 되는 길이 누구에게나 열려 있음을 기본사상으로 하는 우리나라 천태종의 근본경전이다. 화엄경과 함께 우리나라 불교사상의 확립에 크게 영향을 미쳤으며, 삼국시대이래 가장 많이 유통된 불교경전이다. 이 책은 후진의 구마라습이 번역한『법화경』 7권을, 고려 우왕 3년(1377)에 하덕란이 죽은 어머니의 명복과 아버지의 장수를 빌기 위해 정성들여 옮겨 쓴 것이다. 하얀 닥종이에 먹으로 썼으며, 각 권은 병풍처럼 펼쳐서 볼 수 있는 형태로 되어 있다. 접었을 때의 크기는 세로 31.8㎝, 가로 10.9㎝이다…","a":"백지묵서 묘법연화경","c":"국보","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611671.jpg"},{"q":"이 『○○○○○, 4 (妙法蓮華經(諺解) 卷一, 四)』는 대승불교의 대표적인 경전으로 구마라집의 한역본에 계환(戒環)이 주해(註解)하고 일여(一如)가 집주(集註)한 것을 저본으로 세조가 직접 경문에 구결을 달고 윤사로 등이 간경도감에서 번역하여 1463년(세조 9)에 목판으로 간행한 국역불경이다. 한글로 번역하여 正音의 명맥을 이어 발전을 보게 한 귀중한 국역자료인 점과 간경도감에서 간행된 판본의 형태적 특징을 잘 갖추고 있는 것으로 평가되었다. 중세국어사 및 조선전기 판본연구에 있어서 매우 귀중한 자료로서 불교판본학 및 중세국어의 연구에 매우 중요한 학술적 가치를…","a":"묘법연화경(언해) 권1, 4","c":"보물","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615931.jpg"},{"q":"『○○○○○』은 인도의 미륵보살이 지은 글을 당나라의 현장(602∼664)이 번역하여 천자문의 순서대로 100권을 수록한 것으로, 11세기에 간행한 초조대장경 가운데 하나이다. 이것은 100권 가운데 제15권으로, 처음 새긴 본이다. 종이질은 닥나무종이이며, 가로 47.6㎝, 세로 28.6㎝이다. 이 판본은 해인사에서 보관하고 있는 재조대장경 판본과 비교해보면 판수제와 권, 장, 함차 표시의 위치에 차이가 있다.","a":"초조본 유가사지론 권15","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611907.jpg"},{"q":"○○○○○는 1동, 1층 규모로 건축면적 117㎡이다. 반야월역은 ○○선로 역사로 1932년 건립되었다가 2008년 폐역되고 도시계획에 따라 아파트가 건립되면서 2010년 ○○시 동구 신서동 823-25번지로 이전되었다. 구조는 목조트러스조로 지붕 'T'자 형태로 삼각형 박공지붕면이 건물의 중심이 아닌 한쪽에 치우쳐 상징적으로 돌출되어 있다. 이전 복원된 폐역은 작은 도서관으로 활용되고 있다.","a":"대구 구 반야월역사","c":"국가등록문화유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667802.jpg"},{"q":"불씨를 손으로 점화·발사하는 유통식화포(有筒式火砲)는 그 크기와 사용되는 화약의 양, 발사거리에 따라 4가지로 분리하여 천자문에서 그 이름을 따 천(天)·지(地)·현(玄)·황(黃)자총통이라 붙인다. 이 것은 그 중 가장 크기가 작은 것으로, 편리한 이동을 위해 만든 것이다. 총구경 4㎝, 전체길이 50.4㎝로, 임진왜란 5년전인 선조 20년(1587)에 만들었다는 기록이 남아 있다. 포 입구에서부터 점차 두터워지고, 몸에는 대나무 모양의 4마디가 표현되어 있다. 포의 끝은 둥글며, 첫째와 둘째마디 사이에는 손잡이가 달려 있다. 임진왜란과 병자호란을 겪었으나 모습이 완…","a":"황자총통","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614200.jpg"},{"q":"조계산 ○○○는 백제 성왕 7년(529)에 아도화상이 비로암이라 하였던 것을 통일신라 헌강왕 5년(875) 도선국사가 ○○○라 고쳐 불렀다. 이후 고려시대 대각국사 의천이 더욱 크게 하여 대가람을 이루었다고 한다. ○○○은 조선시대 정유재란(1597)으로 불에 타 없어져 현종 1년(1660)에 새로 지었다. 그 후 영조 42년(1766)에 다시 불탄 것을 순조 24년(1824)에 지어 오늘에 이르고 있다. 석가모니불을 모신 ○○○은 ○○○의 중심 법당으로, 그 앞에 만세루와 주축을 이루고 있으며 앞마당에는 ○○○○○ 동ㆍ서 삼층석탑(보물) 2기가 나란히 서 있다. 앞…","a":"순천 선암사 대웅전","c":"보물","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619643.jpg"},{"q":"1956년 건축된 ○○○○○는 교사 1동과 관사 1동으로 구성되어 있다. 교사동은 복도를 전면에 둔 편복도 형식의 목조건물로 전면 중앙에 흰색의 아치형 출입구가 있으며 관사동은 독신교사가 사용한 부분과 부부교사가 사용한 부분으로 나누어져 있다. ○○의 근대기 화교활동을 살펴볼 수 있는 중요한 자료로 평가받고 있다.","a":"강경 화교학교 교사와 사택","c":"국가등록문화유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668599.jpg"},{"q":"○○○에 자리잡고 있는 고려전기의 탑비로 ○○○를 중흥한 정진대사의 것이다. 정진대사(878∼956)는 통일신라 말에서 고려 초에 활약한 승려로, 효공왕 4년(900) 당나라에 들어가 25년간 유학하고 경애왕 1년(924)에 돌아와 신라 경명왕의 극진한 예우를 받았다. 고려 태조 18년(935)에는 ○○○를 두번째로 크게 짓고, 불교의 중흥에 이바지하기도 하였다. 특히 고려 전기의 태조·혜종·정종을 선문(禪門)에 들게 한 장본인으로, 79세의 나이로 입적하자 왕은 ‘정진’이라는 시호와 ‘원오’라는 탑이름을 내리었다. 비는 거북받침돌 위로 비몸을 세우고 머리돌을 올린…","a":"문경 봉암사 정진대사탑비","c":"보물","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620443.jpg"},{"q":"1930년 황해도 곡산군 화촌면 봉산리에서 출토되어 현재는 리움미술관에 전시되어 있는 불상으로 높이 15.5㎝이다. 하나의 커다란 광배(光背)에 본존불과 좌우보살상을 조각한 형태의 ○○○로 현존하는 같은 형식의 불상 중에서 가장 크다. 좌우의 보살상은 본존불보다 훨씬 작게 만들어 광배의 끝에 겨우 매달린 듯 보이는데, 이는 본존불을 한결 돋보이게 하는 효과를 내고 있다. 본존불의 가슴과 광배의 오른쪽 끝에 약간의 흠집이 있을 뿐, 전체적으로 보존 상태가 좋은 편이다. 본존불은 얼굴이 풍만하고 입가에 미소를 띠고 있으며, 머리에는 상투 모양의 머리(육계)가 큼직하다.…","a":"금동신묘명삼존불입상","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611493.jpg"},{"q":"○○○○○에 있는 청동기시대 집터 유적이다. 하천과 평지에 인접한 낮은 구릉과 대지 위에 100여 기 이상의 집터가 있을 것으로 추정된다. 집터는 평면 형태에 따라 둥근 것과 긴 네모꼴인 것이 있다. 둥근 집터는 30∼150cm 깊이로 땅을 파서(수혈식주거지) 만들었으며, 한쪽 벽을 얕게 파서 문을 만든 듯하다. 화덕자리가 발견되지는 않았지만 다수의 저장용 구덩이가 발견되었다. 바닥 중앙에 1m 내외의 긴 타원형 구덩이를 파고 그 구덩이 안에 몇 개의 둥근 구덩이를 만들었다. 네모꼴 집터는 30㎝ 미만으로 땅을 판 반움집이나 지상식에 가까운 것으로 기둥구멍이 발견되지…","a":"부여 송국리 유적","c":"사적","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626588.jpg"},{"q":"이 ○○는 ○○군과 나주시 경계 사이를 흐르는 ○○○을 가로지르는 다리이다. 고려 원종 14년(1273) 무안 법천사의 도승 고막대사가 도술로 이 다리를 놓았다는 전설이 있다. 총 길이 20m, 폭 3.5m, 높이 2.5m로서 5개의 교각 위에 우물마루 형식의 상판을 결구한 널다리로서 동쪽으로는 돌로 쌓은 석축도로가 7∼8m 연결되고 다시 물살을 가르기 위해 세운 최근의 콘크리트 다리가 이어지고 있다. ○○○○○는 널다리이면서도 목조가구의 결구수법인 주두의 가구법을 택한 것이 특징이다. 다리의 상판은 우물마루 형식을 간직하고 있는데, 이는 당시 목조건축과의 관련성을…","a":"함평 고막천 석교","c":"보물","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619870.jpg"},{"q":"○○○○○은 해안으로부터 육지 쪽으로 300여미터 떨어진 ‘쌍호(雙湖)’라 불리는 호수를 매립하여 농토로 사용하기 위한 토사 채취 작업 중 흙에서 다량의 토기와 석기가 발견되면서 유적이 있음을 알게 되었다. 발굴조사를 통해 지금으로부터 약 8천년전 신석기 사람들이 살았던 유적으로 밝혀졌으며, 집터를 비롯하여 불을 피웠던 자리(野外 爐址)와 도구를 제작했을 것으로 보이는 흔적이 확인되었고, 덧무늬 토기(隆起文 土器) 등 다양한 형태의 토기와 어로생활을 짐작케 하는 결합식 낚시(이음낚시), 그물추(漁網錘)와 돌톱, 화살촉 등 당시의 생활을 엿볼 수 있는 특징적인 간석기도…","a":"양양 오산리 유적","c":"사적","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626100.jpg"},{"q":"고려 전기의 ○○○○로, 높이 15.3㎝, 대좌지름 11.2㎝의 크기이며 뚜껑과 몸통 두 부분으로 구성되어 있다. 뚜껑은 향이 피어올라 퍼지도록 뚫어서 장식한 구형(球形) 부분과 그 밑에 받침 부분으로 되어 있다. 구형 부분 곳곳의 교차 지점에는 흰 점이 하나씩 장식되어 있다. 몸통은 두 부분으로 윗부분은 둥근 화로 형태인데, 몇 겹의 국화잎으로 싸여있고 다시 커다란 국화잎이 이를 받치고 있다. 아래 부분은 ○○ 몸체를 받치고 있는 대좌로, 3 마리의 토끼가 등으로 떠받들고 있다. 대좌의 옆면에는 덩굴무늬가 새겨져 있으며 토끼의 두 눈은 검은 점을 찍어서 나타냈다.…","a":"청자 투각칠보문뚜껑 향로","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611513.jpg"},{"q":"○○○○ 용장사곡 석조여래좌상(보물)의 뒤쪽 바위벽에 새긴 ○○○○○이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며 원만한 얼굴에는 온화한 미소를 짓고 있다. 양 어깨에 걸쳐 내린 옷에는 평행선으로 이루어진 잔잔한 무늬가 밀집되어 있다. 손은 오른손을 무릎 위에 올려 손끝이 땅을 향하고 있으며 왼손은 배 부분에 놓여 있다. 불상은 연꽃이 새겨진 대좌 위에 양 발을 무릎 위로 올린 자세로 앉아 있으며, 머리광배와 몸광배는 2줄의 선으로 표현하였다. 아직 판독은 어려우나 글자가 10자 새겨져 있고, 보존 상태도 양호해 8세기 후반에 만들어진 우수한 작품으로 평가…","a":"경주 남산 용장사지 마애여래좌상","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621803.jpg"},{"q":"이 ○○는 ○○○를 창건하고 우리나라에서 화엄종을 처음 시작한 의상대사를 모시고 있는 ○○○○○ 안쪽 벽면에 사천왕과 제석천, 범천을 6폭으로 나누어 그린 그림이다. 현재는 일제강점기에 해체 분리된 ○○를 별도로 보관하고 있다. 흙벽 위에 녹색으로 바탕을 칠하고 붉은색·백색·금색 등으로 채색하였으며, 각각의 크기는 길이 205㎝, 폭 75㎝ 가량이다. 양쪽의 두 천부상은 우아한 귀족풍으로 양감이 풍만하며, 가운데 사천왕은 악귀를 밟고 서서 무섭게 노려 보는 건장한 모습이다. 훼손된 부분이 많고 후대에 덧칠하여 원래의 모습이 많이 사라졌지만 율동감 넘치는 유려한 선에서…","a":"부석사 조사당 벽화","c":"국보","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612794.jpg"},{"q":"한말 ○○군 지역에서 있었던 의병활동 가운데 홍주성 전투에서 희생된 수백 의병들의 유해를 모신 묘소이다. 1905년 일본과의 을사조약이 체결되자 각지에서 의병활동이 일어났는데, 충청남도 ○○지방에서는 이조참판 민종식을 중심으로 활발한 활동이 전개되었다. 1906년 고종 황제의 명을 받아 의병을 모아 남포와 보령에 있는 일본군을 습격하여 병기를 탈취하였으며, 3월 20일에는 홍주성을 함락시켰다. 그러나 일본군의 대포 공격이 본격화되면서 의병 수백명이 전사하여 시체가 홍주천변과 남산 일대에 흩어져 방치되었다가 1949년에 항일의병의 유골임이 밝혀져 이곳에 모셔졌다. ○○…","a":"홍성 홍주의사총","c":"사적","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626700.jpg"},{"q":"○○○○○의 전신인 보성전문학교가 개교 30주년을 기념하여 세운 도서관 건물이다. 1935년에 공사를 시작하여 1937년에 완성한 5층 건물로 설계는 본관을 설계한 박동진이 하였다. 현재 이 건물은 대학원동과 교수연구실로 이용하고 있다. 건축의 양식과 구조는 미국 듀크대학의 도서관을 참고 하였다고 한다. 모서리 부분의 서양 중세풍의 5층 탑 꼭대기 부분은 정교한 고딕식 창장식으로 하여 가장 돋보인다. 형태는 웅장하며 세부적으로는 섬세한 화강암으로 지은 고딕식 건축이다.","a":"서울 고려대학교 중앙도서관","c":"사적","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624944.jpg"},{"q":"○○○는 통일신라 문무왕 20년(680) 고승 석선(奭善)이 세웠고 고려 초기 혜거국사가 넓혀 세웠으나 임진왜란 때 불에 타 나중에 화덕(華德)이 다시 지은 절이다. ○○○은 석가모니불상과 그 생애를 여덟 가지로 나누어 그린 그림을 모신 곳으로 지은 시기는 정확하게 알 수 없으나 여러 차례 수리를 거쳤다. 지금 있는 건물은 조선시대 건축물이다. 규모는 앞면 3칸·옆면 2칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포가 기둥 위와 기둥 사이에도 있는 다포 양식인데, 밖으로 뻗쳐 나온 재료의 끝이 짧고…","a":"안성 석남사 영산전","c":"보물","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615858.jpg"},{"q":"○○○로 들어가는 남쪽 골짜기의 첫 입구에 세워져 있는 탑으로, 커다란 바윗돌로 바닥돌과 아래층 기단을 삼고 그 위로 윗층 기단을 쌓은 후 9층에 이르는 탑신(塔身)을 세운 모습이다. 윗층 기단의 가운데돌은 4장의 널돌로 짜였으며, 네 모서리마다 기둥모양을 새긴 후 다시 면 가운데에 기둥모양을 굵게 새겨 면을 둘로 나누어 놓았다. 또한 기단의 맨윗돌은 탑신의 1층 지붕돌로 대신하고 있는 점이 특이한데, ○○○의 모든 탑이 이러하여 고려시대로 오면서 나타난 특징으로 보인다. 탑신의 각 몸돌에는 면마다 2중으로 마름모꼴을 새기고, 그 안에 꽃무늬를 두었는데, 이러한 수법…","a":"화순 운주사 구층석탑","c":"보물","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619338.jpg"},{"q":"○○은 조선중기의 문신으로 본관은 풍천(豊川), 자는 자룡(子龍)이다. <○○○○>은 17세기 전반의 전형적인 공신도상의 모습을 보여주는데, 단령을 입고 공수한 뒤 의자에 앉아 좌안7분면을 취하고 있으며 바닥에는 화려한 채전(彩氈)을 깔고 두 발은 돗자리를 깐 목제 의답(椅踏) 위에 팔자형으로 벌리고 있다. 이 ○○화는 왼쪽 눈꼬리를 위로 치켜 올려 두 눈의 형상을 차이 나게 묘사한 점, 숱은 적지만 때로는 짧게 때로는 약간 길게 올의 방향을 달리하여 수염의 성질을 잘 살린 표현법 등에서 화가가 인물을 앞에 두고 실사한 느낌이 강하다. 흑단령에는 백한흉배(白鷳胸背)가…","a":"임장 초상","c":"보물","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614888.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하며, 부처가 되는 길이 누구에게나 열려 있다는 것을 중요사상으로 하고있다. 천태종의 근본 경전으로 화엄경과 함께 한국 불교사상 확립에 크게 영향을 끼친 경전이다. 이 책은 흰 종이에 먹으로 쓴 것인데 법화경 7권 가운데 마지막권이며, 병풍처럼 펼쳐서 볼 수 있는 첩장의 형태이며, 크기는 세로 35.6㎝, 가로 139㎝이다. 책 맨 뒤의 조선 태종 5년(1405)에 각지(角之)가 쓴 기록을 보면, 도인(道人) 신운(信雲)이 돌아가신 부모님이 고통과 번뇌에서 벗어나 열반에 이르기를 기원하기 위해 책을 펴냈다고 한다. 이때 법…","a":"백지묵서 묘법연화경 권7","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614613.jpg"},{"q":"귀봉 김수일 선생의 종택으로 현종 1년(1660)에 최초로 지은 것으로 추정되는 조선 중기의 전형적인 종가집이다. 'ㅁ'자형으로 대문채·사랑채·안채·사당채 건물이 있고, 사당에는 운천 '김용'의 위패가 봉안되어 있으며, 종택 내 보물인 ‘운천 호종일기’가 보관되어 있다. 인접하여 ‘의성김씨 종택'(보물)이 있는데, 안채평면이나 가구의 법식이 대종가인 '의성김씨 종택'과 다르면서도 법식이나 기법에서 유사함을 보이고 있다.","a":"안동 귀봉종택","c":"국가민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635720.jpg"},{"q":"고종 27년(1890)에 지은 르네상스풍의 2층 벽돌 건물이다. 한국전쟁으로 건물이 심하게 파괴되어 탑과 지하2층만이 남아있었으나, 1973년에 복구되었다. 한쪽에 탑을 세웠으며, 정문은 개선문 양식이다. 일본군에 의한 명성황후 시해사건 이후 1896년 2월부터 1897년 2월까지 고종이 세자와 함께 피신하여 있던 곳이다. 이 기간동안 친일파인 김홍집 내각이 무너지고 친러시아적인 박정양 내각이 조직되었으며, 서재필이 주도하는 독립협회가 결성되었다. 고종이 거쳐했던 방의 내부는 건물과 같은 르네상스풍의 실내장식을 했다.","a":"서울 구 러시아공사관","c":"사적","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624785.jpg"},{"q":"완구는 일명 ‘댕구’라고도 부르며 유통식(有筒式) 화기의 한 종류로 조선 태종 때 최해산이 만들었다고 한다. 완구는 크게 완(碗), 격목통(激木筒), 약통(藥筒)의 3부분으로 나눌 수 있다. 완은 발사물 즉 큰 돌이나 쇠공을 올려 놓는 곳으로 그릇 모양을 하고 있다. ○○○의 약통은 화약을 넣는 곳으로 점화선을 끼우는 점화구멍을 2개 가지고 있다. 약통과 완 중간에는 격목통이 있는데 이 곳에는 화약이 폭발할 때 생기는 폭발력을 완에 전달하기 위한 나무로 만든 격목이 있다. 이 ○○○는 1970년 3월 경상남도 통영군 앞바다에서 잠수부가 인양한 것이며 크기는 완은 20…","a":"중완구(1986-2)","c":"보물","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622834.jpg"},{"q":"경상북도 ○○시 이산면 ○○○ 길 옆 논 가운데에 있는 마애불로 바위 4면에 모두 불상을 새겼으나 지금은 삼존불(三尊拂) 외에는 형체를 거의 알아볼 수 없다. 본존불은 민머리 위에 상투 모양의 머리묶음이 크게 솟아있으며, 얼굴은 갸름하고 원만하다. 양 어깨를 감싸고 있는 옷은 배에서부터 다리 위로 굵고 부드러운 곡선을 이루면서 늘어져 있다. 오른손은 가슴 위로 들고 왼손은 무릎 위로 비스듬히 내리고 있는 모습이다. 얼굴의 형태와 옷주름 표현 등이 옛 양식을 보이고 있는데, 특히 ○○ 가흥동 ○○○○○ 및 여래좌상과 비슷하다. 좌우에 있는 두 협시보살상은 모두 체구에…","a":"영주 신암리 마애여래삼존상","c":"보물","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621447.jpg"},{"q":"이 ○○물은 한국전쟁 당시 ○○○ 전사자들을 화장하기 위해 건립하여 휴전 직후까지도 사용한 화장 ○○이다. 건물의 벽과 지붕이 훼손되었으나 가장 중요한 ○○○ 굴뚝이 그대로 남아 있다. 주변의 돌을 이용하여 막돌 허튼층쌓기로 만들었다. 한국전쟁 유적으로 중요한 의미가 있을 뿐 아니라 ○○○ 전사자들을 추모하는 ○○로 가치가 있다.","a":"연천 유엔군 화장장 시설","c":"국가등록문화유산","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668141.jpg"},{"q":"무등산 북쪽 ○○○에 자리잡은 가마터로, 고려 후기에서 조선 전기까지 상감청자·분청사기·백자를 굽던 곳이다. 가마의 구조는 사람이 드나드는 출입시설·도자기를 집어넣는 번조실·굴뚝실로 이루어져 있으며, 둥근 무덤 형태가 연결된 모양으로 되어 있다. 『세종실록지리지』의 기록과 출토유물의 연도를 통해 1430년을 전후해 만들어지기 시작된 것으로 보고있다. 그 후 약 70∼80년간 자기제작이 지속되다가 16세기 초에 중단되었던 것으로 짐작된다. 초기에는 분청사기만 만들다가 백자가 생산되기 시작하면서 같이 제작했으나, 분청사기의 무늬가 조잡해지면서 생산량이 줄어들었다. 반면…","a":"광주 충효동 요지","c":"사적","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625344.jpg"},{"q":"구 불정역은 ○○선 역사로 1954년 11월 10일 보통역으로 영업을 개시하였고 역사건립은 1955년 9월 15일 준공되었다. 불정역의 외관 하부는 화강석 마감에 상부는 인근의 구랑리천의 강자갈을 재료로 마감하여 다른 간이역과는 다른 톡특한 외관을 지니고 있다. 박공지붕 측면에 출입구를 배치하였으며 평면은 대합실과 역무실로 구성하였고, 역무실이 승차장쪽으로 돌출되어 승객을 관리하기 편하게 배치하였다. 해방 이후 ○○탄광의 석탄산업과 연계된 역사로서 장소성을 가지고 있다.","a":"문경 구 불정역사","c":"국가등록문화유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669146.jpg"},{"q":"이 가옥은 우리나라 현대 조각의 개척자이자 미술교육의 선구자인 우성 ○○○의 ○○로 사랑채와 안채, 문간채 등으로 이루어져 있다. 수납공간과 높은 다락, 미서기 유리문과 출입구 상부의 채광을 겸한 환기창 등이 특징이다. 가곡 ‘고향의 봄’에서 ‘울긋불긋 꽃 대궐’이라는 노랫말은 바로 이 집을 묘사한 것이다.","a":"창원 소답동 김종영 생가","c":"국가등록문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669432.jpg"},{"q":"­1950년대 외국 건축물을 수용하는 과정에서 절충적으로 표현되어 나타나는 발코니형(바렌다식) 건축물로 건립당시 관공서 건물의 특징을 잘 나타냄","a":"구 홍천군청","c":"국가등록문화유산","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668316.jpg"},{"q":"○○○○○는 미국 남장로교 선교사 레이놀즈 목사가 1900년대 건립한 근대 교육 시설로, 호남과 제주도 지역 기독교 선교에 크게 공헌하였다. 강당은 리차드슨 여사의 기증을 받아 1936년에 강당 겸 체육관 용도로 건립한 장방형 평면의 벽돌조 박공지붕 2층 건물로, 박공면에 3개의 아치형태가 연속된 출입구가 있다. ○○ 건물은 1928년 3층 벽돌조로 건립하였으나, 1982년 화재로 소실되고 현재는 가운데 정면 ○○만 남아 있다. 이 지역 선교 역사를 간직한 건축물로 평가받고 있다.","a":"전주 신흥고등학교 강당과 본관 포치","c":"국가등록문화유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668709.jpg"},{"q":"○○ 궁남지(宮南池) 동쪽에 위치한 ○○○은 백제 이궁지(離宮址)인 망해정(望海亭)이 있었다고 전해지고 있는 곳으로서, 지난 '86년에 충남대박물관의 발굴조사 결과 건물지 초석과 와편들이 다량 출토된 유적지이다. 2000. 5월부터 8월까지 국립○○문화유산연구소가 실시한 추가 발굴조사한 결과에서도 백제에서 조선시대에 걸친 건물지, 분묘, 목책시설 등 다양한 유구 및 유물(건물지5, 석곽묘11기, 토광묘<민묘>18기, 석축시설, 출토유물 50점 등)이 확인되어 이 일대가 백제시대 이후 계속적으로 거주지 또는 묘역으로 활용되었음을 알려주는 중요한 유적이다. <b>※(○○…","a":"부여 화지산 유적","c":"사적","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626673.jpg"},{"q":"조선시대 만들어진 ○○○○ 병으로 야외에서 술, 물을 담을 때 사용하던 용기이다. 자라와 비슷한 모양을 하고 있어 ○○○이라 불리며, 크기는 높이 9.4㎝, 지름 24.1㎝이다. 병 전체를 백토로 두껍게 바르고, 윗면에는 모란꽃과 잎을 간략하게 나타냈다. 무늬가 새겨진 곳 이외의 백토면을 깎아낸 후, 검은 색 안료를 칠하여 흑백의 대조가 대비되는 효과를 가져오게 하였다. 이와 같은 무늬 장식기법을 박지기법이라 하는데, ○○○○ 무늬 중 조형적으로 가장 뛰어나다. 이 병의 박지모란무늬는 구성이 대담하고 활발할 뿐만 아니라 무늬와 바탕면과의 대조를 선명하게 하기 위하여…","a":"분청사기 박지철채모란문 자라병","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611863.jpg"},{"q":"○○○○○은 정교성과 화려함을 두루 갖춘 보관, 이국적이면서도 우아한 귀족풍의 얼굴모습, 단정하고 엄숙하면서도 안정된 신체비례, 간결하지만 탄력 넘치는 옷주름의 표현, 불신 전반에 걸쳐 정교하게 장엄된 영락 장식 등 품격 높은 고려 불교문화의 한 단면을 뚜렷이 보여준다. 이 관음보살좌상은 조성발원문이 남아있지 않지만 현존하는 작품과의 비교를 통해 13세기 전반기에 조성된 보살상으로 추정되는데, 현재 이 시기의 보살상이 거의 남아 있지 않은 점에서 그 자료적 가치는 매우 높다 하겠다. ○○○○○에서는 10종 194점에 이르는 ○○○○이 함께 발견되었다. 복장전적 중 ‘…","a":"안동 보광사 목조관음보살좌상 및 복장유물","c":"보물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622253.jpg"},{"q":"○○○○○은 당시 방대한 화엄경을 은니로 사성한 것 가운데 잔권(殘卷)이나 고려말에 사경 신앙의 면모를 살필 수 있는 중요한 자료이다. 상세한 내용은 다음과 같다. 수진본(袖珍本) 금강반야파라밀경(金剛般若波羅蜜經)은 금강경(金剛經)으로 약칭되는 구마라십(鳩摩羅什) 역(譯)의 금강반야파라밀경(金剛般若波羅蜜經)이다. 권수(卷首)에 신중상(神衆像)과 설법상(說法像), 금강경계청(金剛經啓請), 정구업진언(淨口業眞言), 팔금강상(八金剛像)과 사보살상(四菩薩像), 발원문(發願文), 운하범(云何梵)이 본문 앞에 실려 있다. 그리고 권말에 지기(誌記)가 있고 이어서 범자(梵字)로…","a":"화성 봉림사 목조아미타불좌상 복장전적 일괄","c":"보물","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615955.jpg"},{"q":"이 차는 조선총독부 철도국 경성공장(현재 서울철도차량 정비창)에서 조립한 ○○로 1958년 개조하여 ○○ 유엔군과 미8군 사령관 ○○○○로 운행하였다. 귀빈○○ 17호라고 불렸으며, 1966년 11월 미국 제36대 존슨 대통령이 한국을 방문하였을 때 이 ○○를 이용하였는데, 이를 기념하여 승차권이 발행되기도 하였다.","a":"주한 유엔군사령관 전용 객차","c":"국가등록문화유산","r":"경기도","s":"의왕시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668157.jpg"},{"q":"이 집은 ○○시 대신면 ○○○에 대대로 살아온 창녕 조씨 하산군파의 ○○이다. 1999년 안채 지붕 수리 공사 중에 발견된 상량문과 문중 기록 및 건축 기법을 통해 볼 때 조선 순조 13년(1813)에 이조판서를 지낸 조윤대와 그의 아들인 조봉진, 조용진이 건립한 건물로 추정된다. 이 집은 또한 독립운동가 조성환과 춘천 의병 의병장인 이만응이 거주하였던 역사적인 건축물이다. 전체적인 주택의 배치형식은 사랑채가 안채를 가로막고 서있는 'ㅁ'자형을 이루고 있으며, 대문은 원래 바깥행랑채에 있었다고 하는데 지금은 바깥행랑채가 헐려 남아있지 않다. 안마당으로 통하는 중대문의…","a":"여주 보통리 고택","c":"국가민속문화유산","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633728.jpg"},{"q":"○○○○는 2동, 1층 규모로 역사 건축면적 84.6㎡, 화장실 34.8㎡이다. 춘포역은 전라선로의 역사로 1914년에 건립되어 1914년 11월 이리-전주간 선로를 개통하고 영업을 개시하였다. 구조는 목조로 벽체는 시멘트로 변형되어 있다. 지붕은 맞배형식으로 박공이 철로 방향에 설치되어 있다. 역은 복선화 완료후 폐역되었다.","a":"익산 구 춘포역사","c":"국가등록문화유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668763.jpg"},{"q":"○○○○○은 1708년(숙종 34)에 조성되었지만, 17년 뒤인 1725년(영조 원년)에 중수하였다. 화원은 의균(義均)·석민(碩敏)·성익(性益)·지붕(智朋)·체환(體環)·쾌민(快敏)·삼학(三學)인데, 모두 대구 팔공산 동화사와 파계사의 불화 조성에 참여한 화사로 주로 경상도에서 활약한 것으로 보인다. 이 ○○○은 10m에 이르는 대형의 화면에 연꽃줄기를 든 보살형의 여래만을 단독으로 그렸는데, 의균의 작품 중에서 최대의 역작이다. 대형의 화폭에 단독의 존상만을 그린 구성은 매우 단순하지만 홍색과 녹색, 청색계열의 색만을 이용해 조화와 대비를 훌륭하게 처리하였고, 여…","a":"포항 보경사 괘불탱","c":"보물","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622270.jpg"},{"q":"○○시내를 남동에서 북서쪽으로 가로질러 흐르는 무심천 서북쪽 기슭의 동쪽 비탈진 곳에 분포하고 있다. 107기의 고분이 조사되었는데 106기는 흙을 판 후 무덤을 쓴 널무덤(토광묘)이고, 1기는 널방과 널길을 가진 굴식돌방무덤(횡혈식석실분)이다. 널무덤은 야산 전체에 걸쳐 분포하며, 봉분은 거의 깎여 나가 남아있지 않다. 출토 유물로는 여러가지 토기류·옥과 같은 장신구류·철로 만든 칼이나 도끼같은 무기류·말갖춤(마구류)과 그 밖의 숟가락 등이 나왔다. 90-1호 널무덤에서는 갑옷이 출토되어 백제철갑의 실물을 볼 수 있어 주목되고 있다. ○○○○○은 한 시기에 만들어진…","a":"청주 신봉동 고분군","c":"사적","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626267.jpg"},{"q":"조선 14대 선조의 후궁이자 15대 광해군의 생모(사친) 공빈 김씨(1553~1577)의 묘이다. 공빈은 김희철의 딸로 선조의 후궁이 되어 임해군과 광해군을 낳았으나, 1577년(선조 10) 25세의 젊은 나이에 세상을 떠났다. 광해군은 왕위에 오른 후 어머니를 공성왕후(恭聖王后)로 추존하고 능의 이름을 성릉(成陵)이라 하였으며 신주를 종묘에 모셨다. 그러나 1623년 인조반정으로 광해군이 폐위되자 다시 공빈으로 강등되고 지금의 ○○가 되었다. ○○는 성릉으로 추봉할 때 왕릉의 격식에 맞게 석물을 다시 조성하였기 때문에 문석인, 무석인, 장명등, 혼유석, 석양, 석호…","a":"남양주 성묘","c":"사적","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020081311045300.jpg"},{"q":"○○○○○ 무사전에 봉안되어 있는 지장보살삼존상을 비롯한 시왕·권속○○은 1648년(인조 26) 수조각승 인균(印均)을 비롯한 12명의 조각승들이 참여하여 조성한 작품이다. 지장보살상은 동그란 얼굴에 살이 적당히 올랐으며, 부푼 눈두덩 사이로 짧게 치켜 올린 눈이 인상적이다. 단정한 신체에 표현된 옷 주름은 강직한 직선과 부드러운 곡선을 잘 조화시켜 신체의 굴곡과 양감을 잘 살려내었다. 시왕과 권속상은 그들이 지니고 있는 개성적인 특징과 역할을 다양한 표현력과 연출력으로 생동감 있게 묘사하였다. ○○○ 무사전 조각들은 17세기 불상 양식을 잘 반영하고 있을 뿐만 아니…","a":"여수 흥국사 목조지장보살삼존상·시왕상 일괄 및 복장유물","c":"보물","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620000.jpg"},{"q":"연산의 황산성, 노성의 노○○○ 및 금강 건너의 성흥산성, 뒤쪽의 금○○○과 연결되는 백제의 수도 사비 남쪽 외곽을 방어하기 위해 쌓은 산성이다. 이 산성은 안쪽에 성을 세운 후, 다시 성 밖에 2개의 골짜기를 따라 성을 쌓았다. 현재는 성문터와 성문 밑으로 개울물이 흐르게 하던 수구문, 그리고 우물터와 건물터들이 남아있다. 6세기 전반에 세워진 것으로 둘레 약 1,5㎞, 폭 약 5m, 높이 4m 정도로, 바깥쪽은 돌을 쌓아 올리고 안쪽은 흙을 파서 도랑(호)처럼 만들어 놓았던 것으로 보인다. 이 산성의 특색은 2개의 골짜기를 둘러싼 포곡식(包谷式) 외성을 축조하고,…","a":"부여 석성산성","c":"사적","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626500.jpg"},{"q":"○○○○○은 고려 원종 11년(1270) 2월 고려 조정이 몽고군과 강화를 맺고 강화에서 개경으로 환도하자 이에 맞서 고려 김방경과 몽고의 흔도가 이끄는 여몽연합군에 최후까지 항쟁하다 원종 14년(1273) 전원 순의한 삼별초의 마지막 보루였던 곳으로, 1997년 4월 18일에 사적으로 지정되었다. 이 성은 해발 약 190∼215m에 있으며, 동쪽으로는 고성천이 있고 서쪽으로는 소왕천이 있다. 지형은 남고북저를 하고 있는데, 북쪽인 경우 토성부근이 급격한 경사를 이루고 있고 동쪽은 완만하나 서쪽은 단애를 이루는 하천을 두고 있어 성을 쌓기에는 천연적으로 적합한 지형을…","a":"제주 항파두리 항몽 유적","c":"사적","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628558.jpg"},{"q":"신라 제49대 ○○○의 무덤이다. ○○○은 왕위에 있는 동안 태평성대를 이루었는데, 거리마다 노랫소리가 끊이지 않았고 일본왕이 황금을 바칠 정도였다고 한다. 높이 4.2m, 지름 15.3m의 둥근형태로 흙을 쌓은 원형 봉토무덤으로 무덤을 보호하기 위해 무덤 밑둘레에 돌을 4단으로 쌓았다. 일찍이 도굴되었으며 비에 의한 피해로 긴급조사를 하였다. 관이 놓여 있는 방은 네모 형태로 천장은 둥글게 모아져 있는 활천장(궁륭상천장)이고, 이 방과 연결된 통로인 널길(연도)은 동쪽에 있어 전체적으로 ‘ㄱ’자형이다. 여기서 꽃무늬 토기도 나왔다. 무덤 보호를 위해 다듬은 돌을 4…","a":"경주 헌강왕릉","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627813.jpg"},{"q":"○○○○○은 일주문, 금강문, 사천왕문까지는 좌측의 계곡을 끼고 지형에 맞추어 휘어져 올라온 북쪽에 위치하며, 만세루(萬歲樓)에서 ○○○에 이르기까지는 일직선상에 놓여있다. ○○○을 중심으로 좌우에 선당(禪堂)이 위치해 있으며, ○○○ 앞 뜰에는 2개의 삼층탑이 놓여 있는 2탑식 중정형 가람배치를 가진다. ○○○○○ 가구의 구성 및 부재의 표현기법은 조선후기의 건축적 특징이 잘 표현되었음을 알 수 있다. 임진왜란 직후 재건된 불전들의 경향을 보이며, 아름답고 뛰어난 기법을 보여주는 내·외부 많은 벽화와 불단이 남아 있는 등 보물로 지정해 보존할 역사적·예술적·학술적…","a":"김천 직지사 대웅전","c":"보물","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622260.jpg"},{"q":"회암사는 고려 충숙왕 때인 1328년에 승려 지공(指空)이 창건한 사찰로, 그 제자인 나옹(懶翁)이 불사를 일으켜 큰 규모의 사찰이 되었다. 조선 태조 이성계가 각별히 관심을 가졌으며, 왕위를 물린 후에도 이 곳에서 머무르며 수도생활을 한 것으로 유명하다. 절터의 동쪽 능선 위에 지공과 나옹 그리고 무학의 사리탑이 남과 북으로 나란히 서있고, 그 남쪽 끝에 이 ○○이 자리하고 있다. 바닥돌과 아래받침돌은 하나로 붙여서 만들었으며, 그 위의 중간받침돌은 ○○○를 두어 신라이래의 형식을 따르고 있다. ○○○는 가슴과 배가 서로 붙어 입체감이 없고 엉덩이가 밑에 닿아 부자…","a":"양주 회암사지 무학대사탑 앞 쌍사자 석등","c":"보물","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615751.jpg"},{"q":"고산 ○○○가 54세때인 인조 18년(1640)에 머무르며 『금쇄동기』를 비롯한 여러 문헌들을 집필한 곳인 금쇄동과 금쇄동 안에 위치한 현산고성이다. ○○○는 8살되던 해에 큰아버지에게 입양되어 ○○으로 내려가 살았다. 20세에 승보시에 1등으로 합격하여, 1616년 성균관유생으로서 집권세력을 비난하는 글을 올렸다가 함경도로 유배되었다. 벼슬을 버리고 내려온 후에는 조상이 물려준 엄청난 재산으로 정치와는 관계없이 보길도의 부용동과 새로 찾은 금쇄동에 여러 정자와 각을 지어놓고 풍류를 즐기며 살았다. 금쇄동은 ○○○가 원림(園林)을 조성한 고성(古城)안과 『금쇄동기』에…","a":"해남 윤선도 유적","c":"사적","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627364.jpg"},{"q":"삼국통일을 이룬 신라 제30대 문무왕의 수중릉인 대왕암이 가장 잘 보이는 곳에 위치한 건물이다. 죽어서도 용이 되어 나라를 지키겠다는 문무왕의 호국정신을 받들어 31대 왕인 신문왕이 681년에 세웠다. 신문왕은 해변에 감은사라는 절을 짓고, 용이 된 아버지가 절에 들어와서 돌아다닐 수 있도록 법당 밑에 동해를 향하여 구멍을 하나 뚫어 두었다. 그 뒤에 용이 나타난 곳을 ○○○라고 하였다는 기록이 있다. 또 ○○○에서 신문왕이 용으로부터 세상을 구하고 평화롭게 할 수 있는 옥대와 만파식적이라는 피리를 하나 받았다고도 한다. ○○○라는 이름은 신문왕이 바다에 나타난 용을…","a":"경주 이견대","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627746.jpg"},{"q":"공주에서 ○○쪽으로 23㎞ 떨어진 벌판 가운데에 서 있는 탑으로, 부근에 고려시대 백곡사(白谷寺)라는 절이 있었다고 하나 주위에 기와조각 등이 흩어져 있을 뿐 다른 유물들은 찾아볼 수 없다. 탑은 2단의 기단 위에 9층의 탑신을 올린 모습이다. 아래층 기단에는 안상(眼象)을 돌려 새겼는데, 바닥선이 꽃모양으로 솟아올라 있어 고려시대의 양식상 특징을 드러낸다. 윗층 기단에는 네 모서리와 면의 가운데에 기둥 모양을 새겼으며, 그 위로 알맞은 두께의 돌을 덮어 안정된 모양새를 띠고 있다. 탑신 1층이 큰 점이 특징적인데, 2층부터는 높이가 뚜렷하게 줄어들지만 넓이는 크게…","a":"청양 서정리 구층석탑","c":"보물","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617405.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하는데, 천태종의 근본경전으로 화엄경과 함께 한국 불교사상 확립에 크게 영향을 끼친 경전이다. ○○○○○ 중 권5에서 권7에 해당하는 이 책은 태종 5년(1405)에 성달생·성개 형제가 죽은 아버지의 명복을 빌기 위해 옮겨 쓴 것을 도인(道人) 신문(信文)이 목판에 새겨 찍어낸 것이다. 닥종이에 찍은 목판본으로 3권을 하나의 책으로 엮었으며, 책의 크기는 세로 29㎝, 가로 30.5㎝이다. 책의 첫 머리에는 불경의 내용을 요약하여 그린 변상도(變相圖)가 있는데, 고려 우왕의 극락왕생을 기원하기 위해 정씨 성을 가진 사람이…","a":"묘법연화경 권5~7(1988-2)","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614340.jpg"},{"q":"원래는 완주(完州) 봉림사터에 있던 것을 지금의 위치로 옮겨 세웠다. 2단의 기단(基壇) 위에 5층의 탑신(塔身)을 올린 형태였으나 지금은 탑신의 한 층이 없어지고 4층까지만 남아있다. 아래·위 기단 모두 모서리와 가운데에 기둥 모양의 조각을 두었으며, 기단 위로 4층의 탑신에는 각 층의 몸돌마다 네 모서리에 기둥 모양을 새겨 놓았다. 지붕돌은 경사가 급하고 추녀 끝이 약간 들려 곡선을 이루고 있으며, 밑에는 3단의 받침을 두어 고려시대의 모습을 보여주고 있다. 탑 머리 부분에는 머리 장식이 일부 남아 있으나 훗날 보충한 것으로 보인다. 이 탑은 전체적으로 균형미가…","a":"군산 발산리 오층석탑","c":"보물","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618270.jpg"},{"q":"평안남도 대동군 ○○○ 9호분에서 출토된 ○○교구로, 길이 9.4㎝, 너비 6.4㎝이며, 허리띠를 연결시켜주는 ○○ 장식이다. 머리쪽이 넓고 둥글게 되어 있으며, 안쪽에 이와 평행하게 휘어진 구멍을 만들었고 걸 수 있는 고리를 만들어 허리띠를 매게 하였다. 틀을 만들어 그 위에 금판을 놓고 두드려 용의 윤곽을 만들고 금실과 금 알갱이로 큰 용 한마리와 작은 용 여섯마리를 만들었다. 가장자리는 금실을 꼬아서 돌렸고, 안으로 일정한 넓이의 삼각형을 만들었다. 용과 용사이에는 꽃잎모양의 윤곽을 만들고 그 속에 비취옥(玉)을 끼워 넣었는데 현재 7개만이 남아 있다. 금실을…","a":"평양 석암리 금제 띠고리","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611501.jpg"},{"q":"쇠부리 마을 가운데에 자리잡은 기와집으로 1918년에 지었다. 동향한 넓은 터에 북향 대문을 들어서면 정면에 'T'자형의 사랑채가 있고, 오른쪽으로는 바깥행랑채가 있다. 사랑채 안쪽에는 'ㄱ'자형의 안채와 '一'자형의 안행랑채, 그리고 곳간이 있어 전체적으로 튼 'ㅁ'자형을 이루고 있다. 이 집은 안채, 특히 부엌이 주택전체의 중심을 잡고 있는 집이다. 안채는 'ㄱ'자형의 꺾인 부분을 한번 접은 모양이고 꺾인 좌우가 거의 대등한 규모이다. 그 중앙에 부엌이 있는데, 부엌은 거의 정사각형으로 내부에는 기둥이 두 개만 서 있어 넓게 보인다. 부엌으로 출입하는 통로는 앞에…","a":"함양 허삼둘 고택","c":"국가민속문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635924.jpg"},{"q":"○○○은 조선 상류주택의 별당 건물로 경포호가 멀리 바라다 보이는 곳에 있으며, 조선 중종 25년(1530)에 어촌 심언광이 강원도 관찰사로 있을 때 지은 것으로 전한다. 심언광 선생은 조선 중종 2년(1507) 진사가 된 뒤, 여러 벼슬을 두루 거친 분으로 문장에도 뛰어났다. 이 건물은 3단으로 쌓은 축대 위에 남향으로 지었는데, 규모는 앞면 3칸·옆면 2칸으로 안쪽의 오른쪽 2칸은 대청이며 왼쪽 1칸은 온돌방이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕으로 꾸몄고, 대청 앞면에는 문을 달아 모두 열 수 있게 하였다. 건물 주위에는 툇마루를 돌려 놓…","a":"강릉 해운정","c":"보물","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616406.jpg"},{"q":"조선 숙종 때 경기도와 경상도 지역에서 활동한 승려장인 ○○○○에 의해서 만들어진 조선시대 종이다. ○○○○는 18세기 뛰어난 승려이자 범종 장인으로 전통적인 한국 종의 제조기법에 독창성을 지닌 요소를 결합한 종을 만들었다. 현재 그의 작품 8구가 서로 다른 특징을 보이며 전해지고 있다. 이 종은 조선 후기의 종 형태를 가장 잘 보여주고 있다. 특히 같은 해 만들어진 홍천 수타사○○과 함께 종을 치는 부분인 당좌 주위를 화려한 구름형태의 문양을 첨가한 독특한 당좌 형태로 표현하였다. 명문에 의하면 이 종은 1670년 수타사 ○○보다 3개월 먼저 만들어진 것으로, ○○…","a":"사인비구 제작 동종 - 문경 김룡사 동종","c":"보물","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620025.jpg"},{"q":"｢○○○○○｣은 조선후기 명의(名醫)로 알려진 박한진(朴翰鎭, 1815∼1893)이 살았던 곳으로 1820년 건립되었다고 전하며, ○○○이란 당호는 박한진의 호를 따서 후손들이 붙인 명칭이다. 오고선생 유고집에 전해 내려오는 이야기에 의하면, 박한진이 61세 때인 1875년(고종 12년) 헌종의 생모인 조대비 신정왕후(神貞王后, 1808∼1890)의 병환을 고친 후 임금이 그의 의술을 높이 평가하여 명가전만리(名可傳萬里 : 명성이 만리에 전해질 것이다)라 하여 만리(萬里)라는 호를 내리셨고, 벼슬을 내려 고마움을 표하려 하였으나 그는 이를 거듭 사양하였다고 한다. 이…","a":"봉화 오고당 고택","c":"국가민속문화유산","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2020110911445400.JPG"},{"q":"조선시대 원각사터에 세운 ○○ 최초의 근대식 공원으로 파고다 공원이라고도 불리운다. 원각사는 고려 때 흥복사라 불린 절로, 조선 전기에 절을 넓히면서 원각사로 이름을 바꾸었다. 그러나 불교를 억누르는 정책으로 인해 연산군과 중종때 절이 폐사되었다. 그 후 영국인 브라운의 건의로 이곳에 서양식 공원을 세웠으나, 그 이유와 시기에 대한 정확한 기록은 없다. 공원 안에는 원각사지 10층석탑(국보)과 원각사비(보물)가 있다. 또한 독립선언문을 낭독하고 만세를 부른 팔각정·독립만세 부조판·손병희 선생의 동상들도 있다. 1919년 3월 1일 처음으로 독립선언문을 낭독하고 독립만…","a":"서울 탑골공원","c":"사적","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624973.jpg"},{"q":"○○○○○은 충청남도 유형문화유산으로 지정된 ○○○○○에서 나온 것인데, 1993년 불상은 도난당하고 ○○○○만이 전해진다. ○○○○○의 복장에서는 경전·다라니 등의 인쇄자료와 발원문 및 물목을 기재한 필사자료 등 17종 504종에 이르는 다양한 전적류와 함께 고려말 제작된 복식(답호)과 각종 직물류 및 팔엽통 등의 유물이 발견되었다. 전적류 ○○○○에서 인쇄자료 중 ‘묘법연화경’과 ‘인왕호국반야바라밀경(仁王護國般若波羅蜜經)’은 각각 각필과 석독구결(釋讀口訣)이 있어 국어사 연구에 귀중한 자료로 평가되며 필사자료 중 ‘至正六年(1346)’의 연기(年記)를 지닌 발원문…","a":"서산 문수사 금동여래좌상 복장유물","c":"보물","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618082.jpg"},{"q":"○○○는 신라시대 8대 사찰 중 하나로 절의 역사에 관한 뚜렷한 기록은 없다. 임진왜란 때 ○○○만 남기고 다른 건물들은 모두 불에 타버렸다고 한다. ○○○은 조선 전기의 건물로 추정하며, 건물 안에는 중생의 병을 고쳐 준다는 약사여래를 모시고 있다. 규모는 앞면 1칸·옆면 1칸으로 매우 작은 불당이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로, 지붕 처마를 받치기 위해 장식하여 짜은 간결한 형태는 기둥 위에만 있는 주심포 양식이다. 이와 비슷한 구성을 가진 영암 도갑사 해탈문(국보), 순천 송광사 국사전(국보)과 좋은 비교가 된다. 옆면 지붕이…","a":"창녕 관룡사 약사전","c":"보물","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622368.jpg"},{"q":"경주시 노서동에 있는 ○○○에서 발견된 신라의 ○○으로, 높이 44.4㎝, 머리띠 지름 19㎝이다. ○○은 내관(內冠)과 외관(外冠)으로 구성되어 있는데, 이 ○○은 바깥에 쓰는 관으로 신라○○의 전형적인 형태를 갖추었다. 즉, 원형의 머리띠 정면에 3단으로 ‘출(出)’자 모양의 장식 3개를 두고, 뒤쪽 좌우에 2개의 사슴뿔모양 장식이 세워져 있다. 머리띠와 ‘출(出)’자 장식 주위에는 점선문을 장식하였고, 많은 비취색 옥과 구슬모양의 장식들이 규칙적으로 금실에 매달려 있다. 양 끝에는 가는 고리에 금으로 된 사슬이 늘어진 두 줄의 장식이 있는데, 일정한 간격으로 나…","a":"금관총 금관 및 금제 관식","c":"국보","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612812.jpg"},{"q":"불교경전은 크게 경(經), 율(律), 논(論)으로 나누어 지는데, 아비달마는 부처님의 지혜를 체계적으로 설명하고 있는 논(論)부분을 총칭하여 이르는 말이다. ○○○○○은 성불(成佛)하는데 필요한 부처님의 지혜를 체계적으로 모아 설명하고 있는 부분이라고 할 수 있다. 이 책은 고려 현종 때(재위 1011∼1031) 부처님의 힘으로 거란의 침입을 극복하고자 만든 초조대장경 가운데 하나로, 당나라 현장(玄奘)이 번역한 16권 가운데 권 제13이다. 닥종이에 찍은 목판본으로 종이를 길게 이어 붙여 두루마리처럼 말아서 보관할 수 있도록 되어 있으며, 세로 29㎝, 가로 45.…","a":"초조본 아비달마식신족론 권13","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614463.jpg"},{"q":"이 책은 조선 중기의 문신인 서애 유성룡(1542∼1607)이 임진왜란 때의 상황을 기록한 것이다. 징비란 미리 징계하여 후환을 경계한다는 뜻이다. 유성룡은 퇴계 이황의 문인이며, 김성일과 동문수학하였다. 명종 21년(1566) 문과에 급제하여 승문원권예문관검열, 공조좌랑, 이조좌랑 등의 벼슬을 거쳐 삼정승을 모두 지냈다. 왜적이 쳐들어올 것을 알고 장군인 권율과 이순신을 중용하도록 추천하였고, 화포 등 각종 무기의 제조, 성곽을 세울 것을 건의하고 군비확충에 노력하였다. 또한 도학·문장·글씨 등으로 이름을 떨쳤으며, 그가 죽은 후 문충이라는 시호가 내려졌고, 안동의…","a":"징비록","c":"국보","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612856.jpg"},{"q":"○○○은 조선시대 역대 임금의 초상을 봉안하고 제사를 지내는 건물로 궁궐 밖으로는 종묘를 두었고, 궁 안에는 ○○○을 두었다고 한다. 원래 춘휘전이란 건물로 조선 효종 7년(1656) 경덕궁의 경화당을 옮겨지은 것으로, 숙종 21년(1695)에 ○○○으로 이름을 바꾸었다. 이곳에는 숙종·영조·정조·순조·익종·헌종의 초상을 모시고 있다. 1921년 ○○○ 후원 서북쪽에 ○○○을 새로 지어 왕의 초상을 옮긴 뒤부터 구○○○으로 불리게 되었다. 새로 지은 ○○○에 옮긴 왕의 초상은 1950년 한국전쟁 당시 화재로 소실되어 아쉬움을 더 한다. 구조적으로 간결하고 불필요한 장…","a":"창덕궁 선원전","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614020.jpg"},{"q":"○○○○○은 한국전쟁 당시 소실된 후 철근콘크리트를 사용하여 다포양식의 팔작지붕으로 건립하였고, 현판에 ‘대웅전’이라 하지 않고 ‘○○○’이라 하는 등 불교대중화에 앞장선 운허스님의 뜻이 잘 드러난 건물이다. 근대 건축 재료와 구조로 전통성을 표현하고자 했던 60∼70년대 당시의 기술을 대표하는 사례로 근대건축사적, 불교사적 가치가 크다.","a":"남양주 봉선사 큰법당","c":"국가등록문화유산","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668202.jpg"},{"q":"○○○○○은 의원동, 주택동, 병동이 동일 구조 및 일체화된 지붕으로 건축되었고, 주택동은 별도의 출입구와 마당을 두어 의원동과 분리되게 구성하였으며, 의원동에 접한 병동은 ‘ㄷ’자 형태의 툇마루로 별동의 단층병동과 연결되어 있다. 해방이후 건립된 지방의료시설로 의원, 주택, 병동 건축물 모두가 잘 남아있어 의료사적, 건축사적 보존가치가 높다.","a":"거창 구 자생의원","c":"국가등록문화유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669537.jpg"},{"q":"단속사 터의 금당터 앞에는 동서로 두 탑이 서 있는데 그 중 서쪽에 세워진 것이 이 탑이다. 2단의 기단(基壇)에 3층의 탑신(塔身)을 올린 통일신라시대의 전형적인 모습이나, 동탑에 비하여 많이 부서지고 안에 봉안된 사리함이 도난당하는 등 많은 수난을 겪었다. 기단에는 각 면의 모서리에 기둥 모양의 조각을 두었는데, 아랫단은 가운데에 2개씩을 두고 윗단은 1개씩 두었다. 탑신의 지붕돌은 처마를 직선으로 처리하였으며, 밋밋한 경사가 흐르는 윗면은 네 귀퉁이에서 하늘을 향해 살짝 들어 올렸다. 지붕돌을 경쾌하게 처리한 점이나, 탑의 윗부분으로 갈수록 크기가 알맞게 줄어드…","a":"산청 단속사지 서 삼층석탑","c":"보물","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622339.jpg"},{"q":"경기도 ○○시 봉담읍 ○○○에 있는 ○○○○○ 백제○○○은 1995년 경부고속철도 경기·충청권 구간에 대한 지표조사 및 시굴조사과정에서 처음 발견되었다. 1996∼1997년 사이에 서울대학교박물관과 호암미술관에서 실시한 발굴조사 결과, 원삼국∼삼국시대에 이르는 많은 고분이 밀집되어 분포하고 있는 것이 확인되었다. 고분의 형태는 널무덤(목관묘), 덧널무덤(목곽묘), 돌덧널무덤(석곽묘) 등 여러 형태가 나타나고 있다. 그리고 출토유물은 유리제·구슬·철기류 그리고 다양한 형태의 토기 등이 다수 발견되었다. ○○○○○ 백제○○○은 당시의 묘제와 토기의 변천과정, 편년 연구…","a":"화성 마하리 고분군","c":"사적","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625973.jpg"},{"q":"서애 유성룡의 학문과 업적을 기리기 위한 곳으로, ○○에서 서남쪽으로 낙동강 상류가 굽이치는 곳에 화산(花山)을 등지고 자리하고 있다. 유성룡은 도학·글씨·문장·덕행으로 이름을 날렸을 뿐만 아니라, 임진왜란 때에도 성곽 수축·화기제작을 비롯하여 군비확충에 힘써 많은 공을 세운 인물이다. 원래 풍악서당으로 풍산 유씨의 교육기관 이었는데, 유성룡이 선조 5년(1572)에 이곳으로 옮겼다. 그 후 광해군 6년(1614)에 존덕사를 세워 그의 위패를 모시고, 1629년에 그의 셋째 아들 유진의 위패를 추가로 모셨다. 철종 14년(1863)에는 임금으로부터 ‘병산’이라는 이름…","a":"안동 병산서원","c":"사적","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627867.jpg"},{"q":"1929년 건립된 이 건물은 일본인 자녀 교육을 위해 목포에 처음으로 설립한 ○○○○○의 강당이다. 철근 콘크리트 구조에 앞쪽과 양쪽 면은 두 가지 색깔의 타일로 마감하였으며, 2층에는 폭이 좁은 아치창을 두었다. 목포에 남아 있는 유일한 일제 강점기의 초등학교 건물로 당시 강당 건축의 특징을 잘 나타내고 있다.","a":"구 목포공립심상소학교","c":"국가등록문화유산","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668831.jpg"},{"q":"­1910년경에 건축된 근대기 단층 한옥기와집으로 시조시인 이호우(李鎬雨), ○○○의 ○○ 안채와 사랑채가 'ㄱ'자형으로 구성되어 있다","a":"청도 이호우와 이영도 생가","c":"국가등록문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669141.jpg"},{"q":"○○○○○은 고려시대 문인이었던 최해(崔瀣,1287∼1340)가 편집한 책이다. 그의 문집인 『졸고천백(拙藁千百)』에는 「동인문서(序)」와 「동인사륙서(序)」가 있다. 「동인문서」에 의하면 그는 우리나라 시문을 선집하여 시를「오칠」, 문을「천백」, 병려를「사륙」이라고 이름을 붙였다. 「동인사륙서」에는 「사륙」에 대해 따로 체례(體例) 문제를 서술하였다. 그러나 현재 전하는 『○○○○』에는 「오칠」, 「천백」은 거의 보이지 않고, 「사륙」만이 남아있다. 이 책은 신라와 고려시대의 문장을 모은 것으로, 크기는 가로 19.7㎝, 세로 31.8㎝이며, 권 7의 마지막에『진주…","a":"동인지문사육 권7~9(1981)","c":"보물","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613730.jpg"},{"q":"고려 충렬왕 15년(1289)에 입적한 보각국사 일연의 사리탑과 그의 행적을 기록해 놓은 탑비이다. 일연은 『삼국유사』를 저술하는 등 많은 업적을 이룬 승려인데, 노년에 ○○○에서 늙으신 어머니를 지극히 봉양하였다고 한다. 전하는 말에 의하면, 아침에 해가 뜰 때 이 탑에서 광채가 나와 멀지 않은 곳에 있는 일연스님 어머니의 묘를 비추었다고 한다. 탑은 자연석으로 된 바닥돌 위에 8각의 아래받침돌을 놓았는데 윗면이 급한 경사를 이루고 있다. 가운데받침돌 역시 8각으로, 동물을 조각하였으나 뚜렷하지 않다. 윗받침돌은 8각이지만 원형에 가깝고, 단조롭고 소박한 연꽃이 새…","a":"군위 인각사 보각국사탑 및 비","c":"보물","r":"대구광역시","s":"군위군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620913.jpg"},{"q":"○○○○○토기유적은 지난 2001년 ○○○ 일대에서 분묘조성을 위한 개발사업 중 유적이 노출된 것이 발견되어 긴급 발굴조사를 통해 확인되었다. ○○○○○유적은 영산강의 남안 구릉지역으로 ○○복암리고분군과 반남고분군사이에 있는데 영산강 본류와 인접하여 강을 통한 교통의 ○○에 해당되는 곳이기도 하다. 지난 2001년과 2002년 2차례에 걸친 발굴조사 결과 노출된 17기의 가마 중 총 5기의 가마를 조사하였는데 주로 옹관을 조성하던 가마로 추정된다. 가마에서는 다량의 옹관편을 비롯하여 개배류, 기타 토기편 등이 출토되었고 가마부근에서는 석곽묘 2기가 조사되었다. 유적의…","a":"나주 오량동 요지","c":"사적","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627388.jpg"},{"q":"거대한 천연 암벽에 2구의 불상을 우람하게 새겼는데, 머리 위에는 돌갓을 얹어 토속적인 분위기를 느끼게 한다. 자연석을 그대로 이용한 까닭에 신체 비율이 맞지 않아 굉장히 거대한 느낌이 든다. 이런 점에서 불성(佛性)보다는 세속적인 특징이 잘 나타나는 지방화된 불상이다. 왼쪽의 둥근 갓을 쓴 원립불(圓笠佛)은 목이 원통형이고 두손은 가슴앞에서 연꽃을 쥐고 있다. 오른쪽의 4각형 갓을 쓴 방립불(方笠佛)은 합장한 손모양이 다를 뿐 신체조각은 왼쪽 불상과 같다. 지방민의 구전에 의하면, 둥근 갓의 불상은 남상(男像), 모난 갓의 불상은 여상(女像)이라 한다. 고려 선종이…","a":"파주 용미리 마애이불입상","c":"보물","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615671.jpg"},{"q":"이 책은 북제(北齊)의 승려 도기(道紀)가 각 경전에서 불교 교화에 도움이 되는 인과응보에 관한 설화를 중심으로 편찬한 7권 가운데 2권(○○○○)이다. 권두서명 다음 행에 간략한 목차가 수록되어 있는데 이 책을 구성하고 있는 22개 연(緣: 篇에 해당)의 이름이 구체적으로 나타나고 있어 전체 내용을 조망해 볼 수 있다. 이 간략 목차 다음에 바로 <사견연제일(邪見緣第一)>의 편제(篇題)가 시작되고 있는데, 편제의 다음에는 각 편의 세부 목차가 기재되어 있다. 각 세부 내용이 시작되는 제목 아래에는 전재해 온 내용의 정확한 출처를 소자쌍행(小字雙行)의 형식으로 밝히고…","a":"금장요집경 권1~2","c":"보물","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615118.jpg"},{"q":"이 ○○○는 ○○ 지역 최초의 수도 시설 가운데 하나로, 수도산 기슭에 대봉 1호 ○○○를 건립한 후 급수 수요가 증가하자 2호 ○○○를 추가로 건립하였다. 대봉 1호 ○○○는 원통형 철근콘크리트 구조물로 11개의 원형 창을 일정한 간격으로 배치하였으며, 창 주위에는 곡선형 테두리를 돌려 장식하였다. 붉은 벽돌과 정교하게 가공된 화강석을 사용해 화려하게 장식한 접합정을 비롯하여 염소 투입실, 돔 형태의 작은 건물 등 여러 시설물이 잘 보존되어 있다.","a":"대구 대봉배수지","c":"국가등록문화유산","r":"대구광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667792.jpg"},{"q":"이 건물은 ○○ 지역에서 처음 세워진 교회로, 조선 시대 ○○읍성 병사 숙소로 쓰던 건물의 부재로 건립하였다. 평면은 동서로 긴 장방형으로, 남쪽에 주 출입구를 설치하고 좌우에 창문을 설치하였으며, 주 출입구로 들어가서 오른쪽에 강단을 배치하였다. 전체적으로 보존 상태가 양호하고 ○○ 지역의 초기 한옥형 교회 건축물로 근대 건축사적 가치가 있다.","a":"울진 행곡교회","c":"국가등록문화유산","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669123.jpg"},{"q":"조선 중기의 문신인 초간 권문해(1534∼1591) 선생의 할아버지 권오상 선생이 지었다고 전하는 건물이다. 규모는 앞면 4칸·옆면 2칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 앞쪽에서 보면 오른쪽 3칸은 대청마루고 왼쪽 1칸은 온돌방인데 온돌방은 다시 2개로 나뉘어 있다. 대청 앞면은 문짝 없이 열려 있지만 옆면과 뒷면은 2짝 널문을 달았으며 집 주위로 난간을 돌려 누(樓)집과 같은 모양으로 꾸몄다. 겉모습은 대체로 소박한 구조를 보이고 있으나 안쪽은 천장 부분에 설치한 여러 재료들을 정교하고 화려하게 장식하여 호화롭게 꾸미고 있다. ○…","a":"예천권씨 초간종택 별당","c":"보물","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620996.jpg"},{"q":"1926년 ○○○○○으로 건립하여 현재 ○○○○○ 본관으로 사용하고 있는 지상 4층(지붕층 포함) 건물로, 1977년 대규모로 개.보수가 있었으나 본래의 의장 특징을 그대로 유지하고 있는 등 원형의 보존 상태가 비교적 양호하다. 실내공간을 밝게하기 위해 창호를 넓게 구성하고 이를 위해 철근콘크리트 상인방(上引防)을 사용하는 등 건립 당시의 건축적 특징을 잘 보여주고 있으며, 과학관과 더불어 우리나라 근대시기 교육시설로서의 보존.활용 가치가 있어 등록하였다.","a":"서울 배화여자고등학교 캠벨기념관","c":"국가등록문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017010916415900.JPG"},{"q":"○○○는 덕숭산에 자리잡고 있는 절로, 절에 남겨진 기록에는 백제 후기 숭제법사가 처음 짓고 고려 공민왕 때 나옹이 다시 고친 것으로 기록되어 있고, 또 다른 기록에는 백제 법왕 1년(599)에 지명법사가 짓고 원효가 다시 고쳤다고도 전한다. 석가모니불상을 모셔 놓은 ○○○은 고려 충렬왕 34년(1308)에 지은 건물로, 지은 시기를 정확하게 알 수 있는 우리 나라에서 가장 오래된 목조건물 중의 하나이다. 앞면 3칸·옆면 4칸 크기이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다. 지붕 처마를 받치기 위한 구조가 기둥 위에만 있는 주심포 양…","a":"예산 수덕사 대웅전","c":"국보","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612236.jpg"},{"q":"금강반야바라밀경은 줄여서 ‘금강경’이라고 부르기도 하는데, 조계종의 근본 경전으로 우리나라에서는 반야심경 다음으로 많이 읽히는 경전이다. 이 책은 당나라 현장(玄奘)이 번역한『대반야경』600권 가운데 ○○○○이다. 검푸른 빛이 도는 종이에 금색으로 글씨를 썼으며, 크기는 세로 28.7㎝, 가로 510㎝이다. 1권이 종이 10장을 연결하여 두루마리 형태로 만든 1축으로 되어 있다. 고려 문종 9년(1055)에 김융범이 조·부모의 명복과 가족의 안녕을 위해 만들었는데, 불경의 내용을 정성껏 옮겨 적고 그림을 그려 화려하게 꾸몄다. 권 머리부분은 5장이 탈락되어 있으나,…","a":"감지금니 대반야바라밀다경 권175","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614202.jpg"},{"q":"신라 31대 ○○○의 무덤이다. ○○○은 문무왕의 아들로 귀족들의 반란을 진압한 후 신라 중대 전제왕권을 확고히 하였다. 국립교육기관인 국학을 설립하고, 지방통치를 위해 9주5소경제도를 설치하였고, 고구려·백제·말갈인을 포함시킨 중앙 군사조직인 9서당을 완성하는 등 중앙과 지방의 정치제도를 정비하여 전제왕권을 다졌다. 높이 7.6m, 지름 29.3m의 둥글게 흙을 쌓은 원형 봉토무덤이다. 둘레돌은 벽돌모양으로 다듬어 5단으로 쌓았고 44개의 삼각형 받침돌이 둘레돌을 튼튼하게 받치고 있다. 『삼국사기』에 의하면 낭산(狼山) 동쪽에 ○○○을 장사지냈다고 되어있어, 낭산…","a":"경주 신문왕릉","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627794.jpg"},{"q":"조선 후기 충청도 지역 군현 지도들을 수록한 지도첩이다. 채색필사본이며, 영조~정조 연간에 제작된 것으로 추정된다. 제3책의 충청도 도지도(都地圖)와 제5책의 문의(文義) 지도 뒷면에 ‘비변사(備邊司)’라는 도장이 찍혀 있어, 비변에서 소장하며 사용하던 지도임을 알 수 있다. 지도책은 총 6책으로 구성되어 있으며, 2장의 충청도 전도(全圖)와 67장의 군현 지도가 수록되어 있다. 군현 지도는 1리 방안, 도별 지도는 10리 방안의 눈금 위에 그려져 있다. 한편, 제4책의 12장과 제6책의 16장 등 일부 지도는 방안지도가 아니라 전통적인 회화식 군현지도의 형식을 취하…","a":"호서지도","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614925.jpg"},{"q":"○○○은 경주 황남동고분 제155호 무덤으로 1973년 발굴하여 금관, 팔찌 등 많은 귀중한 유품들과 함께 천마 그림이 발견되어 ○○○이라 부르게 되었다. ○○○○○는 칼 중에서 손잡이 끝부분에 둥그런 고리가 붙어있고 그 고리안에 용이나 봉황, 나뭇잎들을 조각하여 그 소장자의 신분이나 지위를 나타내 주는 칼이다. ○○○에서 고리자루큰칼은 칼자루에 손상이 있을 뿐 양호한 상태를 유지하고 있으며, 유골의 왼쪽부분에서 발견되었다. 칼집과 칼자루는 나무로 만들어 그 위에 얇은 금동을 입혔다. 칼자루 끝 둥근 모양 안에 봉황으로 보이는 새의 머리가 붙어있다. 칼집의 표면에는…","a":"천마총 환두대도","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621297.jpg"},{"q":"이 석탑은 무너져 있던 것을 2000년∼2001년까지 2차례에 걸친 발굴조사를 선행한 후, 석탑 부재를 모아 2002년에 복원하였는데 노반석 아래의 부재는 남아있는 원 부재를 사용하였다. ○○○○○에 관한 문헌기록이 없어 ○○○○○이 언제 건립되었는지 확인할 만한 근거는 아직 밝혀지지 않고 있으나 탑지 주변에서 ‘용(茸)’자명을 비롯한 9점의 명문와가 출토되어 용장사(茸長寺)와의 연관성이 짐작된다. 용장사지(탑상곡 제 1사지)에는 ○○○○과 마애불좌상, 석불좌상이 전해오며, 그 일대에 여러 사찰이 있었던 것으로 보인다. 또한 ○○○○○에서 출토된 와당을 비롯한 여러…","a":"경주 남산 용장계 지곡 제3사지 삼층석탑","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2017040708555600.JPG"},{"q":"1935년 건립된 이 건물은 일제 강점기 당시 건립된 ○○으로, 학교 ○○의 기능을 했을 뿐만 아니라 ○○ 지역 사회의 대형 집회 공간으로 이용해 온 역사적인 장소이다. 15미터나 되는 너비를 중간 기둥 없이 처리한 것이 특징적이며 전체적으로 아주 간결하면서도 기능적이다. 이 건물은 당시 ○○○○○ 학생들이 많은 애국지사 등의 강의를 들으며 청운의 꿈을 키웠던 곳이기도 하다.","a":"인천 제물포고등학교 강당","c":"국가등록문화유산","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667840.jpg"},{"q":"○○○는 신라 진덕여왕 5년(651)에 의상대사가 세웠다고 전하는 절이다. ○○○○은 절에서 석가모니불상을 모셔 놓은 중심 법당을 가리키며 지금 있는 건물은 안에 있는 탱화의 기록으로 영조 원년(1725)에 세운 것으로 생각하고 있다. 규모는 앞면과 옆면이 모두 3칸씩이고 지붕은 옆면에서 볼 때, 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위와 기둥 사이에도 있는 다포 양식으로, 각 공포의 조각 솜씨가 뛰어나다. 가장 주목할만한 점은 건물에 색을 칠한 단청 부분을 들 수 있는데 바깥쪽은 다시 칠하여 원래 모습을 잃었지…","a":"울진 불영사 대웅보전","c":"보물","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622076.jpg"},{"q":"조선 후기의 성리학자이자 문신인 ○○의 ○○이다. 이 ○○ 상은 심의(深衣)를 입고 정자관(程子冠)을 쓴 뒤 두 손을 공수(拱手)한 채 정면을 바라보고 있는 반신상인데, 눈부시게 수려한 용모를 실로 뛰어난 화법으로 묘사하고 있을 뿐만 아니라, 화면 상부에 경산(京山) 이한진(李漢鎭, 1732 ~ 1815)과 기원(綺園) 유한지(兪漢芝, 1760 ~ 1834) 등 당대 명필들의 미려한 찬문(贊文)이 조화롭게 어우러져 있어 조선 후기 연거복(燕居服) ○○화의 가장 아름다운 걸작 가운데 하나로 일컬어진다. 이 ○○ 상은 조선 후기 19세기 초반의 가장 대표적인 유학자 상으…","a":"이채 초상","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614871.jpg"},{"q":"경북 ○○시 ○○○에 있는 3층 석탑으로, 탑 주변에 민가가 들어서 있어 절 터의 흔적은 찾을 수 없으며, 절이름 또한 알 길이 없다. 탑신(塔身)을 받치고 있는 기단(基壇)을 위·아래 2단으로 꾸민 3층 석탑의 모습으로, 주목할 점은 아래층 기단에 아름다운 안상(眼象)이 새겨져 있다는 것이다. 윗층 기단은 윗면에서 상당한 경사를 보이고 각 모서리도 약간 위로 치켜 올려진 전혀 새로운 형식을 갖추었는데, 그 모습이 마치 지붕돌로 보일 정도이다. 탑신은 몸돌과 지붕돌이 각각 하나의 돌로 되어 있고, 지붕돌은 처마밑이 직선이며, 풍경을 달았던 작은 구멍들이 남아 있다.…","a":"안동 평화동 삼층석탑","c":"보물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620214.jpg"},{"q":"○○○○○은 고려시대 김희선 등이 모은 『삼화자향약방』과 조선시대 권중화가 펴낸 『향약간역방』을 중심으로, 당시의 의료경험과 의학서적을 참고, 보충하여 태조 7년(1398)에 펴내고, 이듬해 김희선이 강원감영에서 간행한 의학과 약학에 관한 서적이다. 『○○○○○』총 30권 가운데 제6권으로 완질이 아니다. 목판의 크기도 다소 차이가 있을 뿐만 아니라, 누락된 부분도 있어서 자세한 내용을 다 파악할 수는 없으나, 권근의 『양촌집』과 김성수의 『한의학서지 발전에 관한 고찰』에 의하면 그 간행경위와 약방문 수록 범위 등을 대략 유추할 수 있다. 즉 전 30권에는 ‘338종…","a":"향약제생집성방 권6","c":"보물","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615410.jpg"},{"q":"조선시대 성리학 중심지 중 한 곳인 우암 ○○○○○이다. ○○○은 조선 후기의 성리학자이자 문신으로 조선 효종(재위1649∼1659)을 도와 북벌정책을 추진하는 등 자주적인 정치를 펼쳤으며, 주자학의 대가로서 많은 인재를 양성하였다. 화양서원은 우암 ○○○이 잠시 머물렀던 장소에 세워진 서원으로 조선시대 학자들이 많이 모였던 장소이다. 만동묘의 자리는 중국 명나라 황제인 신종과 의종의 위패를 모신 사당이 있던 곳이다. 만동묘 주변에는 ○○○과 관련된 암서재, 하마비, 읍궁암, ○○○ 무덤 및 신도비 외에 암서재 근처의 암벽에 ‘충효절의’·‘비례부동’이란 글을 새긴 곳…","a":"괴산 송시열 유적","c":"사적","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626350.jpg"},{"q":"원당사의 옛 터에 세워져 있는 석탑이다. 원당사는 조선 중기에 폐지되었고, 1950년대 이후 절터에 새로이 지어진 ○○○가 대신 자리잡고 있다. 탑은 1단의 기단(基壇) 위로 5층의 탑신(塔身)을 두고, 머리장식을 얹어 마무리한 모습이다. 탑 주변에는 돌담이 둘려져 있다. 기단은 뒷면을 뺀 세 면에 안상(眼象)을 얕게 새겼는데, 무늬의 바닥선이 꽃무늬처럼 솟아나도록 조각하였다. 탑신의 1층 몸돌 남쪽면에는 감실(龕室:불상을 모셔두는 방)을 만들어 놓았다. 지붕돌은 윗면의 경사가 그리 크지 않지만, 네 귀퉁이에서 뚜렷하게 치켜 올려져 있다. 꼭대기에 올려진 머리장식은…","a":"제주 불탑사 오층석탑","c":"보물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1623085.jpg"},{"q":"1920년대 건립 이 ○○○는 일제 강점기 ○○○을 중심으로 한국인 억압이 행해졌던 건물이었으며, 1980년 이후에는 부산항운노동조합 사무실로 사용되었다. 장방형의 평면에 중앙 출입구 위에는 박공형 캐노피를 설치하여 정면성을 강조하였고, 내부 공간은 단일 홀 형식으로 단순하게 구성되었다. 내·외부 벽체, 내부 바닥, 지붕 등 근대 건축 초기의 일반적인 재료와 기법을 보여주고 있다.","a":"구 밀양역 파출소","c":"국가등록문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669444.jpg"},{"q":"고려의 승려 제관이 천태사상을 집약하여 정리한 것으로 이론과 실천이 같이 어울려야 비로소 깨달음을 얻을 수 있다는 내용을 담고 있다. 닥종이에 찍은 목판본으로 2권의 책 중 상권 1책이며 크기는 세로 24.5㎝, 가로 16.5㎝이다. 책 끝에 있는 목암노인이 쓴 글에 의하면, 오래된 판본이 있었는데 글자가 크고 책이 무거워 휴대하기 불편하여 굉지대선사(宏之大禪師)가 수여(水如)에게 다시 쓰도록 하여 충숙왕 2년(1315)에 기복도감(祈福都監)에서 간행한 것이다. 이 책은 기복도감에서 다소 뒤에 찍어 낸 판본이지만, 본문이 완전하게 판독될 수 있을 정도로 보존상태가 양…","a":"천태사교의","c":"보물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615948.jpg"},{"q":"○○○은 ○○○의 중심 건물인 근정전의 남문으로 좌우에 ○○이 둘러싸고 있다. 조선시대 태조 4년(1395) ○○○을 세울 때 함께 지었으나 임진왜란으로 불에 타 버렸다. 지금 있는 건물은 고종 4년(1867) ○○○을 다시 지으면서 새로 만든 것이다. ○○○은 앞면 3칸·옆면 2칸의 2층 건물로, 지붕은 앞면에서 볼 때 사다리꼴을 한 우진각지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위뿐만 아니라 기둥 사이에도 있다. 이를 다포 양식이라 하며 밖으로 뻗쳐 나온 부재들의 형태가 날카롭고 곡선을 크게 그리고 있어 조선 후기의 일반적인 수법을 나타내고…","a":"경복궁 근정문 및 행각","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613973.jpg"},{"q":"○○○는 통일신라시대 선종 9산 중 가장 먼저 만들어진 가지산파의 중심사찰로, 헌안왕 4년(860)에 왕의 권유를 받아 체징이 창건하였다. 동부도는 ○○○○쪽 숲 속에 있는 여러 ○○ 중 가장 뛰어난 작품으로 손꼽힌다. 승려의 사리를 두는 탑신(塔身)을 중심으로 아래에는 3단의 기단(基壇)을 두고 위로는 머리장식을 얹었는데, 각 부분이 8각으로 깍여져 있다. 3단으로 된 기단의 맨아랫단과 맨윗단에는 8잎의 연꽃잎을 둘러 새기고 각 귀퉁이마다 꽃장식을 얹은 모습으로, 가운데는 8각의 기둥을 낮게 두었다. 탑신은 한 면에만 자물쇠가 달린 문짝 모양을 새기고, 지붕돌은 다…","a":"장흥 보림사 동 승탑","c":"보물","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618861.jpg"},{"q":"흥법사터라고 전하는 밭 가운데에 서 있는 고려시대의 탑이다. 흥법사는 신라시대부터 고려시대까지 이어지던 거대한 사찰로, 원래 탑 외에도 (전)○○○○○ 염거화상탑·○○○○○ 진공대사탑 및 석관 등이 있었는데, 일제에 의해 강제로 반출되었다가 지금은 국립중앙박물관에서 보관하고 있다. 이 탑은 기단(基壇)을 2단으로 두고, 그 위로 기와집 모습을 본뜬 듯한 탑신(塔身)을 3층으로 쌓아올린 모습이다. 아래층 기단의 각 면에는 안상(眼象)이 3개씩 새겨져 있는데, 꽃모양처럼 솟아올라 있어 고려시대의 특징을 잘 보여주고 있다. 위층 기단의 윗면은 경사져 있고, 보기 드물게 중…","a":"원주 흥법사지 삼층석탑","c":"보물","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616621.jpg"},{"q":"화면 가득 서 있는 모양의 석가삼존불을 배치하고 그 윗부분에 보살과 여래 등을 작게 그린 괘불이다. 원래는 나주 금성산 보흥사(普興寺)에 봉안되었던 것이다. 구성은 석가삼존불입상을 중심으로 윗부분에 관음보살과 대세지보살, 다보여래와 아미타여래가 짝을 이루고 있는데, 당시에 성행하였던 형식이다. 이 괘불은 조선 영조 21년(1745)에 조선후기의 대표적 승려화가인 의겸을 비롯하여 9명의 화원이 함께 그렸다. 옷 문양은 화사하나 형태·채색·필선 등에서 정교함이 줄어들어 의겸의 말년의 그림 경향을 엿볼 수 있는 중요한 작품으로 평가된다.","a":"다보사 괘불탱","c":"보물","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619803.jpg"},{"q":"○○○○○은 줄여서 ‘대불정수능엄경’또는 ‘능엄경’이라 부르기도 하는데, 부처님의 말씀을 머리속으로만 이해하는데 그치지 않고 자신이 직접 경험하여 얻을 것을 주요사상으로 하고 있다. 능엄경은 전 10권으로 되어 있으며, 스님들이 수련과정에서 필수적으로 배우는 경전이다. 대불정여래밀인수증료의제보살만행수능엄경(언해) ○○, 8 (大佛頂如來密因修證了義諸菩薩萬行首楞嚴經(諺解) 卷七, 八)은 당나라의 반자밀제(般刺密帝)가 번역하고 송나라의 계환(戒環)이 해설한 것을 한글로 풀이한 것이다. 볏짚과 닥나무를 섞어 만든 누런 종이에 찍어낸 세로 37.5㎝, 가로 23.8㎝ 크기의…","a":"대불정여래밀인수증요의제보살만행수능엄경(언해) 권7, 8","c":"보물","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613838.jpg"},{"q":"조선 초기의 전형적인 ○○으로 구연이 그대로 외반되고 어깨가 원과 같이 둥글며 허리가 가늘고 아랫부분이 넓게 벌어진 형태를 하고 있다. 몸통전체를 상단ㆍ중단ㆍ하단으로 나누고, 어깨 부분인 상단에는 변형된 연판문과 그 밑에 넓게 펼쳐진 여의두문대를 둘렀다. 넓은 몸통의 중단에는 얼굴은 용의 모습이며 물고기의 몸통을 한 어룡을 2군데에 새기고, 그 사이에 연화절지문과 작은 물오리들을 새겨 넣었다. 어룡과 같은 신비로운 소재와 연꽃과 물오리와 같이 일상적이며 서정적인 소재를 함께 배치하여 독특한 분위기를 자아내고 있다. 유약은 맑고 투명한 엷은 담녹색을 띠고 있으며, 유층…","a":"청자 상감어룡문 매병","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614788.jpg"},{"q":"동북으로 남한산성과 이성산성이 보이는 분지에 있는 절터이며, 발굴조사시 금당터와 4곳의 건물터의 흔적이 발견되었다. 부처를 모시는 건물인 금당은 당시 매우 큰 건물이었고, 금당안에는 지름 5.1m의 8각 대좌 위에 부처를 모셨다. 유물로는 금동불상·기와·도자기·동으로 만든 불기류 등이 나왔고 ‘동사(桐寺)’라는 글씨를 새긴 기와가 나와 이 절의 이름이 동사였음을 알게 해준다. 절터에는 현재 두개의 석탑(보물)이 있다. 후삼국시대에서 고려 전기에 이르는 시기에 지어졌으며, 웅장하고 거대한 규모의 절로서 조선 전기까지 남아 있었으나 그 후에 폐사된 것으로 보인다. <br…","a":"하남 동사지","c":"사적","r":"경기도","s":"하남시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625829.jpg"},{"q":"○○○○○은 줄여서 ‘약사경’이라고 부르기도 하는데, 질병의 치유를 기원하기 위한 경전이다. 이 약사경은 속장경을 간행하기 위해 1086년 흥왕사에 설치한 교장도감(敎藏都監)에서 펴낸 것 가운데 하나이다. 닥종이에 찍어낸 1권으로 크기는 세로 30㎝, 가로 16㎝이며, 제목 아래 대장경의 천자함(千字函:천자문의 순서에 따라 책의 번호를 매기는 방법) 표시인 ‘국(鞠)’자가 적혀 있다. 대각국사 의천이 속장경을 간행하던 중 숙종 6년(1101)에 돌연 병이 생겨 그해 10월에 입적하게 되는데, 그의 병이 치유되길 기원하기 위해 대장경판에 근거하여 간행에 착수하였고 숙종…","a":"약사유리광여래본원공덕경","c":"보물","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615984.jpg"},{"q":"한국전쟁 이후인 1957년에 건립된 관공서 건물로서 외벽에 석재를 이용하여 마감한 건축방법 등은 당시의 건축적 상황을 보여주고 있다. 또한 정면 현관 상부를 동물문양과 무궁화 문양으로 장식 처리한 것이 특징적이다","a":"파주 구 교하면사무소","c":"국가등록문화유산","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018081418301900.jpg"},{"q":"「덕천(德泉)」명(銘) ○○는 여러 예가 있지만 이 ○○의 경우와 같이 입체적인 기형에 문양 및 유태 등 상태가 양호한 것은 드문 편이다. 특히 변형된 여의두문대(如意頭文帶)와 파초연화문, 유문(柳文)의 형태가 고려상감○○의 기본형에서 크게 벗어나지 않아서 15세기 분청사기와 구분되는 예로 볼 수 있다. 상감○○에서 분청으로 변천하는 과정에서 중요한 기준으로 삼을만한 자료로서 가치가 크다.","a":"청자 상감‘덕천’명 연화양류문 매병","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614852.jpg"},{"q":"○○○은 신라 경덕왕 10년(751)에 당시 대상이었던 김대성이 창건을 시작하여 혜공왕 10년(774)에 완성하였으며, 건립 당시에는 석불사라고 불렀다. 경덕왕은 신라 중기의 임금으로 그의 재위기간(742∼765) 동안 신라의 불교예술이 전성기를 이루게 되는데, ○○○ 외에도 불국사, 다보탑, 삼층석탑, 황룡사종 등 많은 문화유산들이 이때 만들어졌다. 토함산 중턱에 백색의 화강암을 이용하여 인위적으로 ○○을 만들고, 내부공간에 본존불인 석가여래불상을 중심으로 그 주위 벽면에 보살상 및 제자상과 역사상, 천왕상 등 총 40구의 불상을 조각했으나 지금은 38구만이 남아있…","a":"경주 석굴암 석굴","c":"국보","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612705.jpg"},{"q":"○○○○○는 한국전쟁 기간 중 피란수도인 ○○에서 대통령 집무실 겸 관저로 사용된 곳으로, 국방· 정치· 외교 등 다양한 분야에서 중요한 정책이 결정되었던 역사적 현장으로서 당시의 모습을 비교적 잘 간직하고 있어 역사적․건축사적 가치가 높은 것으로 평가되고 있다.","a":"부산 임시수도 대통령관저","c":"사적","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2018111215570000.jpg"},{"q":"○○○○○은 줄여서 ‘화엄경’이라고 부르기도 하며, 부처와 중생이 둘이 아니라 하나라는 것을 기본사상으로 하고 있다. 화엄종의 근본경전으로 법화경과 함께 한국 불교사상 확립에 크게 영향을 끼친 경전이다. ○○○○○은 당의 실차난타가 번역한『화엄경』○○ 80권을 옮겨 적은 것인데, 그 가운데 ○○○의 일부분이 전해지고 있다. 검푸른 빛이 도는 종이에 금·은가루를 이용하여 글씨를 쓰고 그림을 그려 화려하게 장식한 것이다. 병풍처럼 펼쳐서 볼 수 있는 형태로 되어 있고, 접었을 때의 크기는 세로 30.5㎝, 가로 15.2㎝이다. 금·은색의 화려한 꽃무늬가 그려진 표지에는…","a":"감지은니 대방광불화엄경 주본 권37","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613811.jpg"},{"q":"일제 강점기 건립 이 건물은 일제 강점기 당시 동경대학교가 대부받았던 국유림에 지어진 직원 ○○로, 2동의 건물이 나란히 배치되어 있다. 현재 외벽은 키 높이까지 벽돌로 마감하였고, 나머지 부분은 회벽과 목재 널판을 사용하였다. 내부는 중복도를 중심으로 실이 배치되어 있고, 방과 방 사이 문지방 윗부분에는 환기창이 설치되어 있으며, 벽에서 창틀이 돌출되어 있는 등 일본 주택의 공간 구성형식을 볼 수 있다.","a":"광양 서울대학교 남부연습림 관사","c":"국가등록문화유산","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668952.jpg"},{"q":"표지에 ‘청송서(聽松書)’라고 쓰여진 이 『○○○○○』은 16세기 학자 청송(聽松) ○○○이 당나라 가도(賈島), 두목(杜牧), 이상은(李商隱)과 송나라 구양수(歐陽脩)의 칠언시를 쓴 것이다. 종이 바탕을 줄[行]에 따라 잘라 첩장하였다. 송명흠(宋明欽, 1705~1768)후손의 기증품으로 송명흠의 아버지 송요좌(宋堯佐, 1678~1723)의 [청은당(淸隱堂)]이란 인영(印影)이 있다. ○○○은 이황과 함께 16세기를 대표하는 도학자 명필로 ○○은 드문 편이다. 현재 그의 소자(小字)는 몇몇 전하고 있는 상황이고 대자(大字)는 목판밖에 전하지 않는다. 이처럼 큰 글자…","a":"성수침 필적","c":"보물","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615530.jpg"},{"q":"이 차는 일본에서 제작하고 조선총독부 철도국 경성공장에서 조립한 승객용 ○○로 1955년 ○○○○○으로 개조되어 이승만 ○○○부터 박정희 ○○○까지 이용하였다. ○○ 안에 각종 시설‧설비가 갖추어져 있고 화려한 의장이 돋보이는 등 전직 ○○○ 관련 유물로 상징적 가치가 높다.","a":"대통령 전용 객차","c":"국가등록문화유산","r":"경기도","s":"의왕시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668152.jpg"},{"q":"「○○○○○」은 통일신라 말이나 고려초에 건립된 것으로 추정되며 경북지역에 집중된 모전석탑의 양식을 지니고 있다. 경북지역 전탑과 모전석탑은 초층탑신의 1면에만 감실을 마련하는 것이 특징인데 감실 좌우 문설주에 당초문을 조각하여 예술성을 높인 점은 이 석탑에만 나타나는 특이한 모습이다. 또한 벽돌모양으로 석재를 다듬을 경우 각진 위치에 자리하는 모서리 돌들을 둥글게 처리하여 탑의 조형에 부드러움을 주고자 한 의지를 느낄 수 있는 점도 특이한 사례이다.","a":"영양 현리 오층모전석탑","c":"보물","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020072712561600.JPG"},{"q":"○○○○○은 풍산 유씨의 동족마을로 빼어난 자연 경관과 민속·유교 전통을 잘 유지하고 있는 조선시대 양반촌이다. 작천 유도관 선생이 이 집에서 살았기 때문에 '○○○○'이라고도 부르며, ○○○○ 북촌의 서쪽 끝 강변 가까이 자리잡고 있다. 세운 시기는 정확히 알 수 없지만 건축수법과 양식으로 미루어 조선중기에 지은 것으로 추정하고 있다. 원래 2동이 있었으나 1934년 홍수로 현재 1동만 남아있다. 안채는 앞면 5칸·옆면 1칸 반 크기로 왼쪽부터 부엌 1칸 반, 안방 1칸, 대청 1칸, 건넌방 1칸으로 남부지방의 전형적인 4칸 '一'자 집이라고 볼 수 있으나 사랑방을…","a":"안동 하회마을 작천고택","c":"국가민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635054.jpg"},{"q":"1937년 건립 이 시설물은 2차 대전 당시 일본군들이 제주도민들을 강제 동원하여 건설한 전투기 ○○○이다. 당시 20기가 건설되었지만, 지금은 19기가 원형 그대로 보존되어 있고 1기는 잔해만 남아 있다. 이 유적은 제주도를 일본군의 출격 기지로 건설하려 했음을 보여주는 지상 건축물로, 진지를 구축하려 했던 인공 동굴은 많이 있으나, 다량의 지상 시설물을 집중적으로 보여주는 예는 이것이 유일하다.","a":"남제주 비행기 격납고","c":"국가등록문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2021042610532800.jpg"},{"q":"○○이란 수렵·어로·채집에 의하여 살아온 옛 사람들이 조개를 먹은 뒤 버린 조개껍데기와 생활쓰레기가 함께 쌓여 이루어진 유적으로 조개더미라고도 한다. ○○○○○은 남해안의 서쪽 끝에 있는데, 군곡초등학교에서 서남쪽으로 300m쯤 떨어진 구릉으로 가공산(334m)의 서쪽에 해당된다. 이 유적은 1986년부터 1988년까지 3차에 걸쳐 국립광주박물관과 목포대학교 박물관에 의해 발굴이 실시되었다. ○○이 겉으로 드러난 범위는 너비가 약 200m, 길이 약 300m에 이르는 서남해안지역에서 가장 큰 것으로 알려져 있다. 발굴은 구릉 경사면에 위치한 패각층을 중심으로 조사되었…","a":"해남 군곡리 패총","c":"사적","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627372.jpg"},{"q":"○○○에 세워져 있는 탑으로, 1단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이나, 기단과 탑신의 여러 군데가 갈라지거나 떨어져 나간 상태이다. 기단은 네 모서리에 두터운 기둥을 세우고, 그 사이마다 판돌을 끼워 두었는데 그 중 한 면에는 판돌이 없이 작은 돌들로 채워져 있다. 이렇게 모서리기둥을 본떠 새기지 않고, 직접 세운 것은 부여 정림사지 오층석탑(국보)에서도 볼 수 있다. 탑신의 1층 몸돌은 각 면마다 감실(龕室)을 팠는데, 목탑에서의 감실은 불상을 모셔두는 곳으로 들어갈 수 있는 공간이었으나, 석탑에서는 이처럼 형식적인 조각만 하게 된다. 두툼한…","a":"강진 금곡사 삼층석탑","c":"보물","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619386.jpg"},{"q":"○○도는 조선 태종 16년(1416) 안무사 오식의 건의로 5세기라는 긴 세월동안 세 지역으로 나누어 통치하였다. 그 중 성읍은 세종 5년(1423)에 지정된 정의현의 읍치(관아가 있는 곳)로서 산골 마을이면서 읍치였다는 특이성을 갖추고 있다. 아늑한 터에, 주변으로는 마을을 둘러싼 높고 낮은 봉우리들이 의젓하게 감싸고 있다. 또한 길들이 굽이 돌아 나 있고 길과 길이 만나는 지점에 평상과 나무들을 두어 쉼터와 모임장소로 사용하도록 하였다. 이 마을 민가는 뭍과는 다른 독특한 건축기법을 사용하고 있다. 대개 一자형 평면을 가진 집 2채를 중심으로 몇가지 배치방식으로…","a":"제주 성읍마을","c":"국가민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1636028.jpg"},{"q":"이 건물은 거제시에서 가장 오래된 교육 기관인 ○○○○○이다. 정면은 대칭형으로, 박공형으로 장식한 현관을 중심으로 교실을 배치하였다. 외관은 당시 인근에서 풍부하게 생산되던 화강석을 직사각형으로 다듬어 쌓는 등 근대기 학교 건물의 전형적인 형식을 취하였다. 석재 채석과 가공, 적벽돌 생산과 운반 등에 주민들이 직접 참여하는 등 교사 건립에 지역공동체가 참여하여 역사적 가치가 높다.","a":"거제초등학교 본관","c":"국가등록문화유산","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669521.jpg"},{"q":"나즈막한 동산이 둘러있는 명당 터에 남북으로 길게 자리잡고 있는 큰집이다. 솟을대문에 적힌 기록에는 \"고종 24년(1887)에 문을 세웠다\"고 적혀 있으나, 안채와 사랑채는 이 문보다 약 50년 전에 지은 것으로 추정된다. 대문은 정면으로 내지않고 북쪽측면으로 내어 언뜻보면 집이 커보이지 않지만 실제로는 50칸이 넘는 큰 규모이다. 대문을 들어서면 바로 사랑마당이며, 마당의 왼쪽으로 길게 줄행랑채가 뻗어있고 오른쪽으로 사랑채가 자리한다. 사랑채 맞은편의 마당끝에는 안채로 통하는 중대문이 있다. 중대문을 들어서면 보이는 ㄷ자형의 안채는 앞이 개방된 가운데 대청을 중심으…","a":"화성 정시영 고택","c":"국가민속문화유산","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633718.jpg"},{"q":"○○○○○은 조선 후기 기호학파의 대표적인 학자인 ○○○ 송준길(宋浚吉, 1606~1672)의 5대조 송요년(宋遙年, 1429~1499)이 15세기 후반 건립하였다고 전해지며, 이후 몇차례 이전을 하여 현재는 1835년 보수할 때의 모습으로 남아 있다. 이 고택은 임진왜란 이전 충청지역 살림집의 흔적을 유추해볼 수 있는 희소성이 있고, 상량문 등의 기록과 유적 등을 통해 변천과정을 명확히 알 수 있는 훌륭한 국가유산이다. 안채는 충청지역에서는 드문 ‘ㄷ’자형 평면을 이루며, 6칸규모의 대청마루와 세로로 긴 안마당 구성은 이 지역 상류주택의 특성을 나타내며, 사랑채는…","a":"대전 동춘당 종택","c":"국가민속문화유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2016083021361800.bmp"},{"q":"고려 공민왕(恭愍王) 20년(1371)에 비구니(比丘尼) 묘지(妙智), 묘수(妙殊)의 시주(施主)에 의해서 사성(寫成)된 것이다. 권수(卷首)에는 일반적인 경변상(經變相)과는 구도가 다른 협시보살을 거느린 불상과 관음보살상(觀音菩薩像)이 각각 금니(金尼)로 묘사되어 있고, 이어 ○○반야바라밀경(金剛般若波羅密經), 묘법연화경 관세음보살 보문품 제25(妙法蓮華經 觀世音菩薩 普門品第二十五), 영가대사 발원문(永嘉大師 發願文)이 필사되어 있다. 권말(卷末)에는 \"홍무 4년 신해 7월 일지(洪武四年辛亥七月日誌), 시주 비구니묘지(施主比丘尼妙智), 동원 비구니 묘수(同願比丘尼妙…","a":"백지금니 금강 및 보문발원","c":"보물","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622165.jpg"},{"q":"○○○○는 조선 태조 7년(1398)에 처음 세우고 정종 2년(1400)에 불에 탄 것을 태종 7년(1407)에 다시 지었으나, 이 역시 임진왜란으로 타버렸다. 지금 있는 건물들은 임진왜란 이후에 다시 지은 것이다. ○○는 대성전을 비롯한 ○○○○ 등 제사를 위한 공간인 대성전 구역과 명륜당, 동재·서재 등 교육을 위한 공간인 명륜당 구역으로 크게 나뉘어 있다. 대성전(大成殿)은 선조 34∼35년(1601∼1602)에 지은 건물로, 공자를 비롯해 증자·맹자·안자·자사 등 4대 성인과 공자의 뛰어난 제자들인 10철, 송조 6현, 그리고 우리나라 명현 18인의 위패를 모…","a":"서울 문묘 및 성균관<대성전·동무·서무·삼문·명륜당>","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613161.jpg"},{"q":"「○○○○○」은 ○○ 풍산김씨 11세손 ○○○ 김양진(1467∼1535)의 ○○으로, 1576년(선조 10) 산음현감(山陰縣監)을 지낸 유연당 김대현(1553∼1602)이 ○○ 풍산김씨 영감댁(경상북도 민속문화유산)에서 이곳으로 이전한 것으로 전해지고 있다. 당초 집은 임진왜란 때 소실되었고, 현재 ○○은 김대현의 아들 김봉조(1571∼1630)가 다시 지었으며, 서편의 큰 사랑채는 1614년(광해군 6)에 건립하였다. ○○○이 있는 마을은 태백산의 지맥(地脈)인 동쪽의 아미산과 서쪽의 도인산, 안산(案山)인 남쪽의 검무산, 배산(背山)인 죽자봉의 가운데에 위치한다.…","a":"안동 허백당 종택","c":"국가민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2673546.jpg"},{"q":"등잔걸이 형태의 유기(鍮器) 촛대로 연꽃 형태의 좌대(座臺) 위에 촛대를 설치하고 두 개의 초꽂이를 얹었다. 높낮이 조절 가능한 촛대, 전통적 소재인 나비나 박쥐 대신 활짝 핀 꽃잎모양의 화선(火扇), 꽃잎의 형태를 부분으로 제작하여 조립할 수 있게 디자인한 연꽃형 좌대에서 근대적인 요소를 찾아볼 수 있다. 전체적으로 연꽃을 소재로 삼아 유기적으로 빚어낸 솜씨가 일품이다. 근대기 공예품이 실용성에서 미술공예로 변모되어 가는 흐름을 제작기법과 조형미를 통해 확인할 수 있어 역사적·공예적 가치가 크다. 1910년에 구세군 선교사로 내한하여 1941년 일제에 의해 강제 추…","a":"유제화형촛대","c":"국가등록문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667328.jpg"},{"q":"청량사터에는 칠층석탑과 ○○○○ 등 2기의 석탑이 남아 있는데, 이 두 탑을 가리켜 오누이탑 혹은 남매탑이라 부르기도 한다. 옛날에 상원이라는 승려가 어려움에 처한 호랑이를 구해주자, 호랑이는 이에 대한 보답으로 처녀를 업어다 주었다. 상원은 처녀와 남매로서의 관계만을 유지하며 수도에 정진하였고, 처녀의 아버지가 그 갸륵한 뜻을 기려 두 탑을 세웠다는 전설이 내려온다. 이 탑은 그 중 ○○○○으로, 1단의 기단(基壇) 위에 5층의 탑신(塔身)을 얹은 모습이다. 바닥돌과 그 위에 둔 기단의 아랫돌은 각 4장의 돌로 짰다. 특이한 점은 기단의 가운데기둥을 별도의 돌로 끼…","a":"공주 청량사지 오층석탑","c":"보물","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618045.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 하며, 부처가 되는 길이 누구에게나 열려 있다는 것을 중요사상으로 하고있다. 천태종의 근본 경전으로 화엄경과 함께 한국 불교사상 확립에 크게 영향을 끼친 경전이다. 이 책은 구마라습(鳩摩羅什)이 한문으로 번역한 것을 옮겨 쓴 것으로, 법화경 7권 가운데 마지막권에 해당된다. 책 뒷면의 표지 속에는 금색으로 법칠사장(法七四丈)이라는 제목이 쓰여 있다. 검푸른 색의 종이 위에 금가루를 이용해 글씨를 썼으며, 병풍처럼 펼쳐서 볼 수 있는 형태이고 크기는 세로 31.3㎝, 가로 11㎝이다. 책 끝부분에는 고려 공민왕 15년(136…","a":"감지금니 묘법연화경 권7","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614611.jpg"},{"q":"­조선 말 전남 구례 일대에서 활약한 의병장 고광순(1848~1907)이 사용한 것으로 알려진 ○○○로 '머지않아 국권을 회복한다'는 \"\"\"\"\"\"\"\"不遠復\"\"\"\"\"\"\"\" 글자가 수놓아져 있어 항일 독립운동과 관련하여 사료적 가치가 크다.","a":"‘불원복(不遠復)’ 태극기","c":"국가등록문화유산","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668618.jpg"},{"q":"진공대사의 사리를 모셔놓은 탑과, 그 옆에 놓여있는 돌로 만든 함이다. 본래는 강원특별자치도 ○○의 흥법사터에 있었으나 1931년 경복궁으로 옮겨 왔으며 현재는 국립중앙박물관 경내에 있다. 진공대사는 통일신라말 ·고려초에 활약한 승려로, 당나라에 유학하고 돌아와 신라 신덕왕의 스승이 되었으며, 특히 고려 태조의 두터운 존경을 받았다. 탑은 전체가 8각으로 이루어진 기본적인 형태로, 기단(基壇)의 아래와 윗받침돌에는 연꽃을 새겼다. 북모양을 하고 있는 가운데받침돌 표면에는 웅장한 구름과 함께 뒤엉켜 있는 용의 몸체를 생동감있게 조각하였다. 탑신의 몸돌은 8각의 모서리마…","a":"원주 흥법사지 진공대사탑 및 석관","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613319.jpg"},{"q":"○○○○○은 고려시대 만들어진 ○○○○으로 높이 29.2㎝, 몸 지름 18.7㎝이다. 각 있게 세워진 두툼한 아가리와 팽배한 어깨 선은 몸체를 지나 밑부분까지 사선으로 줄어들어, 중국 북송의 영향을 받은 듯 하다. 몸체는 참외 모양으로 6등분해서 세로로 골을 만들었으며, 각 면에는 마름모 모양의 선을 상감으로 처리하였다. 그 안에는 청자 태토로 메꾸고 붉은색 자토와 흰색 백토로 모란, 갈대, 버들이 늘어져 있는 그늘에서 물새가 거니는 모습, 연꽃 등을 상감 처리하였다. 아가리 가장자리와 굽 둘레는 연꽃 잎을 도드라지게 돌렸고, 다시 청자 태토로 상감하여 ○○에 청자…","a":"백자 상감모란문 매병","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613265.jpg"},{"q":"원경왕사를 기리기 위해 세운 비(碑)로, 반야사의 옛터에 있었던 것을 1961년에 해인사 경내인 지금의 자리로 옮겼다. 거북받침돌과 비몸, 지붕돌을 갖추었는데, 각 부분이 얇은 것이 특색이다. 비문에 의하면, 원경왕사는 대각국사를 따라 송나라에 갔다가 귀국하여 숙종 9년(1104)에 승통(僧統)이 되었다. 예종의 스승이 되기도 하였고 그 후 귀법사에 머물다 입적하자 왕은 ‘원경’이라는 시호를 내렸다. 비문은 김부일이 짓고 글씨는 이원부가 썼다. 고려 인종 3년(1125)에 만들어진 이 비는 조각기법이나 간단한 형태의 지붕돌 등에서 고려 중기 특징을 잘 나타내고 있다.…","a":"합천 반야사지 원경왕사비","c":"보물","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622352.jpg"},{"q":"화면 가득 화려하게 장엄된 여래를 단독으로 그린 괘불인데, 괘불이란 절에서 큰 법회나 의식을 행할 때 법당 앞 뜰에 걸어 놓고 예배를 드리는 대형 불교그림을 말한다. 이 괘불은 길이 9.66m, 폭 4.97m의 관음보살 입상으로 광배의 끝부분은 화려한 색을 이용하여 불꽃무늬를 표현하였고, 불꽃무늬 안에는 좌우에 각각 작은 불상을 10구씩 두었다. 머리에는 수많은 부처의 얼굴이 있는 보관을 쓰고 있으며, 그 좌우에는 봉황이 그려져 있다. 이목구비는 작게 표현되었고, 신체에 비해 얼굴이 크게 그려졌다. 연꽃 가지를 들고 있으며, 화려한 장식과 문양의 옷 모습이 화면을 압…","a":"금당사 괘불탱","c":"보물","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618670.jpg"},{"q":"○○○○○은 경상남도 ○○군 ○○○에서 보관하고 있는 고려시대의 불교경전과 유명한 승려들의 저술, 시문집 등이 새겨진 목판이다. ○○○에 있는 목판은 모두 54종 2,835판인데 이 중 28종 2,725판이 국보로 지정되어 있고, 26종 110판이 보물로 지정되어 있다. ○○○ 고려각판은 국가기관인 대장도감에서 새긴 ○○○ 대장경판과는 달리 사찰이나 지방관청에서 새긴 것이며, 현재 ○○○ 대장경판전 사이에 있는 동·서 사간판전(寺刊版殿)에 보관되어 있다. 이 목판들은 금강경·화엄경 등의 대승불교 경전과 신라·고려·중국의 유명한 승려, 개인의 시문집 및 저술들이다. 이…","a":"합천 해인사 고려목판","c":"보물","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622815.jpg"},{"q":"소나무 숲이 우거진 야산이 감싸고 도는 곳에 남향으로 자리한 집으로, 건축양식으로 볼 때 19세기 중반에 지어진 것으로 보인다. 입구에도 소나무 숲을 조성하였고, 집 앞에는 연못을 만들고 주위에 버드나무를 심어놓았다. 솟을대문을 낸 '一'자형의 행랑채 뒤에 '一'자형의 사랑채가 있고, 사랑채의 왼쪽 끝에는 중문이 연결되어 있다. 중문을 들어서서 동쪽으로 꺾어 돌아가면 'ㄱ'자형의 안채가 있고 동쪽에 안마당을 감싸며 '一'자형의 광채가 자리한다. 이와는 별도의 축으로 광채 뒷편에 '一'자형의 안사랑채를 배치하고 있는데, 담장을 두르고 대문을 따로 내었다. 안사랑채 왼쪽…","a":"홍성 사운고택","c":"국가민속문화유산","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634382.jpg"},{"q":"무장○○은 1417년 무장진의 병마사에 마을을 다스리는 기능을 주어 무장진 병마사 김노(金蘆)가 쌓은 길이 약 1.2km의 평지성이다. ○○의 남문인 진무루는 앞면 3칸·옆면 2칸의 2층 건물이며, 동문터도 잘 남아 있다. 성 주위를 둘러싼 물길인 해자는 폭 4m·길이 574m 정도로 그 흔적만 남아있다. 성 안의 건물로는 객사·동헌이 있다. 『문종실록』에 의하면 ○○의 둘레는 1,470척(약441m)·높이 7척(약2m)이며, 해자의 둘레는 2,127척(약638m)이고 문은 2개가 있으며, 성의 규모를 넓혀야 한다고 기록되어 있다. 무장○○은 조선시대 옛 ○○의 모습…","a":"고창 무장현 관아와 읍성","c":"사적","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626923.jpg"},{"q":"○○시 가금면에 있는 ○○○의 능선을 따라 둘러 쌓은 둘레 약 2.9㎞의 삼국시대 산성이다. 『신증동국여지승람』14권에 보면 ‘하천 서쪽 28리에 옛 석성이 있다’라는 기록과 『대동지지』에 ‘○○○의 옛 성의 터가 남아 있다’라는 기록이 있다. 1992년 조사결과 성 안에서 발견된 토기 조각과 기와 조각들을 통해 백제·고구려·신라가 차례로 이 성을 점령, 경영하였음을 짐작하게 해준다. 북쪽에 있는 절인 봉학사 지역 일부를 빼고는 성벽이 원래 모습대로 남아 있다. 성벽은 돌을 대강 다듬어 직사각형으로 쌓았는데, 서쪽과 서남쪽에서 그 모습을 볼 수 있다. 또한 북쪽 정상…","a":"충주 장미산성","c":"사적","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626305.jpg"},{"q":"갑오개혁 이후 자주독립의 의지를 다짐하기 위해 중국 사신을 영접하던 영은문(迎恩門)을 헐고 세운 기념물이다. 갑오개혁(1894∼1896)은 내정개혁과 제도개혁을 추진하였던 개혁운동이다. 그러나 외국세력의 간섭으로 성공하지 못하였고 나라의 자주독립 또한 이루지 못하였다. 이에 국민들은 민족의 독립과 자유를 위해서는 어떠한 간섭도 허용하지 않겠다는 다짐으로, 중국사신을 맞이하던 영은문을 헐고 그 자리에 ○○○을 세우게 되었다. 건양(建陽) 원년(1896년) 서재필이 조직한 독립협회의 주도하에 국왕의 동의를 얻고 뜻있는 애국지사와 국민들의 폭넓은 지지를 얻으며, 프랑스 파…","a":"서울 독립문","c":"사적","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624453.jpg"},{"q":"조선시대의 궁궐로서 경운궁으로 불리다가, 고종황제가 1907년 왕위를 순종황제에게 물려준 뒤에 이곳에서 계속 머물게 되면서 고종황제의 장수를 빈다는 뜻의 ○○○으로 고쳐 부르게 되었다. ○○○ 자리에는 조선 9대 임금인 성종의 형 월산대군의 집이 있었다. 임진왜란이 끝나고 한양으로 돌아온 선조는 궁궐이 모두 불에 타고 없어서 임시로 월산대군의 집을 거처로 정하고 선조 26년(1593)부터 궁으로 사용하기 시작하였다. 그리고 근처의 계림군과 심의겸의 집 또한 궁으로 포함하였다. 선조의 뒤를 이은 광해군은 즉위 3년(1611)에 이곳을 경운궁으로 고쳐 부르고 1615년…","a":"덕수궁","c":"사적","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624564.jpg"},{"q":"원효대사가 창건했다고 전해지는 ○○○의 석굴사원 안에 모셔져 있다. 머리에 있는 상투 모양의 큼직한 머리(육계)와 어깨까지 내려온 긴 귀, 원만하면서도 우아한 인상, 왼손을 몸에 붙여 곧바로 내리고 오른손을 가슴에 댄 모습, 그리고 둥근 어깨와 평판적인 가슴, 대좌 위에 곧바로 선 자세 등에서 719년에 만들어진 경주 감산사 ○○○○○의 양식을 이어받은 것임을 알 수 있다. 부드러운 주름을 형성하며 온 몸을 감싸고 있는 옷은 U자형의 옷주름을 이루면서 흘러내려 발목에서 좌우 대칭을 이루고 있다. 부처의 몸에서 나오는 빛을 형상화한 광배(光背)는 끝이 뾰족한 배(舟)…","a":"양산 미타암 석조아미타여래입상","c":"보물","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622845.jpg"},{"q":"기도나 법회 등 절에 행사가 있을 때 사찰의 입구에 세워 부처와 보살의 성덕을 표시하는 기를 당(幢)이라 하며, 이를 달아매는 장대를 당간(幢竿)이라 하고, 이 장대를 양옆에서 지탱하는 두 돌기둥을 ○○○○라 한다. 이 ○○○○의 동남쪽에는 보문사의 옛터가 남아있기는 하지만, ○○○○가 속한 절이 원래 보문사였는지, 아니면 별개의 사원이었는지는 확실하지 않다. 현재 이 ○○○○는 넓은 논 한가운데에 62㎝의 간격을 두고 동·서로 마주보고 서 있다. 아래부분이 대부분 땅속에 파묻혀 있는 상태이기 때문에, 밑의 구조는 확인하기가 어렵다. 양쪽 지주의 전체적인 모양은 가운…","a":"경주 보문사지 연화문 당간지주","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621791.jpg"},{"q":"□ 입지 현황 및 역사문화환경 ○○○○○는 신라의 동악(東岳)인 토함산(土含山) 서측 기슭에 위치하며, 남향으로 배치되어 있다. ○○○의 지형은 북측이 높고 남측이 낮은 북고남저(北高南低)와 동측이 높고 서측이 낮은 동고서저(東高西低)으로 지형에 따라 석축을 가구식으로 조화롭게 쌓았으며, 동측 사역에는 자하문, ○○○, 무설전을 남북 축선에 배치하면서 회랑을 둘러 공간을 구성하고 있다. ○○○의 동·서측면에는 익랑(翼廊)이 놓여 동·서 회랑과 연결되고 남회랑의 동측 모서리에는 좌경루(左經樓)가 있고, 서측 모서리에는 범영루(泛影樓)가 배치되어 있다. 자하문 남측에는…","a":"경주 불국사 대웅전","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622310.jpg"},{"q":"신라 혜공왕 9년(733)에 법조가 영남사의 부속암자로 창건하였다고 전해지는 ○○○의 대웅전에 모셔진 높이 0.97m의 불상이다. 네모진 얼굴에 가는 눈과 입, 넓적한 코, 짧은 목 등이 다소 평판적으로 표현되기는 했으나 단정한 인상을 풍긴다. 어깨는 넓고 둥근 편으로 가슴이 다소 움츠러들어 보인다. 양 어깨에 걸쳐 입은 옷은 너무 두꺼워서 옷주름과 신체의 굴곡을 나타내지 못하고 있다. 부처의 몸에서 나오는 빛을 형상화한 광배(光背)는 2줄의 볼록한 선으로 머리광배와 몸광배를 구분하고, 그 안에 덩굴무늬와 연꽃무늬를 새겨 넣었다. 광배의 바깥부분에는 불꽃이 타오르는…","a":"밀양 무봉사 석조여래좌상","c":"보물","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622727.jpg"},{"q":"○○○ 당시의 공경사대부 및 72명의 제자들과 문답한 것 중 『논어』에 편입된 것을 제외하고 여러 서적을 모아 기록한 것에 원나라 왕광모가 각 장별로 제목을 달고 자세하게 풀이한 것을 붙인 것으로 박은이 강릉감영에서 간행하였다. 박은(1370∼1422)은 조선이 건국된 후 태조 7년(1398)의 제1차 왕자의 난과 정종 2년(1400) 제2차 왕자의 난 때 이방원을 도와 공을 세운 인물이다. 이 책은 박은이 강원도도관찰출척사로 임명받고 부임하였을 때 이 책이 우리나라에 간행되어 있지 않음을 알고 그곳에서 번각(飜刻:한번 새긴 책판 등을 본보기로 삼아 다시 새김)해 낸…","a":"신간표제공자가어구해","c":"보물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616013.jpg"},{"q":"○○○○○은 관산읍에서 방촌으로 넘어가는 23번 국도변 양쪽에 서 있는 2기의 장승으로 고려말에 건립한 성문장승이라는 설과 조선시대 후기(17~18세기)에 창궐한 천연두를 퇴치하고자 세웠다는 설이 있다. ○○○○○은 현재에도 마을에서 매년 정월 대보름에 동제인 별신제의 신격으로서 마을 수호의 기능을 하고 있어 역사적, 학술적 가치가 있다.","a":"장흥 방촌리 석장승","c":"국가민속문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634768.jpg"},{"q":"○○○○○은 석가모니가 보리수 아래에서 설법한 내용을 경전에 담은 것이다. 원나라에 귀화한 인도의 고승 지공(指空)이 고려 금강산법기보살도량(金剛山法起菩薩道場)에 참가하였을 때, 고려 충숙왕이 지공에게 설법을 요청하자 이 책을 내놓고 설법하였다고 한다. 나무에 새겨서 닥종이에 찍은 것으로, 3권이 하나의 책으로 묶여 있으며, 크기는 세로 26.1㎝, 가로 19.2㎝이다. 고려 우왕 12년(1386)에 쓴 이색(李穡)의 간행기록을 통해 1353년에 강금강(姜金剛)이 간행한 것을 고려에서 다시 간행한 것임을 알 수 있다. 이때 예안군 우공(禹公)이 옮겨 새기려다가 완성하…","a":"문수사리보살최상승무생계경","c":"보물","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622821.jpg"},{"q":"○○○○○에 있는 사명대사의 탑 및 비(碑)이다. 사명대사는 임진왜란(1592)과 정유재란 때 승병장으로서 큰 공을 세운 승려로, 이곳 ○○○은 사명대사가 수도하다가 세상을 떠난 곳이다. ○○○이라는 암자 이름은 사명대사 입적 후 광해군이 내린 ‘자통홍제존자’라는 시호에서 따온 것이다. ○○○의 북동쪽 약 20m 지점의 산기슭에 자리잡고 있는 ○○○○○은 조선 후기를 대표할 수 있는 거대한 종 모양의 탑으로, 당당한 형태와 조형미를 보여주고 있다. 기단은 하나의 돌로 2단을 이루었는데, 아랫단은 사각형이고 윗단은 둥근 형태를 보이고 있으며, 그 위에 종 모양의 몸돌을…","a":"합천 해인사 홍제암 사명대사탑 및 석장비","c":"보물","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622949.jpg"},{"q":"○○○은 국가에서 ○○○신에게 제사 지내기 위해 마련한 조선시대의 건축물이다. ○○○은 예로부터 신령스러운 산으로 여겨져 왔으며, 신라 때 5악의 하나로 제사를 지냈다. 조선시대에는 북쪽의 묘향산을 상악으로, 남쪽의 지리산을 하악으로, 중앙의 ○○○을 중악으로 하여 단을 모시고 산신에게 제사를 지냈다. 무학대사의 꿈에 산신이 나타났다는 말을 듣고 태조 3년(1394)에 처음 제사를 지냈다고 전하며, 효종 2년(1651)에 제단이 폐지되었다. 그 후 고종 16년(1879)에 명성황후의 명으로 다시 짓고 ○○○이라 하였다. 구릉지에 동북·서남을 중심축으로 하여 대문간채,…","a":"공주 계룡산 중악단","c":"보물","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618053.jpg"},{"q":"○○○은 근정전 서측에 있는 건물로써, 북쪽으로는 경회루가 자리 잡고 있다. ○○○이 있는 권역은 세종 연간에는 학문을 연구하며, 왕에게 주요 정책을 자문하고 건의하던 기관으로 한글을 창제하는 등 문치의 본산이었던 집현전이 있던 궐내각사의 지역에 해당하며, 동쪽으로 사정전의 왕의 영역과 신하들의 영역이 만나는 접점인 이곳에 궐내의 관청인 각사들이 자리 잡고 있다. ○○○은 고종 때 중건되어 잠시 왕의 편전으로도 사용되었으며, 1894년 갑오개혁 때에는 대한제국의 군국기무처를 여기에 두고, 이후 내각청사로 사용되었다. 4면에는 행각과 남쪽의 외행각이 일곽을 형성하고 있…","a":"경복궁 수정전","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615018.jpg"},{"q":"조선시대 ○○○○○로서 외항아리는 전체 높이 30.9㎝, 아가리 지름 21.4㎝, 밑지름 14.1㎝이고, 내항아리는 전체 높이 19.2㎝, 아가리 지름 10.6㎝, 밑지름 8.3㎝이며, ○○○은 26.6㎝×26.7㎝×4.6㎝이다. ○○○○란 왕실의 왕자나 왕녀가 태어났을 때 태를 담는 항아리를 말하며, 이것과 그 주인공의 이름, 생년월일을 기록한 ○○○을 함께 묻는다. 외항아리는 아가리가 넓으며 밖으로 살짝 말려있다. 짧은 목에 위쪽이 넓고 아래로 내려갈수록 좁아지는 모양을 하고있다. 어깨의 4곳에는 고리를 달았으며, 냄비 뚜껑같이 생긴 뚜껑의 꼭지에 나있는 4개의…","a":"백자 태항아리 및 태지석(1993)","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614655.jpg"},{"q":"조선 후기 중국중심의 세계를 그린 지도이다. 프랑스 국립도서관에 소장된 <혼일강리도>의 왕반지 여지도모회증보본과 같은 원도를 사용했거나 같은 계열의 지도인 것으로 판단된다. 지도의 내용은 17세기 초의 상황을 반영하고 있다. 이 시점에 조선에서 그려진 동아시아 지도 가운데 홋카이도의 존재를 분명히 한 지도라는 점에서 특별한 의미가 있다. 홋카이도의 존재와 그 위치는 조선에서 오랫동안 분명치 않아서 여러 가지 혼선이 있었다는 점을 감안하면 가치가 크다고 할 수 있다. 또한 국내에 전하는 조선시대 제작의 세계지도가 드물다는 점을 고려할 때 자료적 가치도 매우 높다.","a":"천하여지도","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614937.jpg"},{"q":"1952년 건립 이 건물은 1949년에 공사가 시작되었으나 한국전쟁이 일어나 북한군에 의해 파괴되었다가 1951년에 함평을 방문한 교황 사절단의 지원으로 공사가 다시 시작되어 1952년에 완공되었다. 1층에는 성당의 교육 및 사회적 공간으로, 2층에는 순수한 미사의 공간으로 구성하였다. 미사공간은 내부 공간의 분절이 없는 강당형이며, 정면 중앙에 솟아있는 8각 종탑이 특징적이다.","a":"구 함평성당","c":"국가등록문화유산","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668904.jpg"},{"q":"절에 행사가 있을 때 절 입구에 당(幢)이라는 깃발을 달아두는데 이 깃발을 달아두는 장대를 당간(幢竿)이라 하며, 장대를 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. ○○○ 경내에 있는 이 ○○○○는 높이 3.5m로 양쪽 지주가 남북으로 마주보고 서 있다. 지주의 기단은 한 층인데, 잘 다듬은 6장의 길쭉한 돌로 바닥을 두고, 그 위를 두 장의 돌을 붙여서 마무리했다. 기단 위로는 당간을 세우는 받침을 지주 사이에 둥근 형태로 조각하였고, 받침 주변에는 괴임을 새겨두었을 뿐 별다른 꾸밈은 없다. 양쪽 지주의 안쪽 면에는 아무런 조각도 없는 반면에, 바깥면에는…","a":"김제 금산사 당간지주","c":"보물","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618141.jpg"},{"q":"○○○○는 수원도호부의 향교로서 18세기 말 읍치를 이건하면서 향교도 현 위치로 옮겨 다시 지은 독특한 사례로 신읍은 정조가 주도한 화성 축성과 함께 화성유수부로 승격되었는데 서울 다음으로 중요시된 도시로 변모하며 유수부의 위상에 맞춰 향교 역시 격식을 충실히 갖춤. 「○○○○○」은 정조의 어명을 받아 1795년 2고주 7량가 20칸 규모로 다시 지은 건물로, 특히 향교가 현 위치로 이건 되고 ○○○이 새로 지어지는 과정은 당시 공사보고서라 할 수 있는 『화성성역의궤』등의 문헌에 상세히 전함. ○○○의 규모는 서울 문묘, 나주향교, 상주향교, 제주향교, 대정향교와 함…","a":"수원향교 대성전","c":"보물","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122909152500.JPG"},{"q":"○○○○○은 경상남도 의령군 충익사에 소장된 ○○○의 ○○이다. 망우당 ○○○는 임진왜란 때의 의병장으로, ○○은 임진왜란 당시 ○○○가 사용하였던 장검, 말갖춤(마구) 및 평소 사용했던 포도연, 사자철인, 화초문백자팔각대접 등 6점이다. 장검은 길이 86㎝, 너비 3㎝, 자루 16㎝로 칼과 칼집이 한쌍이며, 보존상태가 양호하다. 손잡이 부분은 나무로 되어 있으며, 겉은 가죽끈을 교차하여 감았다. 칼등이 위로 조금 휘여 있으며, 칼집은 윗부분이 약간 부식되어 떨어졌다. 마구는 ○○○가 타고 다니던 말안장으로 부식상태가 심하여 1973년 8월에 보존 처리되었다. 벼루와…","a":"곽재우 유물 일괄","c":"보물","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622806.jpg"},{"q":"큰 농가집 형식의 민가로 'ㄱ'자형 안채, 사랑채, 아래채, 중문채, 헛간 등이 일곽을 이루고 있는 집이다. 안채에서 발견한 기록으로 미루어 조선 고종 1년(1864)에 안채를 지었고 사랑채나 아래채는 훗날 지은 것으로 짐작한다. 안채는 평범한 'ㄱ'자형 구조로 되어 있다. 대청을 중심으로 오른쪽에 고방과 건넌방을, 왼쪽에 안방과 부엌을 설치하였다. 안방의 사면에는 외짝문을 달아 드나들게 만들었는데 특색있는 구성이다. 가묘(家廟)가 없어 대청 1칸 뒷벽에 위패를 모시고 사당공간으로 사용하였으며, 대청 옆에 보기 드물게 고방을 두었다. 고방문은 대청쪽으로 달았고 앞쪽에…","a":"제천 박용원 고택","c":"국가민속문화유산","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633990.jpg"},{"q":"신라말기에 조성된 이 ○○○은 신라 진흥왕이 ○○지방까지 그 영역을 확대한 후 중원소경을 설치하고자 귀척(貴戚)들을 이주시켜 한강유적을 경영하고자 하였던 사실을 증명하는 유적으로서, 누암리 일대에만 230여기의 고분이 위치하고 있다. 발굴된 26기의 고분 가운데 주류를 이루는 것은 굴식돌방무덤(橫穴式 石室墳)이고 앞트기식돌덧널무덤(橫口式 石槨墳) 2기, 소형의 구덩식돌덧널무덤(竪穴式 石槨墓) 3기를 제외한 나머지는 외방무덤(單室墳)임이 확인되었다. 출토된 유물로는 짧은굽다리접시, 바리, 합, 항아리 등의 후기신라양식 토기류와 쇠손칼(鐵刀子), 덩이쇠(鐵鋌) 등의 철기…","a":"충주 루암리 고분군","c":"사적","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626383.jpg"},{"q":"○○ 근교 ○○○ 평지에 있는 신라의 무덤들로, 크고 작은 30여기의 무덤이 모여 있다. 아직 본격적인 조사는 이루어지지 않았지만 1952년에 파괴된 무덤 2기를 조사하였다. 무덤 내부는 직사각형의 구덩이를 파고 덧널(곽)을 설치한 신라 특유의 돌무지덧널무덤(적석목곽분)이다. 유물은 금귀고리와 굽은 옥 등이 수습되었다. 이곳의 무덤들은 모두 ○○시내의 평지 무덤들보다 규모가 작아 신라의 낮은 귀족들의 무덤으로 짐작된다. 이곳은 신라의 시조 박혁거세가 하늘에서 받은 금으로 만든 자(금자)를 숨기기 위해서 40여 개의 가짜무덤을 만들었다는 전설이 내려오는 곳으로 지금도…","a":"경주 금척리 고분군","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627650.jpg"},{"q":"1946년 4월 새로 제정된 육군 모표(帽標)가 그려진 ○○○○ 육군의 초창기 깃발이다. 1946년 1월 남조선 국방경비대가 창설되면서 군복은 비록 일본군 군복을 착용하였으나 모표만은 우리 것을 제정·부착하였으며 이 때 만들어진 모표가 깃발에 인쇄되어 있다. 유일하게 남아있을 뿐만 아니라 현존하는 가장 오래된 ○○○로서 ○○○○ 육군의 애국심과 굳건한 결속 및 군의 역사를 상징적으로 나타내는 유물이다.","a":"대한민국 육군기","c":"국가등록문화유산","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667338.jpg"},{"q":"1938년에 미쓰이(三井)물산주식회사 경성지점 건물로 신축되었으며, 1985년부터는 미문화원으로, 현재는 ○○시청 을지로별관 등으로 사용되고 있다. 외관상으로는 단순하고 장식이 없는 모더니즘 양식에, 입구부분에서 2개층 높이로 프레임진 돌출부 장식이 특징적인 건물로 역사적, 건축적 가치가 있다.","a":"서울 구 미국문화원","c":"국가등록문화유산","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667046.jpg"},{"q":"이 비는 1989년 마을주민이 밭갈이를 하던 중 발견하였으며, 재산분배를 확인하는 증명서의 성격을 지니고 있다. 형태는 네모난 자연석으로 밑부분이 넓고 위가 줄어드는 모습이며, 앞면과 뒷면, 그리고 윗면의 3면에 글자를 새겼다. 비문은 거의 닳지 않아 눈으로 읽을 수 있을 정도로 보존상태가 좋다. 글자는 총 231자이고 서체는 해서체로 보이나, 예서체의 기풍이 많이 남아 있어 비문의 형태와 글씨체면에서 충주 고구려비(국보), 울진 봉평리 ○○○와 매우 비슷하다. 비문은 절거리(節居利)라는 인물의 재산소유와 유산상속문제를 결정한 사실을 기록해 놓은 것으로, 공문서의 성…","a":"포항 냉수리 신라비","c":"국보","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612917.jpg"},{"q":"『○○○○○』은 유가파의 기본적인 논저로 인도의 미륵보살이 지은 글을 당나라의 현장이 번역하여 천자문의 순서대로 100권을 수록한 것이다. 이 책은 고려 고종 33년(1246)에 대장도감에서 간행한 ○○○ 고려대장경 판본 가운데 하나로 전체 100권 가운데 ○○○이다. 닥종이에 찍은 목판본으로 형태는 두루마리처럼 말아서 보관할 수 있도록 되어있고, 세로 36.8㎝, 가로 49㎝ 크기를 26장 이어붙였다. 재조대장경은 전해지고 있는 판본이 다양하지만, 인쇄가 정교하고 종이의 질이 두텁게 뜬 닥나무 종이이면서 표지와 제목이 원형 그대로 남아있는 것은 보기 드문 예이다.…","a":"재조본 유가사지론 권64","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614333.jpg"},{"q":"1945년 금융조합 ○○으로 건축된 우진각지붕의 일식(和風)주택이다. 현관문이 후면에 위치하고, 안방의 도코노마 공간 등 일본식 주택양식을 보여주고 있다. 내외부가 전반적으로 잘 보존되어 있어, 일제강점기 후반 ○○ 연구의 귀중한 자료로 가치가 있다.","a":"구 문경금융조합 사택","c":"국가등록문화유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669130.jpg"},{"q":"전북 ○○군 수동리에 있는 ○○○○ 가마터로, 구릉 위 작은 저수지의 경사진 언덕에 자리하고 있으며, 가마벽 부분·도자기 만들던 도구·○○○○ 조각들이 널려있다. 그릇은 대접·접시·잔·항아리·큰사발 조각이 주류를 이루며, 유약의 색은 회청색을 띠고 그릇을 빚던 흙에는 이물질이 많이 섞여 있다. 문양은 연꽃무늬, 물고기 무늬, 모란무늬 들이 대범하게 그려져 있다. 특히 일부 그릇에 내섬(內贍)* 이라는 글자가 새겨져 있는데, 이는 전라도지방의 ○○○○ 가마터에서 널리 발견되는 것으로 관청용 ○○○○도 제작하였음을 추정할 수 있다. * 내섬(內贍) : 조선 시대에 2품…","a":"고창 분청사기 요지","c":"사적","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626847.jpg"},{"q":"충남 ○○군에 있는 성으로, 길이 약 1,772m의 성벽 중 약 800m의 돌로 쌓은 성벽의 일부분이 남아있다. 처음 지어진 연대는 확실히 알 수 없으며, 『세종실록지리지』에 홍주성의 둘레와 여름과 겨울에도 마르지 않는 샘이 하나 있다는 기록만 있을 뿐이다. 왜구의 침입이 예상되는 고을의 읍성을 새로운 격식에 맞추어 쌓게 되었던 조선 세종 때에 처음 쌓기 시작하여 문종 1년(1451)에 새로 고쳐 쌓았다. 당시 성의 규모는 둘레가 4,856척(약 1.5㎞), 높이는 11척(약 3.3m)이며 문은 4개가 있었고, 여장·적대 등의 여러 시설이 설치되었으며 안에는 우물 2…","a":"홍성 홍주읍성","c":"사적","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626582.jpg"},{"q":"조선 중기의 명장인 이순신의 덕을 기리기 위하여 세운 비이다. ‘타루(墮淚)’란 눈물을 흘린다는 뜻으로, 중국의 양양 사람들이 양호(羊祜)를 생각하면서 비석을 바라보면, 반드시 눈물을 흘리게 된다는 고사성어에서 인용하였다. 비의 형태는 네모난 받침돌 위에, 비몸을 세우고, 머릿돌을 얹은 모습이다.받침돌에는 꽃무늬가 새겨져 있고, 머릿돌에는 구름무늬로 가득 채워져 있으며, 꼭대기에는 머리장식으로 보주(寶珠:연꽃봉오리모양의 장식)가 큼직하게 솟아있다. 비문은 ‘○○○’라는 비의 명칭을 앞면에 크게 새기고, 그 아래로 명칭을 붙이게 된 연유와 비를 세운 시기 등을 적고 있…","a":"여수 타루비","c":"보물","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619597.jpg"},{"q":"고려 ○○의 전통을 이은 조선 전기의 ○○로, 높이 7.6㎝, 입지름 17.5㎝, 밑지름 6.2㎝인 ○○이다. 바탕흙은 석고와 같은 질감으로, 벽이 얇은 그릇이다. 아가리 부분이 밖으로 살짝 벌어지고 안쪽 윗부분에는 단순화된 덩굴무늬가 둘러져 있다. 바깥면에는 그릇의 위와 아랫부분에 두 줄의 띠를 두르고, 그 안에 연꽃 덩굴 무늬를 상감기법으로 표현하였다. 이러한 ○○상감류는 조선시대 15세기 중반경에 주로 만들어진 것으로 대체로 경상도와 일부 지방가마에서 고려의 수법을 계승하였다.","a":"백자 상감연화당초문 대접","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611634.jpg"},{"q":"이 지도는 1602년 중국에서 마테오리치(Matteo Ricci, 1552~1610)와 명나라 학자 이지조(李之藻)가 제작한『○○○○○』의 수정본인 회입(繪入) 『○○○○○』를 1708년(숙종 34) 조선의 관상감에서 모사하여 제작한 것이다. 당시 숙종 임금의 명으로 이국췌(李國萃)와 유우창(柳遇昌)이 당대 화가 김진여(金振汝)와 함께 그린 것으로 제8폭에는 이 지도의 제작 경위가 담긴 최석정의 명문이 씌여져 있다. 8폭의 타원형 세계지도로 중국 중심의 세계를 그린 『혼일강리역대국도지도』가 주류였다. 그러나 이 지도는 당시의 서양지리학이 유입되어 새로운 세계의 모습을…","a":"곤여만국전도","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614090.jpg"},{"q":"○○○에 ○○되어 있는 ○○와 ○○로, 삼보명자수○○·쌍룡문직은○○의 ○○ 2점과 용문자수○○의 ○○ 1점이다. 대각국사 의천이 국왕에게 하사 받은 것으로 전하는 ‘삼보명자수○○’는 다홍색의 무늬가 없는 바탕천을 사용한 것으로 윗면과 측면에 3쌍의 ○○ 끈이 달려있다. ○○의 네 모서리에는 ‘천(天)’, ‘왕(王)’자를 수놓고, 가운데 부분에는 해와 달을 상징하는 삼족오(三足烏)와 절구 찧는 토끼를 평수(平繡: 자수 땀새를 동일하게 수놓음)로 꼼꼼하게 수놓았다. ○○의 품계(品階)는 조각 천을 이은 조(條)의 수로 구분되는데 최고의 품계인 25조로 구성되어 있으며,…","a":"선암사 소장 가사·탁의","c":"국가민속문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634728.jpg"},{"q":"원래 ○○○○○는 중국 원나라 황공소(黃公紹)가 편집한 것을 태충(態忠)이 보완하여 해설을 달아 30권으로 편성한 음운서이다. 이 판본은 조선 세종 16년(1434)에 경상도도관찰출척사로 부임한 신인손이 『○○○○』가 간행되지 못한 것을 알고 세종에게 이를 아뢰어 경주부와 밀양부에서 간행하게 된 것이다. 그 간행에 있어 신인손 이외에 도사 박근, 경주부윤 김을신 등 여러 관리가 관여하였고, 판을 새기는 데에는 대선사(大禪師) 홍희 이하 20여 명의 승려와 이종생 이하 여러 민간인 등 총 109명이 참여하였다. 비교적 정교하게 새겨졌으며, 인쇄가 깨끗하여 원래 판본의…","a":"고금운회거요 권27~30","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614638.jpg"},{"q":"이 상은 윤왕좌(輪王坐)의 보살상으로 금동불로는 규모가 비교적 큰 편이다. 보살상의 세부 표현과 양식은 전반적으로 고려시대의 특징을 잘 계승하고 있으나, 타원형의 양감있는 얼굴모습, 유두를 두드러지게 표현한 점, 몸 전면에 영락이 표현되지 않은 점, 몸을 감고 있는 천의자락의 선이 경직되게 표현된 점 등은 조선전기의 특징으로 여겨진다. 이 보살상은 조선 전반기의 금동상으로서 규모가 큰 편이고 보관 등에 다소 파손된 부분이 있으나 전체적으로 원래의 모습을 잘 보존하고 있다. 또한 이와 같이 크기가 큰 윤왕좌의 보살상은 조선 전기 보살상 중에서는 그 예가 드물며, 신체의…","a":"해남 대흥사 금동관음보살좌상","c":"보물","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619971.jpg"},{"q":"○○○○○는 고려 중기에 만들어진 ○○○○로 높이 10.5㎝, 길이 21.8㎝, 너비 8.2㎝이다. 모서리를 둥글게 깎은 직사각형의 판 위에, 두 마리의 사자가 서로 꼬리를 맞대고 머리로 ○○ 위판을 받치고 있는 모양이다. 사자는 각각 암수를 나타낸 것으로 보이며, 눈은 검은색 안료로 점을 찍어 생생하게 표현했다. ○○ 위판은 연잎을 형상화했으며, 잎맥이 예리하게 새겨져 있다. 표면은 맑은 비취빛 광택이 흐르고 부드러우며 은은한 색조를 띈다. 12세기 전반에 전라남도 강진군 대구면 사당리 일대 가마에서 만들어진 것으로 보인다.","a":"청자 쌍사자형 베개","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613920.jpg"},{"q":"지석묘란 청동기시대 사람들의 무덤으로서 고인돌이라고도 하며, 책상처럼 세운 탁자식(북방식)과 큰 돌을 조그만 받침돌로 고인 바둑판식(남방식)이 있다. ○○○에는 지석묘가 총 13기가 있었으나 현재는 10기만 남아있다. 대체로 자연암석을 떼어내 덮개돌로 사용한 바둑판식 지석묘로, 덮개돌이 큰 것은 길이가 6.35m, 너비 4.5m, 높이 70∼100㎝에 받침돌 8개를 돌려 세웠다. 보통 4개의 받침돌을 이용하는데 반해 8개의 받침돌을 돌려 다른 지역 고인돌에서는 볼 수 없는 독특한 형태를 하고 있다.","a":"부안 구암리 지석묘군","c":"사적","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626799.jpg"},{"q":"고달사터에 쓰러져 있었던 것을 1959년 경복궁으로 옮겨 왔으며, 현재는 국립중앙박물관에 있다. 높이는 2.43m이며 불을 밝히는 화사석(火舍石)까지만 남아있었으나, 2000년에 경기도 기전매장문화연구원이 실시한 발굴조사에서 지붕돌이 출토되었다. 직사각형의 바닥돌 4면에 둥글넓적한 모양의 안상(眼象)을 새기고, 아래받침돌 대신 2마리의 사자를 앉혀 놓았다. 사자는 좌우에서 앞발을 내밀고 웅크리고 있으며, 등 위로 구름이 솟아올라있다. 가운데받침돌에는 구름무늬를 돋을새김하였고, 윗받침돌에는 연꽃을 새겼다. 그 위에 놓인 화사석은 4면에 창을 뚫었다. 우리나라 ○○○○○…","a":"여주 고달사지 쌍사자 석등","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613235.jpg"},{"q":"1944년 평양시 평천리에서 공사를 하던 중 출토된 작은 보살상으로 높이 17.5㎝이다. 전면에 녹이 많이 슬었고 오랫동안 흙속에서 침식된 흔적이 뚜렷하며, 불에 탄 흔적이 많이 남아 있다. 삼국시대에 유행하던 반가상은 오직 백제와 신라에서만 그 유례를 찾아볼 수 있었는데, 이 보살상으로 새롭게 고구려의 예를 확인할 수 있어 주목된다. 머리에는 산 모양의 삼산관(三山冠)을 쓰고 있으며 고개를 약간 숙여 생각에 잠겨 있는 모습이다. 얼굴은 네모난 형으로 눈을 반쯤 감고 있고, 입가에는 엷은 미소가 번져난다. 상체에는 옷을 입고 있지 않아서 잘록한 허리가 그대로 드러나며…","a":"금동미륵보살반가사유상(1964)","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611563.jpg"},{"q":"선릉(宣陵)은 조선 9대 성종(1457~1494, 재위 1469~1494)과 세 번째 왕비 정현왕후 윤씨(1462~1530)의 능이다. 성종은 재위기간 동안 『경국대전』과 『대전속록』, 『국조오례의』를 완성하여 반포하였고, 선비들을 등용하여 기존의 훈구세력과 국정의 균형을 이루게 하였다. 정현왕후는 1473년(성종 4) 성종의 후궁이 되었고, 1480년(성종 11)에 왕비가 되었다. 선릉은 같은 능역에 하나의 정자각을 두고 서로 다른 언덕에 능을 조성한 동원이강릉(同原異岡陵)의 형태로 앞에서 봤을 때 서쪽 언덕이 성종, 동쪽 언덕이 정현왕후의 능이다. ○○은 조선 1…","a":"서울 선릉과 정릉","c":"사적","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624667.jpg"},{"q":"○○○에 남아 있는 낭원대사(834∼930)의 탑비로, 대사의 출생에서부터 경애왕이 대사의 덕을 기려 국사로 예우한 사실 및 입적하기까지의 그의 행적이 실려 있다. 대사가 96세로 입적하자 왕은 ‘낭원’이라는 시호와 ＇오진’이라는 탑이름을 내리었다. 비는 거북받침돌 위로 비몸을 세우고 머릿돌을 올린 모습이다. 용의 머리를 갖춘 거북받침돌은 등에 6각의 벌집 모양이 채워져 있고, 중앙에는 구름무늬로 장식한 높은 비좌(碑座:비를 꽂아두는 부분)가 마련되어 있다. 머릿돌은 밑면에 연꽃을 새기고 그 위로 여의주를 다투는 두 마리의 용을 힘차게 조각해 놓았다. 꼭대기에는 석탑…","a":"강릉 보현사 낭원대사탑비","c":"보물","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616434.jpg"},{"q":"『○○○○○』의 여러 이본 중 성신여자대학교 박물관에 소장된 지도이다. 고산자(古山子) 김정호(金正浩, 생몰년 미상)가 1861년(철종 12)에 제작한 이 지도는 조선의 지도 발달에서 정점에 있으면서 고지도의 백미로 평가받고 있다. 전국의 남북을 22첩으로 나누어 분첩절첩식(分疊折帖式) 형태로 제작하여 모두를 아래 위로 맞추면 전국지도가 된다. 지도의 제1첩에는 방안표, 범례인 지도표와 지도유설, 경도오부지도 등과 함께 조선의 최북단인 온성(穩城), 종성(鐘城), 경원(慶源) 일대의 지도가 수록되어 있다. 「지도유설」에서는 중국의 지도와 지리지의 기원을 말하고 그것들…","a":"대동여지도(1985)","c":"보물","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614093.jpg"},{"q":"○○○는『 ○○○사적』에 따르면 백제 법왕(600)때 세운 절이라고 한다. 이 건물은 원래 미륵전 뜰 가운데 세운 목조탑으로 불경을 보관하던 곳이었는데, 지금은 예전의 기능은 없어지고 안에 불상을 모시고 있다. 조선 인조 13년(1635)에 다시 짓고, 1922년에 지금 있는 위치로 옮겼다. 지붕 위에 남아 있는 조각들은 목조탑이었을 때 흔적이며 건물 안에는 석가모니와 가섭, 아난의 제자상을 모시고 있다. 규모는 앞면 3칸·옆면 3칸 크기이며 지붕은 옆면이 여덟 팔(八)자 모양을 한 팔작지붕이다. 기둥 윗부분에 장식하여 지붕 처마를 받치는 공포는 기둥 위와 기둥 사이…","a":"김제 금산사 대장전","c":"보물","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618552.jpg"},{"q":"경상북도 월성군 감은사 터에 있는 ○○○○○ 의 동쪽에 있는 석탑을 1996년도에 해체·수리하면서 발견된 일괄유물 중 사리 일괄품이다. 1959년에 발견된 ○○○○서○○○○내유물(보물)인 청동제사리기와 구조가 비슷하며, 바깥을 감싸고 있는 외함과 안쪽의 사리기, 그리고 사리병 등으로 구성되어 있다. 외함의 네 벽면에는 사리를 수호하는 사천왕상이 표현되어 있으며, 사천왕상의 주변에는 구름무늬를 새겼고 좌우에는 귀신의 얼굴 모양을 새긴 고리가 배치되어 있다. 사리를 모셔 둔 내함은 기단부, 몸체, 천개의 3부분으로 이루어져 있다. 기단부의 네 모서리에는 별도로 만든 사자…","a":"감은사지 동 삼층석탑 사리장엄구","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614781.jpg"},{"q":"성종 11년(1480)에 작성된 재산분배 기록이다. 이름높은 인물들을 많이 배출한 상산 김씨 가문의 16대손인 ○○○, 김광범 형제와 여식인 전좌랑 한건의 처 등 3남매가 부모가 돌아가신 후 물려받은 토지와 노비를 서로 상의하여 분배하는 ○○○○이다. 재산분배는 성별순이 아닌 나이 순으로 하여 맏아들 ○○○, 한건의 처, 김광범의 순서로 분배하였고, 마지막에 각자의 이름을 적고 그 밑에 수결(지금의 서명)을 하였다. 조선시대 사회 및 가족제도 연구에 귀중한 자료이며, 또한 당시 우리 민족의 남녀평등사상을 확인할 수 있는 귀중한 자료이다.","a":"김광려 삼남매 화회문기","c":"보물","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622858.jpg"},{"q":"대한제국의 마지막 관영공사인 ○○○ 중건시(1904～1906년) 궁안에 건립된 건물(○○○)로 1906년에서 1910년 사이에 궁내부 산하 황족과 귀족들의 근대식 교육기관인 수학원으로 사용되었다. 이후 소유권이 이전되고 1927년경 현 위치로 이축되면서 건물내부의 바닥, 가벽, 지붕, 누각형태의 기단 등이 다소 변형되었으나 기본골격과 측면의 상태가 비교적 양호하게 유지되어 있다. 한국 근대 초기의 ○○○ 관련시설이라는 점과 황족, 귀족들의 근대적 교육기관으로 활용되었다는 점에서 가치가 있다.","a":"경운궁 양이재","c":"국가등록문화유산","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667063.jpg"},{"q":"신라 47대 ○○○의 무덤이다. ○○○은 본명이 김의정으로, 45대 신무왕의 이복동생이다. 재위기간 동안 특별한 치적은 없으나 제방을 수리하는 등 농사를 장려하는데 힘썼다. 『삼국사기』에 의하면 861년 1월에 왕이 죽자 시호를 헌안(憲安)이라 하고 공작지(孔雀趾)에 장사지냈다고 하였으나 공작지의 위치는 알 수 없다. 무덤의 형태는 가장 단순한 형식의 무덤으로 높이 4.3m, 지름 15.3m의 원형 봉토분이다. 밑둘레에는 자연석을 이용하여 둘레돌을 둘렀으나, 현재 몇 개만이 남아 있다. 내부는 굴식돌방무덤(횡혈식석실묘)으로 추정된다. <br/><b>※(신라○○○○ →…","a":"경주 헌안왕릉","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627787.jpg"},{"q":"화강암으로 만들어진 전체 높이 3.5m의 거대한 보살상으로 연꽃이 새겨진 8각의 대좌 위에 서 있다. 이 부근에 건흥사라는 절이 있었다는 것을 감안하면 그 절에서 모시던 보살상으로 추측된다. 머리 위에는 상투 모양의 보계(寶髻)가 솟아 있으며, 보관(寶冠)은 없어진 상태이다. 양감이 줄어든 얼굴에는 작고 가는 눈, 다문 입이 표현되어서 다소 엄숙한 모습이다. 어깨는 각이 져 있으며, 신체는 장방형으로 보살상 특유의 유연성은 부족해 보인다. 가슴에 장식된 목걸이와 양 어깨에 걸쳐 입은 천의(天衣)는 매우 형식적으로 처리되었다. 허리에는 굵은 띠가 있고, 그 아래로는 양…","a":"거창 상림리 석조보살입상","c":"보물","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622599.jpg"},{"q":"｢○○○○○｣는 고려 말 전리판서를 지낸 남휘주(南暉珠, 1326~1372)와 공조참판 남민생(南敏生, 1348~1407)의 묘를 지키고 제사를 받들기 위해 마련된 건물임. 창건 시기는 정확히 알 수 없으나 법당인 남흥사를 개조하여 지어졌다고 전해지고 있으며, 청벽 이수연(靑壁 李守淵, 1693~1748)이 1744년 기록한「○○○○중수기(南興齋舍重修記)」로 미뤄보아 18세기 이전부터 존재하고 있었던 것으로 추정됨. * 재사(齋舍): 조상의 묘소를 수호하고 시제를 받들기 위해 지은 집 * 전리판서(典理判書): 고려 시대 문관의 선임, 공훈 등을 관장하던 전리사의 정3…","a":"안동 영양남씨 남흥재사","c":"국가민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2020122316003800.JPG"},{"q":"○○○ 대웅전의 주존으로 모셔진 이 불상은 고려 말 조선 초에 특히 많이 조성된 건칠불상이다. 양식적으로 이 불상은 다소 길어진 신체의 비례와 형태, 작아진 얼굴, 착의형식, 옷 주름의 표현 등에서 고려후기 불상 양식을 계승한 조선 초기에 제작된 상으로 추정된다. 특히 주먹 쥔 왼손을 오른손으로 감싸 쥔 형태의 지권인(智拳印)의 수인(手印)은 고려후기의 화엄경 변상도에 등장하는 비로자나불의 수인인데, ○○○ 상은 현존하는 조각에서 이 수인이 표현된 이른 예일 뿐만 아니라 조각적으로도 우수한 불상이다.","a":"나주 불회사 건칠비로자나불좌상","c":"보물","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619966.jpg"},{"q":"「○○○○」은 회재(晦齋) 이언적(李彦迪)이 27세 때 지은 「외천잠(畏天箴)」, 「양심잠(養心箴)」, 「경신잠(敬身箴)」, 「개과잠(改過箴)」, 「독지잠(篤志箴)」을 퇴계(退溪) 이황(李滉)이 읽고 크게 감명을 받아 평소 잊지 못하여 오던 중 이언적의 아들 이전인(李全仁, 호(號)는 잠계(潛溪), 1516~1568)의 요청에 의하여 쓴 것으로 전하고 있다. 이러한 내용은 10폭에 적혀 있는 이황의 발문에 보이는데 여기에는 잠계 이전인의 요청에 의해서 썼다는 기록은 없고 끝에 ‘후학 이황 근서(後學 李滉 謹書)’라고 쓴 묵적이 선명히 남아 있다. ‘○○○○’은 퇴계가…","a":"여주이씨 옥산문중 유묵 - 원조오잠, 사산오대","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621172.jpg"},{"q":"조선 숙종 때 경기도와 경상도 지역에서 활동한 승려인 ○○○○에 의해서 1674년에 만들어진 조선시대 종이다. ○○○○는 18세기 뛰어난 승려이자 장인으로 전통적인 신라 종의 제조기법에 독창성을 합친 종을 만들었다. 현재 그의 작품 8구가 서로 다른 특징을 보이며 전해지고 있다. 이 종은 종을 매다는 고리인 용뉴와 소리의 울림을 도와준다는 대나무 모양의 음통에 역동적인 모습의 용이 새겨져 있다. 또한 종의 어깨와 아래 입구 부분에는 연꽃과 덩굴을 새긴 넓은 띠를 두르고 있으며, 어깨 띠 아래에는 사각형 모양의 대가 있고 그 사이사이에는 보살상을 세웠다. 사실적으로 표…","a":"사인비구 제작 동종 - 안성 청룡사 동종","c":"보물","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615627.jpg"},{"q":"신라 55대 왕인 ○○○의 무덤으로, 경명왕의 뒤를 이어 왕위에 올랐다. 재위 4년이 되던 해에 포석정에서 잔치를 베풀고 있을 때, 후백제 견훤의 습격을 받아서 비참한 최후를 마친 왕이다. 무덤은 삼릉계곡 입구의 소나무 숲 안에 있으며, 일반무덤와 같아서 별다른 특징은 없다. 신라왕릉으로는 빈약한 편이며 발굴된 적은 없다. 『삼국사기』에는 ○○○을 남산 해목령에 장사지냈다고 되어있다. 해목령은 ○○○○에서 떨어져 있어서 맞지 않으며, 해목령 가까이에 있는 지금의 일성왕릉을 ○○○○으로 보아야 한다는 견해도 있다. <br/><b>※(○○○○ → ○○○○○)으로 명칭변경…","a":"경주 경애왕릉","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627834.jpg"},{"q":"조선시대(15세기) 이 책은 명나라 임강(臨江) 통수(通守) 섭윤현(葉尹賢)이 증험하여 편집한 의가비전(醫家秘傳)의 질병 처방인 『의가비전수신비용가감십삼방(醫家秘傳隨身備用加減十三方)』과 『경험급구방(經驗急救方)』을 한데 모아 조선전기에 간행한 의서(醫書)이다. 감기·독감·복통 등 13방에 대한 처방, 쓰이는 약재 등과 건강 장수베개를 만드는 부록이 있으며, 권하(卷下)에는 치곽난토사(治霍亂吐瀉)부터 구사부지(久瀉不止)에 이르는 37방에 대한 구급의 의방(醫方)과 약방문(藥方文)을 집성한 내용이 있다. 간행기록이 없어 정확한 제작 시기는 알 수 없지만 판각(板刻) 상태…","a":"증급유방","c":"보물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616142.jpg"},{"q":"『○○○○○』은 18세기 후반의 ○○ 명필인 경산 ○○○이 59세인 1790년(정조 14) 겨울에 오언율시 여러 수를 전서와 예서로 쓴 것이다. 전서는 획이 가늘고 굵기가 일정한 당나라 이양빙(李陽氷)의 옥저전(玉箸篆) 계통이며, 예서는 동한시대 예서비로 유명한 <예기비(禮器碑)>와 <조전비(曺全碑)>를 혼합한 듯하다. ○○○은 앞 시기의 명필인 이인상과 송문흠의 ○○서풍을 계승하여 이를 발전시킨 인물로 이 서첩은 현존하는 ○○○의 몇몇 필적 가운데 그러한 면모를 가장 잘 보여주고 있다.","a":"이한진 전예 경산전팔쌍절첩","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616200.jpg"},{"q":"조선시대 제주지방 통치의 중심지였던 ○○○○○는 지금의 제주 관덕정(보물)을 포함하는 주변 일대 주요 ○○시설이 자리하였던 곳으로 탐라국 이래 조선시대에 이르기까지 제주의 정치·행정·문화의 중심지 역할을 해왔다. ○○시설은 1434년(세종 16) 관부의 화재로 건물이 모두 불타 없어진 뒤 바로 역사를 시작하여 그 다음해인 1435년에 골격이 이루어졌으며, 조선시대 내내 증·개축이 이루어졌다. 그러나 ○○○○○는 일제강점기 때 집중적으로 훼철되어 관덕정을 빼고는 그 흔적을 찾아 볼 수가 없었다. 이에 제주시에서는 1991년부터 1998년까지 4차례 발굴조사를 진행한 결…","a":"제주목 관아","c":"사적","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628521.jpg"},{"q":"이 건물은 ○○○의 전형을 알 수 있는 단층의 합각 함석지붕 목조건축물로, 지붕 목조트러스 가운데 목부재에 쓰여진 기록을 통해 1930년에 목수 성조운(成造運)이 건립하였음을 알 수 있다. ○○○의 환기를 위해 높은 창을 두고 보온을 위해 벽체와 천장에 왕겨를 채웠으며, 외부 마감은 목재 널판을 사용하는 등 목조 건축물로서 독특한 형식을 갖추고 있다.","a":"진천 덕산양조장","c":"국가등록문화유산","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668499.jpg"},{"q":"○○○○○은 줄여서 ‘금강경’이라고 부르기도 하는데, 조계종의 근본경전으로 우리나라에서는 반야심경 다음으로 많이 읽히는 불교경전이다. 이 책은 후진(後秦)의 구마라습(鳩摩羅什)이 번역한 것에 명나라의 천노(川老)가 풀이를 덧붙인 것이다. 닥종이에 찍은 목판본으로 처음에 두루마리 형식으로 만들었던 것을 다시 책의 형태로 고쳐 만들었으며, 크기는 세로 56㎝, 가로 19.1㎝이다. 책머리에 있는 글에 의하면 유향과 강인부가 우왕의 왕비에게 도움을 받아 책을 간행했음을 알 수 있다. 이때 지담(志淡)이 간행을 주관하고 이색(李穡)이 발문(跋文:책의 내용과 그에 관계된 일을…","a":"금강반야바라밀경","c":"보물","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613762.jpg"},{"q":"­○○○를 찍어내기 위해 목재에 4괘와 태극문양을 새긴 ○○으로 희귀할 뿐 아니라 당시 제작기법과 상황을 헤아릴 수 있는 것으로서 사료적 가치가 크다","a":"태극기 목판","c":"국가등록문화유산","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668609.jpg"},{"q":"근대문명의 기반이 된 전기의 생산 및 공급과 관련하여 일제강점기 소규모 전기회사들의 합병및 해방 후 한국전력으로 이어지는 역사를 보여주는 건축물로서 역사적 가치를 갖고 있고, 모더니즘 경향의 외관과 계단실 등의 처리가 특징적이다.","a":"군산 구 남조선전기주식회사","c":"국가등록문화유산","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018081416534700.jpg"},{"q":"가야산 중턱에 자리잡은 ○○○는 통일신라 애장왕 3년(802)에 지은 사찰로, 왕후의 병을 부처의 힘으로 치료해 준 것에 대한 감사의 뜻으로 지었다고 한다. 우리나라 3대 사찰 중 하나이며, 8만대장경을 보관하고 있기 때문에 법보사찰이라고도 부른다. ○○○○은 고려시대에 만들어진 8만여장의 대장경판을 보관하고 있는 건물로, ○○○에 남아있는 건물 중 가장 오래 되었다. 처음 지은 연대는 정확히 알지 못하지만, 조선 세조 3년(1457)에 크게 다시 지었고 성종 19년(1488)에 학조대사가 왕실의 후원으로 다시 지어 ‘보안당’이라고 했다는 기록이 있다. 산 속 깊은…","a":"합천 해인사 장경판전","c":"국보","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1613038.jpg"},{"q":"○○○ 소속의 봉천원(奉天院)에 있던 것을 현재 자리인 대적광전 앞의 왼쪽으로 옮겨 왔다. 우리나라의 탑이 대부분 밝은 회색의 화강암으로 만든 정사각형의 탑인데 비해, 이 탑은 흑백의 점판암으로 만든 ○○○○○이다. 탑을 받치는 기단(基壇)에는 연꽃조각을 아래위로 장식하였다. 탑신부(塔身部)는 각 층마다 몸돌이 있었으나 지금은 가장 위의 2개 층에만 남아 있다. 몸돌은 각 귀퉁이마다 기둥모양이 새겨져 있고, 각 면에는 원을 그린 후 그 안에 좌불상(坐佛像)을 새겨 놓았다. 지붕돌은 낙수면에서 아주 느린 경사를 보이다가, 아래의 각 귀퉁이에서 우아하게 들려있다. 밑면에…","a":"김제 금산사 육각 다층석탑","c":"보물","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618135.jpg"},{"q":"산비탈 두 곳의 커다란 암벽에 시기를 약간 달리하여 부조(浮彫)로 조각되어 있는 9구의 불·보살상(佛·菩薩像)이다. 상부에는 높이 3.5m, 폭 8m의 바위면에 불좌상 1구가 양각되어 있고, 하부에는 불좌상 1구와 공양상(供養像)·반가상(半跏像)을 중심으로 5구의 보살상 등 모두 8구가 새겨져 있다. ○○○○○이 위치하고 있는 곳의 지리학적, 역사적 사실, 조형수법적 특징을 통해서 삼국시대 말기나 통일신라초기에 조성되었으며, 고구려 불상의 착의법과 형식을 따르고 있는 점들을 통해서 고구려 불상의 영향에서 신라시대 불상의 흐름을 함께 보여주는 매우 귀한 자료로 그 학술…","a":"충주 봉황리 마애불상군","c":"보물","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617312.jpg"},{"q":"가락국(금관가야)의 시조이자 ○○ 김씨의 시조인 ○○○의 무덤으로, 납릉(納陵)이라고 부른다. ○○○에 대한 이야기는 『삼국유사』「가락국기」에 전하고 있으나, 무덤이 정확히 언제 만들어졌는지는 알 수 없다. 무덤의 높이는 5m의 원형 봉토무덤인데, 주위 18,000여 평이 왕릉공원으로 되어 있다. 왕릉 구역 안에는 신위를 모신 숭선전과 안향각·전사청·제기고·납릉정문·숭재·동재·서재·신도비각·홍살문·숭화문 등의 건물들과 신도비·문무인석·마양호석·공적비 등의 석조물들이 있다. 고려 문종대까지는 비교적 능의 보존상태가 좋았으나, 조선 초기에는 많이 황폐했던 듯하다. 『세종…","a":"김해 수로왕릉","c":"사적","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628145.jpg"},{"q":"신라 ○○○의 무덤으로 소나무숲으로 둘러싸여 있다. 『삼국사기』에 의하면, 왜국 동북 1,000리 지점에 다파나국의 왕비가 알을 낳았는데 불길하다 하여 보물과 함께 궤짝에 넣어 바다에 띄워 보냈다. 처음에는 금관국(김해)에 닿았으나 사람들이 이상하게 여겨 아무도 거두지 않았고 다시 진한의 아진포에 닿았는데 노파가 거두어 키웠다. 궤짝이 떠오를 때 까치 한 마리가 따라다니며 울었다고 하여 까치 작(鵲)자에서 조(鳥)를 떼고 석(昔)으로 성을 삼고, 아이가 궤를 풀고 나왔다 해서 이름을 탈해(脫解)라 지었다. ○○○은 석(昔)씨의 시조로서 신라 최초 석씨 왕이 되었다.…","a":"경주 탈해왕릉","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627773.jpg"},{"q":"불상을 모시기 위해 나무나 돌, 쇠 등을 깎아 일반적인 건축물보다 작은 규모로 만든 공간을 불감(佛龕)이라 한다. 불감은 그 안에 모셔진 불상의 양식뿐만 아니라, 당시의 건축 양식을 살필 수 있는 중요한 자료가 된다. 43.3㎝ 높이의 ○○○○으로 정면 전체를 여닫이식 문으로 구성하여 예배나 의식 때만 열어서 볼 수 있게 되어 있다. 좌우 문 안쪽면에 칼을 든 인왕상이 1구씩 돋을새김되어 있는데 정교하고 생동감 있게 표현되었다. 정면 벽에는 중앙에 비로자나삼존상과 주위에 10대 제자상을 돋을새김하였다. 비로자나불상은 전형적인 8각의 연꽃무늬 대좌 위에 앉아 있다. 손…","a":"구례 천은사 금동불감","c":"보물","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619970.jpg"},{"q":"○○○○○의 극락전 앞에 동·서로 서 있는 2기의 석탑으로, 두 탑 모두 2단의 기단(基壇)위에 3층의 탑신(塔身)을 세운 모습이다. 먼저 동쪽의 탑은 2단의 기단 대부분이 나중에 보수된 것이라서 돌을 다룬 수법과 끝맺음 처리 부분에서 조화를 잃어버리고 있다. 위층 기단의 각 면에는 가운데와 모서리에 기둥 모양을 새겼다. 탑신의 몸돌과 지붕돌을 각각 따로 새겨 쌓아 올렸으며, 각 몸돌에는 모서리마다 기둥 모양의 조각을 두었을 뿐 다른 장식은 없다. 지붕돌은 밑면의 받침이 4단씩 새겨져 있다. 꼭대기에는 머리장식으로 노반(露盤:머리장식받침), 복발(覆鉢:엎어놓은 그릇모…","a":"대구 동화사 금당암 동·서 삼층석탑","c":"보물","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615161.jpg"},{"q":"○○○의 마애상은 서있는 모습의 부처를 얇은 선으로 새긴 것으로, 장군바위라고 부르는 바위에 새겨져 있다. 무늬가 새겨진 모자 모양의 둥근 보관을 쓰고 있으며 작고 좁은 관대가 옆으로 휘날리고 있다. 목에는 삼도가 굵은 띠처럼 새겨져 있고 가슴에는 대각선으로 가로지른 꽃무늬가 새겨진 속에 입은 옷과 띠매듭이 보인다. 양어깨를 모두 감싼 옷을 입었는데, 가슴 밑에서부터 반원을 그리며 규칙적으로 흘러내린 주름은 볼륨감은 없으나 유려한 선으로 이어져 있다. 반원으로 둥글게 흘러내린 상의자락 밑 양쪽으로 발을 벌렸는데 발가락의 표현이 매우 섬세하다. 균형 잡힌 신체에 사각형…","a":"시흥 소래산 마애보살입상","c":"보물","r":"경기도","s":"시흥시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616080.jpg"},{"q":"○○시내에 상당한 거리를 두고 떨어져 있는 2기의 탑 가운데 동쪽에 위치한 것으로 통일신라 후기의 석탑이다. 탑이 서있는 부근은 백주사(栢州寺)터로 알려져 있기도 하나 추정할 만한 자료는 아직 발견되지 않았다. 탑의 구성은 2단의 기단(基壇) 위에 5층의 탑신(塔身)을 세운 형태로 신라석탑의 기본형을 잃지 않고 있다. 탑의 받침대 역할을 하는 기단부는 여러 개의 돌을 짜맞추어 구성하였으며, 탑신부의 몸돌과 지붕돌은 각각 하나의 돌로 이루어졌다. 특히 지붕돌 밑면의 받침이 1층은 5단인데 비해 2층부터는 4단으로 간략화되어, 양식상 만들어진 시대가 통일신라 후기로 내려…","a":"광주 지산동 오층석탑","c":"보물","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615470.jpg"},{"q":"○○○○○은 ○○공립심상소학교 교사로, 전체적으로 중앙 현관을 기점으로 대칭을 이루고 있고 처마 지붕 아래 돌림띠의 수평적 요소와 세로로 긴 창과 굴뚝의 수직적 요소를 통해 근대적 조형성을 표현하고 있는 등 ○○에 남아있는 가장 오래된 초등학교 교사 건물로서 가치가 있다.","a":"진주 배영초등학교 구 본관","c":"국가등록문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2135827.jpg"},{"q":"마을 중심부에 위치한 이 가옥은 안채, 중 사랑채, 큰 고방채, 작은 고방채, 큰 사랑채, 사당, 대문채 등 7동으로 이루어져 있으며 서남향으로 자리한 대문채를 들어서면 좌측 편에 남향한 큰 사랑채가, 우측으로 별곽(別廓)을 이루어 사당이 위치하고 대문채와 마주 보고 있는 중 사랑채가 안채와 2동의 고방채와 더불어 튼 ＇ㅁ＇자의 몸채를 이루고 서북향으로 배치되어 있다. 가옥배치 및 공간구성의 특징으로는, 몸채의 방향이 지형조건 상 남향을 할 수 있음에도 건축 환경적으로 불리한 서북향을 하고 있는 점, 큰 사랑채가 대문채에서 중 사랑채에 이르는 출입동선을 한눈에 볼 수…","a":"청도 운림고택","c":"국가민속문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635603.jpg"},{"q":"일제강점기 산업시설로 당시의 기술수준을 가늠할 수 있는 중요한 자료 및 근거가 되며, 최근까지 정수시설로 사용되어 온 시설로서 보존상태가 비교적 우수하다.","a":"동해 구 상수시설","c":"국가등록문화유산","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668372.jpg"},{"q":"『○○○○』은 세종 28년(1446)에 소헌왕후가 죽자 그의 명복을 빌기 위해 세종의 명으로 수양대군(후의 세조)이 김수온 등의 도움을 받아 석가의 가족과 그의 일대기를 기록하고 이를 한글로 번역한 책이다. ○○,9,○○○○는 초간본으로 갑인자 활자로 찍은 것이다. 책 머리에『교정(校正)』이라는 붉은 도장이 찍혀 있고, 이 책 속에 잘못 활자가 찍힌 것이나 또는 초고에서 잘못된 것으로 보이는 것을 교정하여 난외(활자판 바깥부분)에 정오(正誤)를 표시한 것이 보여 문자 그대로 교정본임을 확인할 수 있다.","a":"석보상절 권6, 9, 13, 19","c":"보물","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613397.jpg"},{"q":"조선 후기 우리나라의 아름다운 강산을 실제로 보고 그리는 진경산수화풍을 연 겸재 ○○이 영조 10년(1734)에 내금강의 모습을 그린 작품이다. 내금강의 실경을 수묵담채로 그렸으며 크기는 가로 94.5㎝, 세로 130.8㎝이다. 전체적으로 원형구도를 이루고 있고 위에서 아래로 내려다 본 모습이다. 눈덮인 봉우리들은 위에서 아래로 내려긋는 수직준법을 이용하여 거칠고 날카로운 모습으로 표현하였고, 이와 함께 위쪽에는 비로봉이 우뚝 솟아 있으며, 화면 중심으로는 만폭동 계곡이 위에서 아래로 가로지르고 있다. 바위로 이루어진 메마른 느낌의 봉우리들과는 대조적으로 왼편에는 무…","a":"정선 필 금강전도","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611691.jpg"},{"q":"약 200m의 거리를 사이에 두고 마주 서 있는 2구의 석상으로, 사다리꼴 모양의 돌기둥에 얼굴, 손, 대좌 등이 표현되어 있다. 이 불상에 얽힌 전설에 의하면 음력 12월에 두 불상이 만나 1년 동안의 회포를 풀고 새벽닭 우는 소리를 듣고 제자리로 돌아가는 남녀상이라고 한다. 머리에는 4각형의 높은 관(冠) 위에 다시 4각형의 갓을 쓰고 있다. 4각형의 얼굴에는 가는 눈, 짧은 코, 작은 입이 간신히 표현되어 있는데, 토속적인 수호신의 표정이다. 목은 무척 짧게 표현되어서 어깨와 얼굴이 거의 붙어 있는 셈이다. 몸은 사다리꼴의 돌기둥으로 굴곡이 없으며, 팔은 표현되…","a":"익산 고도리 석조여래입상","c":"보물","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618232.jpg"},{"q":"옛 고창 고을의 읍성으로 모양성(牟陽城)이라고도 하는데, 백제 때 고창지역을 모량부리로 불렀던 것에서 비롯되었다. 나주진관, 입암산성 등과 더불어 호남내륙을 방어하는 요충지로, 단종 원년(1453)에 세워진 것이라고도 하고 숙종 때 완성되었다고도 하나 확실하지 않다. 성벽은 비교적 잘 남아 있는데 최근 보수공사를 하여 원형에 가깝도록 복구하였다. 성 둘레는 1,684m이며, 동·서·북문과 옹성이 3개소, 장대지 6개소와 해자들로 된 전략적 요충시설이 갖춰져 있다. 성 안에는 동헌·객사를 비롯하여 22동의 관아건물들로 되어 있었으나 대부분 손실되었다. 이 성은 조선시대…","a":"고창읍성","c":"사적","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626820.jpg"},{"q":"이 건물은 육군 6군단(군단장 이한림 장군)이 지은 성당이다. 1990년 화재로 목조 마루바닥과 지붕틀 등이 소실되긴 하였으나 한국전쟁 직후에 건축된 석조 성당의 전형적인 의장적 특징(종탑과 뾰족한 아치 창호)과 공간적 특징(단일 홀로 구성된 강당형 평면), 화강석 조적 구법의 특징을 잘 간직하고 있다. 한국전쟁 이후 많은 교회 건물을 석조로 세웠지만 ○○○○은 군부대가 직접 세운 것 중 유일하게 남아 있는 건물이다.","a":"구 포천성당","c":"국가등록문화유산","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668076.jpg"},{"q":"이 건물은 태백시에 남아 있는 가장 오래된 관공서이다. 삼척○○○ 태백분소로 설립하였다가 분소가 ○○○로 승격되어 황지동으로 이전함에 따라 삼척군 장성읍사무소로 사용하였다. 중앙의 계단실을 중심으로 좌우대칭형의 평면이며, 1층 출입구와 옥탑부의 지붕은 캔틸레버를 사용하여 중심성을 강조하였다. 장식을 배제하고 수직 루버를 반복적으로 사용하는 등 근대 건축 기법이 잘 나타나 있다.","a":"구 태백등기소","c":"국가등록문화유산","r":"강원특별자치도","s":"태백시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668425.jpg"},{"q":"｢○○○○○｣은 을사늑약(1905년) 이후 충청남도 해안지역에서 의병들이 연합하여 ○○○○에서 전개된 항일 의병전쟁의 처절한 역사적 사실을 확인할 수 있는 장소로서, 전국에서 유일하게 해상 도서를 근거지로 항일투쟁을 벌인 곳이다. 일제가 우리나라를 강점하기 위해 항일세력을 도서지방까지 철저하게 탄압한 실상을 잘 보여주고 있으며, 독립운동사의 참된 가치와 애국혼을 선양할 수 있는 중요한 유적지이다.","a":"당진 소난지도 의병총","c":"국가등록문화유산","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017103015474500.JPG"},{"q":"○○○은 ○○○의 정전이다 ‘인정(仁政)’은 ‘어진정치’라는 뜻이며, ○○○은 ○○○의 법전(法殿)이 된다. 법전은 왕의 즉위식을 비롯하여 결혼식, 세자책봉식 그리고 문무백관의 하례식 등 공식적인 국가 행사 때의 중요한 건물이다. 광해군 때 중건된 이후 순조 3년(1803)에 일어난 화재로 인한 재건, 그리고 철종 8년(1857년)에 보수공사이후 지금에 이르고 있다. ○○○의 넓은 마당은 조회가 있었던 뜰이란 뜻으로 조정(朝廷)이라고 부른다. 삼도 좌우에 늘어선 품계석은 문무백관의 위치를 나타내는 표시로 문무관으로 각각 18품계를 새겼다. 그러나 정(正)4품부터는 종…","a":"창덕궁 인정전","c":"국보","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611746.jpg"},{"q":"○○○○○은 줄여서 ‘화엄경’이라고 부르기도 하며, 부처와 중생이 둘이 아니라 하나라는 것을 기본사상으로 하고 있다. 화엄종의 근본경전으로 법화경과 함께 한국 불교사상 확립에 크게 영향을 끼친 경전이다. 당나라의 실차난타가 번역한『화엄경』○○ 80권을 고려 현종 때 목판에 새긴 초조대장경이다. ○○○○○의 2권을 닥종이에 인쇄한 목판본으로 종이를 이어붙인 두루마리 형태이며, 2권 모두 표지와 첫째장·본문 등이 약간씩 없어졌다. 제목 아래 ‘신역(新譯)’이란 표시가 있어 이 책이 ○○임을 알 수 있다. 책 내용은 선재동자(善財童子)가 53인의 고승을 찾아가는 구도의 과…","a":"초조본 대방광불화엄경 주본 권67, 77","c":"보물","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615424.jpg"},{"q":"1935년 건립 이 건물은 일제 강점기 당시 한센병 환자들에게 ○○ 참배를 강요하기 위하여 지은 ○○이다. 일본 ○○ 건축의 형식과 배치를 취하고 있으며, 목조 건축 양식을 모방하여 철근 콘크리트와 벽돌로 건축되었다. 예배에 사용되는 배전(拜殿)과 신체가 봉안된 본전(本殿)의 2동으로 이루어져 있다.","a":"고흥 구 소록도갱생원 신사","c":"국가등록문화유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668883.jpg"},{"q":"‘○○○○○’는 근대기 만들어졌던 ○○라는 측면 이외에 일본의 수탈을 막기 위해 소안도 주민과 의병들이 1909년에 의거를 일으킨 역사적 장소이며, 또한 이를 계기로 인근 지역(소안도와 신지도 등)으로 전개된 항일운동의 시발점이 되었다는 점에서 항일독립문화유산으로서 국가등록문화유산적 가치가 높다고 할 수 있다.","a":"완도 소안면 구 당사도 등대","c":"국가등록문화유산","r":"전남광주통합특별시","s":"완도군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018101418171100.jpg"},{"q":"­최초의 서양화가로서 후진을 양성하고 근대적 화단을 형성하고 이끌어나간 ○○○ 선생이 살던 곳이다. 선생이 일본 유학을 마치고 돌아와 지은 목조 기와집으로, 근대 초기 한국주택의 특징을 잘 보여준다.","a":"서울 원서동 고희동 가옥","c":"국가등록문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666936.jpg"},{"q":"○○○은 경주 황남동고분 제155호 무덤으로 1973년 발굴하여 금관, 팔찌 등 많은 귀중한 유품들과 함께 천마 그림이 발견되어 ○○○이라 부르게 되었다. ○○○○○은 술, 음식, 약들을 끓이거나 데우는데 사용하던 그릇으로, 대부분 왕릉을 비롯한 큰 무덤에서만 출토된다. 이 청동 초두는 높이 20.5㎝, 몸통 지름 18㎝, 손잡이 길이 13㎝의 크기이다. 전체 형태는 납작한 구형의 몸통에 뚜껑을 덮은 형식으로, 밑에는 3개의 동물 모양 다리가 달렸다. 몸통에는 가로로 한 줄이 돌려 있고 이 위에 휘어진 뿔이 달린 양머리 모양의 액체를 따르는 주구가 달려 있다. 이와…","a":"천마총 자루솥","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621298.jpg"},{"q":"고려시대의 만들어진 ○○○○으로 높이 38.9㎝, 아가리 지름 5.1㎝, 밑지름 15.6㎝이다. 어깨에서 팽배하게 벌어졌다가 몸통 아래에서 좁혀져 세워진 몸체와 각이 진 아가리가 달린 전형적인 고려 ○○이다. 목은 낮고 잘룩하여 작고 낮은 아가리와 조화를 이룬다. 흑백상감 기법으로 몸통의 앞·뒷면에 가는 줄기의 매화와 대나무를 큼직하게 배치하고, 그 사이에 날아오르는 새와 학, 풀을 회화적으로 나타냈다. 병의 표면은 담청록의 맑은 빛깔로 투명하며, 미세하게 갈라진 빙렬이 전면에 나타난다. 회화적인 매(梅), 조(鳥), 죽(竹)의 상감무늬와 맑은 ○○유가 잘 어울리는…","a":"청자 상감매죽학문 매병(1986)","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614242.jpg"},{"q":"1908년 건립 이 시설물은 농업용수가 부족하여 논농사에 부적합한 제주도의 자연환경을 극복하기 위해 ○○○ 폭포의 낙수가 흐르도록 천연암반 지형을 파서 만든 2km의 장거리 ○○○○이다. 이 농업용수 시설로 ○○○ 일대 231,000㎡의 불모지가 옥답(沃畓)으로 변모하였지만, 시공 과정에서 제주도민의 크나큰 희생이 따랐던, 제주도민의 생활상과 농업 환경을 전해주는 시설물이다.","a":"서귀포 천제연 관개수로","c":"국가등록문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669563.jpg"},{"q":"『○○○○○』은 법어(法語), 즉 부처님의 말씀이나 가르침을 적어놓은 것으로 승려들의 수행에 있어 길잡이 구실을 하며, 우리나라에서는 조선시대에 널리 유통되었다. 원나라 ○○○○ 덕이(德異)의 법어 6편과 고려 나옹화상 혜근(慧勤)의 법어 1편을 1책으로 묶은 것이다. ○○○○ 덕이는 고려의 혜감국사 만항(萬恒), 보감국사 혼구(混丘)와 깊은 교류가 있던 인물로, 고려말이후 한국 불교계에 커다란 영향을 끼쳤다. ○○○○○(蒙山和尙法語略綠(諺解))은 조선 혜각존자 신미가 토를 달고 한글로 번역한 것으로, 맨 앞장의 제목에 ‘慧覺尊者信眉譯解(혜각존자신미역해)’라고 그의…","a":"몽산화상법어약록(언해)(1984-3)","c":"보물","r":"서울특별시","s":"동대문구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613873.jpg"},{"q":"○○의 서쪽 주산에 쌓은 가야의 산성이며, 이산성(耳山城)이라고도 한다. 산성의 남쪽 산등성이에는 대가야 무덤들이 분포되어 있어 산성과의 연관성을 보여주고 있다. 산의 가장 높은 곳과 동쪽의 능선을 따라 둥글게 흙으로 쌓은 내성과, 내성의 동쪽과 서쪽 끝에서 시작하여 타원형으로 돌을 쌓은 둘레 약 700m의 외성으로 된 2중 성벽을 가지고 있다. 성벽은 대부분 무너졌으나, 계곡쪽으로는 견고하게 쌓은 성벽이 남아 있다. 현재 외성은 대나무숲이 우거져 있어 먼곳에서 전체 윤곽을 파악하기 힘들며, 성 안에 우물터와 건물터로 보이는 곳이 남아 있다. 외성의 서남쪽에 연결된…","a":"고령 주산성","c":"사적","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627672.jpg"},{"q":"신라시대에 세운 ○○○는 여러 차례 보수를 거쳤는데 지금의 절은 조선 숙종 44년(1718)에 있었던 네 번째 보수 때의 것이다. ○○○○도 이때 세운 것으로 추정한다. 앞면 3칸·옆면 3칸 규모이며 기둥 사이의 간격을 넓게 잡아서 같은 규모의 건물보다 크다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위와 기둥 사이에도 있는 다포 양식으로, 조선 후기의 일반적인 다포계 건물들과는 달리 장식으로 치우치지 않았다. 앞면에는 꽃무늬를 넣은 문을 달았는데, 특히 가운데 칸은 넓어 5짝 여닫이문…","a":"청도 운문사 대웅보전","c":"보물","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621572.jpg"},{"q":"현재 불상의 머리는 후대에 새롭게 붙여 놓은 것으로 발견 당시에는 몸통과 대좌만 있었다. 불상이 앉아 있는 대좌(臺座) 역시 원래 불상과 같이 있던 것인지는 확실하지 않다. 비록 원래의 모습이 많이 없어지고 보존 상태도 그리 좋지 못하나 세부의 조각 수법이 우수하고 안정된 자세를 취하고 있다. 양 어깨에 걸쳐 입고 있는 옷은 소매 하나까지 매우 사실적으로 표현하였고, 짤막하게 이어진 옷주름 역시 활달한 모습이다. 오른손을 무릎 위에 올리고 손끝이 땅을 향하도록 하고 있는데, 이것은 악귀를 물리친다는 의미의 항마촉지인(降魔觸地印)이다. 비록 불상의 신체만 남아 있지만…","a":"안동 안기동 석조여래좌상","c":"보물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620096.jpg"},{"q":"강원특별자치도 ○○군 내촌면 ○○○ 소재의 대승사에 있는 ○○○○○으로 얼굴은 마멸이 심해 세부표현을 분명하게 확인할 수 없다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓은 것 같으며, 정수리 부분에 있는 상투 모양의 머리(육계)는 표현이 분명하지 않다. 옷은 양 어깨에 걸치고 있고, 가슴에는 띠모양의 매듭이 보인다. 어깨는 둥글지만 두껍고 투박하게 보이고, 상체는 8세기 불상에 비해 평판적이고 왜소한 편이어서 당당한 양감이 사라져버린 모습이다. 손은 오른손을 무릎위에 올려 손끝이 아래를 향하고 왼손은 배부분에 놓고 있는 모습이다. 불상이 앉아있는 대좌(臺座)는 상…","a":"홍천 물걸리 석조여래좌상","c":"보물","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616682.jpg"},{"q":"○○○ 원통보전에 모셔져 있는 건칠불상으로, 근처의 영혈사에서 모셔왔다고도 전해진다. 금속으로 만든 팔각 대좌 위에 결가부좌한 채 앉아 있는데, 적당한 크기로 허리를 곧추 세우고 고개만을 앞으로 약간 숙여 마치 굽어보는 듯한 느낌을 준다. 머리에는 화려하기 이를 데 없는 높은 보관을 썼으며, 네모꼴에 가까우면서도 각지지 않은 둥글고 탄력적인 얼굴에는 귀·눈·입·코 등이 단정하게 묘사되어 있다. 목에는 세 개의 주름인 삼도(三道)가 뚜렷하고, 가슴 부분이 두드러지게 표현되었다. 오른손은 가슴에 올리고 왼손은 배에 두었으며 엄지와 중지를 맞댄 손모양을 하고 있는데, 가냘…","a":"양양 낙산사 건칠관음보살좌상","c":"보물","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616920.jpg"},{"q":"『○○○○○』상․중․하 3첩은 17세기의 유명한 문신학자 서계 ○○○의 ○○으로 문인(門人) 이정신(李正臣, 1660~1727)에게 써준 것이다. 상첩(上帖)은 이정신의 시를 차운한 자작시와 자연에 대한 사랑과 혼탁한 세상과 멀리 한 중국의 시문이다. 중첩(中帖)과 하첩(下帖)은 각각 29통과 25통의 간찰로 이정신에게 보낸 것이 대부분이다(中帖 1통 처남 남구만에게, 下帖 6통 박태보의 간찰). 1679~1702년에 쓴 것으로 대부분 『서계집』에 실리지 않았다. 그중 ○○○이 이정신에게 중국 서화첩을 열람품평하게 한 것과 박태보가 <서계초상> 제작에 따른 제반사를…","a":"박세당 필적 서계유묵","c":"보물","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616194.jpg"},{"q":"이 양수장은 삼례와 익산 지역의 상수원을 목적으로 건립하였다. 창호의 상부는 모두 평아치로 구성하였으며 주 출입구 포치(porch) 상부는 수평의 돌림띠 형태로 벽돌을 포개어 쌓았고 각 모서리는 기둥 모양으로 돌출시켜 마감하였다. 당시 치수 사업의 상황과 건설 기술 등을 잘 보여 준다.","a":"완주 구 삼례양수장","c":"국가등록문화유산","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668786.jpg"},{"q":"「○○○○○」은 정면11칸, 측면2칸의 누각형건물로서 현존하는 향교 ○○○ 중 가장 큰 규모임. ○○○은 조선 초기에 「남루(南樓)」라는 이름으로 11칸 장루(長樓) 형태의 독립건물로 존재하다가 17세기 초반에 누각을 수리하여 ○○○으로 사용하기 시작하였으며, 이후 소규모 수리를 거쳐 현재까지 유지되고 있음. ○○○○의 ○○○은 조선초기에 초창되어 17세기 이후 ○○○으로 전용한 사례로 향교 장루의 전통을 계승한 건축물임. 유사한 사례가 강원특별자치도 일부 향교에서 나타나고 있으나 ○○○○○은 그 가운데서도 규모가 크고 건축의 격식이 뛰어나 국가지정유산(보물)으로 지…","a":"강릉향교 명륜당","c":"보물","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122909001400.JPG"},{"q":"○○○○○는 해시계의 일종으로 검은 대리석으로 만들었으며 크기는 가로 58.9㎝, 세로 38.2㎝, 두께 16.3㎝이다. 원리는 그래프 용지에 1㎝ 간격으로 동심원과 10°간격의 방사선을 그어놓고, 그 중심에 막대를 세워 시각에 따른 그림자의 변화를 보는 형태로, 이것은 반구형을 한 해시계 앙부일구를 전개하여 평면에 옮겨 놓은 것과 똑같은 모양이다. 측면에 새겨져 있는 글을 통해 18세기 초에 제작된 것이고 구조와 평면에 그려진 시각선, 절기를 나타낸 선이 중국의 것과 같아 그것을 본 떠 관상감(觀象監)에서 새로 만든 것으로 추정된다. 서울대학교 박물관에는 이들 ○○…","a":"신법 지평일구(1985-2)","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614066.jpg"},{"q":"○○○○○은 ○○군 월항면 선석산 아래 태봉(胎峰) 정상에 있으며, 세종의 적서(嫡庶) 18왕자와 세손 단종의 ○○ 등 19기가 군집을 이루고 있다. ○○은 왕실에 왕자나 공주 등이 태어났을 때 그 태를 넣어두던 곳을 말한다. 전체 19기중 14기는 조성당시의 모습을 유지하고 있으나 세조의 왕위찬탈에 반대한 다섯 왕자의 ○○의 경우 방형의 연꽃잎이 새겨진 대석을 제외한 석물이 파괴되어 남아 있지 않으며, 세조 ○○의 경우에는 즉위한 이후 특별히 귀부를 마련하여 가봉비(加封碑)를 ○○비 앞에 세워두었다. 조선 세종 20년(1438)에서 24년(1442)사이에 조성된 것…","a":"성주 세종대왕자 태실","c":"사적","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627988.jpg"},{"q":"○○○ 강당 뒤쪽의 보호각에 보존되어 있는 ○○○으로, 「○○○사적기(佛國寺事蹟記)」에서 말하는 '광학부도(光學浮屠)'가 곧 이 ○○○을 가리킨다는 견해도 있지만 현재로서는 여래의 ○○○인지 승려의 ○○○인지는 분명하지 않다. 겉모습이 석등과 비슷하게 생긴 ○○○으로, 사리를 모시는 탑신(塔身)을 중심으로 아래는 받침이 되는 기단(基壇)을 두고, 위로는 머리장식을 두었다. 기단은 연꽃잎을 새긴 반원모양의 돌을 위 · 아래에 두고, 그 사이를 북(鼓)모양의 기둥으로 연결하고 있는데 기둥에 새겨진 구름무늬에서 강한 생동감이 묻어난다. 탑신(塔身)은 가운데가 불룩한 원통형…","a":"경주 불국사 사리탑","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620114.jpg"},{"q":"경기도 ○○시 진위면 ○○○에 있는 ○○○○○은 전형적인 고려시대의 불상양식을 나타내고 있다. 불상을 받치는 대좌(臺座)는 없고 불신만 남아 있는 상태이며 오른팔과 양 손은 새로 만들어 끼운 것이고 원래의 것은 절 안에 따로 보관되어 있다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며 정수리 부근에는 상투 모양의 머리(육계)가 큼직하게 있다. 갸름한 얼굴의 세부표현은 분명하고 목에는 3줄의 삼도가 뚜렷하게 표현되어 있다. 옷은 오른쪽 어깨를 드러내고 왼쪽어깨에만 걸치고 있으며 어깨는 거의 수평을 이루면서 넓은 편이다. 어깨 부분에서는 크게 접어 계단식의 주름을…","a":"평택 만기사 철조여래좌상","c":"보물","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615816.jpg"},{"q":"높이 0.98m의 철로 만든 불상으로 단호사 철불좌상(보물)과 같은 양식이며 더욱 엄격미가 강조된 점이 특징이다. 머리에는 날카롭고 뾰족한 소라 모양의 머리칼을 붙여 놓았으며 정수리에는 상투 모양의 머리(육계)가 있다. 삼각형에 가까운 얼굴, 길고 넓은 눈, 꽉 다문 입가로 내려오는 팔자형(八字形)의 주름 등에서 근엄한 인상을 보여주고 있다. 당당한 상체와 무릎을 넓게하고 앉은 자세 등 몸의 균형이 비교적 잘 잡혔지만, 팽팽하면서도 과장된 표현을 하고 있다. 양 어깨에 걸쳐 입은 옷은 좌우대칭을 지키면서 기하학적 옷주름선을 규칙적으로 표현하였으며 엄격성을 강조하고 있…","a":"충주 철조여래좌상","c":"보물","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617001.jpg"},{"q":"이 책은 30분의 불·보살의 이름을 나열하고 불경 이름을 빌려서 편집한 것으로, 이를 외우면 공덕이 생긴다고 한다. 나무에 새겨서 닥종이에 찍은 것으로, 병풍처럼 펼쳐서 볼 수 있는 형태로 되어 있으며, 크기는 세로 21.7㎝, 가로 8.8㎝이다. 책 끝에 있는 기록에 의하면, 고려 충숙왕 복위 8년(1339)에 조시우와 정공연 등이 시주하여, 남영신이 글을 쓰고, 혜일(慧一)이 새겨서 간행하였음을 알 수 있다. 이 책은 불·보살의 이름을 외울 것을 권장한 신앙 의식용으로, 당시 신앙경향의 한 면을 엿볼 수 있는 자료로 평가된다.","a":"삼십분공덕소경","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614351.jpg"},{"q":"○○○○○ 대웅전에 모셔져 있는 나무로 만든 삼세불좌상 중 아미타불을 제외한 석가모니불과 약사불, 그리고 일광·월광·관음·세지보살로 추정되는 네 보살입상이다. 중앙에 모셔져 있는 석가모니불은 본존불로서 삼불상 중 가장 크고 건장한 신체에 넓은 무릎을 하여 안정되어 보인다. 육계의 구분이 명확하지 않아 동그스럼해진 머리는 이마 위쪽과 머리 꼭대기에 중앙계주(계珠)와 정상계주가 표현되어 있으며, 둥글넓적한 얼굴에는 근엄한 듯 온화한 미소가 엿보인다. 옷은 양어깨를 모두 덮고 있는 통견(通肩)형식으로 오른팔이 드러나도록 함으로써 17세기 전반 경 이후 불상들에서 전형적으로…","a":"하동 쌍계사 목조석가여래삼불좌상 및 사보살입상","c":"보물","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622975.jpg"},{"q":"○○○○○은 조선 초기의 ○○○○ 병으로 높이 20.4㎝, 아가리 지름 5.2㎝, 밑지름 8㎝이다. 회색의 바탕흙 위에 백토로 분장을 하여 무늬를 그리고, 그 외의 배경을 긁어낸 뒤, 긁어낸 부분에 다시 철채를 입혀서 어두운 녹색의 배경과 흰 무늬와의 대조가 선명하게 잘 어울리고 있다. 무늬는 변형된 모란무늬이며, 격식에 얽매이지 않는 자유스럽고 활달한 감각을 엿볼 수 있다. 병의 목 주변에는 변형된 연판무늬를 둘렀다. 유약은 투명한 회청색이며 일부 연한 갈색을 띤 곳이 있다. 표면이 매끈하지 않아도 생김새와 도안 의장법에서 친근하고 구수한 멋을 나타내고 있다.","a":"분청사기 박지철채화문 병","c":"보물","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613248.jpg"},{"q":"○○○○○의 안채와 사랑채는 1922년 건립되었고, 행랑채는 1930년에 건립되어 역사가 그리 오래되지 않았으나 개화기 전통가옥 형식에 근대의 건축기법이 가미되는 당시의 시대상과 건축적 특징, 건축양식의 시대 변화를 잘 보여주고 있음","a":"익산 김병순 고택","c":"국가민속문화유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2019031514424500.JPG"},{"q":"향산 이만도(1842~1910년) 등 3대에 걸쳐 독립운동가를 배출하여 ‘삼대독립운동가문’으로 지정된 고택으로, 독립운동사의 지역적 상징성과 역사성을 간직하고 있다. 19세기 초중반에 지은 것으로 추정되는 튼口자형으로 안채와 사랑채의 채간 배치와 평면 및 입면 구성이 경북 북부지방에서 극히 드문 모습으로 고유한 건축적 희소가치가 있다. 집안 내력과 독립운동에 관한 3,000여점 이상의 전적류 및 유품 등의 유물도 잘 보전되고 있다.","a":"안동 향산고택","c":"국가민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635750.jpg"},{"q":"○○○는 신라 선덕여왕 8년(639) 회정선사가 세웠고 조선시대 세종 8년(1426)에 함허대사가 다시 지었는데, 건물 서쪽에서 맑은 물이 솟아나는 것을 보고 이름을 ○○○라 고쳤다고 한다. 이 ○○은 석가모니불상을 모신 대웅보전으로, 1957년 보수공사 때 숙종 15년(1689)에 수리하면서 적은 기록을 찾아냈다. 기록에 따르면 세종 5년(1423)에 새로 고쳐 지은 것이다. 규모는 앞면 3칸·옆면 4칸이지만 원래는 툇마루가 없이 앞면과 옆면이 3칸 건물이었던 것으로 추정한다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이고, 지붕 무게를 받치기 위해…","a":"강화 정수사 법당","c":"보물","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615343.jpg"},{"q":"○○○○○는 신라의 전형적인 평지 이탑식 가람배치(중문‧양탑‧금당‧강당‧회랑)를 기본구조로 하면서 ‘아(亞)’ 자형 건물지 등 독특한 유구가 확인되었으며, 통일신라 시대 전형적인 석탑 양식인 쌍탑에 모두 팔부중이 조각되어 있고 자기류, 전돌류, 토기, 목간, 금속유물, 지진구 등의 많은 유물이 출토되어 신라 사찰건축 등의 연구자료로서 역사적‧학술적 가치가 뛰어남.","a":"경주 인왕동 사지","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2016101309061400.jpg"},{"q":"공주시 ○○○릉에서 출토된 백제시대의 금 귀고리 한 쌍으로 길이는 8.3㎝이다. 왕의 널(관)안 머리 부근에서 발견되었으며, 호화로운 장식이 달려있다. 굵은 고리를 중심으로 2가닥의 장식을 길게 늘어뜨렸다. 하나는 속이 빈 원통형의 중간 장식 끝에 금판으로 된 커다란 나뭇잎 모양의 장식을 달았다. 이 장식은 무늬가 없어 간소하지만 앞·뒷면에 타원형의 작은 잎을 하나씩 붙여 변화를 주었다. 옆으로 보면 안이 굽은 모습을 하고 있다. 원통형의 중간 장식에는 금선과 금구슬을 이용해 장식한 마개가 있고, 서로 마주보게 나뭇잎 모양의 장식을 둘렀다. 다른 한 가닥은 여러 개의…","a":"무령왕 금귀걸이","c":"국보","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612276.jpg"},{"q":"○○○는 통일신라 후기에 창건된 것으로 추정되며 고려 명종 때인 12세기에 원각국사에 의해 중창이 있었던 것으로 추정된다. 고려 고종 때 안종필이 임금의 명을 받아 탑과 ○○, 그리고 금당을 새로 지었다. 절 이름을 국청사(國淸寺)라 하였다가 후에 다시 공민왕에 의해 ○○○로 불리게 되었다. ○○은 ○○○ 안에서 남쪽으로 약 200m 떨어진 언덕 위에 위치하고 있다. 기단부·탑신부·머리장식부로 나뉘어지며 전체적으로 8각의 모습을 이루고 있다. 기단의 아래받침돌은 바닥돌과 한 돌이고 가운데받침돌은 8각의 면마다 무늬를 조각하여 넣었다. 윗받침돌 옆면에는 한 겹의 연꽃잎…","a":"영동 영국사 승탑","c":"보물","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617060.jpg"},{"q":"춘양중학교 안에 동·서로 마주 서있는 2기의 탑으로 쌍탑형식을 띤다. 이 곳은 신라의 옛 사찰인 남화사(南華寺)의 옛터로 알려져 있는데, 신라 문무왕 16년(675)에 원효대사가 여기서 서북쪽으로 6㎞ 정도 떨어진 곳에 현재의 각화사를 창건하면서 이 절은 폐사되었다고 한다. 탑은 2단의 기단(基壇)위에 3층의 탑신(塔身)을 올린 모습으로 두 탑 모두 같은 양식이다. 기단은 아래·위층 모두 4면의 모서리와 가운데에 기둥 모양의 조각을 두었다. 탑신은 몸돌과 지붕돌이 각각 한 돌로 이루어져 있으며, 위층으로 갈수록 규모가 줄어들어 뚜렷한 체감률을 보인다. 각 층의 몸돌에…","a":"봉화 서동리 동·서 삼층석탑","c":"보물","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620038.jpg"},{"q":"지석묘란 고인돌이라고도 하는데, 크고 넓적한 바위를 큰 돌 몇 개로 괴어 놓은 선사시대 무덤을 가리킨다. ○○군 효산리 모산마을에서 월곡제, 춘양면 ○○○로 넘어가는 보성재 양쪽 계곡 지역에 청동기시대의 바둑판식(남방식) 고인돌 596기가 분포하고 있다. 조사 결과 고인돌, 돌방무덤(석실분), 독무덤(옹관묘), 돌널무덤(석관묘), 널무덤(토광묘)을 확인하였고, 석기류, 토기류, 청동기류 치레거리(장신구) 등 다양한 유물이 출토되었다. 특히 주변의 암벽에서 고인돌의 덮개돌을 떼었던 흔적이 남아 있어, 고인돌을 만들었던 과정을 알 수 있게 해준다. ○○○ 산 중턱에는 길…","a":"화순 효산리와 대신리 지석묘군","c":"사적","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627338.jpg"},{"q":"○○○○ 1동, 1층 규모로 건축면적 154.9㎡, 철로길이 좌·우 각각 150m이다. ○○○○은 당초 태릉역으로 불리다가 1958년 1월 1일 ○○○○으로 개칭된 경전선로의 역사로 1939년에 건립되었으며, 1939년 7월 4일 보통역으로 영업을 개시하였다. 구조는 목조로 지붕형태가 이어내림지붕구조를 가진 흔하지 않는 지붕임. 배치는 대합실, 사무실, 숙직실로 나누어져 있으며 대합실은 다른 역사처럼 박공부분에 배치하고 있다. 역은 현재 폐역되어 미 개방중이며, 소유자인 한국철도공사는 일반인들에 임대 예정인 것으로 알려져 있다.","a":"서울 구 화랑대역","c":"국가등록문화유산","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667101.jpg"},{"q":"전체적으로 8각의 평면을 기본으로 삼아 각 부분을 이루고 있으며, 3단으로 이루어진 기단(基壇) 위에 탑신(塔身)을 올리고 지붕돌을 얹은 형태이다. 네모진 바닥돌 위에 올려진 기단은 아래·가운데·윗받침돌로 나뉘어지는데, 아래받침돌 옆면에는 ○○를 새겨 놓았고, 윗면에는 구름을 입체적으로 조각하였다. 낮은 가운데받침돌은 모서리를 죽이고 각 면마다 악기를 연주하는 모습을 새겼다. 윗받침돌은 가운데 띠를 돌리고 아래·윗면에 소박하면서도 큼직한 연꽃을 조각하였다. 사리를 모셔놓은 탑신(塔身)은 낮은 편이며, 모서리에는 기둥 모양을 새기고 앞·뒷면에는 자물쇠가 달린 문짝 모양…","a":"대구 산격동 사자 주악장식 승탑","c":"보물","r":"대구광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615170.jpg"},{"q":"이흥사(利興寺)의 옛터에 남아있는 3층 석탑이다. 이흥사의 창건시기와 규모는 알 수 없으나 조선 후기인 18세기경까지 그 맥을 이어왔던 것으로 알려져 있다. 석탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습으로 꼭대기에는 머리장식을 받치던 받침돌만 남아있다. 탑신의 몸돌과 지붕돌은 각각 다른 돌로 조성되었으며, 지붕돌은 두텁고 낙수면은 경사가 급하다. 1995년 탑을 해체, 보수할 때 땅 속에 묻혀있던 아래층 기단이 지상으로 드러나면서 본래의 모습을 찾게 되었다. 고려 전기에 세워진 것으로 추정되는 이 탑은 기단에 새겨진 가운데기둥의 수가 아래층에 2개…","a":"영광 신천리 삼층석탑","c":"보물","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619207.jpg"},{"q":"석가가 영축산에서 제자들에게 설법하는 장면을 묘사한 ○○○○○이다. 크기는 길이 340㎝, 폭 254㎝이며 비단 위에 채색되었다. 중심에 본존불인 석가여래를 두고 좌우대칭으로 여러 보살과 무리들이 석가를 에워싸고 있다. 주로 녹색과 붉은색을 사용해 밝고 화려하며 옷에 칠해진 금빛이 매우 찬란하다. 이 그림은 다른 ○○○○○와 구별되는 몇 가지 특징이 있다. 첫째, 조선시대 불화에서 석가여래의 광배는 몸뒤의 신광과 머리의 두광을 함께 표현하는데 비해 이 그림은 신광만을 표현했다. 둘째, 부처님의 옷에 밭 전(田)자 무늬가 그려져 있지 않았고 셋째는 부처의 오른쪽 발목에…","a":"파계사 영산회상도","c":"보물","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615268.jpg"},{"q":"이 건물은 1935년에 경성부 공연장으로 건립된 공연시설 건물로, 1954년에 ○○○○○으로 사용되었다가, 현재 ○○시 의회 건물로 사용되고 있다. 정초석에는 건물 건립 당시 경성부윤이던 일본인 다테 시오(伊達四雄)가 쓴 것으로 확인되는 “定礎 昭和十年六月一日伊達四雄“ 기록이 남아 일본이 한국을 침탈했던 뼈아픈 역사를 증언하고 있다. 지하1층 지상3층의 철근콘크리트조 건물로서, 전면 일부를 탑식으로 높여 권위성·상징성을 강조한 것을 볼 수 있다.","a":"서울 구 국회의사당","c":"국가등록문화유산","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666879.jpg"},{"q":"○○○○는 사찰 입구에 세워두는 것으로, 절에서는 행사나 의식이 있을 때 당이라는 깃발을 달아두는데, 깃발을 걸어두는 길쭉한 장대를 당간이라 하며, 당간을 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. 미륵사터의 남쪽에는 2기의 지주가 약 90여 미터의 간격을 두고 서 있는데, 크기와 양식, 조성수법이 같아 같은 시기에 세워진 것으로 본다. 지주를 받치는 기단부(基壇部)는 완전히 파괴되어 대부분이 땅속에 묻혀있는 상태이며, 약간만이 드러나서 그 원모습을 짐작하게 한다. 지주는 원래 모습 그대로 보존되어 있는데, 마주보는 면에는 특별한 장식이 없다. 바깥쪽 면에는…","a":"익산 미륵사지 당간지주","c":"보물","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618245.jpg"},{"q":"세브란스병원에서 에비슨이 한국인 조수 박서양의 도움을 받아 수술하는 장면을 담은 ○○○○○으로 대한제국기 당시의 수술실, 수술도구, 수술인력, 수술복장 등을 보여주는 희귀한 사진의 원판○○이라는 점에서 사료적 가치가 크다. 에비슨(O. R. Avison, 1860-1956)은 캐나다 토론토 의대를 졸업한 북장로교 선교의사로 1893년 7월부터 제중원에서 진료를 시작하여, 제중원을 세브란스병원과 세브란스의학전문 학교로 확대 개편하는 등 우리나라에 근대서양의학이 도입·보급되는 데 중요한 기틀을 마련한 인물이다. ○○에서 에비슨에게 가위를 건네고 있는 박서양(朴瑞陽, 18…","a":"에비슨의 수술장면 유리건판 필름","c":"국가등록문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667303.jpg"},{"q":"「○○○○」는 조선시대 향교의 기능에 따른 건물과 배치구성, 지방행정체계에 대한 설위형식이 지역별로 시기적 변화양상이 있었음을 밝힐 중요한 건축사적 특성을 가진 건물임. ○○․○○는 건축 연혁이 명확하고 조선중기에 중창된 뒤 위치의 변경이 없으며, 대체적으로 당시의 구조양식 등 원형을 잘 간직하고 있음. 특히 정형화되고 엄격한 배치구성이 돋보이며, 문묘 다음으로 큰 규모이며, 경사 지형을 고려한 탁월한 입면구성을 갖추고 있음.","a":"상주향교 대성전‧동무‧서무","c":"보물","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122910360900.jpg"},{"q":"말을 올라 타거나 달릴 때 발로 디디는 ○○○ 부분을 등자라고 한다. 그 중에서 호등(壺鐙)이란 발 딛는 부분을 주머니처럼 넓게하여 쉽게 발을 넣거나 뺄 수 있게 한 것으로 삼국시대 둥근 테를 지닌 고리형의 윤등(輪鐙)에서 발전된 것이다. 이 호등은 높이 14.7㎝, 폭 12.1㎝, 길이 14.9㎝로 말 안장과 쉽게 연결할 수 있도록 사각형 모양으로 튀어 올라오게 하였고, 아랫부분에는 작은 구멍을 뚫었다. 등자의 표면에는 꽃과 사선·불꽃무늬·물고기 뼈 문양을 정교하게 새겼으며, 그 위에 검정색 ○○을 하였다. 통일신라시대 ○○○는 그 수량이 많지 않은데, 그 중 ○○…","a":"청동 옻칠 발걸이","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622062.jpg"},{"q":"1908.10.24. ○○○○○일에 황제 순종이 내린 ○○로, 가로 세로 11cm 크기의 [勅命之寶] 국새(國璽)가 찍혀있다. 선왕인 고종대 부터 추진한 일을 매듭지은 것임을 밝히고 백성들에게 의료의 혜택이 미치도록 하라는 황제의 뜻이 담긴 이 ○○는 ○○○○이 대한제국의 공식 기관임을 선포하는 가장 높은 수준의 공식 문서로서 의학사적·상징적 가치가 크다. 1906.1월 설치된 통감부는 기존 대한제국의 의료기관인 광제원, 의학교, 대한국적십자병원을 병합하기로 결정하고 관제 제정 및 병원 신축을 통해 1908년 ○○○○을 ○○하였으며, 이후 ○○○○은 한국 최고 수준의…","a":"대한의원 개원 칙서","c":"국가등록문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667308.jpg"},{"q":"○○○ 건칠아미타불좌상은 고려 말에서 조선 초기에 유행한 건칠기법으로 조성된 상으로, 체구가 장대하고 각 부의 비례가 균형감 있게 느껴진다. 상호(相好)는 원만하고 머리는 나발(螺髮)이며 정상계주(頂上髻珠)와 중앙계주(中央髻珠)가 있다. 어깨가 둥글고 가슴부분이 융기되어 있으며 측면 역시 두터워 풍부한 양감이 느껴진다. 착의형식이나 가사의 금구장식, 내의를 묶은 매듭의 표현 등 양식적으로 “장곡사 금동 약사여래좌상”(보물, 1346년 제작) 및 지금은 망실된 “문수사 금동여래좌상”(충남도유형문화유산, 1346년)과 같은 고려후기 14세기 전반 불상들과 공통된 양식적…","a":"남원 선국사 건칠아미타여래좌상 및 복장유물","c":"보물","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618712.jpg"},{"q":"송나라의 명신(名臣)들이 황제에게 올린, 시정(施政)에 관한 각종 표문(表文)과 전문(牋文) 중에서 뛰어난 것을 뽑아 편찬한 책으로, 편찬자는 미상이다. 1403년(태종 3) 주조된 조선 최초의 금속활자인 계미자(癸未字)로 간행한 것으로, ○○ 부분만 남아 있는 영본(零本)이다. 본서의 크기는 가로 19㎝, 세로 29㎝이며, 모두 12장으로 구성되었다. 본문의 제10~12장은 일부가 손상되었고, 책의 뒤표지도 결락되었다. 책의 앞뒤에 종이를 1장씩 첨가한 후 진한 황색포 표지를 새로 입히고 붉은 면으로 보강하였다. 계미자는 사용한 기간이 짧기 때문에 현재까지 전해지는…","a":"송조표전총류 권7","c":"국보","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611612.jpg"},{"q":"○○○는 고려 이전에 지어진 사찰로서, 임진왜란 이후 서산대사의 의발이 전수되면서 17~18세기 서산종의 종찰로 선·교 양종의 대도량역할을 한 사찰이며, 경내에는 국보 ‘○○○○○ 북미륵암 마애여래좌상’을 비롯하여 국가지정문화유산 12점과 시도지정문화유산 9점, 그리고 13대종사와 13대강사 등의 부도와 비석들이 소재한 역사적·학술적으로 중요한 유적지이다. 또한 한국의 다양한 불교신앙이 산사의 경내에 수용되었으며, 이는 역사적인 구조물과 전각, 유물, 문서 등에 잘 남아있다. 사찰 운영에서 나타나는 자립성과 승려교육, 한국 선불교의 특징인 영적 수행과 교리 학습의 공…","a":"해남 대흥사","c":"사적","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627462.jpg"},{"q":"가은선로는 가은 일대의 무연탄 개발을 위해 1950년대 건설된 철도이며, ○○○은 가은선로의 역사이다. 이 역은 1955년 4월 8일 준공되어 1956년 9월 15일 은성 보통역으로 영업을 개시하였고 1959년 2월 1일 ○○○으로 개칭하였다. 일제강점기의 간이역 형태와 같이 박공지붕 아래에 출입구를 배치하였으며 평면은 대합실 및 사무소와 매표소로 구성되어 있다. 해방 후에 건축된 목조역사로서 한때 번창했던 석탄산업과 관련된 역사로서 희소적인 가치를 가지고 있다.","a":"문경 구 가은역","c":"국가등록문화유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669143.jpg"},{"q":"1914년 건립 이 건물은 일제 강점기 당시 진해에 자리 잡은 일본 해군 기지인 ○○○○○로 건립되어 현재 대한민국 해군의 진해기지 ○○○로 사용되고 있다. 정면 중앙부에 2층 높이의 현관 포치(porch)가 돌출되어 있고, 그 위쪽에 사각 기둥 형태의 필라스터(pilaster)를 세우고 삼각형의 페디먼트(pediment)를 올려 정면성을 강조하였다. 1층 외벽에 화강석을 사용하여 전반적으로 안정된 느낌을 주며, 창의 상하 인방 및 좌우에 붉은 벽돌과 흰색의 화강석을 사용하여 화려하게 꾸몄다. 진해 지역이 일본의 해군 기지로 이용된 침략의 역사를 보여주고 있다. ※…","a":"구 진해요항부 사령부","c":"국가등록문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669392.jpg"},{"q":"○○○은 세종 때 만든 휴대용 화기로 길이 13.8㎝, 안지름 0.9㎝, 바깥지름 1.4㎝이다. 모양은 화약을 넣는 약실과 화기의 몸체인 총신 사이에 2개의 마디를 두고 약실 부분은 약간 도톰하게 만들었다. 총통 중에서 가장 작은 종류의 화기로, 세종 14년(1432)에 만들었으나 사정거리가 겨우 200보 밖에 되지 않아서 존폐론이 대두되기도 하였다. 그 뒤 1437년 평안도에 많이 보내졌는데, 휴대와 발사가 모두 간편하여 어린이와 부녀자도 쉽게 다룰 수 있었으므로 널리 사용하게 되었다. 또한 적과 싸울 때는 말 위에서 많이 소지하여 연속발사 할 수 있는 장점이 있었…","a":"세총통","c":"보물","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614111.jpg"},{"q":"○○은 영산강 지류인 삼포강을 중심으로 고대문화의 꽃을 피운 곳으로 자미산을 중심에 두고 약 40여기의 고분이 대안리, 신촌리, 덕산리 등지에 분포하고 있다. 일제강점기에 처음으로 발굴되어 세상에 알려진 이 ○○○에서는 다른 지역에서 찾아볼 수 없는 독특한 대형옹관과 함께 금동관, 금동신발, 봉황문 고리자루칼(환두대도) 등 최고 권력자의 위상을 보여주는 다양한 유물이 출토되었다. 옹관고분은 고구려의 적석총, 백제의 석실분, 신라의 적석목곽분, 가야의 석곽묘 등과 달리 영산강 유역에만 분포하던 독특한 묘제이다. 이른 시기의 옹관고분은 지면을 약간 파고 옹을 반쯤 안치한…","a":"나주 반남 고분군","c":"사적","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627472.jpg"},{"q":"회암사는 고려 충숙왕(1328)때 지공(指空)이 창건하여 조선 순조 때인 1800년대에 폐사된 사찰이다. 조선 전기 왕실의 보호를 받던 절로서 태조 이성계가 늙은 후에 머무르면서 수도하던 곳으로도 유명하다. 절터의 북쪽 능선 위에 지공(指空), 나옹(懶翁)의 승탑과 함께 서있는 이 탑은 무학대사(無學大師)의 묘탑이다. 둘레에는 탑을 보호하기 위한 난간이 둘러져 있다. 회암사의 주지이기도 했던 무학은 고려 말에서 조선 초에 활약한 승려로, 조선을 건국한 태조 이성계와의 관계로 더욱 알려지게 되었다. 이성계의 꿈을 풀이하여 왕이 될 것을 예언한 이야기와 한양천도와 관련된…","a":"양주 회암사지 무학대사탑","c":"보물","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615741.jpg"},{"q":"거대한 바위면에 홈을 약간 판 다음 불상을 도드라지게 새겼으며, 머리 위에는 8각의 머리돌을 끼워 넣어 얼굴을 보호하고 있다. 다소 딱딱해 보이지만 강한 의지가 느껴지는 얼굴에는 단정한 미소가 흐르고 있다. 몸은 건장하고 당당하지만 각이지고 평판적인 형태미를 보여주고 있어서 경직된 모습이 나타난다. 옷은 오른쪽 어깨를 드러내고 왼쪽 어깨에만 걸쳐 입고 있으며, 왼팔에 새겨진 옷주름에서는 기하학적인 추상성이 엿보인다. 손은 왼손을 배부분에 대고 오른손은 무릎 위에 가지런히 올려 놓고 있는 모습이고, 불상이 앉아 있는 대좌(臺座)에는 화사한 연꽃 무늬가 겹쳐서 새져져 있…","a":"서울 북한산 구기동 마애여래좌상","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613213.jpg"},{"q":"○○○ 안에서 멀리 떨어져 있는 잔디밭에 건립되었다. ○○○에는 동서 3층 석탑과 석등을 비롯하여 탑·석비 등 많은 석조 유물이 전하고 철조여래좌상이 있으며, 1967년에는 경내에서 통일신라 후기로 추정되는 동종이 발견된 일이 있었다. 탑은 일반적인 양식을 기본으로 하여 맨 아래 바닥돌에서 지붕까지 모두 8각을 이루고 있다. 아래받침돌에는 용틀임과 구름무늬가 아름답게 새겨져 있고, 가운데받침돌은 아무런 무늬를 새기지 않았다. 윗받침돌에는 연꽃 8잎이 위를 향해 피어 탑몸돌을 받치고, 각 모서리를 따라 꽃장식이 표현되어 있다. 탑몸돌은 한 면에만 문을 얕게 조각하고,…","a":"남원 실상사 승탑","c":"보물","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618179.jpg"},{"q":"본 건물은 지상 3층 석조.철근콘크리트조 고딕양식으로 우리나라 여성고등교육기관의 대표적 건물이다. 1935년 신촌에 새 교사를 신축하면서 본관으로 지어 현재에 이르고 있으며, 한국전쟁중 부분적 파손이 있었으나 원래 모습으로 복구하였다.","a":"서울 이화여자대학교 파이퍼 홀","c":"국가등록문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666886.jpg"},{"q":"이 책은 1470년(성종 원년) 4월에 세조의 왕비인 정희대왕대비가 발원하여 돌아가신 세조, 예종, 의경왕의 명복을 빌기 위해 간행한 ○○○○○ 7권 가운데 권 1～2 이다. 이 책은 권돈일, 고말종, 장막동, 우인수, 최금동, 이영산, 최덕산 등 당대의 일류 각수(刻手)들에 의해 이루어져 새김이 매우 정교하다. 우리나라에서 유통된 법화경은 대부분 계환의 해석이 붙어 있는 것을 사용하였는데, 이때 새긴 법화경은 천도의식용으로 사용하기 위해 원문만 새긴 것이다. 이와 같은 판본으로 기 지정되어 있는 <○○○○○ 권 제3~4, 5~7> 중 권7 말 김수온 발문에 간행동기…","a":"묘법연화경 권1~2","c":"보물","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618009.jpg"},{"q":"○○○○○는 경주 미추왕릉 앞에 있는 무덤들 중 C지구 제3호 무덤에서 출토된, 거북 모양의 몸을 하고 있는 높이 15.1㎝, 길이 17.5㎝, 밑지름 5.5㎝의 토기이다. 머리와 꼬리는 용 모양이고, 토기의 받침대 부분은 나팔형인데, 사각형으로 구멍을 뚫어 놓았다. 등뼈에는 2개의 뾰족한 뿔이 달려 있고, 몸체 부분에는 전후에 하나씩, 좌우에 2개씩의 장식을 길게 늘어뜨렸다. 머리는 S자형으로 높이 들고 있고 목덜미에는 등에서와 같은 뿔이 5개 붙어 있다. 눈은 크게 뜨고 아래·위의 입술이 밖으로 말려 있으며, 혀를 길게 내밀고 있다. 꼬리는 물결모양을 이루면서 T…","a":"도기 서수형 명기","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621318.jpg"},{"q":"민애왕(재위 838∼839)의 명복을 빌기 위해서 만든 ○○○○○ 삼층석탑(보물)과 동시에 만들어졌을 것으로 추정되는 높이 1.29m의 불상이다. 둥근 얼굴은 풍만하고 눈·코·입이 작아지고 있으며, 미소가 사라지고 단아한 모습이다. 8세기 불상에 비해 어깨는 뚜렷하게 좁아졌으며, 가슴은 평평하고, 하체의 처리도 역시 둔화되었다. 이러한 위축되고 둔화된 표현은 9세기 중엽에 나타나는 전형적인 불상양식이다. 손모양은 비로자나불이 일반적으로 취하고 있는 모습으로 왼손 검지를 오른손으로 감싼 형태이다. 옷은 양 어깨를 감싸고 있는데, 규칙적으로 얇은 평행의 옷주름선이 있고,…","a":"대구 동화사 비로암 석조비로자나불좌상","c":"보물","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615139.jpg"},{"q":"○○○○○은 경전을 읽으면서 죄를 참회하는 불교의식집을 말하며, 이를 수행하면 영험을 받을 수 있어 죄가 없어지고 복이 생긴다고 한다. 나아가 죽은 사람의 영혼을 구제하여 극락으로 인도함으로써 고통으로부터 벗어나려는 공덕 기원의 뜻을 담고 있다. 이 책은『○○○○○』이 후대로 내려오면서 착오가 생기고 잘못 전해지자 여러 고승들이 다시 바르게 교정한 것으로, 10권 가운데 권 제9와 10이다. 나무에 새겨 찍어낸 목판본으로 2권이 한 책으로 되어 있다. 세종 29년(1447)에 김구덕의 아들과 명빈 설월헌인(雪月軒人) 등이 태종, 원경왕후, 소헌왕후 그리고 부모의 명복…","a":"상교정본자비도량참법 권9~10(1997)","c":"보물","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619571.jpg"},{"q":"○○○○는 사찰 입구에 세워두는 것으로, 절에 행사가 있을 때 이 곳에 당이라는 깃발을 달아 두는데, 이 깃발을 걸어두는 길쭉한 장대를 당간이라 하고 당간의 양 쪽에 서서 이를 버티어 주는 두 돌기둥을 ○○○○라 한다. ○○시내에서 의암호를 따라 ○○역으로 돌아가는 도로 옆에 세워져 있는 이 ○○○○는 아무런 꾸밈새가 없는 간결한 형태이다. 마주 보고 있는 두 기둥 사이에는 2단으로 이루어진 당간의 받침돌이 놓여져 있는데, 아랫단은 둥근조각이 있고, 윗단은 16잎의 연꽃조각이 돌려져 있다. 기둥의 꼭대기는 반원형을 이루고 있고, 한 곳에만 깃대를 고정시켰던 홈의 흔적…","a":"춘천 근화동 당간지주","c":"보물","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616243.jpg"},{"q":"용담사는 백제 성왕 때 창건되었다고 전해지는 사찰로, 전설에 의하면 용담천 깊은 물에 이무기가 살면서 온갖 행패를 부리자 이를 막기위해 신라말 도선국사가 절을 창건하여 용담사라 이름을 지으니, 그 뒤로는 이무기의 나쁜 행동이 없어졌다고 한다. 전설을 뒷받침하듯 절 안의 대웅전은 북쪽을 향하여 용담천 쪽을 바라보고 있다. 불상과 광배(光背)를 하나의 돌에 매우 도드라지게 새긴 거구의 ○○○○○으로 높이가 6m에 이른다. 정수리에 있는 상투 모양의 머리(육계)가 높고 큼직하며, 얼굴은 바위의 손상으로 분명하지는 않으나 힘차고 박력있는 표정임을 알 수 있다. 목에는 형식적…","a":"남원 용담사지 석조여래입상","c":"보물","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618210.jpg"},{"q":"현재 ○○중학교 안에 있는 고려시대의 석불좌상이다. 대좌의 높이까지 포함하여 4m가 넘는 거대한 조각으로 불상 뒤의 광배(光背)가 없어지고, 불상의 얼굴과 오른손, 무릎 및 대좌(臺座) 일부가 없어진 상태이다. 얼굴은 몹시 닳고 머리에도 파손이 심하여 세부는 알 수 없는데 큼직하고 강건해 보인다. 이런 형태의 얼굴은 ○○ 덕전리 마애여래입상과 비슷하며 밝은 미소까지 흡사하다. 옷은 오른쪽 어깨를 드러내고 왼쪽 어깨에만 걸쳐 있으며, 신체는 건장한 편으로 당당한 모습이다. 몸을 가로지르는 옷주름은 평행을 이루고 있는데 조금은 형식적으로 처리되었다. 오른팔은 굵고 우람하…","a":"함양 교산리 석조여래좌상","c":"보물","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622564.jpg"},{"q":"19세기 중엽에 김정호가 제작한 것으로 추정되는 조선 전도(全圖)로, 필사본이다.『대동여지도』와 유사하게 23층의 절첩식(絶帖式)으로 제작되었다. 또, 전체적인 한반도의 윤곽, 산계(山界)와 수계(水界), 도로망 등 대부분의 내용이『대동여지도』와 일치하며, 범례에 해당하는 「지도표(地圖標)」도『대동여지도』와 흡사하다. 『○○○』는 필사본으로 목판본보다 세밀한 기록이 가능했기 때문에『대동여지도』에 비해 약 7천여 개의 지명이 더 수록되어 있다. 특히『대동여지도』에서는 누락되어 있는 방(坊)과 면(面)의 지명이 상세히 수록되어 있다. 지도 내용을 보면, 각 첩마다 도로를…","a":"동여도(2008)","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614780.jpg"},{"q":"○○ 시내에서 동북쪽으로 멀리 떨어진 구릉의 중간에 자리하고 있는 신라 제28대 ○○○○의 무덤이다. ○○○○은 선○○○의 뒤를 이은 신라의 2번째 여왕으로 본명은 승만이다. 진평왕의 동생인 국반갈문왕과 월명부인 사이에서 태어났으며, 신라의 마지막 성골 출신 왕이다. 7년간 왕으로 있는 동안 국력을 기르고 당나라와 적극적 외교를 통해 고구려와 백제를 견제하여 삼국통일의 기초를 닦았다. 무덤은 흙으로 덮은 둥근 모양이고, 아래부분에는 둘레돌을 배치하였다. 둘레돌 사이사이에는 기둥 역할을 하는 12개의 탱석을 끼워 넣었는데, 방향에 따라 12지신상을 새겼다. 그 위에는…","a":"경주 진덕여왕릉","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627572.jpg"},{"q":"○○○사지는 토함산 동쪽의 한 능선이 끝나는 기슭에 마련된 절터로서, 절의 이름을 정확히 알 수 없어 마을의 이름인 ‘○○○’를 따서 ○○○사지라 부르고 있다. 이 곳에는 현재 금당터를 중심으로 동탑과 서탑이 나란히 서 있는데, 1923년 도굴범에 의해 붕괴된 것을 1932년에 복원이 가능한 서탑만을 새로이 복원해 놓았다. 동탑은 1층 탑신(塔身)과 5층까지의 지붕돌만 남아있으나, 서탑은 약간 소실된 것을 빼고는 비교적 온전하게 보존되어 있다. 서탑은 2단의 기단(基壇) 위에 5층의 탑신(塔身)을 갖추고 있는 모습이다. 기단부는 비교적 넓게 만들어져 안정감이 있으며,…","a":"경주 장항리 서 오층석탑","c":"국보","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612902.jpg"},{"q":"조선시대 만들어진 ○○로 검은색 안료를 사용하여 줄무늬를 그려 놓은, 높이 31.4㎝, 아가리 지름 7㎝, 밑지름 10.6㎝인 술병이다. 아가리가 나팔처럼 밖으로 벌어지고 말려 있으며, 목은 잘록하고 가늘다. 몸통은 서서히 넓어져 아랫부분이 볼록한 형태를 하고 있다. 문양은 푸른색으로 먼저 목에 끈을 감고, 그 가닥이 밑으로 길게 늘어지다가 둥글게 말린 모습을 그렸다. 그 위에 검은색 안료을 유연한 필치로 농담을 섞어가면서 운치있게 표현하였다. 굽은 높고 넓으며 굽의 안쪽 바닥에는 한글이 새겨 있다. 조선시대 철화○○는 15세기 후반부터 만들어졌으나, 15∼16세기에…","a":"백자 철화끈무늬 병","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614429.jpg"},{"q":"신라의 여러 사적이 모여있는 곳을 보존하기 위해 하나의 단위로 정한 것이다. 동서는 안압지부터 교동까지, 남북은 월성남의 남천에서 고분공원 앞 첨성로가 있는 곳까지가 ○○○○○에 해당한다. 월성, 동궁과 월지, 첨성대, 계림 등이 각각 하나의 사적으로 지정 되어있으나, 이들 유적 사이사이에도 무수히 많은 지하유적과 유물이 계속 출토되고 있다. 따라서 신라 도성의 중심지역을 보존하기 위해서 사적지를 연결하여 확대 지정한 것이다. 동궁과 월지, ○○ 월성, 첨성대, 계림, 내물왕릉 등 외에도 수십기에 달하는 신라 무덤이 완전한 상태로 보존되어 있다.","a":"경주 동부 사적지대","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627749.jpg"},{"q":"○○○은 근대 모더니즘 양식의 원형 평면으로 구성된 교육시설로 건축가 이천승, 이영래가 설계하였다. 원형 평면의 중심에 나선형 계단을 두고 각 공간을 균등하게 6등분으로 구획하여 5개의 교실과 1개의 화장실과 계단실을 두고 있으며, 외곽에 발코니를 갖는 원통형으로 1950년대 국내에 건축된 몇 안 되는 원형교사로 건축사적 가치가 크다. 발견된 ○○○ 건립기념 동판에 의하면 총공사비 대부분을 학부형들이 부담하였고, 추월영 당시 교장의 증언(1997년 6월 졸업 40주년 행사장)에 의하면 특히 지역 유지였던 윤계성 선생이 거액을 기부함으로써 공사 중단 위기의 ○○○ 건축…","a":"부산 경남고등학교 덕형관","c":"국가등록문화유산","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667767.jpg"},{"q":"조선 중기 유학자이자 경세가인 ○○는 퇴계 이황의 학문을 더욱 발전시켜 중국의 성리학과 차별되는 조선 성리학의 토대를 닦은 인물로서 우리나라 정신사에 지대한 업적을 남긴 인물이다. 율곡 ○○를 배향한 자운서원, 율곡 ○○와 신사임당의 묘소를 포함한 가족묘역이 한 공간에 모여 있는 ‘○○○○○’은 율곡 ○○ 관련 유적을 대표하는 곳으로, 한 인물에서 근원한 문화유산이 모여 있는 장소성의 가치가 큰 곳이다.","a":"파주 이이 유적","c":"사적","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626063.jpg"},{"q":"○○ 손씨 큰 종가로 이 마을에서 시조가 된 양민공 손소(1433∼1484)가 조선 세조 5년(1459)에 지은 집이다. 양민공의 아들 손중돈 선생(1463~1529)과 외손인 이언적(1491∼1553) 선생이 태어난 곳이기도 하다. 一자형 대문채 안에 ㅁ자형 안채가 있고, 사랑채 뒷쪽 높은 곳에 신문(神門)과 사당이 있다. 안채는 지붕 옆면이 여덟 팔'(八)'자 모양인 팔작지붕이고, 사랑채는 지붕 옆면이 사람 인'(人)'자 모양인 맞배지붕이다. 사랑방과 침방이 대청을 사이에 두고 'ㄱ'자형으로 놓여 있는 사랑채 뒷편 정원에는 수백년 묵은 향나무가 있다. 대개 사랑방…","a":"경주 양동마을 송첨종택","c":"국가민속문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634770.jpg"},{"q":"<○○○○○>은 전체 10폭으로 구성되었으며, 8폭에 걸쳐 진하례 광경이 그려져 있고 좌우 양쪽 끝 폭에는 관원들의 좌목과 성명이 적혀 있다. 1874년(고종 11) ○○○가 태어난 것을 축하하기 위하여 그해 2월 14일에 창덕궁 인정전에서 거행한 진하례 의식 광경을 그린 궁중기록화이다. ○○의 그림에는 진하례가 열리고 있는 창덕궁 인정전을 중심에 배치하고 양쪽 옆으로 주변의 다른 건물들과 나무, 산봉우리 등을 그렸으며, 각 인물들과 건물 등이 모두 짙은 색채로 섬세하게 묘사되었다. 전체적으로 평행사선구도가 이용되었으며 진하례 광경은 부감법(俯瞰法)을 써서 표현하였다…","a":"왕세자탄강진하도 병풍","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614847.jpg"},{"q":"○○○은 ○○○의 중심 건물인 인정전의 정문이다. 효종·현종·숙종·영조 등 조선왕조의 여러 임금이 이곳에서 즉위식을 거행하고 왕위에 올랐다. 건물은 앞면 3칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥과 기둥 사이에도 있는 다포 양식으로 꾸몄다. 건물 안쪽 천장은 천장 재료가 훤히 보이는 연등천장이며, 단청은 가장 소박하게 꾸몄다. 왕위를 이어받는 의식이 거행되던 곳으로, 정전인 인정전과 함께 조선왕조 궁궐의 위엄과 격식을 가장 잘 간직하고 있는 건축물이다.","a":"창덕궁 인정문","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613984.jpg"},{"q":"절에 행사가 있을때 절의 입구에는 당(幢)이라는 깃발을 달아두는데 이 깃발을 달아두는 장대를 당간(幢竿)이라 하며, 장대를 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. 이 ○○○○는 ○○○ 입구에 1m 간격을 두고 마주 서 있다. 마주보는 안쪽 옆면과 바깥면에는 아무런 장식이 없고, 양쪽 모서리의 모를 둥글게 다듬었다. 기둥 윗부분은 원을 2겹으로 경사지게 조각하였고, 옆면 3줄의 세로줄이 새겨져 있다. 기둥머리에는 깃대를 단단하게 고정시키기 위한 네모 모양의 홈이 파여 있다. 기둥 사이에는 한 돌로 된 정사각형의 받침 위에 원형을 돌출시켜 깃대를 세우기 위한…","a":"영주 부석사 당간지주","c":"보물","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620691.jpg"},{"q":"국내에 남아있는 고려시대 종 가운데 가장 큰 종으로서 종의 높이 1.33m, 종의 구경은 입구 0.96m이다. 종 위에는 종의 고리 역할을 하는 용뉴가 여의주를 물고 있는 용의 모습으로 표현되었는데, 신라 종의 용보다 고개를 쳐 들어 올린 모습을 하고 있다. 용뉴 뒤에 붙은 음통은 대나무 모양이며, 편평한 부분인 천판 가장자리에는 연꽃무늬를 돌렸다. 몸체의 아래와 위에는 구슬무늬로 테두리를 한 너비 10㎝ 정도의 띠를 두르고, 꽃과 덩굴로 안을 채워 넣었다. 위에 두른 띠 바로 아래로는 4곳에 사각형의 연곽을 만들고 그 안에 가운데가 도드라진 9개의 연꽃(蓮蕾)을 새…","a":"성거산 천흥사명 동종","c":"국보","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611912.jpg"},{"q":"우리나라에 남아있는 가장 큰 종으로 상원사 동종(국보), 청주 운천동 출토 동종(보물)과 더불어 우리나라에 남아있는 완전한 형태의 통일신라시대 범종 3구 중 하나이다. 높이 3.66m, 입지름 2.27m, 두께 11∼25㎝이며, 무게는 1997년 국립경주박물관에서 정밀측정한 결과 18.9톤으로 확인되었다. 신라 경덕왕이 아버지인 성덕왕의 공덕을 널리 알리기 위해 종을 만들려 했으나 뜻을 이루지 못하고, 그 뒤를 이어 혜공왕이 771년에 완성하여 ○○○○○이라고 불렀다. 이 종은 처음에 봉덕사에 달았다고 해서 봉덕사종이라고도 하며, 아기를 시주하여 넣었다는 설화로 인해…","a":"성덕대왕신종","c":"국보","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612744.jpg"},{"q":"이 책은 조선 중종 33년(1538)에 김정국(1485∼1541)이 방대한 『○○○○』의 내용 가운데 필요한 부분만을 간추려 4권으로 편집한 것이다. 원래『○○○○』은 중국 명나라의 호광 등 42명의 학자들이 송나라 때의 성리학설에 원나라때 성리학자의 학설까지 편집해서 만든 것으로, 세종 초에 수입된 이후 우리나라 학자들 사이에 반드시 읽어야 할 책이었다. 중종 33년(1538)에 호남관찰사에 부임한 김정국은 도사 김회백과 의논하여 나주목에 있던 목활자에 부족한 글자와 빠진 글자를 새겨 작업을 실시하였다. 이 책은 조선시대에 학자들의 필독서인『○○○○』을 우리의 실정…","a":"성리대전서절요(1993)","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614634.jpg"},{"q":"이 건물은 1929년경 건립된 주거시설로, 일제 강점기 당시 ○○ 철도 국장이 거주한 관사로 알려져 있으며, 한때 군인 관사로도 사용되었다가 현재는 인근으로 옮겨져 조합사무실로 사용되고 있다. 일제 강점기에 우리나라 침탈을 위한 기반 시설인 철도관사로서 건립되면서, “昭和四年五月 定礎 渡辺”이란 기록이 새겨진 정초석이 남아 일본이 자행했던 한국 침탈의 뼈아픈 역사를 증언하고 있다. 2층 목조 건물로서 건축의 외관을 결정짓는 지붕 형태는 맞배지붕으로 하였으나 평면상 원형으로 돌출된 거실의 지붕은 원뿔형으로 마감하여 독특한 분위기를 연출하고 있어 주변에서 보통 뾰족집으로…","a":"대전 대흥동 일·양 절충식 가옥","c":"국가등록문화유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668000.jpg"},{"q":"○○○은 1동, 1층 규모로 건축면적 93.1㎡, 철로길이 좌·우 각각 150m이 국가등록문화유산으로 지정되었다. ○○○은 전라선로 역사로 1930년 12월 25일 일제강점기 남조선철도주식회사 영업개시와 동시에 건립되었다. 2010년 신풍-성산간 이설공사로 폐역되었다. 지붕형태는 모임지붕으로 대합실이 높고 역무실 등이 낮은 형태이다. 1930년대 초기 역사 형태를 볼 수 있는 국가유산이다.","a":"여수 구 율촌역","c":"국가등록문화유산","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669003.jpg"},{"q":"정영방이 광해군 5년(1613)에 벼슬을 버리고 낙향하여 은둔하였을 때 조성한 것으로 전해지는 조선시대 민가의 정원시설로 연못과 정자로 구성되어 있다. 자양산 남쪽의 완만한 기슭에 위치한 연못을 중심으로 경정과 주일재를 배치하고, 이들을 담장으로 둘러싼 후 담장 밖 북쪽에 수직사를 두었다. 경정은 넓은 대청과 방 2개로 되어있는 큰 정자이며, 주일재는 ‘운서헌’이라고 쓴 현판이 걸려있는 서재이다. 주일재 앞은 연못 쪽으로 내밀어 돌로 쌓은 단을 만들고 그곳에 소나무·대나무·매화·국화를 심어 ‘사우단’이라 이름 지었다. 연못은 사우단을 감싸는 'U'자형의 모양을 하고…","a":"영양 서석지","c":"국가민속문화유산","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635186.jpg"},{"q":"○○○○○은 경기도 광주군 동부면 하사창리의 절터에서 발견된 고려시대의 철불 좌상이다. 얼굴은 둥글지만 치켜 올라간 눈, 꼭 다문 작은 입, 날카로운 코의 표현에서 관념적으로 변해가는 고려시대 불상의 특징을 엿볼 수 있다. 목에는 3줄의 주름인 삼도(三道)가 뚜렷하게 표시되어 있으나 가슴까지 내려와 목의 한계를 명확히 구분짓지 않고 있다. 오른쪽 어깨를 드러내고 왼쪽 어깨만 감싸고 있는 옷에는 간결한 옷주름이 표현되었다. 당당한 어깨와 두드러진 가슴은 석굴암 본존불의 양식을 이어 받은 것이며, 날카로운 얼굴 인상과 간결한 옷주름의 표현은 고려 초기 불상의 전형적인 표…","a":"하남 하사창동 철조석가여래좌상","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613255.jpg"},{"q":"강화읍을 에워싸고 있는 고려시대의 산성이다. 몽골의 침입으로 백성과 국토가 수난을 당하자, 당시 실권자인 최우는 1232년 강화도로 수도를 옮겼다. 왕궁과 성·관아 시설은 1234년 본격적인 공사가 시작되었다. 이 때 개경의 궁궐과 비슷하게 지어 산의 이름도 송악이라 지었다. 성은 흙으로 쌓았고, 내성·중성·외성으로 이루어져 있고, 내성은 주위 약 1,200m로 지금의 강화성이다. 중성은 내성을 지키기 위해 쌓았으며, 외성은 1233년 강화 동쪽해안을 따라 쌓았다. 이 외성은 몽골군이 바다를 건너 공격하지 못하게 한 가장 중요한 방어시설이자, 정부가 39년간 육지로부…","a":"강화산성","c":"사적","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625209.jpg"},{"q":"「○○○○○」은 작은 공간에서도 초연대와 와룡연 그리고 주변에 조경수를 식재하여 정자로서의 많은 요소를 잘 간직하고 있음. ○○○은 기능에 부합되게 최적의 입지를 선정하고 안동권씨 집안의 특별한 관념적 의미를 부여하여 조성한 조경수법의 특이점과 탁월함이 돋보이며, 건축 공간의 위계에 따른 평면구성과 구조양식의 차별성과 다양성은 두드러진 특징으로 평가할 수 있음. 안동권씨 권벌에서 권래 3대에 걸친 창건 과정, 독특한 평면구성과 건축구조 등을 고려했을 때 역사적, 학술적, 예술적, 건축적 가치가 뛰어남.","a":"봉화 한수정","c":"보물","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019122715063300.JPG"},{"q":"○○○의 ○○는 배산구조와 안산, ○○ 배치와 진입로 구조가 시각적으로 뚜렷한 축을 형성하여 한양의 광화문-경복궁-백악산의 축과 매우 흡사한 시각 이미지를 형성하고 있는 곳이다. 현존하는 ○○ 건물인 기성관은 ○○○의 객사로 중심적 역할을 하던 곳으로 단청이 화려하고 웅대한 누의 모습을 보여주고 있으며, 비록 동헌 건물이 헐리고 그 자리에 면사무소가 들어서 있지만 부속 건물이었던 질청이 남아있고 당시 고지도 등의 관련 자료가 많아 당시 읍치 모습을 찾아 볼 수 있는 유적중의 하나이다. 따라서 거제 읍치의 ○○와 거리는 조선후기 읍치의 전형적 경관과 구조를 보여줄 뿐…","a":"거제현 관아","c":"사적","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628477.jpg"},{"q":"○○○○○은 줄여서 ‘지장경’, ‘지장○○○’이라고 부르기도 한다. ○○○○이 여러 가지 방법으로 중생을 교화하여 죄를 짓고 지옥에서 고통받는 중생들까지도 평등하게 구제하고자 하는 큰 뜻을 세운 경전이다. 이 책은 성종 5년(1474)에 정희대왕대비가 공혜왕후의 명복을 빌기 위하여 간행한 것을 성종 16년(1485)에 다시 찍어낸 것이다. 닥종이에 찍은 목판본으로 권 상·중·하로 나누어진 3권을 하나의 책으로 만들었는데, 크기는 세로 32.3㎝, 가로 21㎝이다. 권 상의 책 끝부분에는 보각(補刻:목판의 판면이 고르지 않거나 없어진 부분이 있을 때 다시 손질하여 인쇄…","a":"지장보살본원경(1991)","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614570.jpg"},{"q":"「○○○○○」은 통일신라시대부터 조선시대의 생활유구가 전 지역에 분포하고 있어 ○○시 고대도시의 성격을 파악할 수 있으며 서민생활상을 복원, 연구하는데 역사적 가치가 있는 매우 중요한 생활유적이다. ○○○○○지는 2004년 대한주택공사 등에서 택지개발하기 위하여 발굴조사를 실시한 결과, 통일신라시대부터 조선시대의 건물지, 연못, 수혈유구(竪穴遺構), 구상유구(溝狀遺構) 등과 도기류, 와·전류, 자기류 등 많은 유물이 출토되었다. 특히, 건물지와 우물 등 생활유구 들은 ○○읍성지의 동편 외곽에 거주한 서민들의 생활상을 알 수 있고, 구상유구는 옛 ○○읍성의 시가지 계획…","a":"상주 복룡동 유적","c":"사적","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628025.jpg"},{"q":"이 집은 ○○○ 이삼(李森)이 이인좌의 난(1728년)을 평정한 공로가 인정되어 영조 임금이 내린 하사금으로 지었다. 충남 출신의 ○○○ 선생은 범상치 않은 체력과 힘, 그리고 비범한 지략을 가지고 조선시대를 풍미했던 인물이다. 자연 경사지에 지은 집으로 동쪽을 바라보고 있는 대문채를 들어서면 조선시대 상류주택의 구성 요소인 안채와 사랑채가 ‘ㅁ’자형을 이루어 남쪽을 향하고 있다. 사당은 본채의 동쪽 위에 위치하고 있다. 이 가옥은 충청도 지역의 무인가문을 대표하는 이삼 장군의 서적, 고문서 등의 역사자료와 다양한 유물자료의 문화사적 특성이 명확하게 정리되어 전수되고…","a":"논산 백일헌 종택","c":"국가민속문화유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634452.jpg"},{"q":"○○○○○은 숙종 1년(1675년), 조선 중기의 문신인 팔송 윤황(八松 尹煌, 1571~1639)의 학문과 덕행을 추모하고 지방민의 유학 교육을 위하여 세운 서원이다. 숙종 8년(1682년)에 사액(賜額)을 받았고, 윤황을 비롯한 윤문거(尹文擧, 1606~1672), 윤선거(尹宣擧, 1610~1669), 윤증(尹拯. 1629~1711) 등 충청도 지역 소론계의 대표적인 인물들을 배향(配享, 신주를 모심)하고 있다. 1871년 흥선대원군의 서원철폐령에도 훼철(毁撤)되지 않고, 창건 이후 현재까지 350여 년 동안 한 자리를 지켜 온 유서 깊은 서원이며 특히, ○○○○…","a":"논산 노강서원","c":"사적","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2017091508263200.bmp"},{"q":"○○○○○는 전체 1권으로 구성되어 있으며 본문에 부분적으로 얼룩이 져 있으나 인쇄상태는 매우 양호하다. 책 표지의 우측에는 ‘○○○’ 라고 쓰여 있고 책의 좌측 중앙에 ‘양촌시(陽村集)’이라고 쓰여 있으며 우측 서뇌(書腦)에 ‘단구장(丹丘藏)’이라고 쓰여 있다. 이 책은 명태조(明太祖)가 양촌(陽村) ○○(1352∼1409)에게 친제(親製)하여 하사(下賜)한「태조고황제어제시삼수(太祖高皇帝御製詩三首)」와 명태조(明太祖)의 명(命)에 의해 지은 ○○○ 24수(首)를 모아 권람(權擥)이 주(註)를 붙여 세조(世祖)8년(年)(1462)에 목판본(木版本)으로 간행(刊行)한…","a":"권근 응제시주(1991)","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614529.jpg"},{"q":"낙안성의 동문과 서문을 잇는 큰 도로의 서쪽, 큰 길로부터 북쪽으로 들어가는 골목길에 위치한 초가집이다. 부엌 1칸, 방이 2칸인 아주 작은 집이다. 담장을 쌓다가 터 놓은 부분이 대문인데, 대문을 들어서면 제법 넓은 마당이 있고 마당 깊숙한 곳에 안채가 남향하여 자리잡고 있다. 부엌·큰방·작은방의 순으로 배열되어 있으며, 방 앞에는 툇마루가 있고 큰방 뒷쪽으로 작은 벽장이 있다. 작은방의 옆쪽으로는 'ㄱ'자로 꺾인 돌담을 쌓아 그 사이의 공간을 헛간으로 이용하고 있다. 부엌의 앞에는 우물이 설치되어 있고 넓은 마당의 한 곳을 채마밭과 텃밭으로 쓰고 있다. <b>※…","a":"순천 낙안읍성 대나무 서까래집","c":"국가민속문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634595.jpg"},{"q":"괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞뜰에 걸어놓고 예배를 드리는 대형 불교그림이다. ○○○ 괘불은 길이 659.5cm, 폭 398.3cm의 크기로, 구름을 이용하여 상·중·하 3단으로 구분되었다. ○○○○○은 상단에 비로자나불을 중심으로 노사나불, 석가모니불을 모셔 삼신불을 묘사하고, 그 아랫단에는 약사불과 아미타불, 그리고 상단의 석가모니불을 아울러 삼세불을 표현하였으며, 가장 하단에는 관음보살좌상과 지장보살좌상을 그려 수미산 정상의 도솔천궁을 표현하였다. 이러한 3단 배치는 예배자들에게 삼신불과 삼세불의 세계를 통해 진리를 깨우치게 하고, 관음보…","a":"칠장사 오불회 괘불탱","c":"국보","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612058.jpg"},{"q":"○○○ 안에 서있는 탑비로, 혜덕왕사를 기리기 위하여 세운 것이다. 혜덕은 고려 중기의 승려로서, 정종 4년(1038)에 태어나 11세에 불교의 교리를 배우기 시작하였고, 그 이듬해에 승려가 되었다. 1079년 ○○○의 주지가 되었으며 숙종이 불법(佛法)에 귀의하여 그를 법주(法主)로 삼자 왕에게 불교의 교리에 대한 강의를 하기도 하였다. 59세에 입적하였으며, 왕은 그를 국사로 대우하여 시호를 ‘혜덕’, 탑이름을 ‘진응’이라 내리었다. 현재 비의 머릿돌은 없어졌으며, 비문은 심하게 닳아 읽기가 매우 힘든 상태이다. 비의 받침돌에는 머리가 작고 몸통이 크게 표현된 거…","a":"김제 금산사 혜덕왕사탑비","c":"보물","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618113.jpg"},{"q":"조선 후기에 제작된 채색필사본 지도첩이다. 총 3책으로 구성되어 있으며, 제1책에는 세계지도, 중국지도, 북경과 한양도성도, 전도를 포함한 6장의 지도가 포함되어 있다. 제2책에는 정상기(鄭尙驥)의 『동국지도(東國地圖)』유형의 조선 도별도가 수록되어 있다. 또, 제3책에는 중국 각 성(省)의 지도 16장이 실려있는 등 일반적인 조선후기 지도책과는 내용 구성에서 차이가 있다. 제작 시기와 관련하여서는 수원에 사도세자의 무덤인 현릉원(顯陵園)이 표시되어 있으며 수원부의 치소가 이전 된 것으로 묘사되어 있고, 경기도 금천(衿川)이 시흥(始興)으로 바뀌기 이전의 지명으로 반…","a":"여지도","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614928.jpg"},{"q":"신복사의 옛 터에 남아있는 탑이다. 신복사는 통일신라 때 범일국사(梵日國師)가 창건한 절로, 창건과 관련된 설화가 전해지고 있다. 즉 신라의 한 처녀가 우물에 비친 햇빛을 보고 그 물을 마셨는데 곧 아이를 배어 낳게 되었다. 집안 사람들이 아이를 내다버렸으나, 아이의 주위로 빛이 맴돌아 괴이하게 여겨 다시 데려와 길렀는데, 그 이름을 범(梵)이라 하였다. 범이 출가하여 승려가 된 후 고향에 돌아와 신복사와 굴산사(掘山寺)를 창건하였다고 한다. 창건 이후의 기록은 알려지지 않고 있다. 이 탑은 2층의 기단(基壇)을 쌓고 3층의 탑신(塔身)을 올린 것으로, 각 부분의 모…","a":"강릉 신복사지 삼층석탑","c":"보물","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616355.jpg"},{"q":"ㅇ 충청북도 ○○군 소재 ○○○○○은 지방에 존재하는 가장 큰 규모의 한성백제 시기 토축 산성으로, 내성과 외성의 이중 구조로 된 남성·북성의 독특한 배치를 이루고 있으며 초기단계의 판축기법과 성토다짐이 사용되었고 한성백제 단계의 성문과 수문의 발전 양상을 보여주는 점, 다양한 출토 유물을 통해 당시의 국제정세를 파악할 수 있을 뿐만 아니라 성벽의 잔존상태가 양호하여 한성백제 산성의 특성, 축성기법 등에 관한 연구에 있어서 중요한 학술적 가치를 지님","a":"증평 추성산성","c":"사적","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626404.jpg"},{"q":"ㅇ 의정부는 조선시대 백관을 통솔하고 정무전반을 총괄하는 최고의 행정기관으로 그 위상에 맞추어 광화문 좌측 첫 번째 자리에 위치했음. 500년 동안 조선왕조의 최고 통치기구로서 그 역사성이 매우 높고, 학술조사를 통해 의정부의 주요 건물지 3동(정본당, 협선당, 석획당)과 근대건물지 등이 확인되어 원래의 장소적 가치도 확인 되는 등 역사적·학술적 가치가 뛰어남","a":"의정부지","c":"사적","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020092718184300.JPG"},{"q":"○○○은 이승만 초대 대통령이 거주하던 곳으로, 현재는 그의 유품을 소장하고 있다. 본체인 기와집과 부속 건물인 조각정으로 이루어져 있으며, 조각정은 1948년 당시 초대 내각을 구성하던 곳으로 ‘이승만 기념관’으로 사용하고 있다. 원래 이 일대는 조선 중종(재위 1506∼1544) 때의 학자 신광한의 옛 집터로, 신대(申臺)라고도 하여 많은 사람들이 찾던 명승지였다. 인조(재위 1623∼1649)의 셋째아들 인평대군이 살았던 곳이기도 하다. ○○○ 뒷문 개울가 바위에는 신대를 기념하기 위해 서화가 강세황이 쓴 ‘홍천취벽(紅泉翠壁)’이라는 글씨가 있었으나, 지금은 땅…","a":"서울 이화장","c":"사적","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625107.jpg"},{"q":"『노자』에 대한 주석서는 수없이 많지만 본문만큼이나 주석도 난해한 것이 대부분이다. 이에 비하여 임희일의『○○○○○』는 서명에서 밝히듯이 말로 설명하듯이 쉬운 구의체(口義體) 문장으로 분명하고 뚜렷하게 서술한 관계로 초학자들이 이해하기에 쉽다는 평을 받으면서 동양에서 널리 읽혀졌다. 이 『○○○○○』는 조선에서 계미자(癸未字)에 이어 2번째로 주조된 경자자(庚子字)로 찍은 판본으로 완전한 형태의 전존본(傳存本)이 드물다. 그럼에도 불구하고 이 『○○○○○』는 결장(缺張)이나 훼손된 부분이 없이 전권(全卷)이 온전하게 보존되어 있다. 경자자(庚子字)의 인본(印本)과 전…","a":"노자권재구의","c":"보물","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617402.jpg"},{"q":"이 책은 임진왜란(1592∼1598) 때에 ○○○이 친필로 작성한 일기로 연도별로 7권이다. ○○○은 28살되던 해에 무인 선발시험인 훈련원별과에 응시했으나, 불행하게도 달리던 말이 거꾸러지는 바람에 실격하였고, 4년 뒤 무과에 급제하여 권지훈련원봉사로 처음 벼슬을 시작했다. 사대부가의 전통인 충효와 문학에 있어서 뛰어났을 뿐 아니라 시(詩)를 짓는데도 특출하였다. 전라좌도 수군절도사를 지내던 때 곧 왜적의 침입이 있을 것에 대비하여 여수를 중심으로 배를 만들고 군비를 늘리는 등 일본의 침략에 대처하였다. 1592년 임진왜란이 터지자 옥포대첩, 거북선이 최초로 모습을…","a":"이순신 난중일기 및 서간첩 임진장초","c":"국보","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612255.jpg"},{"q":"○○○ 대웅전 앞에는 동서로 쌍탑이 서 있다. 그 중에 동쪽에 서 있는 것이 이 탑으로 크기는 서로 비슷하지만 서탑이 조각과 장식이 화려한 반면, 동탑은 아무런 장식없이 단정하다. 탑은 1단의 기단(基壇)위에 5층의 탑신(塔身)을 올린 형태로, 서탑의 기단이 2단인 것과는 조금 다른 모습이다. 기단의 각 면에는 모서리와 가운데에 기둥 모양을 조각하였다. 탑신부는 1층 몸돌이 높이에 비해 넓어 안정감이 있다. 또한 각 층 몸돌 너비의 줄어드는 정도에 비해 높이의 줄어드는 정도가 적어서 늘씬해 보인다. 지붕돌은 매우 평평하고 얇은데 몸돌을 따라 너비의 줄어드는 정도가 큰…","a":"구례 화엄사 동 오층석탑","c":"보물","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618774.jpg"},{"q":"○○○의 중심법당인 보광전 앞뜰에 동·서로 세워져 있는 두 탑이다. ○○○는 통일신라 흥덕왕 3년(828)에 홍척(洪陟)이 창건하였으며 풍수지리설에 의거하여, 이 곳에 절을 세우지 않으면 우리나라의 정기가 일본으로 건너간다 하여 지은 것이라 한다. 이 곳에는 3층 석탑 이외에도 석등, 묘탑, 탑비, 부도, 철조여래좌상 등이 있어 유명하다. 탑은 2층으로 된 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습으로, ○○ 두 탑 모두 탑의 머리장식이 거의 완전하게 보존되어 있는 희귀한 예이다. 탑신은 몸돌과 지붕돌이 각각 하나의 돌로 만들어져 통일신라시대의 정형을 보이며,…","a":"남원 실상사 동·서 삼층석탑","c":"보물","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618185.jpg"},{"q":"1930년 건립 이 건물은 대전전기주식회사에 소속된 발전소였으나, 2005년까지 한전 대전 ○○○ 창고 건물로 사용되다가, 현재는 전력연구원 연구시설로 사용되고 있다. 솟을지붕이 있어 환기와 채광 그리고 조형성을 함께 살리고 있으며, 2층 규모의 발전소 시설과 3층 규모의 업무 시설이 맞붙어 건립되었다. 내부 천장에는 발전 설비를 이동시킬 수 있도록 견고한 철제 빔을 설치하였고 건축적 완성도가 높은 건물이다.","a":"한국전력공사 대전보급소","c":"국가등록문화유산","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667953.jpg"},{"q":"○○○○○는 고려말 쇠퇴기에 접어든 청자에 그 기원을 두고 있는데, 조선 초에서 임진왜란 전까지 약 200년간 만들어진 자기류의 하나이다. 높이 9.4㎝, 입지름 35.8㎝, 밑지름 13㎝인 이 그릇의 가장자리 끝부분은 위쪽을 향하여 살짝 올라갔으며, 안쪽 바닥에는 이중으로 원을 돌렸는데, 그 안에 흰색의 꽃무늬를 상감기법으로 그려 넣었다. 3갈래의 가지가 바닥의 넓적한 부분을 자연스럽게 3부분으로 나누었고, 그 사이사이에 같은 방향으로 헤엄치는 물고기 한 마리씩을 상감하였다. 물고기의 윤곽과 비늘 등은 흰색으로 나타냈고, 눈 부분만 검게 나타냈다. 유약의 색깔은 청…","a":"분청사기 상감‘정통5년’명 어문 반형 묘지","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613515.jpg"},{"q":"석가가 영축산에서 설법하는 장면을 그린 ○○○○○으로, 괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞 뜰에 걸어놓고 예배를 드리는 대형 불교그림을 말한다. 괘불에서 많이 그려지는 ○○○상도는 석가가 설법하는 장면을 묘사한 그림이다. 길이 1321cm, 폭 917cm의 이 괘불은 석가를 중심으로 좌우에 문수·보현보살이 서 있고 뒷쪽에는 다보여래, 아미타여래, 관음보살, 세지보살이 있으며, 앉아 있는 2구의 작은 불상도 보인다. 석가는 머리끝에서 다섯 줄기의 빛이 나며 오른쪽 어깨가 드러난 우견편단의 옷을 걸치고 서 있는 모습이다. 각 상들의 얼굴 형태와 어깨는…","a":"개암사 영산회 괘불탱 및 초본","c":"보물","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618680.jpg"},{"q":"통일신라 후기부터 고려시대에 걸쳐 철로 만든 불상이 유행하게 되는데, ○○○○○은 안정감 있는 신체 비례와 양감 있는 체구 등에서 통일신라시대 불상양식을 계승하고 있는 고려 초기 불상 모습을 보여주고 있다. 머리 위에는 상투 모양의 머리(육계)가 있고 이마 위쪽으로는 고려시대 불상에서 자주 나타나는 반달 모양을 분명하게 표현하였다. 얼굴은 둥근 편으로 치켜올라간 눈썹, 긴 눈꼬리, 짧은 인중, 꼭 다문 입 등에서 근엄한 인상을 풍기고 있다. 오른쪽 어깨를 드러내고 왼쪽 어깨에만 걸쳐 입은 옷은 매우 얇게 표현하여 신체의 윤곽을 남김없이 드러낸다. 간략한 옷주름은 국립…","a":"영천 선원동 철조여래좌상","c":"보물","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621143.jpg"},{"q":"○○에서 불국사로 가는 길의 북쪽 구릉자락에 위치한 통일신라시대의 무덤이다. 무덤의 형태는 정사각형이고 흙을 덮어 만든 봉분 아래에는 무덤을 보호하는 의미를 갖는 12지신상이 조각된 둘레돌이 배치되어 있다. 둘레돌을 배치하는 것은 삼국시대 이후부터 내려오는 전통인데, 통일신라시대 ○○지방의 왕릉에서는 12지신상을 조각한 둘레돌을 흔히 볼 수 있다. 이 ○○○은 한변의 길이가 9.5m 높이가 2m이다. 무덤 내부에는 봉분의 남쪽으로 치우쳐 직사각형의 상자형으로 축조된 굴식돌방무덤(횡혈식석실분)이 있다. 시체를 모신 널방(현실)의 동쪽 벽에는 널길(연도)이 나 있다. 유…","a":"경주 구정동 방형분","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627585.jpg"},{"q":"○○○○○는 세조 3년(1457)에 내린 교지로, ○○○에 잡역을 면제할 것을 인정하는 사패교지(공로가 있는 자에게 나라에서 부역을 면해주는 것을 입증하는 문서)이다. 이 교지의 내용은 ‘일찍이 감사와 수령에게 지시한 대로 경상도 ○○○는 다시 심사하여 더욱 보호하고 잡역을 덜어 주라’는 것이다. 이 교지는 가로 66.0cm, 세로 44.7cm로 국왕의 수결(지금의 서명)이 있는 것으로 조선 전기 ○○○의 지위를 살필 수 있는 귀중한 자료로 평가된다.","a":"예천 용문사 감역교지","c":"보물","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621497.jpg"},{"q":"빛벌가야(지금의 ○○군)를 ○○ 영토로 편입한 ○○○이 이곳을 순시하면서 민심을 살핀 후 그 기념으로 세운 비이다. 당시 ○○군은 ○○가 서쪽으로 진출하는데 있어 마치 부채살의 꼭지와 같은 중요한 길목이었는데, ○○○ 16년(555) ○○에 병합되었고, 565년에는 대야주(지금의 합천군)와 합쳐져 비사벌군(比斯伐郡) 또는 비자화군(比自化郡)으로 불리워지게 되었다. 비는 목마산성 기슭에 있던 것을 1924년 지금의 자리로 옮겨 비각안에 모셔 둔 것으로, 자연석의 앞면을 평평하게 다듬어 비문을 새기고, 그 둘레에 선으로 윤곽을 돌려놓은 모습이다. 다른 순수비와 달리 ‘순…","a":"창녕 신라 진흥왕 척경비","c":"국보","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1613008.jpg"},{"q":"○○○○○은 1599년(선조 32) 전라좌수영 객사로 건립한 건물로서 임진왜란과 정유재란을 승리로 이끈 수군 중심기지로서의 역사성과 1718년(숙종 44) 전라좌수사 이제면(李濟冕)이 중창한 당시의 면모를 간직하고 있으며, 건물규모가 정면 15칸, 측면 5칸, 건물면적 240평으로 현존하는 지방관아 건물로서는 최대 규모이다. ○○○의 평면은 68개의 기둥으로 구성되었는데 동·서측 각각 2번째 협칸의 전면 내진주를 이주(移柱)하여 내진주 앞쪽에 고주(高柱)로 처리하였다. 이 고주는 곧바로 종보를 받치고 있고 대량은 맞보로 고주에 결구하여 그 위에 퇴보를 걸었다. 전후면…","a":"여수 진남관","c":"국보","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612571.jpg"},{"q":"○○○은 충청남도 예산군 덕산면 사량리에서 태어나, 덕산보통학교와 오치서숙에서 공부하였고 19세 때 고향에 야학을 세워 농촌계몽운동을 시작했다. 20세 때 각곡독서회를 조직하고 『농민독본』을 편찬했으며, 22세 때 월진회를 조직, 농촌운동을 정열적으로 전개하였다. ○○○○○는 국내에서 독립운동이 어려워지자 23세때 중국으로 망명하여 1931년 김구선생의 한인애국단에 가입하였다. 그 뒤 항일 투쟁을 계속하다가 1932년 4월 29일 혼자 일본의 상해사변 전승축하회가 열리던 상해의 홍구공원에 폭탄을 던져 일본군총사령관 시라가와 등 일본의 군수뇌부를 제거하는데 성공하였다.…","a":"윤봉길의사 유품(1972-1)","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617841.jpg"},{"q":"오랫동안 파묻혀 있었는데, 최근에 바닥을 파고 흩어진 부분을 정리하여 다시 세웠다. 높이 3.5m로, 아래받침돌에는 엎어놓은 연꽃 모양이 새겨졌고, 사잇기둥은 장고모양이며, 윗받침돌에는 솟은 연꽃모양을 새겼다. 불을 밝히는 곳인 화사석(火舍石)은 8각이며 창이 8면에 뚫렸다. 지붕돌은 아랫면에 낮고 널찍한 괴임이 있고, 8각의 끝부분에는 꽃모양을 둥글게 조각하였다. ○○의 창 사이 공간에는 통일신라 진성여왕 5년(891)에 만들었다는 글이 새겨져 있는데, 신라시대 ○○ 가운데 글씨를 새긴 유일한 예로, 비슷한 시대의 다른 작품의 연대와 특징을 연구하는데 있어서 표준이…","a":"담양 개선사지 석등","c":"보물","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618748.jpg"},{"q":"○○○ 마을의 산기슭에 있었던 탑으로, 일제시대에 일본인에 의하여 해외로 반출될 뻔 하였던 것을 간송미술관에 옮겨 세워 놓았다. 한국전쟁 때 탑이 무너져 각 부분이 흩어졌으나, 1964년 다시 세워 원래의 모습을 되찾게 된 것으로, 기단(基壇)과 탑신(塔身)의 각 부분이 8각으로 이루어진 일반적인 모습이다. 기단은 아래받침돌이 상·하 2돌인데, 아래에는 안상(眼象)을 새기고, 위에는 연꽃무늬를 돌린 후 8각마다 꽃조각을 돌출시켰다. 가운데받침돌은 아래에 구름모양을 돋을새김하였고, 그 위는 각 면이 위는 좁고 아래는 넓은 배흘림을 하고 있어 특이하다. 탑신은 몸돌이 가…","a":"괴산 외사리 승탑","c":"보물","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613516.jpg"},{"q":"○○○○는 ○○시 구정면 학산2리 윗골마을의 마을회관 일대에 있는 절터이다. ○○○는 신라 문성왕 13년(851)에 범일국사(梵日國師, 810∼889)가 창건한 사찰로, 우리나라 9산선문(九山禪門) 중의 하나인 사굴산문의 중심 사찰이었다. ○○○는 고려시대에 지방호족들의 지원하에 번성한 후 조선초 이후의 문헌에는 등장하지 않는 것으로 보아 조선초 이후에는 폐사된 것으로 추정된다. 현재 이곳에는 우리나라에서 가장 큰 ○○○○당간지주(보물), 범일국사의 것으로 추정되는 ○○○○승탑(보물), ○○○○○석불좌상(강원특별자치도 문화유산자료) 등이 남아 있어 ○○○ 당시의 규모…","a":"강릉 굴산사지","c":"사적","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626162.jpg"},{"q":"주합루와 영화당 구역을 감싸고 있는 작은 능선을 지나면 골짜기에 ○○○이 자리 잡고 있으며 주변 환경은 아름다운 숲과 연못 및 정자 등이 어우러져 이상적인 경관을 이루고 있다. 우측의 솟을 대문인 장양문은 사랑채로 통하고, 이 문을 지나 사랑마당에 들어서면 좌측에는 안마당과 사랑마당을 경계 짓는 담장이 꺾여 있으며 담장 가운데에 문인 정추문이 있다. 그리고 좌측의 평대문은 안채로 통하는 수인문이다. 사랑채와 안채가 담으로 구분되어 있기는 하나 한번 꺾여 하나로 연결되어 있고, 전체 공간구성은 서로 연결된 만(卍)자 형으로 구성되어 있다. ○○○이란 이름은 원래 사랑채…","a":"창덕궁 연경당","c":"보물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615033.jpg"},{"q":"○○○○○은 그 생김새가 탑비(塔碑)를 닮았다 하여 비상(碑像)이라 불리는데, 아래쪽의 대좌, 중앙의 사면석, 위쪽의 덮개돌이 모두 하나의 돌로 이루어져 있다. T자형을 이루고 있는 이 비상은 정면에 왼발을 내리고 오른발을 왼쪽 다리에 올린 반가상을 크게 새기고 있다. 오른손을 들어 뺨에 대고 생각하는 자세를 취하고 있는 반가상은 머리에 화려한 관(冠)을 쓰고 있으며 목걸이와 구슬장식을 갖추고 있다. 양 측면에는 두손에 보주를 들고 정면을 향하고 있는 보살입상이 새겨져 있는데, 반가상을 본존으로 삼아서 3존 형식을 의도한 것으로 보인다. 뒷면에는 보탑(寶塔)을 크게…","a":"미륵보살반가사유비상","c":"보물","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617015.jpg"},{"q":"○○○는 통일신라시대에 창건되어 화엄종을 널리 알리던 절로, 창건 이후 오늘에 이르기까지 많은 승려들이 이곳에 머물면서 ○○○상의 구현을 이루어 왔다. 신라 후기에는 승려 도선(道詵)에 의해 크게 확장되었고, 고려 문종 때에는 전라도 및 경상도에서 이 절에 매년 곡물을 바치도록 허락해 주어 일주문 밖에 큰 창고를 짓기도 하였다. 임진왜란 때 불타 없어진 것을 7년 만에 여러 건물들을 다시 세웠으며, 이후 여러 번의 보수를 거쳐 현재에 이르고 있다. 이 탑은 절 안의 ○○○○에 서 있는 통일신라시대의 독특한 석탑으로, 네 마리의 사자가 길쭉하고 네모난 돌을 이고 있는…","a":"구례 화엄사 원통전 앞 사자탑","c":"보물","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619008.jpg"},{"q":"이 불상은 머리만 없어졌을 뿐 불신(佛身), 대좌(臺座), 광배(光背)까지 고스란히 남아 있는 백제의 작품이다. 지금의 머리는 새로 만든 것이며, 불상의 현 신체 높이는 156㎝이다. 당당한 어깨, 균형잡힌 몸매, 넓은 하체 등에서 서툰 듯 하면서도 탄력적이고 우아한 면을 보여주고 있다. 양 어깨를 감싸고 있는 옷자락은 길게 내려져서 사각형의 대좌를 덮고 있는데, 앞자락은 U자형, 좌우로는 Ω형의 주름이 대칭으로 2단씩 표현되어 있다. 왼손은 엄지와 가운데 손가락을 구부려 가슴에 대고 오른손은 세번째와 네번째 손가락을 구부려 다리에 올려놓은 특이한 손모양을 하고 있다…","a":"익산 연동리 석조여래좌상","c":"보물","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618224.jpg"},{"q":"○○○○○는 경상북도 월성군 양북면의 ○○○에 모셔진 조선시대 건칠보살좌상이다. 건칠불이란 나무로 골격을 만든 뒤 삼베를 감고 그 위에 진흙을 바른 다음 속을 빼낸 불상을 말하는데, 우리나라에는 남아 있는 예가 매우 적어 이 불상의 가치가 더욱 크다. 타래머리 위에 보관(寶冠)을 따로 만들어 올렸으며 관 표면에는 덩쿨무늬가 화려하게 새겨져 있다. 얼굴은 둥글고 풍만하며 눈·코·입 등이 단아하게 묘사되어 보살상의 특징있는 얼굴을 만들어 내고 있다. 양 어깨에는 천의(天衣)를 걸치고 있으며, 목에는 3가닥의 장식이 달린 목걸이를 하고 있다. 가슴 부분에 있는 독특한 띠매…","a":"경주 기림사 건칠보살반가상","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620861.jpg"},{"q":"고려시대(12세기)의 조형적 특징을 보이는 표주박 형태의 ○○ 주자(注子)이다. 표주박 형태의 병에 참외같은 골 주름 여덟 줄을 깎아내고, 물대는 둥글고 넓은 박 잎을 대롱처럼 말아 붙여 만들고 손잡이는 박 넝쿨을 꼬아 붙인 것 같이 만들었다. 뚜껑 역시 작은 박 잎을 엎어 놓은 형태처럼 만들었으며 밑바닥도 굽을 별도로 깎아내지 않아 마치 표주박의 밑둥을 연상되는 모습으로 만들었다. ○○의 몸통과 물대, 손잡이는 서로 균형을 이루면서 안정감을 보이고 있어 세련미를 더한다. 이 주자는 12세기의 전형적인 비색 ○○ 중 하나로, 각각의 구성요소들이 이상적으로 조화된 ○○…","a":"청자 표주박모양 주전자","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614912.jpg"},{"q":"‘○○○○○’은 일본식 가옥에 서양의 주거 공간(응접실 등)이 절충된 형식으로 1936년 최초 건립된 이후, 한국전쟁 기간 중인 1952년에 소아과 전문병원으로 개원하여 1980년대까지 계속해서 사용되었던 곳으로 오늘날 지역민들의 기억 속에 당시의 흔적이 온전히 남아 있는 등 지역의 근대문화유산적 측면에서 가치가 높다.","a":"군산 구 십자의원","c":"국가등록문화유산","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019090513430800.jpg"},{"q":"「○○○○○」는 1686년(숙종 12년) 건립되고 1884년(고종 21년)과 1888년(고종 25년) 중수된 정자로, 자연암반으로 형성된 동굴에 위치하여 비정형적인 틈 사이에 건물이 끼워져 있음. 또한 상부로 휜 창방(기둥머리를 좌우로 연결하는 부재)의 사용, 방 내부의 연등천장 구성, 바위 틈새를 적절하게 출입구로 활용한 점, 진입의 과정에서 경험하는 어두움과 밝음의 극적 대비 등은 정형의 건물이 대부분을 차지하는 당시의 시대에 파격적으로 시도되었던 건축 형식을 보여줌. ○○○의 평면형태는 상·하층 모두 정면 2칸, 측면 1칸으로 규모도 비슷하지만 상하로 연속되는…","a":"진안 수선루","c":"보물","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019122715290500.JPG"},{"q":"<○○○○○>는 조선 선조 25년(1592) 4월 13일과 14일 이틀 동안 ○○○에서 벌어진 왜군과의 전투장면을 그린 것으로, 크기는 가로 96㎝, 세로 145㎝이다. 비단바탕에 그려진 이 그림은 숙종 35년(1709)에 처음 그려진 것을 화가 변박(卞璞)이 영조 36년(1760)에 다시 그린 것인데 처음 작품은 존재하지 않는다. 높은 곳에서 전투장면을 내려다 보듯 묘사하였는데, 그림 오른쪽 중간에 ○○○ 성곽이 배치되어 있고 그 주변을 왜병 및 왜선이 빈틈없이 에워싼 모습은 아군과 적군의 심한 전력의 격차를 보여준다. 그림의 작품성은 전반적으로 높게 평가되지는 않…","a":"부산진순절도","c":"보물","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613362.jpg"},{"q":"이 탑이 위치하고 있는 ○○○○는 통일신라시대 왕경 내에 형성된 도시가람으로 지리적 입지 상 중요한 역할을 수행한 사찰일 가능성이 높다. 이는 왕경의 중심적 위치에 자리하고 있고 문헌자료와 발굴된 유물로 확인이 되고 있는데 발굴조사과정을 통해 「味呑」명 기와가 수습됨으로써 『삼국유사』에 기록된 미탄사가 이곳임이 밝혀졌고, 추정 금당지 및 강당지를 비롯해 남문지 등 사역의 일단이 확인된 바 있다. ○○○○○은 6.12m의 규모로, 총 35매의 부재로 구성되어 있다. 1980년 이전까지는 도괴로 인하여 기단부와 탑신부의 일부 부재가 소실된 채로 방치되어 있었으나 1980…","a":"경주 미탄사지 삼층석탑","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2017011209530400.JPG"},{"q":"○○○ 전 대통령이 1958년 5월부터 1961년 8월 국가재건최고회의 의장 관사로 이주할 때까지 가족과 함께 생활했고 1979년 서거 후에는 유족들이 살았던 집으로, ○○○ 전 대통령이 5.16군사정변을 계획하고 지휘한 장소로서 한국 현대정치사에서 있어 중요한 역사의 현장이다.","a":"서울 신당동 박정희 가옥","c":"국가등록문화유산","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667202.jpg"},{"q":"고려시대 만들어진 ○○○○로 높이 9.3㎝, 아가리 지름 16.1㎝, 밑지름 6.1㎝ 이다. 바닥면 근처에서 거의 수평으로 퍼졌다가 다시 비스듬히 벌어져 올라간 넓적한 ○○로, 안바닥이 평평하며 두께가 얇아 청동제 ○○ 같이 날렵하게 생겼다. 아가리 끝의 여섯 군데에 조금씩 홈을 내어 여섯 잎의 꽃과 같은 모양을 하고 있다. 이것은 고려 초기의 특징적인 꽃무늬 ○○에서 퇴화된 것으로 생각된다. 그릇 내면에는 마치 비단에 무늬를 넣은 듯, 섬세하고 정교한 최상급의 양각문양들이 새겨있다. 편평한 바닥면에는 물 속에서 놀고 있는 3마리의 물고기 무늬가 있고, 측면에는 각각…","a":"청자 양각연지어문 화형 접시","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614386.jpg"},{"q":"<○○○○>은 조선 중기 문신인 ○○ 선생의 ○○화로, 오른쪽을 바라보며 의자에 앉아있는 가로 96㎝, 세로 165.8㎝ 크기의 전신○○화이다. ○○ 선생은 문인 서화가인 강세황의 아버지로, 대제학, 예조판서 등 여러 벼슬을 한 인물이다. 이 ○○화에서의 모습은 관리들이 쓰는 모자와 녹색 관복을 입고 있으며, 호랑이 가죽이 깔린 의자에 앉아 있다. 얼굴의 묘사는 눈, 코, 턱, 양볼 부분에 가는 선을 이용하여 음영을 넣었으며, 노인 특유의 붉은 기운이 잘 표현되었다. 옷주름은 음영이 들어있지 않은 선으로 몇 개의 주름만 나타내 인물의 기품을 보여주고 있다. 이 그림은…","a":"강현 초상","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613525.jpg"},{"q":"○○의 동쪽 명활산 꼭대기에 자연석을 이용하여 쌓은 둘레 약 6㎞의 신라 산성이다. 성을 쌓은 연대는 정확히 알 수 없으나, 『삼국사기』에 신라 실성왕 4년(405)에 왜병이 ○○○을 공격했다는 기록이 보이므로 그 이전에 만들어진 성임을 알 수 있다. 또한 성을 쌓는 방법에서도 다듬지 않은 돌을 사용한 신라 초의 방식을 보이고 있다. 눌지왕 15년(431)에는 왜구가 이 성을 포위하고 공격하였는데, 이는 이 성이 신라의 수도인 금성을 지키는데 중요한 곳임을 말해준다. 진흥왕 15년(554)에 다시 쌓았고, 진평왕 15년(593)에는 성을 확장했다. 지금은 대부분의 성…","a":"경주 명활성","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627661.jpg"},{"q":"○○○○○ 입구에 서있는 2기의 돌장승이다. 장승은 민간신앙의 한 형태로 마을이나 사찰 입구에 세워 경계를 표시함과 동시에 잡귀의 출입을 막는 수호신의 역할을 하는데 이 장승 역시 경내의 부정을 금하는 수문신상이다. ○○○는 통일신라시대에 창건된 사찰로 높은 산을 뒤로한 협곡에 자리잡고 있다. 절 앞 300m 되는 지점의 길 양쪽으로 마주보고 서있는 이 장승은 남·여의 모습으로 구별된다. 남장승은 선이 깊고 뚜렷하며 수염이 표시되었고, 머리 위에서는 상투를 올린 듯한 모습을 하고 있다. 입 가자장자리에는 송곳니가 아래로 뽀족하게 돌출되었고 몸체에는 ‘하원당장군(下元唐…","a":"나주 불회사 석장승","c":"국가민속문화유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634559.jpg"},{"q":"○○○○○은 풍산 유씨의 동족마을로 빼어난 자연경관과 민속·유교 전통을 잘 유지하고 있는 조선시대 양반촌이다. 이 집은 서애 유성룡(1542∼1607) 선생의 맏형인 겸암 유운룡(1539∼1601) 선생이 학문 연구와 제자를 가르치기 위해 세운 것이다. 조선 명종 22년(1567)에 지었다고 하며 부용대 서쪽 높은 절벽 위에 자리잡고 있다. 정사(사랑채)는 ○○○○이 바라다 보이는 남쪽 절벽 위편에 안채는 정사 뒤쪽에 배치하였다. 정사는 2층 누각 형식으로 앞면 4칸·옆면 2칸 크기이다. 가운데에 대청 4칸을 두고 좌우로는 방을 두었다. 방 앞쪽으로 좁은 퇴를 마련하…","a":"안동 하회마을 겸암정사","c":"국가민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635073.jpg"},{"q":"객사는 고려·조선시대에 각 고을에 설치하였던 것으로 관사 또는 객관이라고도 한다. 객사는 고려 전기부터 있었으며 외국 사신이 방문했을 때 객사에 묵으면서 연회도 가졌다. 조선시대에는 객사에 위패를 모시고, 초하루와 보름에 궁궐을 향해 예를 올리기도 하였으며 사신의 숙소로도 이용하였다. 명나라와 통하는 지방에는 우리 사신을 비롯해 명나라에서 오는 사신도 묵었기 때문에 건물보수에도 큰 어려움이 있었다고 한다. 국가에 일이 생겼을 때에는 백성과 관아가 같이 의식을 행하였다. ○○○○○은 ○○서고를 지은 뒤 남은 재료로 조선 성종 2년(1471)에 서의헌을 고쳐 지었다는 기…","a":"전주 풍패지관","c":"보물","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618384.jpg"},{"q":"탑이 세워져 있는 ○○군 지역은 삼국시대부터 신라의 영역에 속해 있던 곳이며, 진흥왕 때부터 신라의 정치·군사상의 요지가 되었다. 탑은 2단의 기단(基壇)에 3층의 탑신(塔身)을 올린 형태로, 통일신라 석탑의 일반적인 모습이다. 기단에는 위·아래층 모두 각면의 모서리와 가운데에 기둥 모양이 새겨져 있고, 탑신 역시 몸돌의 모서리마다 기둥모양을 한 조각이 있다. 지붕돌은 수평을 이루던 처마가 네 귀퉁이에서 살짝 치켜 올라가 간결한 모습이며, 밑면에는 5단의 받침을 두었다. 1965년 탑을 해체, 복원할 당시 3층 몸돌에서 뚜껑달린 청동잔형사리용기 등의 유물들이 발견되었…","a":"창녕 술정리 동 삼층석탑","c":"국보","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1613016.jpg"},{"q":"참법이란 경전을 읽으면서 죄를 참회하는 불교의식을 말하며, 서방 극락정토의 아미타불을 대상으로 삼는 것을 미타참법(彌陀懺法)이라고 한다. 이 책은 미타참법의 절차를 수록한 것으로 성종 5년(1474)에 세조비인 정희대왕대비가 성종비인 공혜왕후 한씨의 명복을 빌기 위해 간행한 것이다. 닥종이에 찍은 목판본으로 권6에서 권10까지를 1권의 책으로 엮었으며, 크기는 세로 33.4㎝, 가로 22㎝이다. 책 끝에 있는 김수온의 글을 통해 공혜왕후 한씨뿐만 아니라 선대왕과 왕비들의 명복도 함께 빌기 위해 간행했음을 알 수 있다. 또 여기에는 판각에 참여한 당시의 유명한 승려와…","a":"예념미타도량참법 권6~10(1992)","c":"보물","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616001.jpg"},{"q":"○○○○○은 대학의 상징적인 건축물로 석재와 열주 등을 활용하여 대칭성을 강조하고, 고전주의 건축에서 외관과 장식을 단순화, 간략화 하는 등 근대 모더니즘으로의 전환기적 모습을 잘 반영하고 있다.","a":"전북대학교 구 본관","c":"국가등록문화유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019120914002600.jpg"},{"q":"○○○○○는 모두 고려시대의 유물로 절에 관한 중요자료이다. 지정된 유물을 보면 첫째,수선사의 창건연혁과 관련된 형지기 1점, 둘째, 수선사에 소속되어 있는 노비를 기록한 노비문서 1점으로 총 2점이 있다. 고려시대에 묵으로 쓴 글씨가 남아있는 것은 매우 희귀한 예로, 오늘날까지 원래 모습대로 보존된 것은 매우 다행한 일이라고 할 수 있다. 이것들은 고려시대 문서의 양식과 필법 등을 연구하는데 매우 중요한 자료로 판단된다.","a":"순천 송광사 고려고문서","c":"보물","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619289.jpg"},{"q":"○○는 조선왕조의 왕과 왕비, 그리고 죽은 후 왕으로 추존된 왕과 왕비의 신위를 모시는 사당이다. ○○에는 본래의 건물인 정전과 별도의 사당인 영녕전을 비롯하여 여러 부속건물이 있다. 태조 3년(1394)에 한양으로 도읍을 옮기면서 짓기 시작하여 그 이듬해(태조 4년)에 완성되었다. 태조는 4대(목조, 익조, 도조, 환조)의 추존왕을 정전에 모셨으나, 세종 때 정종이 죽자 모셔둘 신실이 없어 중국 송나라 제도를 따라 세종 3년(1421) 영녕전을 세워 4대 추존왕의 신위를 옮겨 모셨다. 정전과 영녕전은 1592년 임진왜란 때 불에 탄 것을 1608년에 다시 지었다.…","a":"종묘","c":"사적","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624572.jpg"},{"q":"1928년 건립 이 건물은 ○○ 지역의 일본인 농장을 관리했던 관리인의 집이다. 중복도를 통해 각 실에 연결되는 전형적인 일식 ○○의 평면형식을 취하고 있으며, 3중 창호의 설치, 덧문의 잠금장치, 외부에 설치된 창호의 수납장 등 정교한 기법을 보여주고 있다. 일제 강점기 당시 이곳에 살았던 농장 관리인의 삶을 짐작하게 함과 동시에 일제에 의한 토지 수탈의 역사를 증언하고 있다.","a":"김제 신풍동 일본식 가옥","c":"국가등록문화유산","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668745.jpg"},{"q":"­미국 GM사가 1918년에 제작한 캐딜락 리무진으로 순종황제(純宗 1874~1926/재위기간 1907~1910)가 주로 탔던 것으로 알려진 자동차이다","a":"순종어차","c":"국가등록문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667109.jpg"},{"q":"조선 후기 경상도 지역 71개 군현의 지도가 수록되어 있는 지도첩으로, 채색필사본이다. 정확한 제작 시기는 명시되어 있지 않지만 지도 내용을 통해 유추해 볼 수 있다. 먼저 제4책에 수록된 안음(安陰)과 산음(山陰)은 1767년에 안의(安義)와 산청(山淸)으로 개칭되므로 이 지도책은 1767년 이전 상황을 반영하고 있다. 그리고 제5책「하동지도」에 표시된 읍치는 1745년(영조 21)에 이전된 곳으로 표시되어 있어 이 지도책이 1745년 이후의 상황에 기초하고 있음을 알 수 있다. 이상을 종합하면, 본 지도책은 영조 연간인 1745~1767년 사이에 제작된 것으로 추…","a":"영남지도","c":"보물","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614921.jpg"},{"q":"○○○○○은 현재 3대에 걸쳐 가업을 이어 전통 제조 기술을 그대로 유지하면서 전통주를 제조하고 있는 건물로 환기를 위해 높은 창을 두고, 보온을 위해 벽체와 천장에 왕겨를 채웠으며, 서까래 위에 산자대신 대자리형식으로 짠 것, 외벽의 일부에 흙벽돌을 사용한 것이 특징적이다. 일제 강점기 한식 목구조를 바탕으로 일식 목구조를 접합하여 대공간을 구성한 절충식 구조로 당시 탁주 생산 공장으로서 기능적 특성을 건축적으로 잘 보여주고 있다.","a":"양평 지평양조장","c":"국가등록문화유산","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2056684.jpg"},{"q":"고려시대부터 배를 만드는 조선소가 있던 자리이다. 특히 임진왜란 때 이순신 장군이 전쟁을 승리로 이끌게 한 거북선을 만들었던 곳으로 잘 알려져 있다. 지도상으로 보면 가막만의 가장 북쪽에 조선소가 있으며 조선소의 바다 입구에는 가덕도와 장도가 조선소의 방패 구실을 하고 있다. 또한 먼 바다에서 보면 육지처럼 보이고, 가까이 봐도 바다인지 호수인지 알아보기 어려워 중요한 해군 군사 방어 지역이었음을 알 수 있다. 현재 이곳에는 거북선을 만들고 수리했던 ‘굴강’, 칼과 창을 갈고 닦았던 ‘세검정’, 수군지휘소였던 ‘선소창’, 수군들이 머물렀던 ‘병영막사’, 거북선을 매어…","a":"여수 선소유적","c":"사적","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627221.jpg"},{"q":"조선시대 궁궐 중 가장 중심이 되는 왕조 제일의 법궁(法宮, 임금이 사는 궁궐)으로 태조 4년(1395)에 한양으로 수도를 옮긴 후 처음으로 세운 궁궐이다. 궁궐의 이름은 정도전이 『시경』에 나오는 “이미 술에 취하고 이미 덕에 배부르니 군자만년 그대의 큰 복을 도우리라”에서 큰 복을 빈다는 뜻의 ‘경복(景福)’이라는 두 글자를 따서 지은 것이다. 1412년 태종은 ○○○의 연못을 크게 넓히고 섬 위에 경회루를 만들었다. 이 곳에서 임금과 신하가 모여 잔치를 하거나 외국에서 오는 사신들에게 연회를 베풀었다. 태종의 뒤를 이은 세종은 주로 ○○○에서 지냈는데, 경회루…","a":"경복궁","c":"사적","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624462.jpg"},{"q":"조선시대 성리학자이며 문신이었던 회재 이언적(1491∼1553)선생 종가의 일부로 조선 중기에 세운 건물이다. 앞면 5칸·옆면 2칸 규모로 건물 내부를 세 부분으로 구분하여, 가운데 3칸은 대청이고 좌우 1칸씩은 온돌방이다. 대청은 앞면 기둥 사이를 개방하고 누마루에서도 대청을 향한 쪽은 개방되어 있으며, 뒤쪽과 옆면은 벽을 쳐서 문짝을 달았다. 평면은 ㄱ자형을 띠고 있고 둥근기둥과 네모기둥을 세워 방과 마루를 배치하고 있다. 이 건물의 기능은 상류주택에 속해있는 사랑채의 연장 건물로 손님접대, 쉼터, 책읽기를 즐기는 따위의 여러 용도로 쓰이던 곳이다. 소박하면서도…","a":"경주 양동 무첨당","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620795.jpg"},{"q":"○○○은 조선중기 17세기의 문인ㆍ명필로 본관은 여주(驪州), 자는 하경(夏卿), 호는 매산(梅山)ㆍ육우당(六寓堂)이다. 소릉(少陵) 이상의(李尙毅, 1560~1624)의 손자이며 이지안(李志安, 1601~1657)의 아들이다. 1666년 문과에 급제, 대사간ㆍ대사성ㆍ예문관제학ㆍ병조참판 등을 지냈다. 아들 옥동(玉洞) 이서(李漵, 1662~1723)는 학자ㆍ명필이었고, 이서의 이복동생 성호(星湖) 이익(李瀷, 1681~1763)은 실학자로 유명하다. 『○○○○○』은 ○○○ 후손 댁에 전래하는 것으로 표지에 “○○○○”이라 쓰고 오른쪽에 “공십(共十)”이라 쓰여 있어…","a":"이하진 필적 천금물전","c":"보물","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616193.jpg"},{"q":"○○○○○은 조선 후기 기호학파의 대표적인 학자인 동춘당 송준길(宋浚吉, 1606~1672)의 둘째 손자인 송병하(宋炳夏, 1646~1697)가 1674년 분가하여 건립한 ○○으로, 송병하의 아들 ○○○ 송요화(宋堯和, 1682~1764)가 1714년 옮겨 지었다. ○○○ 송요화의 부인 안동 김씨(1681~1722)는 조선후기 여류문학을 대표하는 시인으로서 호가 ○○○로 경서와 사서에도 능통하였다 하며 한시 134수를 남겼다. ○○은 조선 중기 ○○지역의 살림집을 이해할 수 있는 건축적 가치를 가지고 있으며, 충청지역에서는 보기 드물게 큰사랑채와 작은사랑채를 동시에…","a":"대전 소대헌·호연재 고택","c":"국가민속문화유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2016083021460100.bmp"},{"q":"보호각 밖에 있는 연화대석(蓮花臺石)과 석탑재(石塔材) 등과 함께 ○○시 남성동 용화전 안에 있던 것을 1982년 10월 남산공원(신봉동 산2-1번지)로 옮긴 후, 2007.06.20일자로 ○○박물관에 옮겨 보관하고 있다. 화강암질의 넓은 돌 2장에 높이 1.27m의 주악상(奏樂像)과 높이 1.23m의 공양상(供養像)을 도드라지게 조각하였다. 주악상은 왼쪽을 향하여 비파(琵琶)를 타고 있는 모습으로, 화관을 쓴 머리는 앞으로 숙이고 한 발을 앞으로 내밀어 유연한 자세를 취하고 있다. 연주하는 자태는 약간 미소를 머금은 단아한 표정이며, 비파를 타는 두 손의 표현은 섬…","a":"상주 석조천인상","c":"보물","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621359.jpg"},{"q":"송나라 진실(陳實)이 불교 경전인 『대장경』에서 중요한 내용을 뽑아서 엮은 것인데, 고려 초 13세기 중엽에 간행한 것이다. 이 책은 제1권 상·중·하 1책으로 구성된 영본(零本)인데, 내용을 보면 선왕품으로부터 번뇌품에 이르기까지 총 17품에 대하여 설명하고 있다. 판심 하단부에는 존식·정안 등의 각수 이름이 새겨져 있다. 판식에 있어서 송본의 형태를 유지하고 있으며, 12세기의 『능엄경』이나 『선문염송』 등과 같이 좁은 판심에 흑어미가 가늘게 이중으로 처리되어 있다. 서체도 송본과 13세기 중반에 유행한 고려본과 같은 형식이다. ○○○○○은 고려 초 13세기 중엽…","a":"대장일람집","c":"보물","r":"대구광역시","s":"달서구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615286.jpg"},{"q":"○○은 민간신앙에서 신이 있다고 믿고 섬겨지는 대상물이다. ○○○○○은 높은 돌기둥과 돌장승이 각각 1쌍으로 이루어져 있다. 돌기둥은 마을 밖의 부정한 것에 대한 침입을 막고 마을의 평안함을 위해 세운 솟대의 일종이다. 이 돌기둥은 각각 할아버지당과 할머니당으로, 할아버지 ○○은 ○○○○○의 주신으로서 꼭대기에는 돌로 조각된 새가 얹혀 있다. 할머니 ○○은 새를 따로 얹지 않고 돌기둥 윗부분에 새겨서 표현한 특징을 보인다. 돌장승 역시 남녀 한 쌍이다. 할아버지로 불리는 상원주장군(上元周將軍)은 탕건(모자의 일종)을 쓰고 수염이 있다. 할머니는 할아버지보다 조금 작은…","a":"부안 서문안 당산","c":"국가민속문화유산","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634477.jpg"},{"q":"○○○○ <○○○○>는 중국 송대(宋代) 구양수(歐陽修, 1007∼1072)가 지은 ‘추성부(秋聲賦)’를 단원 ○○○가 그림으로 그려낸 시의도(詩意圖)이다. 화면의 왼쪽에는 백문타원인(白文楕圓印)으로 기우유자(騎牛游子)라 찍혀 있으며 추성부 전문이 ○○○의 자필로 쓰여져 있는데, 끝 부분에 ‘을축년동지후삼일(乙丑年冬至後三日) 단구사(丹邱寫)’라 하였으므로 이 그림은 1805년 즉, 단원의 나이 61세에 제작된 것임을 알 수 있다. 그런데 이 해는 단원이 죽기 바로 전 해로 추정되므로 그의 마지막 기년작이자 죽음을 앞두고 그린 작품으로 믿어진다. 화면의 오른쪽에는 메마…","a":"김홍도 필 추성부도","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614794.jpg"},{"q":"1929년 건립한 이 건물은 ○○○ 교인 및 지부의 업무를 총괄 집행하는 곳이다. 일제 강점기 말기에는 공립학교 교실로, 광복 후에는 태극지하종교연합회 사무실로, 한국전쟁 당시에는 인민군 여단사령부로 사용되었다. 중앙 1칸의 한옥 지붕을 가진 현관과 상·중·하인방이 뚜렷이 구분되는 벽면이 특징적이며, 수막새에는 ‘수(水)’자를 형상화하여 조각하였고, 암막새에는 ○○○를 상징하는 ‘궁을도형(弓乙圖形)’ 무늬가 새겨져 있다.","a":"대전 수운교 본부사무실","c":"국가등록문화유산","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667987.jpg"},{"q":"누에치기를 처음 했다는 중국 고대 황제의 황비 서릉씨를 누에신(잠신蠶神)으로 모시고 제사를 지내던 곳이다. 이 단은 고려 성종 2년(983)에 처음 쌓은 것으로, 단의 앞쪽 끝에 뽕나무를 심고 궁중의 잠실(蠶室)에서 누에를 키우게 하였다. 세종대왕은 누에를 키우는 일을 크게 장려했는데, 각 도마다 좋은 장소를 골라 뽕나무를 심도록 하였으며, 한 곳 이상의 잠실을 지어 누에를 키우도록 하였다. 그러다가 중종 원년(1506)에는 여러 도에 있는 잠실을 ○○ 근처로 모이도록 하였는데 지금의 강남 잠실이 바로 옛 잠실들이 모여 있던 곳이다. ○○○의 설치 이후 매년 3월에…","a":"서울 선잠단지","c":"사적","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624459.jpg"},{"q":"○○○는 신라 선덕여왕 12년(643) 인도의 스님 광유가 세워 임정사라 불렀고, 그 뒤 원효대사가 새롭게 고쳐 지어 ○○○로 이름을 바꾸었다고 한다. 이 절은 천년에 한번 핀다는 한약초 ‘우담바라’가 있었다는 전설이 있기도 한 곳이다. ○○○○은 지혜의 빛으로 세상을 비춘다는 비로자나불을 모셔 놓은 법당을 가리킨다. 선덕여왕 때 세워진 후 여러 차례에 걸쳐 수리한 것으로 지금 건물은 조선 인조 7년(1629)에 크게 고쳤을 때의 것으로 보인다. 규모는 앞면 5칸·옆면 3칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 지붕 처마를 받치기 위해…","a":"경주 기림사 대적광전","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621548.jpg"},{"q":"조선 19대 숙종의 후궁이자 21대 영조의 생모(사친)인 숙빈 최씨(1670~1718)의 원이다. 숙빈은 최효원의 딸로 7세에 궁녀로 입궁하여, 1693년(숙종 19) 숙종의 후궁이 되고 이듬해에 연잉군(영조)을 낳았다. 1699년(숙종 25) 숙빈에 봉해진 후, 1718년(숙종 44) 49세로 세상을 떠났다. 숙빈 최씨가 세상을 떠난 후 영조는 묘소 근처에 시묘막을 지어 어머니의 죽음을 애도하였다. 이후 영조는 왕위에 오른 후 묘소 입구에 신도비를 세웠으며, 1744년(영조 20) 사당의 이름을 육상묘, 묘의 이름을 소령묘라 하였다. 이후 1753년(영조 29) 왕…","a":"파주 소령원","c":"사적","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020081316591500.jpg"},{"q":"○○○ 대웅전과 팔상전 사이에 있는 통일신라시대의 ○○으로, 사자를 조각한 석조물 가운데 가장 오래되었으며 매우 독특한 형태를 하고 있다. 넓다란 8각의 바닥돌 위에 올려진 사자 조각은 두 마리가 서로 가슴을 맞대고 뒷발로 아래돌을 디디고 서서 앞발과 주둥이로는 윗돌을 받치고 있는 모습이다. 아랫돌과 윗돌에는 각각 연꽃을 새겨 두었는데, 윗돌에 두 줄로 돌려진 연꽃무늬는 옛스러운 멋을 풍기며, 현재 남아있는 사자조각들 가운데 가장 뛰어나 머리의 갈기, 다리와 몸의 근육까지도 사실적으로 표현하였다. 불을 밝혀두는 화사석(火舍石)은 8각으로 높직하며, 네 곳에 창을 내어…","a":"보은 법주사 쌍사자 석등","c":"국보","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612140.jpg"},{"q":"극락보전 후불벽 앞면에 그려져 있는 아미타삼존불벽화이다. 앉은 모습의 아미타불을 중심으로 왼쪽에 관음보살이, 오른쪽에는 지장보살이 서 있는 구도를 하고 있다. 화면의 맨 위부분에는 구름을 배경으로 좌우에 각각 3인씩 6인의 나한상을 배치하고 그 위에는 작은 화불이 2구씩이 그려져 있다. 아미타극락회도 장면을 그린 이 벽화는 앞에 모셔진 아미타삼존불상과 매우 비슷한 모습을 하고 있다. 중앙의 본존불은 비교적 높은 연꽃대좌 위에 결가부좌한 모습으로 양어깨를 모두 감싼 옷을 입고 있으며 뒤로는 키모양의 광배가 표현되었다. 왼쪽에 서있는 관음보살은 머리칼이 어깨 위에 흘러내…","a":"강진 무위사 극락전 아미타여래삼존벽화","c":"국보","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612602.jpg"},{"q":"신라 경문왕 7년(862) 도의선사가 창건한 ○○○에 모셔져 있는 이 삼불좌상은 본존불인 석가불을 중앙에 안치하고, 오른쪽에는 아미타불, 왼쪽에 약사불을 배치하고 있다. 무량사 소조아미타불상(5.4m)과 함께 가장 거대한 소조불상(5m)으로, 신체 각 부분이 비교적 조화를 잘 이루고 있는 작품이다. 장중하고 원만한 얼굴과 두껍게 처리한 옷은 당당한 불상양식에 걸맞는 표현기법을 보여준다. 작은 소라 모양의 머리칼 표현은 강한 인상을 나타내고 있는데 이는 조선 후기 양식이 나타나기 시작한 시대적 특징을 보여주는 것이다. 본존불에서는 삼불의 조성기와『묘법연화경』을 비롯한…","a":"완주 송광사 소조석가여래삼불좌상 및 복장유물","c":"보물","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618685.jpg"},{"q":"원래 부석사 동쪽 산 너머 절터에 있었던 것을 옮겨온 것으로서 양식상 동일한 조각가에 의하여 만들어진 것으로 추정된다. 동쪽의 여래상은 얼굴이 타원형이며, 약간의 미소를 머금은 흔적이 있다. 두 손은 없어졌으나 두 팔이 가슴쪽으로 올라가 있어 왼손 검지를 오른손으로 감싸 쥔 손모양을 취하고 있는 비로자나불의 모습을 형상화한 것으로 보인다. 양 어깨를 감싸고 있는 옷에는 당시 유행하던 얇게 빚은 듯한 촘촘한 평행의 옷주름이 표현되었다. 대좌(臺座)의 가운데 부분은 8각인데 각 면에는 공양보살상을 조각하였다. 서쪽의 여래상은 동쪽의 여래상보다 좀 더 당당하며 불신의 선들…","a":"영주 북지리 석조여래좌상(1963-2)","c":"보물","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020031017475400.jpg"},{"q":"○○○○○은 줄여서 ‘○○○○○’, ‘○○○’이라고 부르기도 하는데 부모의 소중한 은혜에 대한 부처님의 가르침을 얘기한 경전이다. ○○○은 구마라습이 번역한 것이며, 이 책은 고려 우왕 4년(1378)에 예문관대제학 한천(韓蕆)의 시주로 간행한 것이다. 닥종이에 찍은 목판본으로 병풍처럼 펼쳐서 볼 수 있는 형태이며, 접었을 때의 크기는 세로 29㎝, 가로 11.3㎝이다. 일반적인 ○○○과 같이 부모의 10가지 소중한 은혜를 글과 그림으로 함께 나타내고 있으며, 책 뒤에는 불설○○○○태골경이 함께 들어있다. 이 책은 오래된 귀중본일 뿐만 아니라 여러 종의 그림이 정교하…","a":"불설대보부모은중경(1981)","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613698.jpg"},{"q":"<○○○○○>은 조선의 문신이며 학자였던 ○○○의 상반신을 그린 ○○화로 가로 62.5㎝, 세로 134㎝ 크기이다. ○○○은 중종 38년(1543) 우리나라 최초의 서원인 백운동서원(후의 소수서원)을 세워 학문진흥에 힘썼다. 이 ○○화는 사모관대의 정장 관복을 차려입고 왼쪽을 바라보고 있는 모습을 그렸다. 얼굴은 간략한 선으로 묘사하고, 넉넉한 몸체에 목은 거의 표현하지 않아 권위적인 기품이 엿보인다. 옷의 깃을 낮게 표현한 것은 다른 ○○화에도 나타나는 것으로 당시 유행하던 양식으로 생각된다. 이 그림의 정확한 제작연대를 추정하기 힘들지만 색이 바라고, 훼손된 상태…","a":"주세붕 초상","c":"보물","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621496.jpg"},{"q":"○○○은 ○○○에 속한 암자로 신라말에 지은 것으로 전한다. 조선 명종 1년(1546) 인종의 태실(胎室)을 팔공산에 모시게 되자 ○○○을 수호사찰로 정하고 크게 고쳤다고 한다. 극락세계를 상징하는 아미타삼존불을 모시고 있는 ○○○은 인조 21년(1643)에 지은 것으로 지금 있는 건물은 그 뒤로 여러 차례 수리한 것이다. 규모는 앞면 3칸·옆면 3칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 기둥 위부분에 장식하여 짜은 구조가 기둥 위뿐만 아니라 기둥 사이에도 있다. 이를 다포 양식이라 하는데 재료의 형태와 짜임이…","a":"영천 은해사 백흥암 극락전","c":"보물","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621521.jpg"},{"q":"「○○○○○」은 육각형 평면에 마루, 온돌방, 벽장 등이 교묘하게 분할 구성된 점, 원형과 방형의 기둥이 조화롭게 사용된 점, 마루의 바닥높이에 차이를 두어 외부공간과 자연스럽게 연결을 추구한 수법과 더불어 육각 평면위에 팔작지붕을 꾸미는 독특한 목구조결구방식 등 다양한 부분에서 전통건축의 구조기법을 연구할 수 있는 중요한 자료로 평가됨.","a":"경주 귀래정","c":"보물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019122715241300.JPG"},{"q":"○○○와 백장암 약수암을 포함한 일대로서 지리산 북쪽 기슭에 있다. ○○○는 신라 흥덕왕 3년(828)에 증각대사 홍척이 창건하였으며, 제자 수철대사와 편운대사도 이 절에서 배출되었다. 조선시대 정유재란 때 화재를 입어 200여 년 동안 폐허로 남아 있었고, 승려들은 백장암에서 머물며 그 명맥을 이어왔다. 숙종 때 다시 지었고 고종 때 화재를 입어 작게 지은 것이 현재의 모습이다. 현존하는 건물로는 보광전·약사전·명부전 등이 있다. 중요문화유산으로는 백장암 3층석탑(국보)·○○○ 수철화상능가보월탑(보물)과 탑비(보물)·○○○ 석등(보물)·부도(보물)·○○○ 3층석탑(…","a":"남원 실상사","c":"사적","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626899.jpg"},{"q":"272.2×137.9cm에 달하는 1축의 대형 조선전도로, 표현된 범위는 조선과 만주의 일부를 아우르고 있다. 지도의 재질은 세견(細絹)으로 세 폭을 이어 만들었는데, 정교하게 그려진 솜씨로 볼 때 도화서의 화원이 그린 것으로 추정된다. 조선의 전체적인 모습, 수록된 정보의 종류와 양이 정상기(鄭尙驥, 1678-1752)의 <동국지도> 원본 계통과 동일하다. 1767년에 산청(山淸)과 안의(安義)로 바뀌는 산음(山陰)과 안음(安陰)이 변경 이전의 지명으로 기록되어 있는 점 등에서 1755년에서 1757년 사이에 제작된 것으로 추정된다. 이 지도는 만주를 함께 그린 것…","a":"동국대지도","c":"보물","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614910.jpg"},{"q":"큰 사발(大鉢)의 형상을 한 ○○○○○은 높이 1.2m, 지름 2.7m, 둘레 10.8m, 두께 10∼3㎝의 거대한 크기로, 상부의 외반된 전이 달린 구연부는 둥글게 처리하였고 기벽(器壁)의 두께는 3∼5㎝ 정도이며 무게는 약 20여 톤으로 추정된다. 비교적 단순한 구조에, 몸체에는 아무런 문양이나 기록이 주조되지 않아 제조연대·제작자 및 제조방법 등을 알 수 없지만, 용해온도가 청동보다 훨씬 높은 주철로 주조된 대형의 주물솥이라는 점에서 기술사적 측면에서 귀중한 자료이다. 신라시대 성덕왕대에 제작되었다고 전해지지만 ○○○의 사세(寺勢)가 가장 융성했던 조선시대 제작…","a":"보은 법주사 철솥","c":"보물","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617348.jpg"},{"q":"○○○는 동해안에 있는 통일신라시대의 사찰로 지금은 3층석탑 2기와 금당 및 강당 등 건물터만 남아있다. 신라 문무왕은 삼국을 통일한 후 부처의 힘을 빌어 왜구의 침입을 막고자 이곳에 절을 세웠다. 절이 다 지어지기 전에 왕이 죽자, 그 뜻을 이어받아 아들인 신문왕이 682년에 완성하였다. 문무왕은 “내가 죽으면 바다의 용이 되어 나라를 지키고자 하니 화장하여 동해에 장사지낼 것”을 유언하였는데, 그 뜻을 받들어 장사한 곳이 절 부근의 대왕암이며, 그 은혜에 감사한다는 뜻으로 절 이름을 ○○○라 하였다고 전한다. 발굴조사를 통하여 강당·금당·중문이 일직선상에 배치되어…","a":"경주 감은사지","c":"사적","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627602.jpg"},{"q":"ㅇ 5~6세기경에 조성된 대규모의 고총고분으로 ○○지역만의 독특한 문화를 향유하고 있어 이 지역의 독자적 문화를 밝힐 수 있는 매우 중요한 유적임과 동시에, 묘제와 출토유물 양상을 볼 때 신라의 지방지배 방식의 변화를 잘 보여주고 있어 역사적·학술적·문화적 가치가 높은 유적임","a":"의성 금성면 고분군","c":"사적","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020040109501500.jpg"},{"q":"○○○○○ 및 ○○○○은 원래 부석사에 모셔져 있던 것을 ○○○로 옮겨 놓은 것으로, 후불탱화를 나무로 깎아 돋을새김, 또는 뚫을새김으로 표현한 것이다. 탱화란 천이나 종이에 그림을 그려 족자나 액자의 형태로 만들어서 거는 불화의 일종으로, 대개 법당 본존불의 뒤에 후불탱화로 걸린다. 조선 후기에는 이런 목각탱이 꽤 유행하였는데, 이것은 그 가운데에서 가장 뛰어난 기량을 보여주고 있다. 이것은 아미타후불탱화를 조각한 것으로 중앙에는 광배와 연꽃을 새긴 대좌를 새기고, 여기에 별도의 나무로 깎은 아미타불상을 안치하고 있다. 이 좌우로 5단에 걸쳐 협시상들을 안치하고 있…","a":"문경 대승사 목각아미타여래설법상 관계문서","c":"보물","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621217.jpg"},{"q":"○○○는 1919년 3·1운동 당시 경성의학전문학교 학생으로 학생들을 동원하는 등 3·1독립운동의 주된 역할을 하였으며, 상해에 대한민국 임시정부가 설립되자 독립운동 자료조사 및 수집 등 활동을 하였다. 1920년에는 안창호의 비서로 근무하였으며, 흥사단에 입단하여 활동하였다. 도산 안창호의 권고로 1924년 귀국 후 복학하고 수양동맹회, 동우회에서 독립운동을 계속하였으며, 이후 교육과 치료 및 국민 보건위생계몽을 하다가 1936년 경성의학전문학교의 외과 강사로 근무 중 순직하신 독립 운동가이다.","a":"망우 독립유공자 묘역 - 유상규 묘소","c":"국가등록문화유산","r":"경기도","s":"구리시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/201710301509580k.JPG"}]);